window.HOT_DASHBOARD_UNITS = [{"unit": 1, "theme": "Brevity and Silence", "themeZh": "簡潔與沉默", "antonymLessons": [2], "cards": [{"w": "concise", "p": "adj.", "d": "Giving much information clearly in few words.", "c": "簡潔的；簡明的", "s": "Because the journal limits abstracts to 150 words, the epidemiologist spent days revising her summary until it was concise enough to convey the study's design, sample size, and central finding without sacrificing any of the statistical detail that reviewers would need to evaluate it.", "t": "由於該期刊將摘要限制在一百五十字以內，這位流行病學家花了好幾天修改她的摘要，直到它夠簡潔，能在不犧牲審查者評估時所需的任何統計細節之下，傳達研究設計、樣本數與核心發現。", "as": "Unlike the verbose memos of his predecessors, the new director's concise reports were praised as judicious and incisive, allowing even skeptical board members to grasp the company's precarious finances within minutes of opening them.", "at": "與前任主管冗長的備忘錄不同，新任主管簡潔的報告被讚譽為明智而一針見血，讓即使抱持懷疑態度的董事，也能在打開報告幾分鐘內就掌握公司岌岌可危的財務狀況。"}, {"w": "reticent", "p": "adj.", "d": "Reluctant to reveal one's thoughts or feelings.", "c": "沉默寡言的；有所保留的", "s": "Although the retired diplomat had witnessed several of the most consequential negotiations of the Cold War, he remained reticent about them in interviews, politely declining to discuss specific conversations and insisting that confidentiality was a promise that did not expire when one left office.", "t": "雖然這位退休外交官親眼見證了冷戰時期幾場最具影響力的談判，他在受訪時對這些事卻始終有所保留，客氣地拒絕談論具體的對話內容，並堅稱保密是一項承諾，不會因卸任而失效。", "as": "The normally reticent physicist became surprisingly voluble when asked about her research, but she grew wary again once reporters began asking about the scandal surrounding her laboratory, offering only deliberately ambiguous replies.", "at": "這位平時沉默寡言的物理學家被問到自己的研究時，變得出乎意料地健談；但當記者開始詢問她實驗室捲入的醜聞時，她又變得謹慎起來，只給出刻意模稜兩可的回答。"}, {"w": "succinct", "p": "adj.", "d": "Expressed clearly and precisely in very few words.", "c": "簡明扼要的；簡潔的", "s": "The Supreme Court justice was admired for her succinct opinions; where colleagues filled forty pages with historical digressions, she could state the constitutional question, apply the relevant precedent, and announce the holding in fewer than ten carefully reasoned paragraphs.", "t": "這位最高法院大法官以簡明扼要的判決意見書著稱；同僚動輒用四十頁篇幅穿插歷史題外話，她卻能在不到十段縝密推理的文字中，陳述憲法爭點、援引相關判例並宣布判決結果。", "as": "Asked to explain the debacle, the chief engineer gave a succinct account that debunked several spurious rumors, pointing instead to a single overlooked discrepancy in the collapsed bridge's original load calculations.", "at": "被要求解釋這場慘敗時，總工程師給出了一段簡明扼要的說明，揭穿了好幾則不實的謠言，並指出問題其實出在倒塌橋梁原始載重計算中一個被忽略的誤差。"}, {"w": "laconic", "p": "adj.", "d": "Using very few words; expressing much briefly.", "c": "言簡意賅的；惜字如金的", "s": "When journalists pressed the famously laconic Vermont farmer to describe the devastating flood that had destroyed his barn and half his herd, he replied only, 'Bad year,' and returned to repairing the fence, leaving reporters to supply the drama themselves.", "t": "當記者追問這位以惜字如金聞名的佛蒙特州農夫，請他描述那場摧毀他的穀倉和半數牲口的洪水時，他只回了一句「年頭不好」，便又回頭修補籬笆，讓記者們自行去渲染戲劇性的情節。", "as": "The novelist's laconic dialogue, in which characters exchange only a few clipped phrases, conveys tension more effectively than the grandiloquent speeches of her contemporaries, whose verbose, ostentatious prose often obscures the emotions it intends to reveal.", "at": "這位小說家筆下簡短扼要的對白，讓角色之間只交換寥寥數語，卻比她同時代作家那些浮誇的長篇演說更能有效傳達緊張感；那些作家冗長而賣弄的文筆，往往反而遮蔽了它想揭示的情感。"}, {"w": "terse", "p": "adj.", "d": "Brief and abrupt, sometimes to the point of rudeness.", "c": "簡短生硬的；扼要的", "s": "After months of polite correspondence, the publisher's terse two-line email ('We will not be renewing your contract. Please return the advance.') signaled to the novelist that the relationship had soured beyond repair and that further negotiation would be pointless.", "t": "在幾個月客氣的書信往來之後，出版商那封簡短生硬的兩行電子郵件（「我們不會與您續約，請退還預付金。」）讓這位小說家明白，雙方關係已惡化到無可挽回，再談下去也毫無意義。", "as": "Irritated by the reporter's insolent questions, the normally affable senator gave a terse reply, then strode out of the crowded briefing room, leaving his aides to mollify the indignant press corps.", "at": "被記者無禮的提問激怒後，這位平時和藹可親的參議員簡短生硬地回了一句，便大步走出擠滿人的簡報室，留下幕僚去安撫憤憤不平的記者團。"}, {"w": "brevity", "p": "n.", "d": "The quality of being brief in speech or writing.", "c": "簡潔；簡短", "s": "Lincoln's Gettysburg Address, at roughly 270 words, owes much of its enduring power to its brevity; Edward Everett, who had spoken for two hours before him, later wrote that he wished he had come as close to the heart of the occasion in two hours as the president had in two minutes.", "t": "林肯的蓋茲堡演說僅約兩百七十字，其歷久不衰的感染力很大程度上來自它的簡潔；在他之前演講了兩個小時的愛德華．艾佛瑞特後來寫道，他真希望自己花兩個小時所觸及的典禮核心，能像總統在兩分鐘內做到的那樣深刻。", "as": "Critics praised the brevity of the eulogy, noting that its restrained, unpretentious language moved mourners far more deeply than the hackneyed platitudes and grandiloquent tributes that usually dominate such solemn occasions.", "at": "評論者稱讚這篇悼詞的簡潔，指出其節制而樸實的語言，遠比這類莊嚴場合中常見的陳腐套話與浮誇頌詞更能深深打動弔唁者。"}, {"w": "pithy", "p": "adj.", "d": "Brief but full of meaning and force.", "c": "精闢的；言簡意賅的", "s": "Benjamin Franklin's Poor Richard's Almanack popularized dozens of pithy sayings, such as 'Well done is better than well said,' whose compact phrasing made practical moral advice easy for colonial readers to remember, repeat, and pass on to their children.", "t": "班傑明．富蘭克林的《窮理查年鑑》讓數十句精闢的格言廣為流傳，例如「做得好勝過說得好」；這些格言措辭精簡，使殖民地讀者容易記住、複誦，並傳給自己的孩子。", "as": "Rather than offering banal platitudes, the economist summed up the heated debate over inflation with one pithy observation that was both erudite and accessible, and even her most cynical critics conceded its force.", "at": "這位經濟學家沒有搬出平庸的陳腔濫調，而是用一句精闢的評論總結了這場關於通膨的激烈辯論；這句話既博學又淺顯易懂，連她最憤世嫉俗的批評者也承認其說服力。"}, {"w": "quiescent", "p": "adj.", "d": "In a state of inactivity or dormancy.", "c": "靜止的；不活動的", "s": "Although the varicella-zoster virus can remain quiescent in nerve cells for decades after a childhood case of chickenpox, a weakened immune system in later life may allow it to reactivate, producing the painful rash known as shingles.", "t": "雖然水痘帶狀疱疹病毒在童年感染水痘後，可能在神經細胞中靜止潛伏數十年，但晚年免疫系統衰弱時，它可能重新活化，引發疼痛的皮疹，也就是俗稱「皮蛇」的帶狀疱疹。", "as": "Geologists warn that the volcano's quiescent state may be an illusion: beneath its tranquil surface, magma is slowly accumulating, and the transient tremors recorded last spring could be an ominous sign of an imminent eruption.", "at": "地質學家警告，這座火山的靜止狀態可能只是假象：在平靜的表面下，岩漿正緩慢累積，而去年春天記錄到的短暫震動，可能是火山即將噴發的不祥徵兆。"}, {"w": "taciturn", "p": "adj.", "d": "Habitually silent and reserved in speech.", "c": "沉默寡言的", "s": "Calvin Coolidge was so taciturn that Washington hostesses competed to coax more than a few words from him; according to a popular anecdote, when a dinner guest bet she could get more than two words out of him, he replied, 'You lose.'", "t": "卡爾文．柯立芝沉默寡言到華府的女主人們競相設法讓他多說幾句話；根據一則流傳甚廣的軼事，曾有一位晚宴賓客跟他打賭，說她能讓他說出超過兩個字，他只回答：「妳輸了。」", "as": "The taciturn Danish sculptor rarely discussed her work in interviews, yet critics found her aloof demeanor oddly compelling, and her eclectic installations, assembled from obsolete factory machinery, received widespread critical acclaim.", "at": "這位沉默寡言的丹麥雕塑家很少在受訪時談論自己的作品，但評論家覺得她冷漠疏離的態度別具魅力，而她以廢棄工廠機械組裝而成、風格多元的裝置藝術，也廣受評論界讚譽。"}, {"w": "curt", "p": "adj.", "d": "Abruptly and rudely short.", "c": "簡短無禮的/唐突的", "s": "His curt reply left little room for further discussion.", "t": "他簡短無禮的回應幾乎不留任何討論的空間。", "as": "She gave a curt nod and walked away without another word.", "at": "她冷淡地點了點頭,便一言不發地走開了。", "a": 1}, {"w": "aphoristic", "p": "adj.", "d": "Expressed in short, memorable phrases.", "c": "格言式的;警句般的", "s": "The professor's aphoristic style made his lectures easy to quote and remember.", "t": "這位教授格言式的講課風格,讓人容易引用也容易記住。", "as": "Her writing is famously aphoristic , packing whole arguments into single sentences.", "at": "她的文筆以格言般著稱,能把整個論點濃縮進一句話裡。", "a": 1}, {"w": "brusque", "p": "adj.", "d": "Short, abrupt, dismissive.", "c": "唐突的/生硬的", "s": "The manager's brusque reply left the new intern feeling unwelcome.", "t": "經理生硬的回覆讓這位新實習生感覺不受歡迎。", "as": "Despite his brusque manner, he is known to be fiercely loyal to his friends.", "at": "儘管他態度唐突,大家都知道他對朋友極為忠誠。", "a": 1}, {"w": "truncated", "p": "adj.", "d": "Cut short.", "c": "截短的/縮短的", "s": "Due to time constraints, the speaker gave a truncated version of his usual lecture.", "t": "由於時間限制,講者發表了一場截短版的演講。", "as": "The magazine printed a truncated excerpt of the full novel.", "at": "這本雜誌刊登了整部小說的一段節錄縮短版。", "a": 1}, {"w": "elliptical", "p": "adj.", "d": "Having the shape of an ellipse; using deliberately brief or indirect expression.", "c": "橢圓形的;省略的", "s": "Planets travel in elliptical orbits around the sun.", "t": "行星以橢圓形軌道繞著太陽運行。", "as": "His elliptical answer left the reporters more confused.", "at": "他省略含糊的回答讓記者們更加困惑。", "a": 1}]}, {"unit": 2, "theme": "Wordiness and Talkativeness", "themeZh": "冗長與多話", "antonymLessons": [1], "cards": [{"w": "circumlocution", "p": "n.", "d": "The use of many words to avoid saying something directly.", "c": "迂迴的說法；拐彎抹角", "s": "Rather than admitting that the drug trial had failed, the pharmaceutical company's press release relied on elaborate circumlocution, describing the disappointing results as 'not yet aligned with initial expectations' and the abandoned study as 'a strategic recalibration of the clinical timeline.'", "t": "這家製藥公司的新聞稿沒有承認藥物試驗失敗，而是用盡拐彎抹角的說法，把令人失望的結果形容為「尚未符合初步預期」，並把已放棄的研究稱為「臨床時程的策略性調整」。", "as": "Annoyed by the minister's circumlocution, the incisive journalist demanded a succinct answer, observing that candor, not evasion, was what voters expected from an official accused of squandering public funds.", "at": "被部長拐彎抹角的說法惹惱後，這位一針見血的記者要求他給出簡明扼要的回答，並指出選民期待一位被控揮霍公帑的官員坦誠以對，而不是閃爍其詞。"}, {"w": "colloquial", "p": "adj.", "d": "Characteristic of informal, everyday conversation.", "c": "口語的；通俗的", "s": "Mark Twain's decision to narrate Adventures of Huckleberry Finn in the colloquial speech of an uneducated Missouri boy, complete with regional grammar and slang, shocked some nineteenth-century critics who believed that serious literature required formal, polished English.", "t": "馬克．吐溫決定以一個未受教育的密蘇里男孩的口語來敘述《頑童歷險記》，連同地方性的文法和俚語都保留下來，這讓一些認為嚴肅文學必須使用正式、精練英文的十九世紀評論家大為震驚。", "as": "The poet's colloquial diction, drawn from the chatter of city streets, struck pretentious critics as banal, yet younger readers found her eclectic blend of slang and classical allusion refreshingly novel.", "at": "這位詩人取材自城市街頭閒談的口語化用詞，在自命不凡的評論家看來平庸乏味，但年輕讀者卻覺得她融合俚語與古典典故的多元風格新穎得令人耳目一新。"}, {"w": "digress", "p": "v.", "d": "To stray temporarily from the main subject.", "c": "離題；偏離主題", "s": "The biology professor's tendency to digress from his lecture on cellular respiration into long stories about his fieldwork in the Amazon delighted some students, but others complained that the exam covered material he had never actually finished explaining in class.", "t": "這位生物學教授在講授細胞呼吸作用時，常常離題去講他在亞馬遜雨林做田野調查的長篇故事，讓一些學生聽得津津有味，但也有學生抱怨考試考到了他在課堂上根本沒講完的內容。", "as": "Whenever the historian began digressing into trivial anecdotes, her meticulous co-author would gently steer the discussion back to the debacle at Gallipoli and the strategic errors that caused it.", "at": "每當這位歷史學家開始離題講些瑣碎的軼事，她那位一絲不苟的共同作者就會溫和地把討論拉回加里波利戰役的慘敗，以及導致這場慘敗的戰略失誤。"}, {"w": "diffuse", "p": "adj.", "d": "Wordy and lacking focus or clear organization.", "c": "冗長散漫的；不集中的", "s": "Reviewers rejected the dissertation's first draft as diffuse, noting that its central argument about Ottoman trade networks was buried beneath hundreds of pages of loosely connected observations, repetitive summaries, and tangents that never returned to the thesis.", "t": "審查委員認為這篇博士論文的初稿冗長散漫而予以退回，指出它關於鄂圖曼貿易網絡的核心論點，被埋沒在數百頁鬆散相連的觀察、重複的摘要，以及始終沒有回到論旨的枝節之中。", "as": "The committee found the report so diffuse that its key recommendation was nearly invisible, so an astute editor abridged it into a concise summary that even the most phlegmatic legislators read with interest.", "at": "委員會認為這份報告冗長散漫到幾乎看不出它的關鍵建議，於是一位精明的編輯將它刪節成一份簡潔的摘要，連最冷淡的立法委員都讀得津津有味。"}, {"w": "eloquence", "p": "n.", "d": "Fluent, persuasive, and moving skill in speaking or writing.", "c": "口才；雄辯", "s": "Frederick Douglass's eloquence so astonished nineteenth-century audiences that some skeptics refused to believe he had ever been enslaved, assuming that no one denied a formal education could speak with such moving clarity, logical force, and command of classical rhetoric.", "t": "弗雷德里克．道格拉斯的雄辯口才令十九世紀的聽眾大為驚嘆，以致一些懷疑者拒絕相信他曾經是奴隸，認定沒有受過正規教育的人不可能說話如此清晰動人、邏輯有力，又能駕馭古典修辭。", "as": "Her eloquence won the debate not through flashy flourishes but through lucid, judicious arguments that left even her most belligerent opponents unable to impugn her reasoning.", "at": "她憑藉雄辯贏得了這場辯論，靠的不是華麗的修辭，而是清晰而明智的論證，讓即使是最好鬥的對手也無從質疑她的推理。"}, {"w": "grandiloquent", "p": "adj.", "d": "Using pompous, lofty language to impress others.", "c": "浮誇的；誇大其詞的", "s": "The dictator's grandiloquent speeches, filled with references to 'the eternal destiny of the motherland' and 'the immortal glory of our ancestors,' contrasted sharply with the grim reality of food shortages and power outages that ordinary citizens endured every day.", "t": "這位獨裁者浮誇的演說充斥著「祖國永恆的命運」和「先祖不朽的榮光」之類的字眼，與一般民眾每天忍受的糧食短缺和停電等嚴峻現實形成強烈對比。", "as": "The candidate's grandiloquent promises about restoring the nation's glory struck many voters as pretentious, and his ostentatious campaign rallies only reinforced the impression that he was a braggart rather than a serious leader.", "at": "這位候選人關於恢復國家榮光的浮誇承諾，讓許多選民覺得自命不凡，而他鋪張炫耀的造勢晚會，更加深了他只是個愛吹牛的人、而非認真領袖的印象。"}, {"w": "loquacious", "p": "adj.", "d": "Very talkative; fond of talking.", "c": "話多的；健談的", "s": "The loquacious tour guide filled every silence on the six-hour bus ride with stories about local legends, family gossip, and regional politics, so that by the time the group reached the ancient monastery, several exhausted passengers were pretending to sleep just to escape the commentary.", "t": "這位話多的導遊在六小時的巴士車程中，用地方傳說、家族八卦和區域政治的故事填滿每一段沉默，以致於團員抵達那座古老修道院時，好幾位疲憊的乘客正假裝睡覺，只為了躲開他的解說。", "as": "The loquacious host of the talk show, normally ebullient and jocular, became oddly reticent when guests asked about the lawsuit that had tarnished his reputation.", "at": "這位脫口秀主持人平時話多、熱情洋溢又愛說笑，但當來賓問起那件損害他名譽的訴訟時，他卻變得異常沉默。"}, {"w": "verbose", "p": "adj.", "d": "Using more words than are needed.", "c": "冗長的；囉嗦的", "s": "Software engineers often criticize older technical documentation as verbose, since a manual that devotes twelve pages to a single installation step forces users to wade through redundant definitions and repeated warnings before finding the one command they actually need.", "t": "軟體工程師常批評舊的技術文件冗長囉嗦，因為一本花十二頁說明單一安裝步驟的手冊，迫使使用者在找到真正需要的那一行指令之前，必須費力讀過一堆重複的定義和警告。", "as": "The legislation was so verbose that few lawmakers read it completely, allowing a clandestine provision buried on page nine hundred to give a mercenary contractor lucrative and unprecedented control over the state's prisons.", "at": "這項法案冗長到很少有議員把它讀完，使得一條藏在第九百頁的祕密條款，讓一家唯利是圖的承包商取得了對該州監獄有利可圖、前所未有的控制權。"}, {"w": "garrulous", "p": "adj.", "d": "Excessively talkative, especially about trivial matters.", "c": "喋喋不休的；嘮叨的", "s": "In Chaucer's Canterbury Tales, the garrulous Wife of Bath delivers a prologue longer than many of the tales themselves, rambling cheerfully through her five marriages, her opinions on scripture, and countless personal anecdotes before finally beginning the story she has promised the other pilgrims.", "t": "在喬叟的《坎特伯里故事集》中，喋喋不休的巴斯婦人所講的開場白比許多故事本身還長，她興致勃勃地東拉西扯，談她的五段婚姻、她對經文的看法以及數不清的個人軼事，最後才開始講她答應其他朝聖者的故事。", "as": "The garrulous neighbor's endless gossip seemed harmless, but detectives later realized that her trivial chatter contained a crucial clue about the furtive stranger who had been seen lingering near the house.", "at": "那位喋喋不休的鄰居沒完沒了的閒話看似無害，但警探後來發現，她瑣碎的閒聊中藏著一條關鍵線索，指向那名曾被人看見在房子附近徘徊、鬼鬼祟祟的陌生人。"}, {"w": "prattle", "p": "v.", "d": "To talk at length in a foolish or trivial way.", "c": "喋喋不休地閒扯；胡扯", "s": "During the hearing, the witness continued to prattle about his vacation plans, his favorite restaurants, and a dispute with his landlord, until the exasperated judge reminded him that the court needed only a simple answer about where he had been on the night of the robbery.", "t": "聽證會上，這名證人一直喋喋不休地閒扯他的度假計畫、他最喜歡的餐廳，以及他和房東的糾紛，直到惱怒的法官提醒他，法庭只需要他簡單回答搶案當晚他人在哪裡。", "as": "While the guests prattled about trivial matters like the weather and the menu, the astute diplomat quietly gathered intelligence from the nonchalant ambassador seated beside her.", "at": "當賓客們閒扯著天氣和菜單之類的瑣事時，這位精明的外交官悄悄從坐在她身旁、漫不經心的大使那裡蒐集情報。"}, {"w": "rant", "p": "v.", "d": "To speak loudly, angrily, and at length.", "c": "大聲咆哮；激動地痛罵", "s": "Instead of responding calmly to the scientific criticism of his methods, the embattled researcher ranted for twenty minutes during the conference session, shouting accusations at his critics and pounding the lectern, a performance that damaged his credibility far more than the original critique.", "t": "這位飽受抨擊的研究人員沒有冷靜回應學界對他研究方法的批評，反而在研討會上咆哮了二十分鐘，對批評者大聲指控、猛拍講台；這番表現對他信譽的傷害，遠比原本的批評還要大。", "as": "Rather than ranting at the referee, the coach adopted a stoical silence, knowing that a vociferous tirade would only earn a penalty and intimidate his already sluggish players.", "at": "這位教練沒有對裁判大聲咆哮，而是選擇隱忍地保持沉默，因為他知道一番大吵大鬧的怒罵只會招來判罰，還會嚇到他那些原本就動作遲緩的球員。"}, {"w": "rhetorical", "p": "adj.", "d": "Relating to language used to persuade or impress.", "c": "修辭的；為修辭效果的", "s": "Historians note that Martin Luther King Jr.'s 'I Have a Dream' speech derives much of its rhetorical power from anaphora, the deliberate repetition of a phrase at the start of successive sentences, a technique that builds emotional momentum and makes the speech memorable.", "t": "歷史學家指出，馬丁．路德．金恩的〈我有一個夢〉演說，其修辭力量很大程度上來自首語重複法，也就是在連續句子的開頭刻意重複同一個片語；這種技巧能累積情感動能，使演說令人難忘。", "as": "The senator's rhetorical skill could not disguise the spurious statistics in her speech, and an incisive fact-checker soon debunked her most ostentatious claims.", "at": "這位參議員的修辭技巧掩蓋不了她演講中那些虛假的統計數據，一位眼光犀利的事實查核者很快就揭穿了她最誇張的說法。"}, {"w": "voluble", "p": "adj.", "d": "Speaking fluently, readily, and at length.", "c": "健談的；口若懸河的", "s": "Normally shy in seminars, the graduate student became remarkably voluble whenever conversation turned to medieval astronomy, speaking rapidly and fluently for long stretches about astrolabes, star charts, and the Islamic scholars who had preserved and refined Ptolemy's calculations.", "t": "這名研究生平時在研討課上很害羞，但只要話題轉到中世紀天文學，他就變得口若懸河，滔滔不絕地談論星盤、星圖，以及保存並改良托勒密計算的伊斯蘭學者。", "as": "The voluble salesman's charm concealed a devious scheme: his glib assurances persuaded gullible investors to squander their savings on a fraudulent company run by a notorious charlatan.", "at": "這位能言善道的推銷員的魅力背後藏著一個狡詐的詭計：他油嘴滑舌的保證說服了容易受騙的投資人，把積蓄揮霍在一家由惡名昭彰的騙子經營的詐騙公司上。"}, {"w": "effusive", "p": "adj.", "d": "Expressing feelings of gratitude, pleasure, or approval in an unrestrained manner.", "c": "熱情洋溢的;過分熱情的", "s": "He gave an effusive thank-you speech at the award ceremony.", "t": "他在頒獎典禮上發表了一段熱情洋溢的感謝致詞。", "as": "Her effusive praise embarrassed the shy student.", "at": "她過分熱情的讚美讓這位害羞的學生感到尷尬。", "a": 1}, {"w": "bombastic", "p": "adj.", "d": "High-sounding but with little meaning; inflated.", "c": "誇誇其談的/浮誇的", "s": "His bombastic speech failed to convey a clear message.", "t": "他那浮誇的演說未能傳達出清楚的訊息。", "as": "Critics mocked the politician's bombastic promises during the campaign.", "at": "評論家嘲笑這位政治人物在競選期間誇大不實的承諾。", "a": 1}, {"w": "long-winded", "p": "adj.", "d": "Tediously lengthy in speech or writing.", "c": "冗長的;囉唆的", "s": "His long-winded speech caused half the audience to check their phones.", "t": "他冗長的演講讓半數聽眾都開始滑起了手機。", "as": "The report was so long-winded that few colleagues finished reading it.", "at": "這份報告如此冗長,以至於很少有同事讀完它。", "a": 1}, {"w": "ramble", "p": "v./n.", "d": "To talk or write at length without a clear purpose; a leisurely walk.", "c": "漫談;閒逛", "s": "He tends to ramble whenever he talks about his college years.", "t": "每當他談起大學時光,總是傾向漫無邊際地閒扯。", "as": "They took a pleasant ramble through the countryside on Sunday.", "at": "他們在週日於鄉間享受了一段愜意的漫步閒逛。", "a": 1}, {"w": "turgid", "p": "adj.", "d": "Swollen, excessively embellished in style or language.", "c": "腫脹的/浮誇的", "s": "The professor's turgid prose made his lectures a chore to follow.", "t": "這位教授浮誇艱澀的文風讓他的講課變得難以跟上。", "as": "The river grew turgid after days of continuous rain.", "at": "在連日不斷的降雨後,這條河流變得高漲腫脹。", "a": 1}, {"w": "discursive", "p": "adj.", "d": "Rambling, lacking order.", "c": "散漫的/離題的", "s": "His discursive lecture wandered from topic to topic without a clear point.", "t": "他這場散漫的講座東拉西扯,毫無明確重點。", "as": "The professor's discursive writing style makes his essays difficult to follow.", "at": "這位教授散漫的寫作風格讓他的文章難以理解。", "a": 1}]}, {"unit": 3, "theme": "Arrogance and Pride", "themeZh": "傲慢與自大", "antonymLessons": [15, 71], "cards": [{"w": "arrogant", "p": "adj.", "d": "Having an exaggerated sense of one's own importance.", "c": "傲慢的；自大的", "s": "The young surgeon's arrogant refusal to consult the nurses, whom he considered beneath him, proved costly when he dismissed their warning about a patient's allergy, an error that a more humble physician would almost certainly have avoided.", "t": "這位年輕外科醫師傲慢地拒絕徵詢護理師的意見，認為她們不如自己；當他對護理師關於病患過敏的警告置之不理時，這種態度付出了慘痛代價，而一位較謙虛的醫師幾乎肯定能避免這個錯誤。", "as": "The arrogant general dismissed his scouts' cautious reports as frivolous, and his refusal to heed their warnings led to a debacle in which his army was trapped in a labyrinth of narrow mountain passes.", "at": "這位傲慢的將軍把偵察兵謹慎的報告斥為無聊小事，而他拒絕聽從警告，導致了一場慘敗：他的軍隊被困在迷宮般的狹窄山路之中。"}, {"w": "contemptuous", "p": "adj.", "d": "Showing that one considers someone or something worthless.", "c": "輕蔑的；鄙視的", "s": "Many established painters were openly contemptuous of the first Impressionist exhibition in 1874; one critic sneered that the loose brushwork looked like wallpaper in its earliest stage, and several refused to treat the movement as serious art at all.", "t": "許多成名畫家對一八七四年的首次印象派畫展公開表示輕蔑；一位評論家譏諷那些鬆散的筆觸看起來像是剛起稿的壁紙，還有好幾位畫家根本拒絕把這個畫派當成嚴肅的藝術。", "as": "The aristocrat's contemptuous dismissal of the artisans who built his palace revealed an odious snobbery, and his ostentatious spending soon became a frequent target of vociferous public criticism.", "at": "這位貴族輕蔑地看待為他建造宮殿的工匠，暴露出令人憎惡的勢利心態，而他鋪張炫耀的揮霍也很快成為民眾大聲批評的常見目標。"}, {"w": "complacent", "p": "adj.", "d": "Smugly satisfied and unaware of possible dangers.", "c": "自滿的；自鳴得意的", "s": "After decades as the world's dominant camera maker, the company grew complacent, assuming customers would always prefer film; executives ignored the early digital sensors developed in their own laboratories, and rivals who embraced the new technology soon captured the market.", "t": "在稱霸全球相機市場數十年後，這家公司變得自滿，以為顧客永遠會偏好底片；高層忽視了自家實驗室早期研發的數位感光元件，而擁抱新技術的對手很快就奪走了市場。", "as": "Public health officials warned that a complacent attitude toward the virus, even after infections became negligible, could prove detrimental, since a single virulent new strain might rapidly spread through a population whose vigilance had faded.", "at": "公共衛生官員警告，即使感染人數已微不足道，對病毒抱持自滿的態度仍可能造成危害，因為只要出現一種毒性強的新變種，就可能在警覺心已鬆懈的人群中迅速蔓延。"}, {"w": "disdainful", "p": "adj.", "d": "Showing scorn for something considered unworthy.", "c": "輕蔑的；不屑的", "s": "Classically trained musicians in the 1920s were often disdainful of jazz, dismissing its improvised solos as undisciplined noise, yet within a generation many conservatories had added jazz programs and recognized musicians like Louis Armstrong as genuine innovators.", "t": "一九二〇年代受古典訓練的音樂家常對爵士樂不屑一顧，把它的即興獨奏斥為毫無章法的噪音；然而不到一個世代，許多音樂學院就已增設爵士課程，並認可路易．阿姆斯壯等音樂家為真正的創新者。", "as": "The disdainful critic dismissed the debut novel as hackneyed and derivative, yet his pretentious review was soon forgotten while the book became a classic.", "at": "這位不屑的評論家把那部處女作斥為陳腐又缺乏原創，但他那篇自命不凡的書評很快就被遺忘，而那本書卻成了經典。"}, {"w": "insolent", "p": "adj.", "d": "Boldly rude and disrespectful toward authority.", "c": "傲慢無禮的；目無尊長的", "s": "When the young officer answered the admiral's order with an insolent shrug and a sarcastic remark in front of the entire crew, he was immediately relieved of duty, since naval discipline treated such open disrespect toward a superior as a serious offense.", "t": "當這名年輕軍官在全體船員面前以傲慢無禮的聳肩和一句挖苦話回應上將的命令時，他立刻被解除職務，因為海軍紀律把這種公然冒犯上級的行為視為嚴重違紀。", "as": "The insolent apprentice mocked his master's antiquated methods, but his impudent remarks only revealed how little he understood the craft he was so eager to scorn.", "at": "這個傲慢無禮的學徒嘲笑師傅過時的手法，但他那番無禮的言論只暴露出他對自己急於鄙視的這門手藝有多麼無知。"}, {"w": "presumptuous", "p": "adj.", "d": "Overstepping proper limits; taking too much for granted.", "c": "冒昧的；放肆的", "s": "Junior researchers sometimes worry that it would be presumptuous to correct a senior professor's calculation in public, yet philosophers of science argue that progress depends on precisely such willingness to challenge authority whenever the evidence demands it.", "t": "資淺的研究人員有時擔心，當眾糾正資深教授的計算會顯得冒昧，但科學哲學家主張，科學的進步正仰賴這種只要證據需要，就願意挑戰權威的態度。", "as": "Critics considered it presumptuous for the novice director, whose debut film was banal and lackluster, to extol his own work as an unprecedented achievement in cinema.", "at": "評論家認為，這位新手導演的處女作平庸又乏味，他卻把自己的作品吹捧為電影史上前所未有的成就，實在是太過放肆。"}, {"w": "pretentious", "p": "adj.", "d": "Trying to appear more important or cultured than one is.", "c": "自命不凡的；做作的", "s": "The art critic mocked the gallery's pretentious wall labels, which described a simple red square as 'a transcendent interrogation of chromatic hegemony,' arguing that inflated academic jargon often disguised the absence of any genuine idea about the work itself.", "t": "這位藝評家嘲諷畫廊自命不凡的展品說明牌，它把一個簡單的紅色方塊形容為「對色彩霸權的超驗詰問」；他認為，浮誇的學術術語往往只是在掩飾作品本身毫無真正的想法。", "as": "The restaurant's pretentious menu, full of grandiloquent descriptions of ordinary dishes, could not disguise the insipid food, and diners soon abandoned it for more unpretentious, palatable fare elsewhere.", "at": "這家餐廳自命不凡的菜單，用浮誇的詞藻描述普通的菜色，卻掩蓋不了食物的平淡無味，顧客很快就轉往別處，去吃更樸實、更可口的餐點。"}, {"w": "supercilious", "p": "adj.", "d": "Behaving as though one is superior to others.", "c": "目中無人的；高傲的", "s": "The museum's supercilious curator, who raised an eyebrow whenever visitors asked basic questions, was eventually replaced by a director who believed that public institutions had a duty to welcome newcomers rather than make them feel ignorant and unwelcome.", "t": "這座博物館那位目中無人的策展人，每當參觀者問些基本問題就挑起眉毛；後來他終於被一位新館長取代，這位館長認為公共機構有責任歡迎初來乍到的人，而不是讓他們覺得自己無知又不受歡迎。", "as": "The supercilious sommelier treated the diners with obvious disdain, and his condescending remarks about their unsophisticated taste struck everyone as petty, impudent, and needlessly belligerent.", "at": "這位目中無人的侍酒師明顯對用餐的客人不屑一顧，他對客人品味粗俗的那番居高臨下的評論，讓所有人都覺得小家子氣、無禮，而且毫無必要地咄咄逼人。"}, {"w": "ostentatious", "p": "adj.", "d": "Showy in a way meant to impress or attract notice.", "c": "炫耀的；鋪張的", "s": "During the Gilded Age, wealthy industrialists built ostentatious mansions in Newport, Rhode Island, complete with marble ballrooms and gold-leaf ceilings, less to provide comfortable homes than to display their newly acquired fortunes to rival families.", "t": "在鍍金時代，富有的實業家在羅德島州的新港興建奢華炫耀的豪宅，配備大理石舞廳和金箔天花板；與其說是為了提供舒適的住所，不如說是要向敵對家族炫耀他們新得的財富。", "as": "The billionaire's ostentatious yacht, adorned with a lavish gold staircase, struck observers as a vulgar contrast to the austere lives of the indigent fishermen who worked in the harbor where it was docked.", "at": "這位億萬富翁鋪張炫耀的遊艇，飾有奢華的黃金階梯，在旁觀者眼中，與停泊港口裡那些貧困漁民的簡樸生活形成了庸俗的對比。"}, {"w": "braggart", "p": "n.", "d": "A person who boasts loudly about achievements.", "c": "吹牛者；自誇的人", "s": "The Roman playwright Plautus created the comic character of the boastful soldier, a cowardly braggart who brags endlessly of imaginary victories and the enemies he claims to have slain, only to flee at the first sign of genuine danger.", "t": "羅馬劇作家普勞圖斯創造了「吹牛軍人」這個喜劇角色：一個膽小的吹牛者，不停誇耀他那些想像中的勝利和他聲稱殺過的敵人，卻在真正的危險一出現時就落荒而逃。", "as": "The braggart's egotistical boasts about his fortune proved spurious when investigators discovered that he was virtually indigent, having squandered his inheritance on gambling years earlier.", "at": "這個吹牛者自我中心地誇耀自己的財富，結果被證明是假話；調查人員發現他幾乎一貧如洗，多年前就已把遺產揮霍在賭博上。"}, {"w": "egotistical", "p": "adj.", "d": "Excessively absorbed in oneself; conceited.", "c": "自我中心的；自負的", "s": "The orchestra's musicians complained that their egotistical new conductor rearranged every program to feature his own compositions, demanded that his name appear in larger type than the composers', and spoke in rehearsals almost exclusively about his past triumphs.", "t": "樂團成員抱怨，他們那位自我中心的新指揮把每場節目都改成以他自己的作品為主，要求他的名字要印得比作曲家還大，而且排練時幾乎只談他過去的輝煌成就。", "as": "The egotistical chef was so contemptuous of criticism that he rebuffed every suggestion from his staff, and his intractable arrogance and rancorous outbursts eventually drove away his most talented cooks.", "at": "這位自我中心的主廚對批評極為輕蔑，拒絕了員工的每一項建議，而他那難以駕馭的傲慢與充滿怨恨的暴怒，最終趕走了他最有才華的廚師。"}, {"w": "haughty", "p": "adj.", "d": "Arrogantly proud and scornful of others.", "c": "高傲的；傲慢的", "s": "In Pride and Prejudice, Mr. Darcy's haughty refusal to dance with Elizabeth Bennet at the Meryton ball, together with his remark, made within her hearing, that she is merely 'tolerable' and not handsome enough to tempt him, establishes the poor first impression that much of the novel's plot is devoted to overturning.", "t": "在《傲慢與偏見》中，達西先生在梅里頓舞會上高傲地拒絕與伊莉莎白．班奈特共舞，還在她聽得到的地方說她只是「還過得去」，不夠漂亮、引不起他的興趣；這奠定了糟糕的第一印象，而小說的大部分情節正是在扭轉這個印象。", "as": "The haughty duchess treated her servants with disdain, yet when her fortune collapsed and she became indigent, she was forced to depend on the benevolent charity of the very servants she had scorned, whose magnanimous forgiveness astonished her.", "at": "這位高傲的公爵夫人以輕蔑的態度對待僕人，然而當她家道中落、陷入貧困時，卻不得不仰賴那些曾被她鄙視的僕人好心的接濟，而他們寬宏大量的原諒令她大為震驚。"}, {"w": "narcissist", "p": "n.", "d": "A person excessively absorbed in self-admiration.", "c": "自戀者", "s": "Psychologists distinguish healthy self-esteem from the behavior of a true narcissist, who constantly seeks admiration, exploits others without guilt, and reacts with rage to even mild criticism because his inflated self-image is, paradoxically, extremely fragile.", "t": "心理學家把健康的自尊和真正自戀者的行為區分開來；自戀者不斷尋求讚美，毫無愧疚地利用他人，甚至對溫和的批評也勃然大怒，因為他膨脹的自我形象其實極為脆弱。", "as": "The narcissist's obsession with his own reflection on social media left him oblivious to his friends' needs, and his egotistical demands for constant adulation eventually alienated even his most obsequious and servile admirers.", "at": "這個自戀者沉迷於自己在社群媒體上的形象，對朋友的需要渾然不覺，而他自我中心地要求不斷被奉承，最終連他最阿諛諂媚、卑躬屈膝的崇拜者也疏遠了他。"}, {"w": "swagger", "p": "v.", "d": "To walk or behave in a boastful, arrogant way.", "c": "大搖大擺地走；神氣十足", "s": "Contemporary accounts describe how the victorious pirate captain swaggered through the captured port, a jeweled sword at his hip and stolen silks draped over his shoulders, deliberately displaying his triumph to the frightened merchants who watched from shuttered windows.", "t": "當時的記載描述，那位獲勝的海盜船長如何大搖大擺地穿過被攻占的港口，腰間掛著鑲滿寶石的佩劍，肩上披著搶來的絲綢，刻意向躲在緊閉窗戶後觀望、驚恐萬分的商人炫耀他的勝利。", "as": "The champion swaggered onto the stage with exuberant confidence, but the audience found his vociferous boasts about defeating every adversary rather hackneyed.", "at": "這位冠軍帶著洋溢的自信大搖大擺地走上舞台，但觀眾覺得他大聲誇口打敗所有對手的說法相當陳腐。"}, {"w": "overbearing", "p": "adj.", "d": "Domineering and unpleasantly controlling.", "c": "專橫的;高壓的", "s": "Her overbearing mother controlled every decision in her life.", "t": "她那專橫的母親掌控著她生活中的每一個決定。", "as": "The team resented their overbearing new manager.", "at": "這支團隊對他們新來的專橫經理感到不滿。", "a": 1}, {"w": "snobbish", "p": "adj.", "d": "Tending to associate only with people of a similar background.", "c": "勢利的/自命清高的", "s": "Her snobbish attitude made it hard for her to make friends at the new school.", "t": "她那勢利的態度讓她在新學校很難交到朋友。", "as": "The club had a reputation for being snobbish and exclusive.", "at": "這間俱樂部以勢利排外而聞名。", "a": 1}, {"w": "vain", "p": "adj.", "d": "Having excessive pride in one's appearance; producing no result.", "c": "虛榮的;徒勞的", "s": "He was too vain to be seen wearing an unfashionable outfit.", "t": "他太過虛榮,不願被看到穿著不時髦的服裝。", "as": "Their efforts to save the failing company proved vain .", "at": "他們試圖挽救這家瀕臨倒閉公司的努力最終證實是徒勞的。", "a": 1}, {"w": "pompous", "p": "adj.", "d": "Self-important and grandiose in manner.", "c": "自負的;浮誇的", "s": "The pompous professor rarely acknowledged any idea but his own.", "t": "這位自負的教授很少承認除了自己以外的任何想法。", "as": "His pompous tone alienated much of the audience.", "at": "他浮誇的語氣讓大部分的觀眾感到疏離。", "a": 1}, {"w": "imperious", "p": "adj.", "d": "Pressing authority upon others; bossy, commanding, and acting like an absolute ruler (Commanding upon).", "c": "專橫的、傲慢的、頤指氣使的", "s": "The staff resented the manager's imperious tone, as she frequently barked commands without offering any explanation.", "t": "員工們很反感經理那頤指氣使的語氣，因為她經常在不提供任何解釋的情況下大聲發號施令。", "as": "With an imperious wave of his hand, the king ordered the guards to remove the protesting diplomats from the room.", "at": "國王專橫地一揮手，命令警衛將抗議的外交官帶出房間。", "a": 1}, {"w": "hubris", "p": "n.", "d": "Excessive pride or self-confidence.", "c": "傲慢;狂妄自大", "s": "His hubris led him to underestimate his opponents.", "t": "他的狂妄自大讓他低估了對手。", "as": "The tragedy explores the fatal consequences of hubris .", "at": "這齣悲劇探討了傲慢帶來的致命後果。", "a": 1}, {"w": "condescending", "p": "adj.", "d": "Characteristic of those who treat others with arrogance.", "c": "居高臨下的/傲慢的", "s": "His condescending tone made the new employees feel unwelcome.", "t": "他居高臨下的語氣讓新進員工感到不受歡迎。", "as": "She hated being spoken to in such a condescending manner.", "at": "她很討厭被人用這種高高在上的方式對待。", "a": 1}, {"w": "grandiose", "p": "adj.", "d": "On a magnificent or exaggerated scale.", "c": "宏偉的/誇大的", "s": "His grandiose plans for the company left investors skeptical.", "t": "他對公司提出的宏大計畫讓投資人心存懷疑。", "as": "The palace's grandiose architecture was designed to impress visiting dignitaries.", "at": "這座宮殿宏偉的建築設計旨在讓來訪的顯要人物印象深刻。", "a": 1}, {"w": "narcissistic", "p": "adj.", "d": "Having an excessive interest in or admiration of oneself.", "c": "自戀的", "s": "The narcissistic actor demanded constant attention from the crew.", "t": "這位自戀的演員要求劇組工作人員時時刻刻關注他。", "as": "Her narcissistic boss took credit for everyone else's work.", "at": "她那自戀的老闆把每個人的功勞都據為己有。", "a": 1}]}, {"unit": 4, "theme": "Dull and Unoriginal", "themeZh": "乏味與陳腐", "antonymLessons": [28], "cards": [{"w": "derivative", "p": "adj.", "d": "Imitating the work of others; lacking originality.", "c": "模仿的；缺乏原創性的", "s": "Although the young architect's first skyscraper attracted attention, critics dismissed it as derivative, pointing out that its bronze-tinted glass curtain walls, exterior bronze I-beams, and open entrance plaza closely reproduced features of the Seagram Building, which Mies van der Rohe had designed half a century earlier.", "t": "雖然這位年輕建築師的第一棟摩天大樓引起了關注，評論家卻認為它缺乏原創性，指出它的古銅色玻璃帷幕牆、外牆的青銅工字樑和開放式入口廣場，幾乎照搬了密斯．凡德羅半個世紀前所設計的西格拉姆大廈的特色。", "as": "Critics who had praised the band's debut dismissed its second album as derivative, complaining that its songs merely recycled the melodies of obscure 1970s groups and that the musicians had grown complacent, even pretentious, after their early acclaim.", "at": "曾稱讚這支樂團首張專輯的評論家，認為他們的第二張專輯缺乏原創，抱怨那些歌曲只是在重複一九七〇年代冷門樂團的旋律，而且團員在早期獲得讚譽後，變得自滿，甚至自命不凡。"}, {"w": "insipid", "p": "adj.", "d": "Lacking flavor, interest, or vigor.", "c": "枯燥乏味的；淡而無味的", "s": "Food scientists discovered that tomatoes bred for uniform color and long shelf life tended to be insipid, because the genetic mutation responsible for even ripening also suppressed the production of the sugars and aromatic compounds that give homegrown varieties their rich flavor.", "t": "食品科學家發現，為了顏色均勻和保存期長而培育的番茄往往淡而無味，因為造成均勻成熟的基因突變，同時也抑制了糖分和芳香化合物的生成，而正是這些物質賦予自家種植品種濃郁的風味。", "as": "Diners found the celebrated chef's newest dish surprisingly insipid; his epicurean reputation could not disguise the fact that the stew was neither savory nor palatable.", "at": "用餐者覺得這位知名主廚的最新菜色出奇地淡而無味；他講究美食的名聲也掩蓋不了這道燉菜既不鮮美也不可口的事實。"}, {"w": "lackluster", "p": "adj.", "d": "Lacking brilliance, energy, or excitement; dull.", "c": "黯淡無光的；平淡乏味的", "s": "Economists attributed the region's lackluster growth during the 1990s to declining investment in education and infrastructure; while neighboring states attracted technology firms and expanded rapidly, its output rose by barely one percent a year for nearly a decade.", "t": "經濟學家把這個地區在一九九〇年代黯淡的成長歸因於教育和基礎建設投資的減少；當鄰近各州吸引科技公司進駐並迅速擴張時，該地區的產出近十年來每年僅勉強成長約百分之一。", "as": "After a lackluster first half, the sluggish team seemed listless and apathetic, but the coach's impassioned halftime speech transformed them into a vibrant, determined squad.", "at": "在表現平平的上半場之後，這支動作遲緩的球隊顯得無精打采、漠不關心，但教練在中場休息時慷慨激昂的演說，讓他們脫胎換骨，成為一支充滿活力、意志堅定的隊伍。"}, {"w": "mundane", "p": "adj.", "d": "Ordinary and everyday; lacking excitement.", "c": "平凡的；世俗的", "s": "Social historians increasingly study mundane records such as grocery receipts, laundry lists, and household account books, arguing that these seemingly unremarkable documents reveal more about how ordinary people actually lived than the speeches of kings or the decrees of governments.", "t": "社會史學家越來越常研究平凡的紀錄，例如雜貨收據、洗衣清單和家庭帳簿，他們認為，這些看似不起眼的文件，比國王的演說或政府的法令更能揭示一般人實際上如何生活。", "as": "The novelist transforms mundane events, such as a trivial argument over breakfast, into moments of profound insight, and her incisive, meticulous prose makes even the most prosaic details seem extraordinary.", "at": "這位小說家能把平凡的事件，例如一場早餐時的瑣碎爭吵，轉化為深刻洞察的時刻；她犀利而一絲不苟的文筆，讓即使最平淡的細節也顯得非比尋常。"}, {"w": "banal", "p": "adj.", "d": "So lacking in originality as to be boring.", "c": "平庸的；陳腐的", "s": "The philosopher Hannah Arendt famously described the evil of the Nazi bureaucrat Adolf Eichmann as banal, observing that he was not a monstrous fanatic but an ordinary, thoughtless official who spoke in clichés and carried out atrocities as routine administrative tasks.", "t": "哲學家漢娜．鄂蘭有一句名言，形容納粹官僚阿道夫．艾希曼的邪惡是平庸的；她觀察到，他並不是一個殘暴的狂熱分子，而是一個平凡、不經思考的官員，滿口陳腔濫調，把暴行當作例行行政工作來執行。", "as": "The commencement speaker's banal advice to 'follow your passion' disappointed the discerning graduates, who had hoped for an erudite, incisive address rather than a series of empty slogans.", "at": "畢業典禮演講者那句「追隨你的熱情」的平庸建議，讓眼光敏銳的畢業生大失所望；他們原本期待一場博學而犀利的演說，而不是一連串空洞的口號。"}, {"w": "platitude", "p": "n.", "d": "A remark used so often it has become meaningless.", "c": "陳腔濫調；老生常談", "s": "After the factory closure eliminated three thousand jobs, residents grew angry when the company's spokesperson offered only the platitude that 'change brings new opportunities,' a statement that provided no concrete information about retraining programs, severance pay, or future employment.", "t": "工廠關閉造成三千人失業後，公司發言人只說了一句「改變帶來新機會」的陳腔濫調，讓居民十分憤怒，因為這句話完全沒有提供任何有關職業再訓練計畫、資遣費或未來就業的具體資訊。", "as": "The politician's speech was a tedious string of platitudes about unity, and its vapid optimism did nothing to mollify voters who were indignant about the precarious economy.", "at": "這位政治人物的演講是一連串關於團結的冗長陳腔濫調，那種空洞的樂觀完全無法安撫因經濟岌岌可危而憤慨的選民。"}, {"w": "vapid", "p": "adj.", "d": "Lacking liveliness, interest, or intellectual substance.", "c": "乏味的；空洞的", "s": "Media scholars argue that algorithm-driven entertainment tends to become vapid, because programs engineered to appeal to the widest possible audience avoid challenging ideas, complex characters, or unfamiliar themes, leaving viewers with pleasant but intellectually empty content.", "t": "媒體學者認為，演算法驅動的娛樂節目往往變得空洞乏味，因為那些為了吸引最廣大觀眾而設計的節目，會避開具挑戰性的想法、複雜的角色或陌生的主題，只留給觀眾愉快卻缺乏思想內涵的內容。", "as": "The talk show's vapid conversations about celebrity fashion seemed frivolous to serious viewers, who longed for the incisive, thought-provoking debates the program had featured in its early, more contentious years.", "at": "這個脫口秀關於名人時尚的空洞對話，在認真的觀眾眼中顯得輕浮無聊；他們懷念節目早期那些犀利、發人深省，而且更具爭議的辯論。"}, {"w": "cliche", "p": "n.", "d": "An overused expression or idea that lacks originality.", "c": "陳腔濫調；老套", "s": "Film critics have noted that the 'mad scientist' who builds a dangerous machine in a remote castle has become such a cliche that contemporary screenwriters either avoid the figure entirely or present it ironically, knowing audiences will immediately recognize its familiar conventions.", "t": "影評人指出，「在偏遠城堡裡打造危險機器的瘋狂科學家」已成為一種老套，因此當代編劇不是完全避開這個角色，就是以反諷的方式呈現，因為他們知道觀眾會立刻認出其中熟悉的套路。", "as": "The novelist cleverly subverts the cliche of the brooding hero, giving her protagonist a jocular wit and an affable charm that render the usual gloomy stereotype obsolete.", "at": "這位小說家巧妙地顛覆了陰鬱英雄的老套形象，賦予她的主角愛說笑的機智與和藹可親的魅力，讓常見的陰沉刻板印象顯得過時。"}, {"w": "hackneyed", "p": "adj.", "d": "Made dull and meaningless through overuse.", "c": "陳腐的；老掉牙的", "s": "Literary agents report receiving hundreds of fantasy manuscripts built on the same hackneyed premise, in which an orphaned farm boy discovers he is the chosen one destined to defeat a dark lord, a plot so familiar that many agents stop reading after the first page.", "t": "文學經紀人表示，他們收到數百份奇幻小說稿件，都建立在同一個老掉牙的前提上：一個成為孤兒的農場男孩發現自己是天選之人，注定要打敗黑暗魔王；這個情節熟悉到許多經紀人讀完第一頁就停下來了。", "as": "The advertising agency rejected the hackneyed slogan as derivative and insipid, demanding instead an ingenious, novel campaign that would distinguish the brand from its competitors and win acclaim from jaded consumers.", "at": "這家廣告公司以缺乏原創又平淡無味為由，否決了那句老掉牙的標語，要求改出一個巧妙新穎的宣傳活動，讓品牌與競爭對手有所區別，並贏得已感厭倦的消費者讚賞。"}, {"w": "prosaic", "p": "adj.", "d": "Lacking imagination or poetic beauty; dull.", "c": "平淡無奇的；乏味的", "s": "Although legends claimed the ancient tunnels had been built to hide royal treasure, archaeologists found a far more prosaic explanation: the passages were simply drainage channels that carried rainwater away from the city's crowded markets and prevented seasonal flooding.", "t": "雖然傳說宣稱這些古老隧道是為了藏匿王室寶藏而建，考古學家卻發現了一個平淡得多的解釋：這些通道只是排水渠道，用來把雨水從城市擁擠的市集排走，防止季節性淹水。", "as": "Readers expecting a thrilling tale of espionage found the memoir disappointingly prosaic, since the former spy devoted most chapters to mundane paperwork rather than the audacious, clandestine missions and covert operations promised on the cover.", "at": "期待一本刺激間諜故事的讀者，發現這本回憶錄平淡得令人失望，因為這位前間諜把大部分章節都花在平凡的文書作業上，而不是封面上承諾的大膽祕密任務和隱密行動。"}, {"w": "trite", "p": "adj.", "d": "Overused and consequently of little importance; stale.", "c": "陳腐的；老套的", "s": "Speechwriters for the new prime minister deliberately avoided trite phrases such as 'a bright future for our children,' believing that voters had grown so weary of empty campaign language that only concrete, specific promises would persuade them to take the speech seriously.", "t": "新任總理的講稿撰寫人刻意避開「為我們的孩子創造光明未來」這類老套的說法，因為他們認為選民早已厭倦空洞的競選語言，只有具體明確的承諾才能讓選民認真看待這篇演說。", "as": "The teacher praised the student's essay for avoiding trite conclusions, noting that its incisive analysis, astute observations, and judicious use of evidence made it far more compelling than the banal summaries most classmates submitted.", "at": "老師稱讚這名學生的文章避開了老套的結論，指出它犀利的分析、精闢的觀察和對證據明智的運用，使它遠比大多數同學交出的平庸摘要更具說服力。"}, {"w": "commonplace", "p": "adj./n.", "d": "Ordinary and unremarkable; a common occurrence or saying.", "c": "平凡的;常見的事", "s": "Smartphones have become so commonplace that few people remember life without them.", "t": "智慧型手機已變得如此普遍,少有人還記得沒有它的生活。", "as": "\"Practice makes perfect\" has become something of a commonplace phrase.", "at": "「熟能生巧」已經成了一句相當常見的說法。", "a": 1}, {"w": "humdrum", "p": "adj.", "d": "Lacking excitement or variety; dull.", "c": "單調乏味的", "s": "She grew tired of her humdrumedaily routine.", "t": "她對自己單調乏味的日常生活感到厭倦。", "as": "The film turned an otherwise humdrum story into something magical.", "at": "這部電影將一個原本平淡無奇的故事轉化成充滿魔力的作品。", "a": 1}, {"w": "pedestrian", "p": "n.", "d": "A person who travels by foot.", "c": "行人", "s": "The new crosswalk was installed to improve safety for pedestrians.", "t": "這座新的斑馬線是為了提升行人的安全而設置的。", "as": "Drivers must always yield to pedestrians at marked crossings.", "at": "駕駛人在標示的行人穿越道上必須永遠禮讓行人。", "a": 1}, {"w": "bland", "p": "adj.", "d": "Lacking strong flavor, interest, or character.", "c": "乏味的;平淡的", "s": "The hospital cafeteria served the same bland menu every single day.", "t": "醫院的自助餐廳每天都供應同樣乏味的菜單。", "as": "Critics called the sequel a bland imitation of the original film.", "at": "評論家批評這部續集是原版電影平淡無味的模仿。", "a": 1}, {"w": "tedious", "p": "adj.", "d": "Too long, slow, or dull; tiresome and monotonous.", "c": "冗長乏味的；單調沉悶的", "s": "Entering handwritten financial records into the electronic database turned out to be a extremely tedious task.", "t": "將手寫的財務記錄輸入電子資料庫，結果證明是一項極其「冗長乏味的（單調沉悶的）」工作。", "as": "", "at": "", "a": 1}, {"w": "monotonous", "p": "adj.", "d": "Dull, repetitive, and lacking variety.", "c": "單調的;乏味的", "s": "The factory job quickly became monotonous and exhausting.", "t": "這份工廠工作很快就變得單調又疲累。", "as": "His monotonous lecture put half the class to sleep.", "at": "他單調乏味的講課讓班上一半的學生都睡著了。", "a": 1}, {"w": "stale", "p": "adj.", "d": "No longer fresh; overused and uninteresting.", "c": "不新鮮的;陳腐的", "s": "The bread had gone stale after sitting out overnight.", "t": "這條麵包放了一整夜後已經不新鮮了。", "as": "Critics found the sequel's jokes stale and repetitive.", "at": "評論家認為這部續集的笑話陳腐又重複。", "a": 1}, {"w": "stereotyped", "p": "adj.", "d": "Conforming to an oversimplified, standardized conception.", "c": "刻板印象化的", "s": "The film was criticized for its stereotyped portrayal of the characters.", "t": "這部電影因對角色進行刻板印象化的描繪而受到批評。", "as": "She refused to accept stereotyped notions about her generation.", "at": "她拒絕接受對她這一代人刻板印象化的觀念。", "a": 1}, {"w": "threadbare", "p": "adj.", "d": "Worn thin from use; overused and unconvincing.", "c": "破舊的;老套的", "s": "He wore a threadbare sweater that had seen better days.", "t": "他穿著一件已經破舊不堪、曾經風光一時的毛衣。", "as": "The defense lawyer's threadbare argument failed to sway the jury.", "at": "這位辯護律師老套的論點未能說服陪審團。", "a": 1}, {"w": "uninspired", "p": "adj.", "d": "Lacking creativity, originality, or enthusiasm.", "c": "缺乏靈感的;平庸的", "s": "Critics called the sequel uninspired and derivative of the original.", "t": "評論家認為這部續集缺乏靈感,只是原作的翻版。", "as": "The team delivered an uninspired performance in the second half.", "at": "這支隊伍在下半場的表現顯得平庸乏味。", "a": 1}]}, {"unit": 5, "theme": "Calming and Soothing", "themeZh": "安撫與緩和", "antonymLessons": [7], "cards": [{"w": "alleviate", "p": "v.", "d": "To make pain, suffering, or a problem less severe.", "c": "減輕；緩和", "s": "To alleviate the chronic water shortages that had forced farmers to abandon their fields, engineers in the Negev Desert developed drip irrigation, a technique that delivers small amounts of water directly to plant roots and dramatically reduces the losses caused by evaporation.", "t": "為了減輕長期缺水迫使農民放棄田地的問題，內蓋夫沙漠的工程師研發出滴灌技術，這種技術能將少量的水直接送到植物根部，大幅減少因蒸發造成的水分流失。", "as": "Relief workers struggled to alleviate the suffering of the emaciated refugees, whose precarious camp lacked ample food, and the benevolent donations of foreign charities arrived only after weeks of delay.", "at": "救援人員努力減輕骨瘦如柴的難民所受的苦難，他們棲身的營地岌岌可危，缺乏充足的食物，而外國慈善機構好心的捐贈，在延誤了好幾週之後才送達。"}, {"w": "ameliorate", "p": "v.", "d": "To make a bad situation better or more tolerable.", "c": "改善；改良", "s": "Nineteenth-century reformers such as Edwin Chadwick sought to ameliorate the appalling living conditions in London's industrial slums by building sewers, supplying clean water, and enforcing sanitation laws, measures that sharply reduced deaths from cholera and typhoid within a generation.", "t": "十九世紀的改革者，例如艾德溫．查德威克，試圖透過興建下水道、供應乾淨的水以及執行衛生法規，來改善倫敦工業貧民窟惡劣的生活條件；這些措施在一個世代內大幅降低了霍亂和傷寒的死亡人數。", "as": "The new governor promised to ameliorate the plight of indigent families, but skeptics noted that her predecessor's similar pledges had proved spurious and that the state's finances remained precarious.", "at": "新任州長承諾要改善貧困家庭的困境，但懷疑者指出，她前任類似的承諾已被證明是空話，而州政府的財政依然岌岌可危。"}, {"w": "appease", "p": "v.", "d": "To calm someone by giving in to their demands.", "c": "安撫；姑息", "s": "In 1938, British Prime Minister Neville Chamberlain hoped to appease Adolf Hitler by allowing Germany to annex part of Czechoslovakia, but the concession only encouraged further aggression, and within a year Europe was at war.", "t": "一九三八年，英國首相張伯倫希望透過允許德國併吞捷克斯洛伐克的部分領土來安撫希特勒，但這項讓步只助長了更多侵略行為，不到一年歐洲便陷入戰爭。", "as": "The cantankerous critic was impossible to appease; he berated the orchestra for its lackluster tempo and dismissed the soloist's virtuoso performance as ostentatious display.", "at": "這位脾氣暴躁的評論家根本無法安撫；他痛斥樂團的速度平淡無力，還把獨奏家精湛的演出貶為賣弄炫技。"}, {"w": "assuage", "p": "v.", "d": "To make an unpleasant feeling less intense.", "c": "緩和；平息（情緒）", "s": "To assuage public fears after the nuclear accident, the government released hourly radiation readings from dozens of monitoring stations, hoping that transparent data would calm residents more effectively than official reassurances, which many citizens no longer trusted.", "t": "為了緩和核災後民眾的恐懼，政府每小時公布數十個監測站的輻射讀數，希望透明的數據能比官方的保證更有效地安撫居民，因為許多民眾已不再信任官方說法。", "as": "The candid apology from the company's chief executive did little to assuage the anger of investors, who remained indignant that their savings had been squandered through such imprudent decisions.", "at": "公司執行長坦率的道歉，幾乎無法平息投資人的怒氣；他們仍對自己的積蓄因如此輕率的決策而被揮霍殆盡感到憤慨。"}, {"w": "conciliate", "p": "v.", "d": "To win over or reconcile through friendly acts.", "c": "安撫；調和；爭取（好感）", "s": "After the bitter civil war, the new president sought to conciliate the defeated rebels by appointing several of their leaders to cabinet posts and granting amnesty to former soldiers, gestures intended to persuade former enemies that they had a future in the united nation.", "t": "在慘烈的內戰之後，新總統試圖撫慰戰敗的叛軍，任命其中幾位領袖擔任內閣職位，並赦免前士兵；這些舉動旨在說服昔日的敵人，讓他們相信自己在統一的國家中仍有未來。", "as": "Hoping to conciliate her belligerent rivals within the party, the prime minister offered them prominent cabinet posts, a magnanimous gesture that gradually eased years of rancorous division.", "at": "為了爭取黨內那些好鬥的對手，首相提供他們重要的內閣職位；這個寬宏大量的舉動逐漸化解了多年來充滿怨恨的分裂。"}, {"w": "mitigate", "p": "v.", "d": "To make something harmful less severe or serious.", "c": "減輕；緩和", "s": "Coastal cities in the Netherlands have built floating homes, storm-surge barriers, and parks designed to absorb excess water, all intended to mitigate the damage that rising sea levels and increasingly powerful storms are expected to cause over the coming century.", "t": "荷蘭的沿海城市興建了漂浮屋、防暴潮屏障和可吸收多餘水量的公園，全都是為了減輕未來一個世紀海平面上升和日益強烈的暴風雨預計將造成的損害。", "as": "Engineers designed the levees to mitigate the effects of flooding, but the unprecedented turbulence of the storm and the detrimental erosion of the riverbanks overwhelmed even these meticulous preparations.", "at": "工程師設計這些堤防是為了減輕洪水的影響，但暴風雨前所未有的劇烈擾動，加上河岸遭受的有害侵蝕，連這些一絲不苟的準備也抵擋不住。"}, {"w": "mollify", "p": "v.", "d": "To soothe the anger or anxiety of someone.", "c": "撫慰；平息（怒氣）", "s": "To mollify the furious passengers whose flight had been delayed overnight, the airline offered hotel vouchers, meal credits, and a full refund, though several travelers insisted that no compensation could make up for missing a family wedding the following morning.", "t": "為了平息航班延誤一整夜的乘客的怒氣，航空公司提供了飯店住宿券、餐點抵用金和全額退款，但仍有幾位旅客堅稱，無論什麼補償都彌補不了他們錯過隔天早上家族婚禮的遺憾。", "as": "Nothing the manager said could mollify the irate customer, whose vociferous complaints about the restaurant's insipid food and the waiter's supercilious attitude echoed through the dining room.", "at": "經理說什麼都無法平息那位暴怒顧客的怒氣，他大聲抱怨餐廳的食物淡而無味、服務生目中無人，聲音響徹整個用餐區。"}, {"w": "pacify", "p": "v.", "d": "To bring peace or calm to someone or something.", "c": "使平靜；平定", "s": "Developmental psychologists have found that rhythmic rocking and low, steady sounds such as a heartbeat can pacifyedistressed infants more quickly than feeding, possibly because these sensations resemble the conditions babies experienced in the womb.", "t": "發展心理學家發現，有節奏的搖晃和低沉穩定的聲音，例如心跳聲，比餵奶更能快速讓不安的嬰兒平靜下來，可能是因為這些感覺與嬰兒在子宮中所經歷的環境相似。", "as": "The colonial governor attempted to pacify the rebellious province with a combination of lavish bribes and threats designed to intimidate local leaders, but these devious tactics only intensified the turmoil.", "at": "殖民地總督企圖以豐厚的賄賂與用來恐嚇地方領袖的威脅雙管齊下，來平定這個叛亂的省分，但這些狡詐的手段只讓動盪更加劇烈。"}, {"w": "allay", "p": "v.", "d": "To reduce or put to rest fear, worry, or suspicion.", "c": "減輕；消除（疑慮）", "s": "To allay parents' concerns about the new vaccine, pediatricians held community meetings at which they explained the results of large clinical trials, described possible side effects honestly, and answered questions until even the most hesitant families felt reassured.", "t": "為了消除家長對新疫苗的疑慮，小兒科醫師舉辦社區說明會，解釋大型臨床試驗的結果，坦白說明可能的副作用，並一一回答問題，直到連最猶豫的家庭也感到安心。", "as": "The central bank's candid statement helped allay investors' fears of an imminent debacle, and the volatile market, after weeks of turbulence, finally began to stabilize.", "at": "央行坦率的聲明幫助消除了投資人對即將發生大崩盤的恐懼，而動盪不安的市場在經歷數週的劇烈波動後，終於開始趨於穩定。"}, {"w": "quell", "p": "v.", "d": "To put an end to something, typically by force.", "c": "鎮壓；平息", "s": "Roman emperors frequently relied on the legions to quell provincial uprisings, and historians estimate that the campaign to crush the Jewish revolt of 66 CE involved more than sixty thousand soldiers and ended with the destruction of Jerusalem's Temple.", "t": "羅馬皇帝經常仰賴軍團鎮壓行省的叛亂；歷史學家估計，西元六十六年鎮壓猶太人起義的戰役動用了超過六萬名士兵，最後以耶路撒冷聖殿被摧毀告終。", "as": "The authorities quelled the riot within hours, but the underlying animosity between the two communities, fueled by years of rancorous disputes, remained an ominous threat to the city's fragile tranquility.", "at": "當局在數小時內平息了暴動，但兩個社群之間因多年充滿怨恨的爭端而助長的潛在敵意，仍是對這座城市脆弱安寧的不祥威脅。"}, {"w": "mediate", "p": "v.", "d": "To act as a go-between to settle a dispute.", "c": "調解；斡旋", "s": "In 1978, President Jimmy Carter invited Egypt's Anwar Sadat and Israel's Menachem Begin to Camp David and spent thirteen days shuttling between their cabins to mediate the negotiations, eventually helping the two former enemies reach a historic peace agreement.", "t": "一九七八年，美國總統卡特邀請埃及總統沙達特和以色列總理比金前往大衛營，花了十三天在兩人的小屋之間來回奔走，居中調解談判，最終協助這兩個昔日敵人達成歷史性的和平協議。", "as": "The retired judge agreed to mediate the contentious dispute between the union and management, and her impartial, judicious approach gradually eased the animosity that had stalled negotiations for months.", "at": "這位退休法官同意居中調解工會與資方之間爭議不斷的糾紛，她公正而明智的做法逐漸化解了讓談判停滯數月的敵意。"}, {"w": "placate", "p": "v.", "d": "To make someone less angry or hostile.", "c": "安撫；使息怒", "s": "Facing mounting protests over rising bread prices, the eighteenth-century French government placated the crowds in Paris by temporarily lowering grain taxes, but the measure did nothing to address the deeper economic inequalities that would erupt into revolution only a few years later.", "t": "面對因麵包價格上漲而日益升高的抗議，十八世紀的法國政府暫時降低穀物稅來安撫巴黎的群眾，但這項措施完全沒有處理更深層的經濟不平等，而這些不平等僅僅幾年後就爆發成大革命。", "as": "Attempting to placate the indignant villagers, the mining company offered a lavish compensation package, but residents remained wary, suspecting the offer was a devious ploy to silence their complaints about polluted water.", "at": "為了安撫憤慨的村民，這家礦業公司提出一份優渥的賠償方案，但居民仍保持警惕，懷疑這項提議是一個狡猾的計謀，目的是讓他們對水源污染的抱怨噤聲。"}, {"w": "soothe", "p": "v.", "d": "To gently calm or comfort.", "c": "安撫;撫慰", "s": "She sang softly to soothe the crying infant.", "t": "她輕聲唱歌來安撫這個哭泣的嬰兒。", "as": "The warm bath helped soothe his sore muscles.", "at": "這場溫水浴有助於舒緩他痠痛的肌肉。", "a": 1}, {"w": "calm", "p": "adj./n.", "d": "Not showing or feeling nervousness or excitement; a state of peace.", "c": "冷靜的;平靜", "s": "She remained remarkably calm throughout the entire emergency.", "t": "在整場緊急事件中,她始終保持出奇的冷靜。", "as": "A sense of calm settled over the village once the storm had passed.", "at": "暴風雨過後,一股平靜的氛圍籠罩了整個村莊。", "a": 1}]}, {"unit": 6, "theme": "Friendly and Sociable", "themeZh": "友善與合群", "antonymLessons": [7], "cards": [{"w": "affable", "p": "adj.", "d": "Friendly, easy to talk to, and approachable.", "c": "和藹可親的；平易近人的", "s": "Although the Nobel laureate was famous for her uncompromising rigor in the laboratory, graduate students who visited her office were surprised to find her affable and unpretentious, happy to chat about their half-finished experiments and quick to put even the most nervous newcomer at ease.", "t": "雖然這位諾貝爾獎得主以在實驗室中毫不妥協的嚴謹著稱，但拜訪她辦公室的研究生卻驚訝地發現她和藹可親、毫不做作，樂於討論他們尚未完成的實驗，也總能很快讓最緊張的新人放鬆下來。", "as": "Unlike his haughty and supercilious predecessor, the new ambassador was affable with local officials, and his willingness to mediate small disputes over coffee did more to placate the restless provinces than any grandiloquent speech.", "at": "與他那傲慢自大、目中無人的前任不同，新任大使對地方官員和藹可親；他願意在喝咖啡時調解小糾紛，這比任何浮誇的演講都更能安撫那些躁動不安的省份。"}, {"w": "congenial", "p": "adj.", "d": "Pleasant and agreeable, especially because suited to one's tastes.", "c": "意氣相投的；宜人的", "s": "After years of isolation at a provincial university, the young philosopher found the Vienna Circle wonderfully congenial: its members shared her enthusiasm for logic and science, welcomed her blunt criticisms, and met each week in a café where ideas were debated with good humor rather than hostility.", "t": "在一所地方大學孤立多年之後，這位年輕哲學家發現維也納學圈與她非常意氣相投：成員們和她一樣熱愛邏輯與科學，歡迎她直率的批評，而且每週在咖啡館聚會，以幽默而非敵意的態度辯論各種想法。", "as": "The congenial atmosphere of the writers' retreat encouraged even the most reticent poets to share their drafts, and the director's pithy, constructive feedback helped them prune verbose passages without any sense of humiliation.", "at": "作家駐村營融洽宜人的氛圍，讓即使是最沉默寡言的詩人也願意分享草稿，而主任精闢且具建設性的回饋，幫助他們刪減冗長的段落，卻絲毫不讓人感到難堪。"}, {"w": "convivial", "p": "adj.", "d": "Friendly and lively, especially when eating and drinking together.", "c": "歡樂的；好交際的", "s": "Historians of the Enlightenment argue that London's coffeehouses were not merely places of refreshment but convivial spaces in which merchants, scientists, and pamphleteers shared tables, swapped gossip over steaming cups, and, amid the laughter and noise, formed the alliances that shaped commercial and intellectual life.", "t": "研究啟蒙運動的歷史學家認為，倫敦的咖啡館不僅是提供飲料的場所，更是歡樂熱鬧的交際空間：商人、科學家和小冊子作者在此同桌而坐，一邊喝著熱騰騰的咖啡一邊交換八卦，並在笑聲與喧鬧中結成了塑造商業與知識生活的同盟。", "as": "Far from the stiff, taciturn banquets of the old court, the new king's feasts were convivial affairs, though critics complained that their ostentatious displays of wealth and the garrulous toasts that lasted past midnight bordered on vulgarity.", "at": "新國王的宴會與舊宮廷那種拘謹沉悶的宴席截然不同，總是歡樂熱鬧；但批評者抱怨，宴會上炫耀財富的浮華排場，以及持續到午夜之後、喋喋不休的祝酒詞，簡直近乎粗俗。"}, {"w": "amicable", "p": "adj.", "d": "Characterized by friendliness and goodwill, without serious disagreement.", "c": "友好的；和睦的", "s": "Although the two research universities had spent a decade quarreling over patent rights to the gene-editing technique, their lawyers eventually negotiated an amicable settlement that divided licensing revenues evenly and allowed scientists from both institutions to resume their once-productive collaboration.", "t": "儘管這兩所研究型大學為了基因編輯技術的專利權爭吵了十年，雙方律師最終仍協商出一份友好的和解協議，平分授權收入，並讓兩校的科學家得以恢復曾經成果豐碩的合作。", "as": "The amicable separation of the two nations, achieved through patient mediation rather than war, helped allay regional fears of violence and showed that even deeply rooted hostility could be ameliorated by skillful diplomacy.", "at": "這兩個國家透過耐心的調停而非戰爭達成友好分離，有助於平息區域內對暴力衝突的恐懼，也證明了即使是根深蒂固的敵意，也能藉由高明的外交手腕加以緩和。"}, {"w": "amiable", "p": "adj.", "d": "Having a pleasant, friendly, and good-natured disposition.", "c": "友善的；和藹的", "s": "Jane Austen's narrator gently mocks Mr. Bingley as almost too amiable: so eager to please everyone and so incapable of suspecting ill intentions in others that his good nature makes him easily manipulated by friends and relatives who hope to steer his romantic choices.", "t": "珍·奧斯汀筆下的敘述者溫和地嘲諷賓利先生近乎過於和善：他太急於討好每個人，又完全不會懷疑別人居心不良，以致他的好脾氣讓他很容易被那些想左右他婚戀選擇的朋友和親戚操縱。", "as": "The amiable host tried to pacify his quarreling guests with a few jokes, but his attempt to mollify them failed when one arrogant critic launched into a long rant about the hackneyed plot of the play they had just seen.", "at": "這位和藹的主人試圖用幾個笑話安撫爭吵不休的賓客，但當一位傲慢的評論家開始滔滔不絕地抨擊他們剛看完那齣戲的陳腐情節時，他平息眾人情緒的努力便宣告失敗。"}, {"w": "cordial", "p": "adj.", "d": "Warm, sincere, and politely friendly.", "c": "熱誠的；友好的", "s": "Despite decades of Cold War rivalry, the 1975 docking of an American Apollo capsule with a Soviet Soyuz spacecraft featured a remarkably cordial exchange: the two commanders shook hands through the open hatch, traded gifts, and shared a meal broadcast to millions of viewers on both sides of the Iron Curtain.", "t": "儘管美蘇之間有數十年的冷戰對抗，1975年美國阿波羅太空艙與蘇聯聯盟號太空船對接時，雙方的互動卻格外熱誠友好：兩位指揮官透過敞開的艙門握手、互贈禮物，並共進一餐，畫面向鐵幕兩側數百萬觀眾播出。", "as": "Although the meeting between the two rival chief executives was cordial, observers noted that their terse replies and reticent body language suggested that the merger talks had not truly assuaged years of bitter competition.", "at": "雖然兩家對手公司執行長的會面氣氛客氣友好，但觀察人士注意到，他們簡短生硬的回答和拘謹保留的肢體語言顯示，合併談判並未真正化解多年來的激烈競爭。"}, {"w": "gregarious", "p": "adj.", "d": "Fond of company; sociable and outgoing.", "c": "愛交際的；合群的", "s": "Psychologists have found that gregarious people, who seek out crowded parties and strike up conversations with strangers on trains, tend to report higher daily happiness, yet even naturally introverted participants felt happier when instructed to behave more sociably for a week.", "t": "心理學家發現，喜歡參加熱鬧派對、會在火車上主動與陌生人攀談的愛交際者，往往表示日常幸福感較高；然而，即使是天生內向的受試者，在被要求連續一週表現得更外向合群之後，也感到更快樂。", "as": "The gregarious senator could charm almost anyone at a fundraiser, but his loquacious speeches and colloquial jokes struck some voters as pretentious attempts to seem like an ordinary citizen rather than sincere expressions of his character.", "at": "這位愛交際的參議員在募款餐會上幾乎能迷住任何人，但他滔滔不絕的演講和口語化的笑話，在部分選民眼中只是刻意裝成普通市民的做作之舉，而非真誠展現其性格。"}, {"w": "levity", "p": "n.", "d": "Humor or lightheartedness, especially at a serious moment.", "c": "輕鬆幽默；輕浮", "s": "Abraham Lincoln was often criticized for telling jokes during the darkest months of the Civil War, but he defended his levity as a necessity, explaining to grieving colleagues that without occasional laughter the strain of so much bloodshed would have broken him entirely.", "t": "亞伯拉罕·林肯常因在南北戰爭最黑暗的幾個月裡講笑話而受到批評，但他辯稱這種輕鬆幽默是必要的，並向悲痛的同僚解釋，若沒有偶爾的笑聲，如此多流血犧牲帶來的壓力早已將他徹底擊垮。", "as": "A moment of levity during the tense negotiations helped mitigate the hostility in the room: when the weary mediator made a self-deprecating joke, even the most taciturn delegates laughed, and that brief laughter appeased tempers enough for the talks to resume.", "at": "緊張談判中的片刻輕鬆幽默，有助於緩和會場裡的敵意：當疲憊的調解人說了個自嘲的笑話時，連最沉默寡言的代表也笑了出來，而這短暫的笑聲平息了眾人的怒氣，讓談判得以繼續進行。"}, {"w": "jocular", "p": "adj.", "d": "Fond of joking; humorous or playful in manner.", "c": "詼諧的；愛開玩笑的", "s": "Darwin's private letters to his botanist friend Joseph Hooker are surprisingly jocular, full of good-natured teasing, mock complaints about the barnacles he spent eight years dissecting, and playful exaggerations—a lighthearted tone that contrasts sharply with the cautious, carefully hedged prose of On the Origin of Species.", "t": "達爾文寫給植物學家友人約瑟夫·胡克的私人信件出奇地詼諧，充滿善意的調侃、對他花了八年解剖的藤壺所發的假意抱怨，以及俏皮的誇飾——這種輕鬆的語氣與《物種起源》中謹慎、措辭保留的文字形成強烈對比。", "as": "The professor's jocular asides kept his lectures lively, but students noticed that his humor never caused him to digress: each joke was succinct, pointed, and designed to make an otherwise prosaic concept in thermodynamics memorable.", "at": "這位教授詼諧的插話讓他的課生動活潑，但學生注意到他的幽默從不使他離題：每個笑話都簡潔扼要、一針見血，目的是讓熱力學中原本平淡無奇的概念令人印象深刻。"}, {"w": "genial", "p": "adj.", "d": "Friendly, affable.", "c": "和藹的/親切的", "s": "The genial host made every guest feel instantly welcome.", "t": "這位和藹可親的主人讓每位賓客都立刻感到賓至如歸。", "as": "Despite his intimidating size, he had a genial smile that put people at ease.", "at": "儘管體型嚇人,他親切的笑容卻讓人感到放鬆。", "a": 1}, {"w": "companionable", "p": "adj.", "d": "Friendly and sociable; pleasant to be with.", "c": "友好隨和的;易相處的", "s": "Their companionable silence during the long drive was more comfortable than conversation.", "t": "他們在漫長車程中友好而自在的沉默,比交談更讓人感到自在。", "as": "The old dog was companionable and gentle with every visitor.", "at": "這隻老狗對每位訪客都溫和又易相處。", "a": 1}, {"w": "gracious", "p": "adj.", "d": "Courteous, kind, and pleasant, especially to a subordinate.", "c": "親切的;有禮的", "s": "Our gracious host made sure every guest felt welcome.", "t": "我們親切的主人確保每位賓客都感到賓至如歸。", "as": "She gave a gracious acceptance speech after winning the award.", "at": "她在獲獎後發表了一段有禮得體的獲獎感言。", "a": 1}, {"w": "hospitable", "p": "adj.", "d": "Friendly and welcoming to guests or strangers.", "c": "好客的;殷勤的", "s": "The small village was known for being remarkably hospitable .", "t": "這座小村莊以出奇的好客聞名。", "as": "Their hospitable home always had room for one more guest.", "at": "他們好客的家總是有多餘的空間招待客人。", "a": 1}, {"w": "courteous", "p": "adj.", "d": "Polite and considerate in manner.", "c": "有禮貌的;謙恭的", "s": "The courteous waiter refilled our water without being asked.", "t": "這位有禮貌的服務生沒等我們開口就幫忙加水。", "as": "She remained courteous even when the customer was rude.", "at": "即使顧客很無禮,她仍保持謙恭有禮。", "a": 1}, {"w": "urbane", "p": "adj.", "d": "Polished, witty: (anti: diatribe).", "c": "溫文爾雅的/都市化的", "s": "The host greeted every guest with an urbane smile and a witty remark.", "t": "主人以溫文爾雅的微笑和機智的言談迎接每一位賓客。", "as": "His urbane manner made him popular at every diplomatic event.", "at": "他溫文有禮的舉止讓他在每場外交場合都廣受歡迎。", "a": 1}, {"w": "sociable", "p": "adj.", "d": "Friendly and enjoying the company of others.", "c": "善於社交的;親切的", "s": "He was sociable and quickly made friends at the new office.", "t": "他善於社交,很快就在新辦公室裡交到了朋友。", "as": "The retreat encouraged sociable activities like group hikes.", "at": "這場靜修活動鼓勵團體健行等社交活動。", "a": 1}, {"w": "camaraderie", "p": "n.", "d": "Brotherhood, jovial unity.", "c": "同志情誼/友愛", "s": "The long road trip built a strong sense of camaraderie among the teammates.", "t": "這趟長途旅行讓隊友之間培養出深厚的同志情誼。", "as": "There was a real camaraderie among the soldiers who had served together for years.", "at": "這些一起服役多年的士兵之間有著真摯的袍澤情誼。", "a": 1}]}, {"unit": 7, "theme": "Hostile and Argumentative", "themeZh": "敵意與好鬥", "antonymLessons": [5, 6], "cards": [{"w": "antagonism", "p": "n.", "d": "Active hostility or opposition between people or groups.", "c": "敵對；對抗", "s": "The long-standing antagonism between Thomas Edison and George Westinghouse during the so-called War of the Currents led Edison's allies to stage public demonstrations in which animals were electrocuted with alternating current, a grim publicity campaign intended to convince Americans that his rival's system was lethally dangerous.", "t": "在所謂的「電流之戰」期間，湯瑪斯·愛迪生與喬治·威斯汀豪斯之間長期的敵對，導致愛迪生的盟友公開示範以交流電電死動物，這場殘酷的宣傳活動意在讓美國人相信對手的系統具有致命危險。", "as": "The antagonism between the two schools of economists was so entrenched that every conference became a contest of grandiloquent rhetoric, and only an affable moderator with a gift for amicable compromise could keep the debates civil.", "at": "這兩派經濟學家之間的對立根深蒂固，每次研討會都淪為浮誇言辭的較勁，只有一位和藹可親、善於促成友好妥協的主持人，才能讓辯論保持文明。"}, {"w": "contentious", "p": "adj.", "d": "Causing or likely to cause heated argument.", "c": "引起爭議的；好爭論的", "s": "The ownership of the Parthenon sculptures, removed by Lord Elgin in the early 1800s, remains one of the most contentious issues in cultural heritage law, pitting Greek officials who demand their return against British Museum trustees who insist the marbles were legally acquired.", "t": "埃爾金勳爵於十九世紀初移走的帕德嫩神廟雕塑，其所有權至今仍是文化遺產法中最具爭議的問題之一，一邊是要求歸還的希臘官員，另一邊則是堅稱這些大理石雕像乃合法取得的大英博物館董事。", "as": "In a contentious town hall meeting, residents who opposed the new highway delivered a voluble stream of objections, while the mayor tried in vain to placate them with banal assurances that the project would benefit everyone.", "at": "在一場爭論激烈的市民大會上，反對新公路的居民滔滔不絕地提出一連串異議，而市長則試圖用陳腔濫調的保證來安撫他們，聲稱這項工程將造福所有人，卻徒勞無功。"}, {"w": "disputatious", "p": "adj.", "d": "Fond of arguing; inclined to dispute.", "c": "好辯的；愛爭論的", "s": "Samuel Johnson's companions often noted that he was so disputatious in conversation that he would happily defend a position he did not actually believe, simply for the pleasure of contradicting whoever was speaking and overpowering his opponents with sheer force of wit and erudition.", "t": "山繆·約翰生的友人常提到，他在交談中極為好辯，甚至樂於為自己其實並不相信的立場辯護，只為了享受反駁眼前說話者的樂趣，並以純粹的機智與淵博學識壓倒對手。", "as": "The disputatious philosopher would seize on any platitude a student uttered and dismantle it with pithy counterarguments, yet his disdainful tone made even his most cogent objections seem arrogant rather than enlightening.", "at": "這位好辯的哲學家會抓住學生說出的任何陳腔濫調，用精闢的反駁將其逐一拆解；然而他輕蔑的語氣，卻使他最有說服力的反對意見也顯得傲慢自大，而非發人深省。"}, {"w": "predator", "p": "n.", "d": "An animal or person that preys on or exploits others.", "c": "掠食者；掠奪者", "s": "Regulators warned that payday lenders operating near military bases had become financial predators, deliberately targeting young enlisted soldiers with loans whose annual interest rates exceeded 300 percent and trapping many borrowers in cycles of debt they could not escape.", "t": "監管機關警告，在軍事基地附近營業的發薪日貸款業者已成為金融掠奪者，刻意鎖定年輕的入伍士兵，提供年利率超過百分之三百的貸款，使許多借款人陷入無法脫身的債務循環。", "as": "Documentaries often portray the shark as a ruthless predator, but marine biologists argue that such hackneyed images are derivative of Hollywood thrillers and that this banal stereotype hampers conservation efforts for species that are now critically endangered.", "at": "紀錄片常把鯊魚描繪成冷酷無情的掠食者，但海洋生物學家認為，這類老套的形象只是仿效好萊塢驚悚片，而這種陳腐的刻板印象阻礙了對如今已極度瀕危物種的保育工作。"}, {"w": "animosity", "p": "n.", "d": "Strong dislike or hostility toward someone.", "c": "敵意；仇恨", "s": "The bitter animosity between Isaac Newton and Gottfried Leibniz over who had invented calculus lasted until Leibniz's death in 1716, and Newton, then president of the Royal Society, secretly wrote much of the supposedly impartial committee report that accused his rival of plagiarism.", "t": "艾薩克·牛頓與哥特佛萊德·萊布尼茲之間為了誰發明微積分而產生的強烈敵意，一直持續到萊布尼茲於1716年去世為止；當時身為皇家學會會長的牛頓，還暗中撰寫了那份號稱公正、指控對手剽竊的委員會報告的大部分內容。", "as": "Years of animosity between the rival architects had poisoned their professional relationship, so when one publicly called the other's design hackneyed and insipid, no amount of cordial diplomacy could pacify him.", "at": "兩位互相較勁的建築師多年來的敵意早已毒害了彼此的專業關係，因此當其中一人公開批評對方的設計陳腐乏味時，無論多麼客氣友好的斡旋都無法平息對方的怒氣。"}, {"w": "captious", "p": "adj.", "d": "Inclined to find fault or raise petty objections.", "c": "吹毛求疵的；挑剔的", "s": "The peer reviewer's report was so captious that the authors struggled to take it seriously: rather than addressing the study's central methodology, it devoted three pages to complaints about comma placement, the font used in one figure, and the order in which references were listed.", "t": "那位同儕審查者的報告極為吹毛求疵，作者們實在很難認真看待：報告沒有討論這項研究的核心方法，反而花了三頁篇幅抱怨逗號位置、其中一張圖使用的字型，以及參考文獻的排列順序。", "as": "The captious critic dismissed the novel's eloquence as mere ornament and complained that its dialogue was too colloquial, yet readers found his own reviews far more trite than anything he claimed to despise.", "at": "這位吹毛求疵的評論家把這部小說的優美文筆貶為純粹的裝飾，還抱怨其對白太過口語化，然而讀者卻覺得他自己的書評遠比他聲稱厭惡的任何東西都更加陳腐。"}, {"w": "belligerent", "p": "adj.", "d": "Hostile, aggressive, and eager to fight.", "c": "好戰的；挑釁的", "s": "Diplomatic historians note that Kaiser Wilhelm II's belligerent speeches, including his notorious urging that German troops sent to China behave like the Huns of Attila, alarmed British leaders and helped convince them that Germany's expanding navy was intended for aggression rather than defense.", "t": "外交史學家指出，德皇威廉二世好戰的演說——包括他惡名昭彰地鼓吹派往中國的德軍要像阿提拉的匈人一樣行事——令英國領導人深感不安，並使他們相信德國不斷擴張的海軍是為了侵略而非防禦。", "as": "Rather than conciliate his critics, the belligerent commander issued a contemptuous statement mocking their concerns, a haughty response that only intensified public outrage and made a negotiated peace seem even more remote.", "at": "這位好戰的指揮官非但沒有安撫批評者，反而發表了一份輕蔑的聲明嘲弄他們的憂慮；這種傲慢的回應只讓民眾的憤怒更加高漲，也讓透過談判實現和平的希望顯得更加渺茫。"}, {"w": "pugnacious", "p": "adj.", "d": "Eager or quick to argue, quarrel, or fight.", "c": "好鬥的；愛挑釁的", "s": "Known for his pugnacious temperament, the nineteenth-century anatomist Thomas Henry Huxley relished public confrontations so much that he earned the nickname 'Darwin's Bulldog,' famously clashing with Bishop Samuel Wilberforce at the 1860 Oxford debate over evolution.", "t": "十九世紀解剖學家湯瑪斯·亨利·赫胥黎以好鬥的性格聞名，他非常熱衷於公開交鋒，因而贏得「達爾文的鬥牛犬」這個綽號；他在1860年牛津的演化論辯論中與山繆·威爾伯福斯主教激烈交鋒，此事廣為人知。", "as": "The pugnacious talk-show host loved to swagger across the stage and rant at his guests, but his insolent interruptions and constant personal attacks eventually alienated even loyal viewers who had once admired his bluntness.", "at": "這位好鬥的脫口秀主持人喜歡在臺上大搖大擺地走來走去，對著來賓高聲咆哮，但他無禮的插話與不斷的人身攻擊，最終連那些曾經欣賞他直率作風的忠實觀眾也疏遠了。"}, {"w": "bellicose", "p": "adj.", "d": "Eager to fight or go to war; aggressive.", "c": "好戰的；尚武的", "s": "Historians argue that the bellicose rhetoric of newspapers owned by William Randolph Hearst, which published lurid and often exaggerated stories about Spanish atrocities in Cuba, helped push a hesitant American public toward war with Spain in 1898.", "t": "歷史學家認為，威廉·藍道夫·赫斯特旗下報紙那些好戰的言論——大量刊登聳人聽聞、往往誇大其詞的西班牙在古巴暴行報導——促使原本猶豫不決的美國民眾在1898年走向對西班牙的戰爭。", "as": "The general's bellicose speeches were long on grandiloquent threats but short on strategy, and diplomats hoped that quiet mediation could allay the fears of neighboring states before his pretentious bluster provoked an actual war.", "at": "這位將軍好戰的演說充滿浮誇的威脅，卻缺乏實際戰略；外交官們希望在他那做作的虛張聲勢真正引發戰爭之前，能透過低調的調停來消除鄰國的疑懼。"}, {"w": "cantankerous", "p": "adj.", "d": "Bad-tempered, argumentative, and difficult to deal with.", "c": "脾氣暴躁的；難相處的", "s": "By the end of his career, the once-celebrated astronomer had grown so cantankerous that younger colleagues avoided the observatory dining hall, knowing that any casual remark about the weather, the telescope schedule, or university politics might provoke an irritable twenty-minute lecture on everyone else's incompetence.", "t": "到了職業生涯末期，這位曾經備受讚譽的天文學家變得脾氣極為暴躁，年輕同事們都避開天文台的餐廳，因為他們知道，任何關於天氣、望遠鏡排程或大學政治的隨口一提，都可能引來他一場長達二十分鐘、怒氣沖沖地數落別人無能的訓話。", "as": "The cantankerous old editor was notoriously taciturn with strangers, but when a young writer submitted a verbose, hackneyed manuscript, he responded with a terse note that simply read, 'Cut everything you love.'", "at": "這位脾氣暴躁的老編輯以對陌生人沉默寡言出了名，但當一位年輕作家交來一份冗長又陳腐的稿件時，他回了一張簡短生硬的紙條，上面只寫著：「把你所有心愛的段落全刪了。」"}, {"w": "polemical", "p": "adj.", "d": "Strongly critical or argumentative in writing or speech.", "c": "論戰的；爭論性的", "s": "Thomas Paine's Common Sense was openly polemical, attacking the very idea of hereditary monarchy as absurd and ridiculing King George III as a 'royal brute,' and its fierce, combative style helped convert thousands of hesitant colonists to the cause of independence in 1776.", "t": "湯瑪斯·潘恩的《常識》具有鮮明的論戰色彩，抨擊世襲君主制本身荒謬可笑，並嘲諷英王喬治三世為「皇家野獸」；其猛烈好鬥的文風，在1776年促使數以千計猶豫不決的殖民地居民轉而支持獨立大業。", "as": "Her polemical essay attacked the complacent assumptions of mainstream economists, but critics argued that its sweeping claims were too diffuse to persuade anyone not already inclined to agree, and that its rhetorical flourishes obscured her evidence.", "at": "她那篇論戰性的文章抨擊主流經濟學家自滿的假設，但批評者認為，文中籠統的主張太過散漫，無法說服原本就不傾向認同的人，而且修辭上的華麗詞藻也掩蓋了她的論證依據。"}, {"w": "truculent", "p": "adj.", "d": "Ready to fight, cruel.", "c": "好鬥的/兇暴的", "s": "The truculent customer began shouting at the staff over a minor mistake.", "t": "這位好鬥的顧客因為一個小失誤而對員工大聲咆哮。", "as": "His truculent tone made it clear he was ready for a confrontation.", "at": "他兇狠的語氣清楚表明他已準備好要對抗到底。", "a": 1}, {"w": "antagonistic", "p": "adj.", "d": "Showing hostility or opposition.", "c": "敵對的/對抗性的", "s": "His antagonistic behavior created tension at work.", "t": "他充滿敵意的行為在職場上造成了緊張氣氛。", "as": "The two rival companies have maintained an antagonistic relationship for years.", "at": "這兩家競爭公司多年來一直維持著敵對的關係。", "a": 1}, {"w": "militant", "p": "adj./n.", "d": "Combative and aggressive in support of a cause.", "c": "好戰的;激進分子", "s": "The group's militant tactics alarmed even its own supporters.", "t": "這個團體激進好戰的策略甚至讓自己的支持者也感到不安。", "as": "A militant faction broke away to pursue more aggressive protests.", "at": "一個激進派系分裂出去,追求更為激烈的抗爭手段。", "a": 1}, {"w": "acrimonious", "p": "adj.", "d": "Bitter.", "c": "嚴厲的/辛辣的", "s": "The couple went through an acrimoniousedivorce that lasted nearly two years.", "t": "這對夫妻經歷了一場長達近兩年、爭執激烈的離婚訴訟。", "as": "The meeting became acrimonious when the two managers began shouting at each other.", "at": "當兩位經理開始互相大吼時,這場會議變得劍拔弩張。", "a": 1}, {"w": "fractious", "p": "adj.", "d": "Quarrelsome.", "c": "易怒的/好爭吵的", "s": "The fractious committee could not agree on even the simplest issues.", "t": "這個易於爭吵的委員會連最簡單的議題都無法達成共識。", "as": "The toddler grew fractious after missing his afternoon nap.", "at": "這個小孩因為錯過午睡而變得易怒難纏。", "a": 1}, {"w": "vitriolic", "p": "adj.", "d": "Biting, burning.", "c": "刻薄的/惡意的", "s": "The critic wrote a vitriolic review that devastated the young author.", "t": "這位評論家寫了一篇尖酸刻薄的評論,讓這位年輕作家深受打擊。", "as": "Her vitriolic comments online sparked a heated backlash.", "at": "她在網路上刻薄的言論引發了強烈的反彈。", "a": 1}]}, {"unit": 8, "theme": "Generosity and Extravagance", "themeZh": "慷慨與揮霍", "antonymLessons": [9], "cards": [{"w": "prodigal", "p": "adj.", "d": "Spending money or resources wastefully and recklessly.", "c": "揮霍的；浪費的", "s": "The Spanish crown's prodigal use of the silver shipped from Potosí during the sixteenth century, spent on endless wars and extravagant court ceremonies rather than on domestic industry, helps explain why Spain repeatedly declared bankruptcy despite controlling one of the richest mines in history.", "t": "十六世紀時，西班牙王室揮霍從波托西運回的白銀，將其花在連綿不斷的戰爭和奢華的宮廷儀式上，而非發展本國產業，這有助於解釋為何西班牙雖然掌控著史上最富饒的銀礦之一，卻仍一再宣告破產。", "as": "The prodigal heir mocked his father's careful habits, yet after years of ostentatious parties and pretentious art purchases, he was forced to appease his creditors by selling the family estate.", "at": "這位揮霍無度的繼承人嘲笑父親謹慎持家的習慣，然而在多年舉辦浮華派對、購買附庸風雅的藝術品之後，他不得不變賣家族莊園來安撫債主。"}, {"w": "altruistic", "p": "adj.", "d": "Showing selfless concern for the well-being of others.", "c": "利他的；無私的", "s": "Biologists long puzzled over the altruistic behavior of vampire bats, which regurgitate blood meals to feed hungry roostmates that would otherwise starve, until field studies revealed that individuals who share food are more likely to receive help themselves when they fail to find prey.", "t": "生物學家長久以來對吸血蝙蝠的利他行為感到不解：牠們會反芻吸食到的血液，餵養原本會餓死的飢餓同伴；直到野外研究揭示，願意分享食物的個體在自己覓食失敗時，也更有可能得到幫助。", "as": "Although the billionaire described her donation as purely altruistic, skeptics pointed to the ostentatious press conference, the egotistical speech that accompanied it, and the pretentious gold plaque bearing her name as evidence that vanity, not generosity, was her true motive.", "at": "雖然這位億萬富翁形容她的捐款完全出於無私，但懷疑者指出那場浮華的記者會、伴隨而來的自我吹捧演說，以及刻有她名字的俗麗金色牌匾，認為這些都證明她真正的動機是虛榮而非慷慨。"}, {"w": "magnanimous", "p": "adj.", "d": "Generous and forgiving, especially toward a rival or enemy.", "c": "寬宏大量的；寬大的", "s": "Rather than humiliating the defeated Confederate soldiers at Appomattox in 1865, Ulysses S. Grant was remarkably magnanimous, allowing them to keep their horses for spring planting and ordering his own troops to share rations with their starving former enemies.", "t": "1865年在阿波馬托克斯，尤利西斯·格蘭特並未羞辱戰敗的南方邦聯士兵，反而展現了非凡的寬宏大量：他允許他們保留馬匹以便春耕，並下令自己的部隊與這些飢腸轆轆的昔日敵人分享口糧。", "as": "The magnanimous debate champion refused to swagger after her victory; instead she offered her defeated rival a cordial embrace and praised her opponent's eloquence in a speech so gracious that it seemed to mollify even the most partisan fans.", "at": "這位寬宏大量的辯論冠軍在勝利後並未趾高氣揚，而是給了落敗的對手一個熱情的擁抱，並在演說中讚揚對方的雄辯口才；她的言辭如此得體，似乎連最偏激的支持者都被安撫下來。"}, {"w": "munificent", "p": "adj.", "d": "Extremely generous in giving money or gifts.", "c": "慷慨的；大方的", "s": "Andrew Carnegie's munificent funding of public libraries—more than 2,500 buildings constructed across the English-speaking world between 1883 and 1929—transformed access to books in small towns that had never before been able to afford a collection open to ordinary readers.", "t": "安德魯·卡內基慷慨捐助公共圖書館——1883年至1929年間在英語世界興建了兩千五百多座——徹底改變了小城鎮取得書籍的管道，這些城鎮過去從未負擔得起一座向一般讀者開放的藏書館。", "as": "The munificent endowment from the anonymous donor did much to alleviate the university's budget crisis, though some faculty were wary of the reticent benefactor's motives and worried that the gift might quell open debate about how research is funded.", "at": "這筆來自匿名捐贈者的豐厚捐款大大緩解了大學的預算危機，不過部分教職員對這位低調寡言的捐助者動機有所提防，並擔心這份贈禮可能會壓制有關研究經費來源的公開討論。"}, {"w": "benevolent", "p": "adj.", "d": "Kind and well-meaning; eager to help others.", "c": "仁慈的；慈善的", "s": "The nineteenth-century mill owner Robert Owen considered himself a benevolent employer: at his textile factory in New Lanark he refused to hire young children, opened one of Britain's first infant schools, and provided his workers with affordable housing, medical care, and evening classes.", "t": "十九世紀的紡織廠主羅伯特·歐文自認是一位仁慈的雇主：他在新拉納克的紡織廠拒絕雇用年幼的孩童，開辦了英國最早的幼兒學校之一，並為工人提供平價住宅、醫療照護和夜間課程。", "as": "The benevolent queen tried to ameliorate the suffering of her poorest subjects, but her haughty ministers dismissed such reforms with disdainful remarks, and their supercilious attitude eventually provoked a popular uprising.", "at": "這位仁慈的女王試圖改善最貧困子民的苦難，但她那些傲慢的大臣卻以輕蔑的言論駁斥這些改革，而他們目中無人的態度最終激起了民眾起義。"}, {"w": "largess", "p": "n.", "d": "Generous giving of money or gifts to others.", "c": "慷慨贈與；慷慨", "s": "Roman emperors cultivated popularity through public largess, distributing free grain to hundreds of thousands of citizens and funding spectacular gladiatorial games—a strategy the satirist Juvenal mocked as 'bread and circuses,' arguing that it kept the populace content while stripping it of political power.", "t": "羅馬皇帝透過公開的慷慨施予來博取民心，向數十萬公民發放免費穀物，並資助壯觀的角鬥士競技——諷刺作家尤維納利斯譏之為「麵包與馬戲」，認為這種手段讓民眾心滿意足，卻剝奪了他們的政治權力。", "as": "The tycoon's largess was legendary, but his ostentatious charity galas and grandiloquent speeches about civic duty struck many observers as a calculated way to placate critics of his company's labor practices.", "at": "這位大亨的慷慨贈與堪稱傳奇，但他浮華的慈善晚宴和關於公民責任的浮誇演說，在許多觀察者看來，只是為了安撫那些批評其公司勞工政策的人而精心盤算的手段。"}, {"w": "lavish", "p": "adj.", "d": "Extremely generous or extravagant in giving or spending.", "c": "慷慨的；奢華的", "s": "Critics of the 2014 Winter Olympics in Sochi pointed to the lavish spending on the games—an estimated fifty billion dollars, much of it devoted to roads, stadiums, and luxury hotels that now sit largely empty—as evidence that the event served political prestige more than athletics.", "t": "2014年索契冬季奧運的批評者指出，這屆奧運的花費極其奢華——估計高達五百億美元，大部分用於興建如今大多閒置的道路、體育場和豪華飯店——證明這場盛會服務政治聲望的成分多過服務體育。", "as": "The director praised her cast with lavish compliments, but critics found the film itself lackluster, its dialogue full of trite sentiments and its plot so derivative that it seemed assembled from scraps of older movies.", "at": "導演對演員們讚不絕口，但影評人卻認為這部電影本身平淡乏味，對白充滿陳腐的情感，情節更是毫無新意，彷彿是用舊電影的片段拼湊而成的。"}, {"w": "philanthropic", "p": "adj.", "d": "Seeking to promote others' welfare through generous donations.", "c": "慈善的；博愛的", "s": "John D. Rockefeller's philanthropic campaign against hookworm in the American South, launched in 1909, funded free testing, treatment, and sanitation programs for hundreds of thousands of people and is now regarded as a model for modern public-health initiatives.", "t": "約翰·洛克斐勒於1909年在美國南方發起的慈善防治鉤蟲運動，資助數十萬人接受免費檢驗、治療與衛生改善計畫，如今被視為現代公共衛生倡議的典範。", "as": "The philanthropic foundation tried to mitigate the effects of the drought, but its well-meaning director was criticized for issuing verbose reports and banal press releases instead of delivering food quickly to the villages most affected.", "at": "這個慈善基金會試圖減輕乾旱帶來的衝擊，但其立意良善的負責人卻因只發表冗長的報告和陳腔濫調的新聞稿，而非迅速將糧食送往受災最嚴重的村莊，而遭到批評。"}, {"w": "squander", "p": "v.", "d": "To waste money, time, or opportunities carelessly.", "c": "揮霍；浪費", "s": "Economists who study resource-rich nations describe a 'resource curse' in which governments squander windfall oil revenues on prestige projects and political patronage rather than investing in education and infrastructure, leaving their economies dangerously dependent on a single commodity whose price can collapse overnight.", "t": "研究資源豐富國家的經濟學家描述了一種「資源詛咒」：政府把意外得來的石油收入揮霍在面子工程和政治酬庸上，而非投資於教育與基礎建設，導致經濟危險地依賴單一商品，而該商品的價格可能一夜之間崩跌。", "as": "The team squandered a twenty-point lead, and the coach's terse postgame comments did little to assuage angry fans, who found his platitudes about 'learning from adversity' as insipid as the team's second-half performance.", "at": "球隊揮霍掉二十分的領先優勢，而教練賽後簡短生硬的評論也幾乎無法平息球迷的怒氣；球迷覺得他那些「從逆境中學習」的陳腔濫調，就跟球隊下半場的表現一樣乏味。"}, {"w": "bountiful", "p": "adj.", "d": "Abundant; giving generously.", "c": "豐盛的;慷慨的", "s": "The farmers celebrated an unusually bountiful harvest this year.", "t": "農民們慶祝今年異常豐盛的收成。", "as": "Their host was bountiful with both food and hospitality.", "at": "他們的主人在食物和待客之道上都十分大方。", "a": 1}, {"w": "profligate", "p": "adj.", "d": "Wasteful: (anti:frugal=economical=stingy).", "c": "揮霍的/放蕩的", "s": "His profligate spending habits left him deeply in debt within a few years.", "t": "他揮霍無度的消費習慣讓他在幾年內就債台高築。", "as": "The company was criticized for its profligate use of shareholder funds.", "at": "這家公司因揮霍股東資金而受到批評。", "a": 1}, {"w": "spendthrift", "p": "n./adj.", "d": "A person who spends money extravagantly or wastefully.", "c": "揮霍者;揮霍無度的", "s": "His family worried he was becoming a spendthrift after the inheritance.", "t": "他的家人擔心他繼承這筆遺產後會變成一個揮霍者。", "as": "The spendthrift habits of the previous manager left the department in debt.", "at": "前任經理揮霍無度的習慣讓這個部門陷入了債務。", "a": 1}, {"w": "extravagant", "p": "adj.", "d": "Spending or using much more than is necessary, reasonable, or affordable.", "c": "奢侈的；鋪張的；過度的", "s": "The billionaire's extravagant lifestyle eventually drove him into bankruptcy.", "t": "這位億萬富翁奢侈的生活方式最終使他破產。", "as": "The critic called the film's costly effects an extravagant waste of the studio's budget.", "at": "影評人稱電影昂貴的特效是對製片廠預算的過度浪費。", "a": 1}, {"w": "liberal", "p": "adj./n.", "d": "Open to new behavior or opinions; generous.", "c": "自由派的;慷慨的", "s": "The university encouraged liberaledebate on controversial topics.", "t": "這所大學鼓勵學生針對爭議話題進行自由開放的辯論。", "as": "He was known for his liberaledonations to local charities.", "at": "他以慷慨捐助當地慈善機構聞名。", "a": 1}, {"w": "generous", "p": "adj.", "d": "Showing readiness to give freely; ample.", "c": "慷慨的;豐厚的", "s": "Her generousedonation funded the entire scholarship program.", "t": "她慷慨的捐款資助了整個獎學金計畫。", "as": "The restaurant serves generous portions at every meal.", "at": "這家餐廳每一餐都提供豐盛的份量。", "a": 1}]}, {"unit": 9, "theme": "Stinginess and Thrift", "themeZh": "吝嗇與節儉", "antonymLessons": [8], "cards": [{"w": "frugal", "p": "adj.", "d": "Careful and sparing in spending money or using resources.", "c": "節儉的；儉樸的", "s": "Benjamin Franklin's Poor Richard's Almanack urged colonial readers to be frugal, filling its pages with maxims such as 'A penny saved is two pence clear,' and Franklin himself claimed that careful economy in his youth had allowed him to retire from printing at forty-two.", "t": "班傑明·富蘭克林的《窮理查年鑑》勸誡殖民地讀者要節儉，書中充滿「省下一便士，等於淨賺兩便士」之類的格言；富蘭克林本人也聲稱，年輕時的精打細算讓他在四十二歲就得以從印刷業退休。", "as": "Although the family was famously frugal, the parents were lavish with praise and affable with every visitor, and their magnanimous spirit helped their children resist the ostentatious habits of wealthier classmates.", "at": "雖然這家人以節儉出名，但父母從不吝於讚美，對每位訪客也都和藹可親；他們寬厚的胸襟幫助孩子們抵擋了家境較富裕同學那種炫富的習氣。"}, {"w": "parsimonious", "p": "adj.", "d": "Extremely unwilling to spend money; excessively stingy.", "c": "吝嗇的；極度節儉的", "s": "Historians of the Irish Famine criticize the British Treasury's parsimonious approach to relief: officials under Charles Trevelyan, determined to keep public spending to a minimum, closed food depots and insisted that the starving work on public projects for meager wages.", "t": "研究愛爾蘭大饑荒的歷史學家批評英國財政部在救濟上極度吝嗇：查爾斯·屈維廉手下的官員為了將公共支出壓到最低，關閉了糧食供應站，並堅持要飢民從事公共工程以換取微薄工資。", "as": "The parsimonious landlord refused to repair the leaking roof, and his laconic, contemptuous replies to tenants' complaints only intensified their animosity until they organized a citywide rent strike that drew national attention.", "at": "這位吝嗇的房東拒絕修理漏水的屋頂，而他對房客抱怨所作的簡短又輕蔑的回應，只讓房客的敵意愈來愈深，最後他們組織了一場引起全國關注的全市性拒繳房租行動。"}, {"w": "avarice", "p": "n.", "d": "Extreme greed for money or material wealth.", "c": "貪婪；貪財", "s": "In Dante's Inferno, souls guilty of avarice are condemned to the fourth circle, where they push enormous weights in endless collisions with the spendthrifts—a punishment suggesting that hoarding wealth and wasting it recklessly are two sides of the same sin.", "t": "在但丁的《地獄篇》中，犯下貪婪之罪的靈魂被打入第四層地獄，在那裡推著巨大的重物，與揮霍者無止境地相互碰撞——這種懲罰暗示，囤積財富與肆意揮霍其實是同一種罪的兩面。", "as": "The documentary portrayed the CEO's avarice as the root of the scandal, showing how his arrogant disregard for regulations and his ostentatious lifestyle were funded by schemes that defrauded thousands of complacent investors.", "at": "這部紀錄片將執行長的貪婪描繪為醜聞的根源，呈現出他對法規傲慢的漠視與奢華炫富的生活方式，如何靠著詐騙數千名掉以輕心的投資人的計謀來支撐。"}, {"w": "austere", "p": "adj.", "d": "Severely simple and plain, without comfort or luxury.", "c": "簡樸的；樸素的；嚴峻的", "s": "The Shakers, a religious community that flourished in nineteenth-century America, built furniture of deliberately austeredesign—chairs and cabinets without carving, inlay, or ornament—believing that plain, useful objects reflected spiritual purity, and collectors now prize these simple pieces for their elegant restraint.", "t": "震顫派是十九世紀在美國興盛的宗教團體，他們刻意以簡樸的設計製作家具——椅子和櫥櫃上沒有雕刻、鑲嵌或任何裝飾——相信樸實實用的器物能反映心靈的純淨；如今收藏家珍視這些簡單作品所展現的優雅節制。", "as": "The monastery's austere routine of silence, fasting, and prayer appealed to the taciturn novelist, who had grown weary of the city's garrulous literary parties, its pretentious critics, and the endless pressure to promote his books.", "at": "修道院裡靜默、禁食與祈禱的簡樸作息，深深吸引了這位沉默寡言的小說家，因為他早已厭倦了城市裡喋喋不休的文學派對、裝腔作勢的評論家，以及無止境的新書宣傳壓力。"}, {"w": "mercenary", "p": "adj.", "d": "Motivated chiefly by a desire for money or gain.", "c": "唯利是圖的；圖利的", "s": "Critics accused the pharmaceutical company of purely mercenary motives when it raised the price of a decades-old antiparasitic drug from about thirteen dollars to $750 per pill overnight, arguing that its executives cared only about profits and not at all about the vulnerable patients who depended on the medicine.", "t": "當這家製藥公司一夜之間將一種已有數十年歷史的抗寄生蟲藥物，從每顆約十三美元調漲到七百五十美元時，批評者指責該公司純粹出於唯利是圖的動機，認為其高層只在乎利潤，完全不顧依賴這種藥物的弱勢病患。", "as": "Some historians portray the explorer as a mercenary adventurer, but others argue that his altruistic work among the sick and his magnanimous treatment of captured enemies complicate such a hackneyed caricature.", "at": "有些歷史學家把這位探險家描繪成唯利是圖的冒險者，但也有人認為，他照顧病患的無私工作以及寬待被俘敵人的寬大胸襟，使這種老套的醜化形象難以成立。"}, {"w": "miserly", "p": "adj.", "d": "Unwilling to spend money, like a miser.", "c": "吝嗇的；小氣的", "s": "Hetty Green, once considered the richest woman in America, was so miserly that she reportedly wore the same black dress until it fell apart, ate cold oatmeal to avoid heating costs, and delayed treatment for her son's injured leg while searching for a free clinic.", "t": "海蒂·格林曾被視為美國最富有的女性，據說她吝嗇到同一件黑色洋裝一直穿到破爛為止、為了省下加熱的費用而吃冷燕麥粥，還為了尋找免費診所而延誤兒子腿傷的治療。", "as": "The museum's miserly acquisitions budget forced the curators to rely on donors' largess, and their obsequious letters to wealthy patrons, full of grandiloquent flattery, struck younger staff as a humiliating way to appease the board.", "at": "博物館吝嗇的典藏預算迫使策展人仰賴捐贈者的慷慨解囊，而他們寫給富有贊助人那些充滿浮誇奉承之詞的諂媚信件，在年輕員工看來，只是一種為了討好董事會而自取其辱的做法。"}, {"w": "penurious", "p": "adj.", "d": "Extremely stingy and unwilling to spend money.", "c": "吝嗇的；一毛不拔的", "s": "Though he had amassed a fortune as a shipping magnate, the old man remained so penurious that he paid his household staff below the legal wage, refused to replace the cracked windows of his mansion, and kept detailed ledgers recording every candle his servants burned.", "t": "雖然這位老人身為航運大亨累積了巨額財富，他卻依然吝嗇到極點：付給家中僕役的工資低於法定標準，拒絕更換豪宅裡破裂的窗戶，還記了詳細的帳簿，記錄僕人們點過的每一根蠟燭。", "as": "The penurious publisher paid his translators so little that only the most desperate would accept his contracts, and his terse, disdainful refusals to renegotiate earned him a reputation as an insolent bully throughout the industry.", "at": "這位吝嗇的出版商付給譯者的稿酬少得可憐，只有走投無路的人才會接受他的合約；而他每次都以簡短又輕蔑的態度拒絕重新談判，使他在整個業界落得蠻橫無禮的惡霸名聲。"}, {"w": "thrifty", "p": "adj.", "d": "Using money and resources carefully and without waste.", "c": "節儉的；精打細算的", "s": "Researchers studying household finances in postwar Japan found that thrifty families, who saved nearly a fifth of their income by buying secondhand goods, cooking at home, and avoiding consumer debt, supplied much of the capital that banks lent to the rapidly expanding manufacturing sector.", "t": "研究戰後日本家庭財務的學者發現，那些節儉的家庭透過購買二手物品、在家烹飪以及避免消費性借貸，存下將近五分之一的收入，為銀行貸給迅速擴張的製造業的資金提供了大部分來源。", "as": "The thrifty couple avoided the ostentatious weddings fashionable among their friends, preferring a convivial dinner for a few relatives, and they politely ignored the haughty remarks of guests who considered such simplicity a sign of poverty.", "at": "這對節儉的夫妻避開了朋友間流行的鋪張婚禮，寧可為幾位親戚辦一場歡樂溫馨的晚宴；對於那些把這種簡樸視為窮酸象徵的賓客所發表的傲慢言論，他們也禮貌地置之不理。"}, {"w": "stingy", "p": "adj.", "d": "Not generous, not inclined to spend or give.", "c": "小氣的/吝嗇的", "s": "He had a reputation for being stingy even with his closest friends.", "t": "他以對即使是最親近的朋友也很小氣而聞名。", "as": "The restaurant's stingy portions left many customers still hungry.", "at": "這間餐廳吝嗇的份量讓許多顧客吃完仍覺得餓。", "a": 1}, {"w": "penny-pinching", "p": "adj.", "d": "Extremely careful and reluctant with spending money.", "c": "斤斤計較的;吝嗇的", "s": "His penny-pinching habits allowed him to retire early with substantial savings.", "t": "他斤斤計較的習慣讓他能夠帶著豐厚的存款提早退休。", "as": "The company's penny-pinching approach to salaries drove away talented employees.", "at": "這家公司對薪資斤斤計較的做法讓有才華的員工紛紛離職。", "a": 1}, {"w": "economical", "p": "adj.", "d": "Using money or resources carefully and without waste.", "c": "節約的;經濟實惠的", "s": "Buying in bulk is more economical in the long run.", "t": "長遠來看,大量採購更為經濟實惠。", "as": "She lived a simple, economical lifestyle.", "at": "她過著簡樸節約的生活方式。", "a": 1}, {"w": "covetous", "p": "adj.", "d": "Having a strong desire for something belonging to another.", "c": "貪婪的;垂涎的", "s": "He cast a covetous glance at his neighbor's new car.", "t": "他對鄰居的新車投以貪婪的一瞥。", "as": "Her covetous eyes settled on the diamond necklace.", "at": "她貪婪的目光落在那條鑽石項鍊上。", "a": 1}, {"w": "grasping", "p": "adj.", "d": "Greedy for money or possessions.", "c": "貪婪的;愛佔便宜的", "s": "The grasping landlord raised rent every year without warning.", "t": "這位貪婪的房東每年都毫無預警地漲租。", "as": "He was portrayed as a grasping businessman in the documentary.", "at": "這部紀錄片將他描繪成一個貪婪的商人。", "a": 1}, {"w": "hoard", "p": "v.", "d": "To accumulate and store items secretly or excessively.", "c": "囤積；密藏", "s": "Panicked consumers began to hoard non-perishable groceries during rumors of upcoming supply chain transportation disruptions.", "t": "在傳出供應鏈運輸即將中斷的謠言期間，恐慌的消費者開始「囤積」不易腐爛的食品。", "as": "", "at": "", "a": 1}, {"w": "provident", "p": "adj.", "d": "Making prudent provision for the future.", "c": "有遠見的;節儉的", "s": "Her provident habits of saving allowed her to retire comfortably.", "t": "她節儉有遠見的儲蓄習慣讓她能夠舒適地退休。", "as": "The provident farmer stored extra grain in case of a poor harvest.", "at": "這位有遠見的農夫儲存了額外的穀物,以防收成不佳。", "a": 1}]}, {"unit": 10, "theme": "Trouble and Confusion", "themeZh": "困境與混亂", "antonymLessons": [], "cards": [{"w": "adversity", "p": "n.", "d": "Serious difficulty or misfortune.", "c": "逆境；困境", "s": "Studies of children who grew up during the Great Depression found that many developed remarkable resilience: having endured hunger, unemployment in the family, and frequent moves in search of work, they later reported that early adversity had taught them resourcefulness and a deep appreciation for financial security.", "t": "針對在經濟大蕭條期間成長的孩童所做的研究發現，許多人培養出非凡的韌性：他們經歷過飢餓、家人失業，以及為了找工作而頻繁搬家，後來表示，早年的逆境教會了他們隨機應變，也讓他們深深珍惜經濟上的安穩。", "as": "In the face of adversity, the frugal immigrant family refused to squander their meager savings, and their quiet, stoical perseverance eventually allowed them to open a bakery whose convivial atmosphere made it a neighborhood landmark.", "at": "面對逆境，這個節儉的移民家庭拒絕揮霍他們微薄的積蓄，而他們默默堅忍的毅力，最終讓他們開了一家麵包店，店裡歡樂溫馨的氣氛使它成為社區的地標。"}, {"w": "conflagration", "p": "n.", "d": "A large and destructive fire.", "c": "大火；大火災", "s": "The Great Chicago Fire of 1871 began in a small barn on the city's southwest side, but strong winds, a long drought, and densely packed wooden buildings turned it into a conflagration that burned for two days, destroyed more than 17,000 structures, and left roughly 100,000 residents homeless.", "t": "1871年的芝加哥大火起初只是城市西南側一座小穀倉裡的火苗，但強風、長期乾旱以及密集的木造建築，使它演變成一場延燒兩天的大火，燒毀了一萬七千多棟建築物，約十萬名居民因而無家可歸。", "as": "After the conflagration destroyed the old quarter, the mayor's grandiloquent promises to rebuild did little to mollify residents, and his ostentatious ribbon-cutting ceremonies only deepened their animosity toward city hall.", "at": "大火燒毀舊城區後，市長浮誇的重建承諾幾乎無法安撫居民，而他那些鋪張的剪綵典禮，更加深了民眾對市政府的敵意。"}, {"w": "confounding", "p": "adj.", "d": "Causing surprise and confusion; baffling.", "c": "令人困惑的；費解的", "s": "For decades, astronomers found the rotation of spiral galaxies deeply confounding: stars at the outer edges were orbiting just as fast as those near the center, a pattern that contradicted Newtonian predictions and eventually led researchers to propose the existence of invisible dark matter.", "t": "數十年來，天文學家一直對螺旋星系的自轉現象深感困惑：位於外緣的恆星繞行速度竟與靠近中心的恆星一樣快，這種模式與牛頓力學的預測相矛盾，最終促使研究人員提出看不見的暗物質存在的假說。", "as": "The novel's confounding final chapter, in which the narrator constantly digresses into unexplained symbols, frustrated reviewers who had praised the succinct style of the author's earlier books, though a few defended the ending as a deliberate rejection of prosaic, hackneyed storytelling.", "at": "這部小說令人費解的最後一章中，敘事者不斷離題，轉向一些未加解釋的象徵，令曾經讚揚作者早期作品簡潔文風的評論家大感失望；不過也有少數人為這個結局辯護，認為它是有意拒絕平淡陳腐的敘事方式。"}, {"w": "debacle", "p": "n.", "d": "A sudden and complete failure; a fiasco.", "c": "慘敗；大失敗", "s": "The 1961 Bay of Pigs invasion, in which some 1,400 CIA-trained Cuban exiles were overwhelmed by Castro's forces within three days, proved such a debacle for the Kennedy administration that the president publicly accepted responsibility and quietly forced the CIA's director to resign.", "t": "1961年的豬玀灣入侵事件中，約一千四百名受中央情報局訓練的古巴流亡者在三天內就被卡斯楚的部隊擊潰，這對甘迺迪政府而言是一場慘敗，總統不得不公開承擔責任，並悄悄迫使中情局局長辭職。", "as": "The product launch was a debacle: the company's ostentatious marketing campaign had promised a revolution, but reviewers found the device insipid and its software so derivative that executives could not placate furious investors.", "at": "這次產品發表是一場大失敗：公司浮誇的行銷活動號稱將掀起一場革命，但評論者卻認為這款裝置平淡乏味，軟體也毫無新意，主管們根本無法安撫憤怒的投資人。"}, {"w": "cryptic", "p": "adj.", "d": "Mysterious or obscure in meaning; puzzling.", "c": "隱晦的；神秘難解的", "s": "Emily Dickinson's poems puzzled her first editors, who found many lines so cryptic—full of unconventional dashes, compressed metaphors, and abrupt shifts in thought—that they altered her punctuation and wording before publication in 1890, changes that later scholars painstakingly reversed.", "t": "艾蜜莉·狄金生的詩作讓她最初的編輯們大感困惑，他們發現許多詩句十分隱晦——充滿非傳統的破折號、高度濃縮的隱喻和突如其來的思緒轉折——因此在1890年出版前更動了她的標點和用字，而這些修改後來被學者們費盡心力地還原。", "as": "The spy's cryptic message was deliberately terse, but the analysts, wary of reading too much into a single phrase, refused to digress into speculation and instead compared it with dozens of earlier, equally laconic transmissions.", "at": "這名間諜的隱晦訊息刻意寫得極為簡短，但分析人員擔心對單一詞句過度解讀，因此拒絕偏離主題去臆測，而是拿它與數十則先前同樣言簡意賅的傳訊相互比對。"}, {"w": "enigma", "p": "n.", "d": "A person or thing that is mysterious or hard to understand.", "c": "謎；難以理解的人或事", "s": "Despite centuries of speculation, the purpose of Stonehenge remains an enigma: archaeologists have variously interpreted the massive stone circle as a solar calendar, a burial site, a place of healing, and a monument uniting distant communities, yet no single theory accounts for all the evidence.", "t": "儘管人們推測了好幾個世紀，巨石陣的用途至今仍是個謎：考古學家曾分別將這座巨大的石圈解讀為太陽曆、墓葬地、療癒之所，以及聯合遠方社群的紀念建築，但沒有任何單一理論能解釋所有證據。", "as": "To his biographers the reclusive composer remains an enigma: he was taciturn in public and disdainful of interviews, yet his private letters reveal a voluble, jocular man who delighted in gossip about his rivals.", "at": "對傳記作家而言，這位離群索居的作曲家至今仍是個謎：他在公開場合沉默寡言，對訪談不屑一顧，然而他的私人信件卻顯示他是個健談、詼諧，又熱衷於談論對手八卦的人。"}, {"w": "labyrinth", "p": "n.", "d": "A complicated network of winding passages; a maze.", "c": "迷宮；錯綜複雜的事物", "s": "The medina of Fez, one of the largest car-free urban areas in the world, is a labyrinth of more than nine thousand narrow, winding alleys, many of them dead ends, and even lifelong residents sometimes rely on landmarks such as fountains and mosques to find their way.", "t": "非斯舊城是世界上最大的無車都市區之一，由九千多條狹窄蜿蜒的巷弄構成，宛如一座迷宮，其中許多巷子是死路，就連土生土長的居民有時也得靠噴泉、清真寺等地標來辨認方向。", "as": "The tax code has become a labyrinth of exceptions and loopholes, and critics argue that its verbose regulations, written in grandiloquent legal jargon rather than concise language, benefit only wealthy taxpayers who can afford expert guides.", "at": "稅法已成為一座充滿例外條款與漏洞的迷宮，批評者認為，那些以浮誇的法律術語而非簡潔語言寫成的冗長法規，只對負擔得起專業顧問的富裕納稅人有利。"}, {"w": "quandary", "p": "n.", "d": "A state of uncertainty about what to do; a dilemma.", "c": "困惑；進退兩難", "s": "Doctors treating the elderly patient faced an ethical quandary: an aggressive surgery might extend her life by several years but carried a high risk of complications, while a gentler course of medication would preserve her comfort but almost certainly allow the cancer to spread.", "t": "為這位年長病患治療的醫生們陷入了倫理上的兩難：積極的手術或許能延長她數年壽命，但併發症風險很高；而較溫和的藥物療法雖能保持她的舒適，卻幾乎必然會讓癌症擴散。", "as": "The regulators were in a quandary: if they tried to placate the angry public with strict new rules, they might squander the fragile goodwill of the industry, yet a complacent response would only intensify public animosity.", "at": "監管機關陷入兩難：如果他們試圖以嚴格的新規定安撫憤怒的民眾，可能會揮霍掉業界脆弱的善意；然而若是回應得自滿怠慢，只會加深民眾的敵意。"}, {"w": "precarious", "p": "adj.", "d": "Dangerously unstable or uncertain; likely to collapse.", "c": "不穩定的；岌岌可危的", "s": "Many gig-economy workers describe their livelihoods as deeply precarious: without guaranteed hours, health insurance, or protection against sudden termination, a single slow month or minor illness can leave them unable to pay rent, and few have savings to cushion such shocks.", "t": "許多零工經濟的勞工形容自己的生計極不穩定：由於沒有保障的工時、健康保險，也不受突然解雇的保護，只要一個月生意清淡或生一場小病，就可能讓他們付不出房租，而且很少人有積蓄可以緩衝這類衝擊。", "as": "The ceasefire remained precarious, and diplomats worked to conciliate the bellicose factions on both sides, knowing that a single insolent remark from either commander could reignite the fighting along the disputed border.", "at": "停火協議依然岌岌可危，外交官們努力安撫雙方好戰的派系，因為他們知道，只要任何一方指揮官說出一句無禮的話，就可能讓爭議邊界沿線的戰火再度燃起。"}, {"w": "turbulence", "p": "n.", "d": "A state of violent disorder, unrest, or instability.", "c": "動盪；騷亂", "s": "The year 1848 brought such political turbulence to Europe—barricades in Paris, uprisings in Vienna and Berlin, and nationalist revolts in Hungary and Italy—that conservative governments, once restored to power, responded with censorship, secret police, and the suppression of liberal newspapers.", "t": "1848年為歐洲帶來了極大的政治動盪——巴黎街頭築起街壘，維也納和柏林爆發起義，匈牙利和義大利也掀起民族主義叛亂——以致保守派政府在恢復權力後，以審查制度、秘密警察和查禁自由派報紙作為回應。", "as": "During the financial turbulence of 2008, the central bank tried to allay public fears with a succinct statement, but commentators found its tone complacent, and a few even accused officials of a haughty disregard for ordinary savers.", "at": "在2008年的金融動盪期間，央行試圖以一份簡明扼要的聲明來平息大眾的恐慌，但評論員認為其語氣自滿，有些人甚至指責官員們對一般存款戶抱持傲慢漠視的態度。"}, {"w": "turmoil", "p": "n.", "d": "A state of great confusion, disturbance, or uncertainty.", "c": "混亂；騷動", "s": "In the years after the 1929 stock market crash, the American banking system was thrown into turmoil as panicked depositors rushed to withdraw their savings, thousands of banks collapsed, and the absence of federal deposit insurance meant that many families lost everything they had saved.", "t": "1929年股市崩盤後的幾年裡，美國銀行體系陷入一片混亂：驚慌的存戶爭相提領存款，數以千計的銀行倒閉，而由於缺乏聯邦存款保險，許多家庭因此失去了所有積蓄。", "as": "Amid the turmoil of the election, the candidate tried to pacify voters with mundane promises about road repairs, but his rivals' pugnacious attacks and the voluble protests in the streets drowned out his message.", "at": "在選舉的一片混亂中，這位候選人試圖用修路之類平凡無奇的承諾來安撫選民，但對手好鬥的攻擊以及街頭喧嚷不休的抗議聲，完全淹沒了他的訴求。"}, {"w": "dilemma", "p": "n.", "d": "A situation requiring a choice between equally undesirable options.", "c": "困境;兩難", "s": "She faced a moral dilemma over whether to report her friend.", "t": "她面臨一個道德困境,不知該不該舉報她的朋友。", "as": "The company's dilemma was choosing between profit and ethics.", "at": "這家公司陷入了在利潤與道德之間抉擇的兩難。", "a": 1}, {"w": "plight", "p": "n.", "d": "Predicament, dangerous situation.", "c": "困境/苦境", "s": "The documentary raises awareness about the plight of refugees worldwide.", "t": "這部紀錄片提高了大眾對全球難民困境的關注。", "as": "Local farmers described their plight after years of drought.", "at": "當地農民描述了他們在多年乾旱後所面臨的困境。", "a": 1}, {"w": "predicament", "p": "n.", "d": "A difficult, unpleasant, or embarrassing situation.", "c": "困境;窘境", "s": "He found himself in quite a predicament after losing his passport abroad.", "t": "他在國外弄丟護照後陷入了相當棘手的困境。", "as": "The team faced a serious predicament with only one player left uninjured.", "at": "這支隊伍面臨嚴重的困境,只剩下一名球員未受傷。", "a": 1}, {"w": "maelstrom", "p": "n.", "d": "A destructive whirlpool which rapidly sucks in objects.", "c": "大漩渦/混亂局面", "s": "The sailors steered desperately to avoid the deadly maelstrom.", "t": "水手們拼命操舵,試圖躲避這個致命的大漩渦。", "as": "The scandal plunged the entire administration into a political maelstrom.", "at": "這起醜聞讓整個政府陷入一場政治風暴的漩渦之中。", "a": 1}, {"w": "chaos", "p": "n.", "d": "Absolute disorder.", "c": "混亂/混沌", "s": "The power outage plunged the entire office into chaos.", "t": "這場停電讓整間辦公室陷入一片混亂。", "as": "Without a clear leader, the meeting quickly descended into chaos.", "at": "由於沒有明確的主持人,這場會議很快就陷入混亂。", "a": 1}]}, {"unit": 11, "theme": "Harmful and Wicked", "themeZh": "有害與邪惡", "antonymLessons": [72], "cards": [{"w": "detrimental", "p": "adj.", "d": "Tending to cause harm or damage.", "c": "有害的；不利的", "s": "Ecologists monitoring the coastal estuary found that runoff from upstream fertilizer use was detrimental to the native oyster beds: the excess nitrogen triggered algal blooms that depleted dissolved oxygen, and within five years the harvest had fallen by more than half.", "t": "監測沿海河口的生態學家發現，上游施用肥料所產生的逕流對當地原生的牡蠣床有害：過量的氮引發藻華，耗盡水中的溶氧，五年內牡蠣產量便減少了一半以上。", "as": "Economists warned that the government's prodigal spending, though intended to alleviate the immediate turmoil of the recession, could prove detrimental in the long run by leaving the nation in a precarious fiscal position.", "at": "經濟學家警告，政府揮霍無度的支出雖然意在緩解經濟衰退帶來的眼前動盪，長遠來看卻可能造成損害，使國家陷入岌岌可危的財政處境。"}, {"w": "devious", "p": "adj.", "d": "Using dishonest or underhanded tricks to get what one wants.", "c": "狡詐的；不正當的", "s": "Investigative reporters eventually exposed the lobbyist's devious strategy: rather than openly opposing the clean-air bill, he quietly funded a network of seemingly independent citizen groups that flooded legislators with letters claiming the regulations would destroy local jobs.", "t": "調查記者最終揭露了這名說客的狡詐策略：他並未公開反對這項清淨空氣法案，而是暗中資助一個看似獨立的公民團體網絡，讓這些團體寄出大量信件給議員，聲稱這些法規將摧毀地方的就業機會。", "as": "In the chronicle, the devious courtier learns to placate the haughty king with lavish flattery while covertly spreading rumors that deepen the animosity between rival noble families, ensuring that no one notices his own steady rise to power.", "at": "在這部編年史中，那位狡詐的朝臣學會用大量的奉承安撫傲慢的國王，同時暗中散播謠言，加深敵對貴族家族之間的仇恨，確保沒有人察覺他自己正穩步掌權。"}, {"w": "iniquitous", "p": "adj.", "d": "Grossly unfair and morally wrong.", "c": "極不公正的；邪惡的", "s": "Nineteenth-century reformers denounced the iniquitous system of debtors' prisons, in which impoverished families could be jailed indefinitely for small debts, often unable to earn the very money they needed to secure their release.", "t": "十九世紀的改革者譴責極不公正的債務人監獄制度：在這種制度下，貧困家庭可能因小額債務而遭無限期監禁，往往無法賺得換取自由所需的那筆錢。", "as": "Charles Dickens, whose father was imprisoned for debt, wrote with impassioned eloquence about the iniquitous treatment of the poor, contrasting the ostentatious wealth of factory owners with the penurious lives of the children who labored for them.", "at": "父親曾因負債入獄的狄更斯，以慷慨激昂的雄辯描寫窮人所受的不公待遇，將工廠老闆炫耀的財富與替他們做工的童工貧困的生活形成對比。"}, {"w": "pernicious", "p": "adj.", "d": "Causing great harm, often gradually and unnoticed.", "c": "有害的；潛移默化地危害的", "s": "Public health officials consider lead contamination especially pernicious because its effects are invisible at first: children exposed to old paint or corroded pipes may show no symptoms for years, even as the metal steadily impairs their cognitive development and attention span.", "t": "公共衛生官員認為鉛污染特別有害，因為它的影響起初難以察覺：接觸老舊油漆或鏽蝕水管的兒童可能多年毫無症狀，而這種金屬卻持續損害他們的認知發展與專注力。", "as": "The historian argued that the most pernicious legacy of the war was not the conflagration that leveled the capital but the lingering animosity between neighboring communities, a turmoil of suspicion that no treaty could quell.", "at": "這位歷史學家認為，這場戰爭最有害的遺緒並非夷平首都的那場大火，而是鄰近社群之間揮之不去的仇恨——一種任何條約都無法平息的猜疑與動盪。"}, {"w": "ominous", "p": "adj.", "d": "Suggesting that something bad is about to happen.", "c": "不祥的；預示凶兆的", "s": "Seismologists grew alarmed when the volcano's usual tremors gave way to an ominous silence, accompanied by a rapid swelling of its northern flank, signs that magma was accumulating beneath the surface faster than it could escape.", "t": "火山平常的震動轉變為一片不祥的寂靜，同時北側山坡迅速隆起，地震學家因此深感警覺，因為這些跡象顯示岩漿在地表下累積的速度超過了它能釋出的速度。", "as": "The ominous headlines about a banking debacle prompted even the most complacent investors to sell their shares, and the resulting turbulence in the markets bewildered economists who had predicted a long period of quiescent markets and steady growth.", "at": "關於銀行業崩盤的不祥頭條，促使連最自滿的投資人也拋售持股，隨之而來的市場動盪讓原本預測市場將長期平靜、經濟穩定成長的經濟學家大感困惑。"}, {"w": "nefarious", "p": "adj.", "d": "Wicked, criminal, or villainous in nature.", "c": "邪惡的；不法的", "s": "Interpol agents spent three years tracing the smuggling ring's nefarious activities, which included forging export permits, bribing customs officials, and trafficking looted antiquities from war zones to private collectors in Europe and Asia.", "t": "國際刑警組織的探員花了三年追查這個走私集團的不法勾當，包括偽造出口許可證、賄賂海關官員，以及將戰區遭掠奪的古物販運給歐洲與亞洲的私人收藏家。", "as": "The documentary portrays the nefarious hackers not as cryptic geniuses but as mercenary opportunists, motivated purely by avarice and indifferent to the hospitals whose computer systems they crippled during the worst months of the pandemic.", "at": "這部紀錄片並未把那些邪惡的駭客描繪成神祕難解的天才，而是唯利是圖的投機分子，他們純粹受貪婪驅使，對於在疫情最嚴峻的幾個月裡遭他們癱瘓電腦系統的醫院漠不關心。"}, {"w": "virulent", "p": "adj.", "d": "Extremely harmful or infectious; bitterly hostile.", "c": "劇毒的；惡毒的", "s": "Epidemiologists were alarmed that the new strain proved far more virulent than its predecessors, spreading through an entire hospital ward within days and causing severe pneumonia even in young patients with no underlying medical conditions.", "t": "流行病學家深感憂慮，因為這株新病毒的毒性遠比先前的病株強，數天之內就傳遍整個病房，甚至讓沒有任何潛在疾病的年輕病患罹患嚴重的肺炎。", "as": "The critic's virulent review, a rant that mocked the young composer's symphony as derivative and banal, provoked a contentious debate about whether reviewers should temper their judgments when assessing a debut.", "at": "這位評論家惡毒的樂評簡直是一篇謾罵，嘲諷這位年輕作曲家的交響曲抄襲模仿又陳腐平庸，引發了一場激烈的爭論：評論者在評價新人的首部作品時，是否應該緩和自己的批判。"}, {"w": "deleterious", "p": "adj.", "d": "Causing harm or damage, especially to health.", "c": "有害的；有損健康的", "s": "Although the herbicide was initially praised for boosting crop yields, later studies revealed its deleterious effects on pollinators: even trace amounts impaired the navigation abilities of honeybees, preventing many from finding their way back to the hive.", "t": "這種除草劑起初因能提高作物產量而備受讚揚，但後來的研究揭露了它對授粉昆蟲的有害影響：即使只是微量，也會損害蜜蜂的導航能力，使許多蜜蜂找不到回巢的路。", "as": "Nutritionists caution that the deleterious effects of a diet heavy in sugar are often obscured by lavish advertising, which presents sweetened cereals as wholesome and dismisses scientific warnings as the alarmist prattle of overly austere critics.", "at": "營養學家提醒，高糖飲食的有害影響往往被鋪天蓋地的廣告所掩蓋，這些廣告把含糖穀片包裝成健康食品，並把科學警告貶為過度嚴苛的批評者危言聳聽的胡言亂語。"}, {"w": "baneful", "p": "adj.", "d": "Causing great harm, ruin, or destruction.", "c": "有害的；毀滅性的", "s": "Historians of the Irish famine emphasize the baneful consequences of relying on a single crop: when blight destroyed the potato harvests of the 1840s, roughly a million people died and another million emigrated, permanently reshaping the island's population.", "t": "研究愛爾蘭大饑荒的歷史學家強調，仰賴單一作物會帶來毀滅性的後果：當枯萎病摧毀了1840年代的馬鈴薯收成，約有一百萬人死亡，另有一百萬人移居海外，永久改變了這座島嶼的人口結構。", "as": "Critics of the regime described its censorship as baneful, arguing that by punishing every outspoken journalist and rewarding only hackneyed propaganda, the government had made public debate so insipid that citizens grew complacent about their own lack of freedom.", "at": "該政權的批評者形容其新聞審查危害深遠，認為政府懲罰每一位敢言的記者、只獎勵陳腔濫調的宣傳，使公共討論變得索然無味，以致公民對自身缺乏自由一事變得安於現狀。"}, {"w": "malicious", "p": "adj.", "d": "Intending to harm, upset, or damage others.", "c": "惡意的；存心不良的", "s": "Cybersecurity analysts traced the outage to a malicious program disguised as a routine software update; once installed, it encrypted the utility's billing records and displayed a message demanding payment in cryptocurrency before the files would be restored.", "t": "資安分析師追查出這次系統中斷的源頭是一個偽裝成例行軟體更新的惡意程式；安裝後，它便將這家公用事業公司的帳單紀錄加密，並顯示訊息要求以加密貨幣付款，否則不會恢復檔案。", "as": "Though the columnist claimed her remarks were merely jocular, the malicious gossip she spread about her rival's private life was so contemptuous and insolent that even her loyal readers began to question her integrity.", "at": "雖然那位專欄作家聲稱她的言論只是開玩笑，但她散播關於對手私生活的惡意八卦是如此輕蔑又無禮，連她的忠實讀者也開始質疑她的人品。"}, {"w": "odious", "p": "adj.", "d": "Extremely unpleasant and deserving hatred or disgust.", "c": "可憎的；令人厭惡的", "s": "Many Northern readers who had once tolerated slavery as an unfortunate economic necessity came to see it as truly odious after reading Frederick Douglass's firsthand accounts of families sold apart at auction and of laborers whipped for the smallest infractions.", "t": "許多原本把奴隸制當成不幸但必要的經濟制度而予以容忍的北方讀者，在讀了道格拉斯親身記述家人在拍賣會上被拆散出售、勞工因最輕微的過失而遭鞭打的經歷後，開始認為奴隸制真正令人憎惡。", "as": "The ambassador found the dictator's swagger odious, yet he chose to conciliate rather than confront him, reasoning that a cordial tone might mitigate the regime's belligerent posture toward its neighbors.", "at": "這位大使覺得那名獨裁者趾高氣揚的模樣令人厭惡，但他選擇安撫而非對抗，理由是友好的語氣或許能緩和該政權對鄰國的好戰姿態。"}, {"w": "rancorous", "p": "adj.", "d": "Marked by deep, long-lasting bitterness and resentment.", "c": "積怨很深的；充滿怨恨的", "s": "The partnership between the two founders, once celebrated as a model of collaboration, became so rancorous after a dispute over patent royalties that they spent the next decade suing each other and refused to appear together even at the company's anniversary celebration.", "t": "這兩位創辦人的合夥關係曾被譽為合作典範，卻在一場專利權利金糾紛後變得積怨甚深，兩人在接下來的十年裡互相提告，甚至拒絕一同出席公司的週年慶祝活動。", "as": "Once the budget talks collapsed over the contentious issue of taxation, the rancorous debate between the two parties degenerated into a polemical shouting match, and the negotiator, normally affable and patient, finally abandoned his efforts to appease either side.", "at": "預算協商因具爭議性的稅收問題破裂後，兩黨之間積怨已深的辯論淪為一場充滿論戰火藥味的叫罵，而那位平時和藹又有耐心的協調者，最終也放棄了安撫任何一方的努力。"}, {"w": "vicious", "p": "adj.", "d": "Deliberately cruel or violent.", "c": "凶惡的;惡毒的", "s": "The dog was labeled vicious after several unprovoked attacks.", "t": "這隻狗在數次無端攻擊事件後被貼上了凶惡的標籤。", "as": "She endured a vicious smear campaign during the election.", "at": "她在這場選舉中承受了一場惡毒的抹黑行動。", "a": 1}, {"w": "noxious", "p": "adj.", "d": "Harmful, poisonous, or very unpleasant.", "c": "有害的/有毒的", "s": "The noxious fumes from the factory polluted the air in the nearby town.", "t": "這座工廠排放的有毒煙霧污染了附近城鎮的空氣。", "as": "Workers wore masks to avoid inhaling the noxious gas.", "at": "工人們戴上口罩,以避免吸入這種有害氣體。", "a": 1}, {"w": "malevolent", "p": "adj.", "d": "Having or showing a desire to cause evil or harm.", "c": "惡意的；狠毒的", "s": "A malevolent spirit haunted the old manor and terrified every visitor.", "t": "一個惡毒的靈體出沒於老莊園，驚嚇每位訪客。", "as": "Rival executives organized a malevolent campaign to destroy the CEO's reputation.", "at": "競爭對手高層策劃惡意行動，企圖毀掉執行長的名譽。", "a": 1}, {"w": "malignant", "p": "adj.", "d": "Dangerous, deadly, or likely to invade healthy tissue and spread uncontrollably.", "c": "惡性的；致命的；極具危害的", "s": "The biopsy confirmed that the tumor was malignant and required immediate treatment.", "t": "活體檢查證實腫瘤為惡性，需要立即治療。", "as": "The dictator's malignant ideology destroyed individual freedom and fueled unrest.", "at": "獨裁者極具危害的思想毀掉個人自由並引發動盪。", "a": 1}, {"w": "sinister", "p": "adj.", "d": "Evil, ominous.", "c": "邪惡的", "s": "There was something sinister about the way he smiled before leaving the room.", "t": "他離開房間前的那個笑容帶著一絲邪惡的意味。", "as": "The old mansion had a sinister reputation among the townspeople.", "at": "這座古老的宅邸在鎮民間有著邪惡不祥的名聲。", "a": 1}, {"w": "lethal", "p": "adj.", "d": "Deadly.", "c": "致命的/致死的", "s": "The snake's bite delivers a lethaledose of venom within seconds.", "t": "這種蛇的咬傷會在幾秒內注入致命劑量的毒液。", "as": "Police recovered a lethal weapon at the crime scene.", "at": "警方在犯罪現場找到了一件致命的武器。", "a": 1}, {"w": "toxic", "p": "adj.", "d": "Poisonous; harmful.", "c": "有毒的;有害的", "s": "The factory was fined for dumping toxic waste into the river.", "t": "這家工廠因將有毒廢棄物傾倒入這條河流而遭到罰款。", "as": "The workplace became increasingly toxic under the new management.", "at": "在新任管理層領導下,這個職場環境變得越來越有害。", "a": 1}, {"w": "insidious", "p": "adj.", "d": "Sly, seductive, treacherous.", "c": "陰險的/潛伏的", "s": "The disease's insidious symptoms went unnoticed for years.", "t": "這種疾病潛伏隱匿的症狀多年來都未被察覺。", "as": "Corruption can spread through an organization in insidious ways.", "at": "貪腐可能會以陰險潛伏的方式蔓延整個組織。", "a": 1}, {"w": "malefactor", "p": "n.", "d": "A person who commits a crime or other wrong; an evildoer.", "c": "罪犯；作惡者；歹徒", "s": "The detective gathered every guest to expose the hidden malefactor.", "t": "偵探召集所有賓客，揭露隱藏的作惡者。", "as": "The names of notorious malefactor were posted at the village gate.", "at": "臭名昭彰的罪犯姓名被張貼在村莊大門。", "a": 1}, {"w": "depraved", "p": "adj.", "d": "Morally corrupt; wicked.", "c": "墮落的;邪惡的", "s": "The novel's depraved villain shows no remorse.", "t": "這本小說裡墮落邪惡的反派毫無悔意。", "as": "The court called his crimes shockingly depraved .", "at": "法庭稱他的罪行極其邪惡令人震驚。", "a": 1}, {"w": "heinous", "p": "adj.", "d": "Hatefully evil.", "c": "十惡不赦的", "s": "The court sentenced him for committing a heinous crime.", "t": "法院因他犯下十惡不赦的罪行而判他入獄。", "as": "It was a heinous act of betrayal that no one could forgive.", "at": "那是一次令人髮指的背叛行為,沒有人能夠原諒。", "a": 1}]}, {"unit": 12, "theme": "Criticizing and Scolding", "themeZh": "批評與責備", "antonymLessons": [19], "cards": [{"w": "deprecate", "p": "v.", "d": "To express disapproval of; to play down as unimportant.", "c": "反對；不贊成；貶低", "s": "Early critics of Impressionism deprecated the movement's loose brushwork and unfinished-looking canvases, dismissing Monet's paintings as mere sketches, yet within a generation the same techniques were being taught in academies and celebrated as a revolution in the depiction of light.", "t": "印象派早期的評論者對這個畫派鬆散的筆觸和看似未完成的畫作頗不以為然，把莫內的畫貶為僅是草圖；然而不到一個世代，同樣的技法便在美術學院裡傳授，並被譽為描繪光線的一場革命。", "as": "The modest physicist tended to deprecate her own role in the discovery, describing it as fortuitous, yet her colleagues insisted that her meticulous methods, rather than luck, had resolved the enigma that had confounded the field for decades.", "at": "這位謙虛的物理學家總是貶低自己在這項發現中的角色，稱之為幸運的巧合，但她的同事堅稱，是她一絲不苟的研究方法而非運氣，解開了困擾這個領域數十年的謎團。"}, {"w": "impugn", "p": "v.", "d": "To challenge something as false or call it into question.", "c": "質疑；抨擊", "s": "During cross-examination, the defense attorney sought to impugn the expert witness's credibility by revealing that her laboratory had received substantial funding from the plaintiff's company, suggesting that her conclusions about the product's safety might not be entirely impartial.", "t": "在交互詰問時，辯護律師試圖質疑專家證人的可信度，揭露她的實驗室曾獲得原告公司的大筆資助，暗示她對該產品安全性所下的結論可能並非完全公正。", "as": "Rather than engage with the substance of the report, the senator chose to impugn the motives of its authors, delivering a grandiloquent and contemptuous speech that dismissed their careful findings as the work of mercenary activists.", "at": "這位參議員並未針對報告的實質內容回應，而是選擇質疑撰寫者的動機，發表了一篇浮誇又輕蔑的演說，把他們嚴謹的研究結果貶為唯利是圖的運動人士之作。"}, {"w": "rebuke", "p": "v.", "d": "To express sharp disapproval of someone's behavior.", "c": "斥責；指責", "s": "The United Nations Security Council formally rebuked the government for launching missile tests in defiance of international agreements, warning that further provocations would result in expanded sanctions on the country's energy exports.", "t": "聯合國安理會正式譴責該國政府違反國際協議發射飛彈試射，並警告若再有挑釁行為，將擴大對該國能源出口的制裁。", "as": "The editor did not hesitate to rebuke the young reporter, whose verbose and pretentious article was full of trite phrases and digressions that obscured the story's few important facts.", "at": "編輯毫不猶豫地斥責這位年輕記者，因為他那篇冗長又矯揉造作的報導充滿陳腔濫調和離題的段落，掩蓋了報導中少數幾項重要事實。"}, {"w": "rebuff", "p": "v.", "d": "To reject an offer, request, or person bluntly.", "c": "斷然拒絕；冷落", "s": "When the multinational corporation offered to buy the family-owned vineyard for triple its appraised value, the owners politely but firmly rebuffed the proposal, explaining that preserving their grandparents' winemaking traditions mattered more to them than any sum of money.", "t": "當這家跨國企業提出以估價三倍的價格收購這座家族經營的葡萄園時，園主禮貌但堅定地回絕了這項提議，表示對他們而言，保存祖父母的釀酒傳統比任何金錢都重要。", "as": "The reticent novelist would routinely rebuff journalists seeking interviews, and her terse replies were often mistaken for haughty disdain, though friends insisted that she was simply shy and found the publicity surrounding her work mundane.", "at": "這位沉默寡言的小說家經常斷然拒絕前來邀訪的記者，她簡短的回覆常被誤解為高傲的輕蔑，但朋友們堅稱她只是害羞，而且覺得圍繞她作品的宣傳活動枯燥乏味。"}, {"w": "reprove", "p": "v.", "d": "To criticize or correct someone, usually gently.", "c": "責備；告誡", "s": "In her letters to her son at boarding school, Abigail Adams gently reproved him for neglecting his studies of Latin and Greek, reminding him that a nation struggling to establish itself would need citizens educated well enough to govern wisely.", "t": "愛碧蓋兒‧亞當斯在寫給就讀寄宿學校的兒子的信中，溫和地責備他荒廢了拉丁文與希臘文的學業，並提醒他，一個正努力立足的國家將需要受過良好教育、能明智治國的公民。", "as": "The mentor would reprove her apprentices kindly rather than harshly, believing that an affable correction could ameliorate their technique more effectively than the cantankerous outbursts favored by her own former teacher.", "at": "這位導師總是和善而非嚴厲地告誡學徒，她相信溫和親切的指正比起她從前老師慣用的暴躁斥責，更能有效改進他們的技藝。"}, {"w": "castigate", "p": "v.", "d": "To criticize or punish someone severely.", "c": "嚴厲批評；懲戒", "s": "In a scathing editorial, the medical journal castigated the pharmaceutical firm for concealing data from its clinical trials, arguing that withholding evidence of serious side effects had placed thousands of patients at unnecessary risk.", "t": "這份醫學期刊在一篇措辭尖銳的社論中嚴厲批評這家製藥公司隱瞞臨床試驗數據，指出隱匿嚴重副作用的證據使數千名病患承受了不必要的風險。", "as": "Environmental groups castigated the mining company for its pernicious disregard of local ecosystems, accusing its executives of avarice and of using lavish public-relations campaigns to mollify critics while rivers turned toxic.", "at": "環保團體嚴厲譴責這家礦業公司對當地生態系統的有害漠視，指責其高層貪婪無度，並在河川變得有毒之際，利用鋪張的公關活動來安撫批評者。"}, {"w": "berate", "p": "v.", "d": "To scold someone angrily and at length.", "c": "嚴厲斥責；痛罵", "s": "Witnesses described how the frustrated conductor berated the orchestra for nearly twenty minutes during the rehearsal, shouting at individual players for every missed entrance until several musicians walked off the stage in protest.", "t": "目擊者描述，那位氣急敗壞的指揮在排練時痛罵整個樂團將近二十分鐘，對每一個沒跟上進場拍子的樂手個別大吼，直到好幾位樂手憤而離開舞臺以示抗議。", "as": "The arrogant manager would berate his staff in long, garrulous tirades, yet his outbursts did nothing to alleviate the turmoil in the department and only deepened the employees' antagonism toward him.", "at": "那位傲慢的經理總是用冗長又嘮叨的長篇大論痛罵員工，但他的發作絲毫無助於緩解部門的混亂，只加深了員工對他的敵意。"}, {"w": "censure", "p": "v.", "d": "To express formal, official disapproval of someone.", "c": "（正式）譴責；責難", "s": "In 1954 the United States Senate voted to censure Joseph McCarthy for conduct that brought the chamber into dishonor, a formal reprimand that effectively ended the influence of the senator whose reckless accusations of communist infiltration had ruined many careers.", "t": "1954年，美國參議院表決譴責約瑟夫‧麥卡錫有損議院聲譽的行為；這項正式的懲戒實際上終結了這位參議員的影響力，他草率地指控共產黨滲透，曾毀了許多人的職業生涯。", "as": "The medical board censured the physician for his presumptuous habit of prescribing experimental drugs without consent, finding that his conduct, though perhaps benevolent in intent, had placed vulnerable patients in a precarious position.", "at": "醫師公會正式譴責這名醫師擅自在未經同意下開立實驗性藥物的做法，認定他的行為或許出於善意，卻使弱勢病患陷入岌岌可危的處境。"}, {"w": "chastise", "p": "v.", "d": "To criticize or punish someone severely for wrongdoing.", "c": "懲罰；嚴厲責備", "s": "Puritan magistrates in colonial New England would publicly chastise residents who skipped Sunday services, sometimes confining them in wooden stocks in the town square so that their neighbors could witness the consequences of neglecting religious duty.", "t": "殖民時期新英格蘭的清教徒地方官會公開懲罰缺席主日禮拜的居民，有時把他們鎖在城鎮廣場的木製足枷中，讓鄰居目睹怠忽宗教義務的下場。", "as": "In his memoir the former chancellor chastised himself for having been so complacent, admitting that his austere budget, intended to mitigate the debt crisis, had instead deepened the adversity of the poorest citizens.", "at": "這位前財政大臣在回憶錄中自責當年太過自滿，承認他那份原本要緩解債務危機的緊縮預算，反而加深了最貧困公民的困境。"}, {"w": "upbraid", "p": "v.", "d": "To scold or criticize someone sharply and bitterly.", "c": "嚴厲責罵；申斥", "s": "In the final act of the play, the aging king upbraids his eldest daughter for her ingratitude, condemning her in a furious speech for repaying years of generosity with cruelty and contempt.", "t": "在劇本的最後一幕，年邁的國王嚴厲責罵長女忘恩負義，以一段憤怒的獨白痛斥她以殘酷與輕蔑回報他多年來的慷慨。", "as": "Rather than placate the protesters, the governor chose to upbraid them as insolent troublemakers, a bellicose response that only intensified their animosity and turned a peaceful demonstration into prolonged turmoil.", "at": "州長沒有安撫抗議群眾，反而嚴厲斥責他們是無禮的滋事分子；這種好鬥的回應只加深了他們的敵意，使一場和平的示威演變成長期的動盪。"}, {"w": "reprimand", "p": "v.", "d": "To show sharp disapproval.", "c": "譴責", "s": "The teacher reprimanded the students for talking during the exam.", "t": "老師譴責了在考試中講話的學生。", "as": "He received a formal reprimand from his boss for arriving late every day.", "at": "他因為每天遲到而受到上司正式的譴責。", "a": 1}, {"w": "chide", "p": "v.", "d": "To voice disapproval.", "c": "斥責/責備", "s": "The coach began to chide the players for their lack of effort.", "t": "教練開始斥責球員們不夠努力。", "as": "Her mother would gently chide her for staying up too late.", "at": "她的媽媽總是溫和地責備她熬夜太晚。", "a": 1}, {"w": "admonish", "p": "v.", "d": "To warn, reprove.", "c": "警告", "s": "The teacher admonished the students to finish their homework before playing games.", "t": "老師告誡學生們要先寫完作業才能玩遊戲。", "as": "The coach admonished the players for skipping practice.", "at": "教練告誡那些缺席練習的球員。", "a": 1}, {"w": "reproach", "p": "v.", "d": "To rebuke, reprimand.", "c": "責備/斥責", "s": "Her mother's silent reproach hurt more than any harsh words.", "t": "母親無聲的責備比任何嚴厲的話語都更讓她難受。", "as": "He couldn't bear the reproach in his coach's eyes after the loss.", "at": "落敗之後,他無法承受教練眼中流露出的責備。", "a": 1}, {"w": "condemn", "p": "v.", "d": "To express strong disapproval of; to sentence to punishment.", "c": "譴責;判刑", "s": "World leaders quickly moved to condemn the attack on civilians.", "t": "各國領袖迅速對這起攻擊平民的事件表達譴責。", "as": "The judge chose to condemn him to community service rather than jail time.", "at": "法官選擇判處他社區服務,而非監禁。", "a": 1}, {"w": "excoriate", "p": "v.", "d": "To criticize severely.", "c": "嚴厲批評/痛斥", "s": "The critic excoriated the director for the film's clumsy pacing.", "t": "這位評論家嚴厲抨擊導演讓這部電影的節奏顯得笨拙。", "as": "The senator was excoriated in the press for his controversial remarks.", "at": "這位參議員因發表爭議言論而在媒體上遭到猛烈抨擊。", "a": 1}, {"w": "denounce", "p": "v.", "d": "To criticize publicly.", "c": "公開譴責/揭發", "s": "World leaders quickly moved to denounce the attack.", "t": "各國領袖迅速採取行動,公開譴責這起攻擊事件。", "as": "She stood up in the meeting to denounce the unfair treatment of new hires.", "at": "她在會議中站起來公開譴責新進員工受到的不公平待遇。", "a": 1}, {"w": "remonstrate", "p": "v.", "d": "To make a forceful protest or objection.", "c": "抗議;力爭", "s": "Residents began to remonstrate against the proposed factory closure.", "t": "居民開始針對這項擬議的工廠關閉展開抗議。", "as": "She chose to remonstrate with her manager over the unfair policy.", "at": "她選擇就這項不公平的政策向她的經理力爭。", "a": 1}]}, {"unit": 13, "theme": "Indifferent and Unemotional", "themeZh": "冷漠與不動聲色", "antonymLessons": [16], "cards": [{"w": "detached", "p": "adj.", "d": "Not emotionally involved; aloof or objective.", "c": "超然的；冷漠的；不帶感情的", "s": "Anthropologists are trained to remain detached while conducting fieldwork, recording rituals and customs without judging them by the standards of their own culture, although many admit that years of living within a community make such objectivity difficult to sustain.", "t": "人類學家受過訓練，在進行田野調查時要保持超然客觀，記錄各種儀式與習俗而不以自身文化的標準加以評判；不過許多人也承認，在一個社群中生活多年後，很難一直維持這種客觀。", "as": "The narrator's detached voice, terse and almost clinical, describes the family's adversity without sentiment, a technique that critics once dismissed as vapid but now praise for making the novel's quiet tragedies all the more poignant.", "at": "敘事者超然冷靜的口吻簡潔得近乎臨床記錄，毫不煽情地描述這個家庭的苦難；評論家曾把這種手法斥為乏味，如今卻稱讚它讓小說中無聲的悲劇更加令人心酸。"}, {"w": "impassive", "p": "adj.", "d": "Showing no emotion on the face or in manner.", "c": "面無表情的；不動聲色的", "s": "Throughout the three-hour sentencing hearing, the defendant sat impassive at the table, his face revealing neither remorse nor defiance as the victims' families read aloud statements describing how the fraud had destroyed their savings.", "t": "在長達三小時的量刑聽證會中，被告始終面無表情地坐在桌前；當受害者家屬朗讀陳述、描述這場詐騙如何毀掉他們的積蓄時，他的臉上既沒有悔意，也沒有反抗。", "as": "The diplomat remained impassive while the belligerent minister delivered his rant, and her calm restraint did more to mollify the tense delegates than any eloquence could have achieved.", "at": "當那位好戰的部長發表激烈的謾罵時，這位外交官始終不動聲色，她冷靜的克制比任何雄辯都更能安撫緊張的與會代表。"}, {"w": "indifferent", "p": "adj.", "d": "Having no interest in or concern about something.", "c": "漠不關心的；不在乎的", "s": "Economists were puzzled that consumers seemed largely indifferent to the rising price of streaming subscriptions, continuing to pay for multiple services even after successive increases, a pattern suggesting that convenience mattered more to them than cost.", "t": "經濟學家感到不解的是，消費者似乎對串流訂閱價格的上漲大多不以為意，即使價格接連調漲，仍繼續付費訂閱多個服務；這種模式顯示，對他們而言，便利比成本更重要。", "as": "The candidate's ostentatious campaign events could not disguise how indifferent he was to the penurious farmers of the region, whose quandary over falling crop prices he dismissed with a few hackneyed promises.", "at": "這位候選人鋪張浮誇的競選活動，掩蓋不了他對該地區貧困農民的漠不關心；面對農民因作物價格下跌而陷入的困境，他只用幾句陳腔濫調的承諾就打發了。"}, {"w": "remote", "p": "adj.", "d": "Distant in manner; not friendly or involved.", "c": "冷淡的；疏遠的；遙遠的", "s": "Biographers describe the composer as a remote figure even to his own children, who recalled that he spent most evenings alone in his study and spoke to them chiefly through brief notes left on the dining-room table.", "t": "傳記作家形容這位作曲家即使對自己的孩子也很疏遠；孩子們回憶說，他大多數晚上都獨自待在書房，主要是透過留在餐桌上的簡短字條跟他們說話。", "as": "The emperor grew increasingly remote from his subjects, surrounding himself with obsequious advisers and lavish palaces while the provinces descended into turmoil and adversity that he scarcely acknowledged.", "at": "這位皇帝與子民日漸疏遠，身邊圍繞著阿諛奉承的顧問與奢華的宮殿，而各省則陷入動盪與困苦，他卻幾乎不聞不問。"}, {"w": "nonchalant", "p": "adj.", "d": "Calm and casual, showing no anxiety or strong interest.", "c": "若無其事的；漫不經心的", "s": "Although the veteran pilot later admitted that his heart had been pounding, his voice on the recorded radio transmission sounded almost nonchalant as he informed air-traffic controllers that both engines had failed and that he intended to land on the river.", "t": "雖然這位資深機師事後承認當時心跳得很厲害，但在無線電通訊錄音中，他告知塔臺兩具引擎都已失效、打算降落在河面上時，聲音聽起來幾乎若無其事。", "as": "The insolent heir adopted a nonchalant attitude toward the family fortune, squandering millions on ostentatious parties as though the prodigal habits of his youth could never lead to financial ruin.", "at": "這位傲慢無禮的繼承人對家族財富抱持滿不在乎的態度，在鋪張炫耀的派對上揮霍數百萬，彷彿他年少時揮金如土的習慣永遠不會招致財務崩潰。"}, {"w": "apathetic", "p": "adj.", "d": "Showing no interest, enthusiasm, or concern.", "c": "冷漠的；無動於衷的", "s": "Political scientists studying the region found that voters were not apathetic by nature; rather, decades of rigged elections had convinced many citizens that participation was pointless, so turnout rose sharply once independent observers began monitoring the polls.", "t": "研究該地區的政治學者發現，選民並非天生冷漠；而是數十年來操縱選舉的情況讓許多公民相信參與毫無意義，因此一旦有獨立觀察員開始監督投票，投票率便大幅上升。", "as": "Teachers worry that a curriculum dominated by banal worksheets and mundane drills makes students apathetic, and they argue that even a little levity in the classroom can rekindle the curiosity such insipid lessons have extinguished.", "at": "教師們擔心，以陳腐的練習卷和枯燥的反覆操練為主的課程會讓學生變得冷漠，他們主張，課堂上即使多一點輕鬆幽默，也能重新點燃被這些乏味課程澆熄的好奇心。"}, {"w": "phlegmatic", "p": "adj.", "d": "Calm and unemotional; not easily excited or upset.", "c": "冷靜的；沉著的；遲鈍的", "s": "Ancient physicians, following the theory of the four humors, believed that an excess of phlegm produced a phlegmatic temperament, describing such people as calm, slow to anger, and unlikely to be stirred by either joy or fear.", "t": "古代醫生依循四體液說，認為黏液過多會造就冷靜沉著的氣質，並形容這樣的人平和、不易動怒，也不容易被喜悅或恐懼所觸動。", "as": "The phlegmatic engineer listened patiently to the cantankerous client's verbose complaints about delays, and his steady composure allayed the man's anger far more effectively than any argument could have done.", "at": "這位沉著冷靜的工程師耐心聽完那位脾氣暴躁的客戶對進度延誤的冗長抱怨，他穩重的態度比任何辯解都更有效地平息了對方的怒氣。"}, {"w": "aloof", "p": "adj.", "d": "Cool and distant; not friendly or forthcoming.", "c": "冷淡的；疏遠的", "s": "Classmates remembered the future physicist as aloofeduring his university years, seldom joining study groups or social gatherings, though later accounts suggested that his apparent coldness concealed an intense shyness rather than any sense of superiority.", "t": "同學們記得這位日後的物理學家在大學時代相當冷淡疏離，很少參加讀書會或社交聚會；不過後來的記述顯示，他表面上的冷漠其實掩藏著極度的害羞，而非任何優越感。", "as": "The new ambassador, whose aloof manner was often mistaken for disdain, surprised the gregarious local officials by proving remarkably cordial once they gathered at the convivial banquet held in her honor.", "at": "這位新任大使冷淡疏離的態度常被誤認為輕蔑，但在為她舉辦的歡樂宴會上，她卻表現得格外熱情親切，讓那些善於交際的地方官員大感意外。"}, {"w": "listless", "p": "adj.", "d": "Lacking energy or enthusiasm, often from illness or sadness.", "c": "無精打采的；倦怠的", "s": "Veterinarians warn that a normally playful puppy that becomes listless, refusing food and sleeping far more than usual, may be suffering from a serious infection and should be examined promptly rather than simply allowed to rest.", "t": "獸醫提醒，一隻平常活潑好動的幼犬若變得無精打采、拒絕進食且睡得比平常多很多，可能是罹患了嚴重的感染，應盡快就醫檢查，而不是只讓牠休息。", "as": "After months of adversity, the refugees appeared listless and gaunt, and aid workers knew that even a munificent shipment of supplies could only partially alleviate the hardships they had endured.", "at": "歷經數月的苦難後，難民們看起來無精打采又形容枯槁；救援人員知道，即使送來大批慷慨捐贈的物資，也只能部分減輕他們所承受的苦難。"}, {"w": "stoical", "p": "adj.", "d": "Enduring pain or hardship without complaint or visible emotion.", "c": "堅忍的；不動聲色的", "s": "Letters from Civil War soldiers often display a stoical acceptance of hardship, describing frostbite, hunger, and the deaths of close friends in calm, almost matter-of-fact language that rarely betrays the suffering the writers must have felt.", "t": "南北戰爭士兵的家書常流露出對苦難的坦然承受，他們以平靜、近乎就事論事的語氣描述凍傷、飢餓與摯友的死亡，字裡行間鮮少透露出寫信人必定感受過的痛苦。", "as": "The stoical explorer endured the austere conditions of the Antarctic winter without complaint, rationing supplies in frugal portions and refusing to let the turmoil of the storms disrupt the expedition's careful scientific work.", "at": "這位堅忍的探險家毫無怨言地忍受南極冬季的嚴酷環境，以節儉的份量配給物資，並拒絕讓暴風雪帶來的混亂打亂探險隊嚴謹的科學工作。"}, {"w": "stoic", "p": "adj.", "d": "Unaffected by passion or feeling.", "c": "堅忍的/淡然的", "s": "She remained stoic even as the doctor delivered the difficult diagnosis.", "t": "即使醫生宣布這個艱難的診斷結果,她依然表現得十分淡然堅忍。", "as": "His stoic expression gave no hint of the grief he felt inside.", "at": "他那淡然的表情絲毫沒有透露出內心的悲痛。", "a": 1}, {"w": "stolid", "p": "adj.", "d": "Expressing little sensibility, unemotional.", "c": "遲鈍的/麻木的", "s": "The stolid guard showed no reaction to the crowd's shouting.", "t": "這位面無表情的守衛對群眾的吶喊毫無反應。", "as": "Despite the chaos around him, he remained stolid and unmoved.", "at": "儘管周遭一片混亂,他仍舊麻木不為所動。", "a": 1}, {"w": "dispassionate", "p": "adj.", "d": "Not influenced by strong emotion; impartial.", "c": "冷靜客觀的;不帶感情的", "s": "The judge gave a dispassionate assessment of the evidence.", "t": "法官對證據給出了冷靜客觀的評估。", "as": "She remained dispassionate even while discussing her own case.", "at": "即使在討論自己的案件時,她仍保持不帶感情的態度。", "a": 1}, {"w": "unemotional", "p": "adj.", "d": "Not showing or influenced by emotion.", "c": "不動感情的;冷靜的", "s": "The judge remained unemotional while delivering the difficult verdict.", "t": "這位法官在宣布這項艱難的判決時始終不動聲色。", "as": "His unemotional response to the tragedy surprised his friends.", "at": "他對這場悲劇不帶感情的反應讓他的朋友們感到驚訝。", "a": 1}, {"w": "lukewarm", "p": "adj.", "d": "Moderately warm; showing little enthusiasm.", "c": "溫的;不太熱情的", "s": "He complained that the soup had gone lukewarm by the time it arrived.", "t": "他抱怨這碗湯送到時已經變得不冷不熱了。", "as": "The audience gave the performance only a lukewarm reception.", "at": "觀眾對這場表演的反應只是不太熱情。", "a": 1}, {"w": "perfunctory", "p": "adj.", "d": "Done without care, superficial.", "c": "敷衍的", "s": "He gave a perfunctory apology that didn't seem sincere at all.", "t": "他做出了一個敷衍的道歉,聽起來一點也不真誠。", "as": "The security guard did only a perfunctory check of everyone's bags.", "at": "警衛只對每個人的包包做了敷衍了事的檢查。", "a": 1}, {"w": "blasé", "p": "adj.", "d": "Indifferent, not responsive to excitement.", "c": "玩世不恭的/厭倦的", "s": "After years in the industry, she had grown blasé about celebrity encounters.", "t": "在這個產業待了多年之後,她對遇到名人已經變得不當一回事。", "as": "He seemed strangely blasé about losing his job.", "at": "他對於丟掉工作這件事顯得出奇地無動於衷。", "a": 1}, {"w": "disinterested", "p": "adj.", "d": "Not influenced by personal interest; impartial.", "c": "公正無私的", "s": "A disinterested mediator helped the two sides reach an agreement.", "t": "一位公正無私的調解人幫助雙方達成協議。", "as": "Judges must remain disinterested regardless of public opinion.", "at": "法官無論輿論如何都必須保持公正無私。", "a": 1}, {"w": "callous", "p": "adj.", "d": "Unfeeling.", "c": "冷酷無情的", "s": "His callous remarks about the tragedy shocked everyone in the room.", "t": "他對這場悲劇冷酷無情的評論震驚了在場所有人。", "as": "Years of hardship had left her feeling callous toward others' complaints.", "at": "多年的艱苦生活讓她對別人的抱怨變得冷漠無情。", "a": 1}]}, {"unit": 14, "theme": "Lazy and Sluggish", "themeZh": "懶散與遲緩", "antonymLessons": [16, 70], "cards": [{"w": "indolent", "p": "adj.", "d": "Habitually lazy and avoiding effort.", "c": "懶惰的；好逸惡勞的", "s": "Eighteenth-century reformers often portrayed the aristocracy as indolent, arguing that nobles who lived entirely on inherited rents and spent their days at cards and hunting contributed nothing to the nation's prosperity while the peasants who worked their land went hungry.", "t": "十八世紀的改革者常把貴族描繪成好逸惡勞的一群人，認為那些完全靠世襲地租過活、整天打牌狩獵的貴族對國家的繁榮毫無貢獻，而為他們耕種土地的農民卻在挨餓。", "as": "The novel satirizes an indolent prince who squanders the royal treasury on lavish banquets, surrounded by obsequious courtiers whose flattery keeps him complacent while his kingdom slides toward ruin.", "at": "這部小說諷刺一位懶散的王子，他把國庫揮霍在奢華的宴會上，身邊圍繞著阿諛奉承的朝臣，他們的諂媚讓他自滿安逸，而他的王國卻一步步走向毀滅。"}, {"w": "soporific", "p": "adj.", "d": "Tending to cause sleep or drowsiness.", "c": "催眠的；令人昏昏欲睡的", "s": "Neuroscientists studying the effects of chamomile tea found that its reputation as a soporific remedy may be partly justified, since one of its compounds binds to the same brain receptors targeted by mild sedatives, although the effect is far weaker than that of prescription medication.", "t": "研究洋甘菊茶效果的神經科學家發現，洋甘菊茶被認為有助眠功效的名聲或許有一定道理，因為其中一種化合物會與溫和鎮靜劑所作用的大腦受體結合，不過效果遠比處方藥物微弱。", "as": "The keynote speaker's soporific lecture, a verbose catalog of platitudes delivered in a monotone, left even the most avid members of the audience struggling to stay awake.", "at": "主講人那場令人昏昏欲睡的演講，以單調的語調冗長地羅列一連串陳腔濫調，連台下最熱衷的聽眾都得努力保持清醒。"}, {"w": "sedentary", "p": "adj.", "d": "Involving much sitting and little physical activity.", "c": "久坐的；不活動的；定居的", "s": "A long-term study of office workers found that those whose jobs were almost entirely sedentary faced a significantly higher risk of heart disease, even if they exercised vigorously on weekends, suggesting that long uninterrupted hours of sitting carry risks of their own.", "t": "一項針對上班族的長期研究發現，工作幾乎完全需要久坐的人罹患心臟病的風險明顯較高，即使他們週末劇烈運動也一樣；這顯示長時間不間斷地坐著本身就帶有風險。", "as": "Anthropologists contrast the sedentary farming villages of the river valley with the nomadic herders of the surrounding steppe, whose austere, itinerant way of life required them to travel with the seasons.", "at": "人類學家將河谷中定居務農的村落，與周圍草原上逐水草而居的游牧民族作對比；後者簡樸刻苦、四處遷徙的生活方式，使他們必須隨著季節移動。"}, {"w": "stagnant", "p": "adj.", "d": "Not flowing or developing; showing no activity or growth.", "c": "停滯的；不流動的；不景氣的", "s": "Economists attributed the region's stagnant wages to the closing of its steel mills, noting that although unemployment eventually declined, the new service jobs paid far less, so that median household income in 2010 was barely higher than it had been in 1980.", "t": "經濟學家將該地區薪資停滯不前歸因於鋼鐵廠的關閉，並指出雖然失業率最終下降，但新的服務業工作薪水低得多，以致2010年的家庭所得中位數僅略高於1980年。", "as": "Critics argued that the once innovative studio had grown stagnant, releasing derivative sequels and hackneyed remakes because its complacent executives preferred safe profits to creative risk.", "at": "評論家認為，這家曾經銳意創新的電影公司已經停滯不前，只推出模仿抄襲的續集和陳腐老套的翻拍片，因為自滿的高層寧可獲取穩當的利潤，也不願承擔創作上的風險。"}, {"w": "lethargic", "p": "adj.", "d": "Sluggish and drowsy, lacking energy.", "c": "昏昏欲睡的；無精打采的", "s": "Marine biologists observed that the sea turtles became increasingly lethargic as water temperatures dropped below ten degrees Celsius, floating motionless near the surface until rescuers could transport them to heated tanks for recovery.", "t": "海洋生物學家觀察到，當海水溫度降到攝氏十度以下時，海龜變得愈來愈遲緩無力，一動也不動地漂浮在海面附近，直到救援人員將牠們送往溫水池中休養。", "as": "The once ebullient student became lethargic and withdrawn during the semester, and her conscientious teacher, wary of dismissing the change as trivial, contacted the school counselor.", "at": "這位一向活潑開朗的學生在這學期變得無精打采、孤僻退縮，她那位認真負責的老師不敢把這種轉變當成小事，便聯絡了學校的輔導老師。"}, {"w": "lassitude", "p": "n.", "d": "Physical or mental weariness; a lack of energy.", "c": "倦怠；疲乏；無精打采", "s": "Medical historians note that sailors on long eighteenth-century voyages often complained of deep lassitude weeks before the more visible symptoms of scurvy appeared, a weariness that physicians initially blamed on idleness rather than on the absence of fresh fruit.", "t": "醫學史學家指出，十八世紀長途航行的水手在壞血病較明顯的症狀出現前數週，常會抱怨極度倦怠；醫生起初把這種疲乏歸咎於懶散，而非缺乏新鮮水果。", "as": "A pervasive lassitude settled over the city after the debacle of the failed revolution, and even its most zealous activists grew apathetic, convinced that further protest would only invite more turmoil.", "at": "革命失敗的慘敗之後，一股瀰漫的倦怠籠罩全城，連最狂熱的運動人士也變得冷漠，深信再抗議只會招致更多動盪。"}, {"w": "languor", "p": "n.", "d": "A pleasant or dreamy feeling of tiredness or inactivity.", "c": "慵懶；倦怠；悶熱的沉寂", "s": "Literary critics have observed that Tennessee Williams used the oppressive heat of the American South to create a mood of sensual languor in his plays, with characters lounging on porches and speaking in slow, drawn-out sentences as the afternoon stretches endlessly on.", "t": "文學評論家指出，田納西‧威廉斯利用美國南方令人窒息的炎熱，在劇作中營造出一種感官上的慵懶氛圍：劇中人物懶洋洋地倚在門廊上，用緩慢拖長的語句說話，而午後時光彷彿無止盡地延續。", "as": "The novel's opening chapters, steeped in the languor of a seaside resort, are deliberately quiescent, and some readers find this prosaic stretch insipid until the sudden turmoil of the third chapter transforms the story.", "at": "這部小說的開頭幾章充滿海濱度假勝地的慵懶氣息，刻意寫得平靜沉寂；有些讀者覺得這段平淡的篇幅索然無味，直到第三章突如其來的動盪才讓整個故事改頭換面。"}, {"w": "sluggish", "p": "adj.", "d": "Moving or responding slowly; lacking energy.", "c": "遲緩的；緩慢的；萎靡的", "s": "Analysts warned that the recovery would remain sluggish as long as interest rates stayed high, since businesses were reluctant to borrow for new factories and consumers continued to postpone major purchases such as cars and houses.", "t": "分析師警告，只要利率居高不下，經濟復甦就會持續遲緩，因為企業不願借錢興建新工廠，而消費者也繼續延後購買汽車、房屋等大件商品。", "as": "Despite lavish government subsidies intended to ameliorate the crisis, the economy remained sluggish, and frugal households, wary of further turmoil, saved rather than spent their modest incomes.", "at": "儘管政府祭出大筆補貼以改善危機，經濟依然疲軟，節儉的家庭因擔心更多動盪，選擇把微薄的收入存起來而不是花掉。"}, {"w": "torpid", "p": "adj.", "d": "Mentally or physically inactive; dormant or numb.", "c": "遲鈍的；麻木的；蟄伏的", "s": "During the coldest weeks of winter, the hummingbirds enter a torpid state each night, lowering their body temperature and heart rate dramatically to conserve energy, then gradually reviving at dawn before resuming their search for nectar.", "t": "在冬季最寒冷的幾週，蜂鳥每晚都會進入蟄伏狀態，大幅降低體溫與心跳以保存能量，然後在黎明時逐漸甦醒，再繼續尋找花蜜。", "as": "The once vibrant debate club had become torpid under an apathetic adviser, its meetings reduced to banal discussions until a new teacher revived the students' interest in rhetorical skill.", "at": "這個曾經充滿活力的辯論社在一位冷漠的指導老師帶領下變得死氣沉沉，社團聚會淪為平淡乏味的討論，直到一位新老師重新激起學生對修辭技巧的興趣。"}, {"w": "lethargy", "p": "n.", "d": "A lack of energy or enthusiasm.", "c": "無精打采;倦怠", "s": "The heat left everyone in a state of lethargy .", "t": "這股熱氣讓每個人都感到倦怠無力。", "as": "He struggled with lethargy after the long illness.", "at": "在這場長期的疾病後,他一直與倦怠感搏鬥。", "a": 1}, {"w": "inert", "p": "adj.", "d": "Without power to move.", "c": "遲鈍的/惰性的", "s": "The gas is chemically inert and does not react with other substances.", "t": "這種氣體在化學上是惰性的,不會與其他物質產生反應。", "as": "After the accident, his left arm remained inert for several weeks.", "at": "意外發生後,他的左臂有好幾週都動彈不得。", "a": 1}, {"w": "dormant", "p": "adj.", "d": "Asleep, resting.", "c": "休眠的/靜止的", "s": "The volcano had been dormant for over a century before it erupted.", "t": "這座火山在爆發前已經沉寂超過一個世紀。", "as": "Her passion for painting lay dormant for years before she picked up a brush again.", "at": "在她重新拿起畫筆之前,她對繪畫的熱情已沉寂多年。", "a": 1}, {"w": "torpor", "p": "n.", "d": "A state of physical or mental inactivity; lethargy.", "c": "遲鈍；麻木", "s": "During the extraordinarily harsh winter months, the arctic ground squirrel enters a deep state of physiological torpor to conserve energy. Its heart rate drops dramatically until the warm spring sun finally returns.", "t": "在極其嚴寒的冬季，北極地松鼠會進入一種深度的生理**麻木（冬眠）**狀態以節省能量。它的心率會急劇下降，直到溫暖的春日陽光最終回歸。", "as": "", "at": "", "a": 1}, {"w": "enervated", "p": "adj.", "d": "Drained of energy or vitality.", "c": "虛弱無力的;疲憊的", "s": "The tropical heat left the travelers feeling enervated .", "t": "熱帶的酷熱讓旅客們感到虛弱無力。", "as": "Weeks of overwork left her completely enervated .", "at": "數週的過度工作讓她感到極度疲憊。", "a": 1}]}, {"unit": 15, "theme": "Submissive and Servile", "themeZh": "順從與卑屈", "antonymLessons": [3, 17, 61], "cards": [{"w": "compliant", "p": "adj.", "d": "Willing to obey rules or yield to others' wishes.", "c": "順從的；遵從的；合規的", "s": "Regulators discovered that although the factory appeared compliant with emissions standards during scheduled inspections, its operators routinely disabled the pollution filters at night, releasing several times the legal limit of sulfur dioxide into the surrounding valley.", "t": "監管機關發現，雖然這座工廠在定期檢查時看似符合排放標準，但操作人員經常在夜間關閉污染過濾裝置，向周圍的山谷排放數倍於法定上限的二氧化硫。", "as": "The dictator preferred compliant ministers to candid ones, and his obsequious cabinet, eager to appease him, offered only grandiloquent praise while the country slid into economic turmoil.", "at": "這位獨裁者偏好順從聽話的部長，而非直言不諱的人；他那群阿諛奉承的內閣成員急於討好他，只會獻上浮誇的讚美，而國家卻逐漸陷入經濟動盪。"}, {"w": "subservient", "p": "adj.", "d": "Excessively willing to obey others; treated as less important.", "c": "屈從的；卑躬屈膝的；次要的", "s": "Feminist literary critics have argued that many Victorian novels cast women in subservient roles, portraying the ideal wife as someone who sacrificed her own ambitions and opinions in order to support the career and comfort of her husband.", "t": "女性主義文學評論家認為，許多維多利亞時代的小說都把女性塑造成屈從的角色，將理想的妻子描繪成為了支持丈夫的事業與舒適生活而犧牲自身抱負與意見的人。", "as": "Critics charged that the newspaper had become subservient to its wealthy owner, publishing lavish tributes to his allies and refusing to impugn even his most egregious decisions, a complacent stance that alienated its once loyal readers.", "at": "批評者指責這家報紙已屈從於其富有的老闆，刊登對其盟友極盡吹捧的報導，連他最惡劣的決策也不敢質疑；這種自滿的立場疏遠了原本忠實的讀者。"}, {"w": "submissive", "p": "adj.", "d": "Ready to yield to the authority or control of others.", "c": "順從的；服從的", "s": "Ethologists have observed that lower-ranking wolves display submissive behavior toward the pack's dominant pair, lowering their heads, tucking their tails, and rolling onto their backs to avoid conflicts that might otherwise result in serious injury.", "t": "研究動物行為的學者觀察到，地位較低的狼會對狼群中的主導配偶表現出順從的行為，牠們低頭、夾起尾巴，並翻身露出腹部，以避免可能導致重傷的衝突。", "as": "The once submissive colony grew increasingly bellicose after the empire imposed new taxes, and its contentious assemblies, no longer willing to placate distant officials, began openly to defy royal decrees.", "at": "帝國開徵新稅之後，這個原本順從的殖民地變得愈來愈好戰，其爭論不休的議會不再願意安撫遠方的官員，開始公然違抗王室的詔令。"}, {"w": "subordinate", "p": "adj.", "d": "Lower in rank, position, or importance.", "c": "下級的；從屬的；次要的", "s": "In the Roman army, centurions held authority over the soldiers in their units but remained subordinate to the legion's commanding officers, a carefully structured chain of command that allowed orders to travel rapidly across a force of several thousand men.", "t": "在羅馬軍隊中，百夫長對所屬部隊的士兵握有指揮權，但仍隸屬於軍團的指揮官；這種結構嚴謹的指揮體系，使命令能迅速傳達到數千人的部隊。", "as": "The general insisted that his subordinate officers remain vigilant, warning that any complacent lapse during the cease-fire could reignite the turmoil and push the region back into precarious conflict.", "at": "將軍堅持要求部屬軍官保持警覺，並警告在停火期間任何自滿的疏失，都可能再度引發動盪，使該地區重新陷入岌岌可危的衝突之中。"}, {"w": "obsequious", "p": "adj.", "d": "Too eager to please or obey; fawning.", "c": "諂媚的；奉承的", "s": "Courtiers at Versailles competed to be obsequious in the presence of Louis XIV, praising his every remark and fighting for the privilege of handing him his shirt each morning, since royal favor determined who would receive lucrative offices and pensions.", "t": "凡爾賽宮的朝臣在路易十四面前爭相獻媚，讚美他的每一句話，並爭搶每天早晨為他遞上襯衫的特權，因為國王的恩寵決定了誰能獲得肥缺與年金。", "as": "The haughty director surrounded himself with obsequious assistants who praised his most banal ideas as visionary, and this complacent circle left him unable to recognize the trite quality of his recent films.", "at": "那位傲慢的導演身邊圍繞著一群諂媚的助理，把他最平庸的點子都吹捧為高瞻遠矚；這個自滿的小圈子使他無法看清自己近期電影的陳腐。"}, {"w": "servile", "p": "adj.", "d": "Excessively eager to serve or please; slavishly obedient.", "c": "奴性的；卑屈的", "s": "The historian argued that the nineteenth-century regional parliament was largely servile, routinely approving whatever budgets the governor proposed and never once in fifty years rejecting a measure that had the support of the crown.", "t": "這位歷史學家認為，十九世紀的地方議會基本上唯命是從，例行公事般批准總督提出的任何預算，五十年來從未否決過任何一項獲王室支持的措施。", "as": "Abolitionist writers condemned the iniquitous system that forced enslaved people into servile obedience, and their impassioned eloquence helped convert many complacent Northern readers to the cause of emancipation.", "at": "廢奴主義作家譴責那個逼迫奴隸卑屈服從的不公制度，他們慷慨激昂的雄辯，使許多原本安於現狀的北方讀者轉而支持解放黑奴的運動。"}, {"w": "fawning", "p": "adj.", "d": "Displaying exaggerated flattery or affection to win favor.", "c": "阿諛奉承的；巴結的", "s": "The biography's reviewers complained that its author was too fawning toward her subject, describing the billionaire's every business decision as visionary and omitting the lawsuits, failed ventures, and labor disputes that had marked much of his career.", "t": "這本傳記的書評家批評作者對傳主過於阿諛奉承，把這位億萬富翁的每一個商業決策都描述成高瞻遠矚，卻略去了他職業生涯中屢見不鮮的訴訟、失敗的投資與勞資糾紛。", "as": "The fawning tributes that greeted the general's return were so grandiloquent and ostentatious that skeptical journalists wondered whether the celebrations were meant to disguise the debacle of his final campaign.", "at": "迎接將軍凱旋的那些阿諛奉承的頌詞是如此浮誇又鋪張，以致抱持懷疑的記者不禁懷疑，這些慶祝活動是否是為了掩飾他最後一場戰役的慘敗。"}, {"w": "slavish", "p": "adj.", "d": "Copying or obeying without any originality or independent judgment.", "c": "盲從的；毫無創意地模仿的；奴性的", "s": "Art historians have noted that many Roman sculptures are slavish copies of earlier Greek bronzes, reproducing every fold of drapery and strand of hair so faithfully that scholars use them to reconstruct originals that were melted down centuries ago.", "t": "藝術史學家指出，許多羅馬雕像是早期希臘青銅像亦步亦趨的仿製品，連衣褶與髮絲都如實複製，以致學者能利用它們重建早在幾世紀前就被熔毀的原作。", "as": "The critic dismissed the film as a slavish imitation of earlier thrillers, calling it derivative and lackluster and complaining that its hackneyed plot twists could be predicted from the opening scene.", "at": "這位影評人把這部電影貶為一味模仿早期驚悚片的作品，稱其抄襲且平淡無奇，並抱怨其陳腐老套的情節轉折從開場就能預料。"}, {"w": "sycophant", "p": "n.", "d": "A person who flatters powerful people to gain advantage.", "c": "諂媚者；馬屁精", "s": "Historians suggest that the emperor's disastrous military campaigns resulted partly from his reliance on a single sycophant who praised every plan as brilliant, while experienced generals who raised objections were quietly dismissed from court.", "t": "歷史學家認為，這位皇帝災難性的軍事行動，部分原因在於他倚賴一名把每項計畫都吹捧為英明的諂媚者，而提出異議的資深將領則被悄悄逐出朝廷。", "as": "The memoir portrays the senator's chief aide as a sycophant whose obsequious flattery and fawning loyalty concealed a devious ambition, and readers are left to wonder why so astute a politician, normally contemptuous of flattery, failed to see through him.", "at": "這本回憶錄把那位參議員的首席助理描繪成一個諂媚者，他阿諛奉承的言詞與巴結的忠誠背後隱藏著狡詐的野心，讀者不禁納悶，如此精明、平時對奉承不屑一顧的政治人物為何沒能識破他。"}, {"w": "toady", "p": "n.", "d": "A person who flatters or obeys others to win favor.", "c": "馬屁精；奉承者", "s": "In Dickens's novel, the villainous clerk Uriah Heep plays the role of a humble toady, constantly declaring how lowly he is and flattering his employer, while secretly scheming to seize control of the firm and its finances.", "t": "在狄更斯的小說中，邪惡的書記員烏利亞‧希普扮演一個謙卑的馬屁精，不斷聲稱自己有多卑微並奉承雇主，暗地裡卻密謀奪取公司及其財務的控制權。", "as": "The satirist mocked the minister as a toady to wealthy donors, a pretentious figure whose grandiloquent speeches about public service could not disguise his mercenary eagerness to reward those who funded his campaigns.", "at": "這位諷刺作家嘲諷該部長是富裕捐款人的馬屁精，一個裝腔作勢的人物，他那些關於公共服務的浮誇演說，掩蓋不了他急於回報金主的唯利是圖。"}, {"w": "obedient", "p": "adj.", "d": "Willing to comply with orders or requests.", "c": "順從的;聽話的", "s": "The well-trained dog remained obedient even amid the chaos.", "t": "這隻訓練有素的狗即使身處混亂之中依然聽話順從。", "as": "She raised her children to be respectful and obedient .", "at": "她把孩子教養得既懂得尊重又聽話順從。", "a": 1}, {"w": "deferential", "p": "adj.", "d": "Showing respect for another's authority.", "c": "恭敬的/順從的", "s": "The young intern remained deferential toward the senior staff at all times.", "t": "這位年輕實習生始終對資深員工保持恭敬的態度。", "as": "He spoke in a deferential tone whenever addressing his professor.", "at": "每次和教授說話時,他都用一種恭敬的語氣。", "a": 1}, {"w": "groveling", "p": "adj.", "d": "Behaving with excessive humility; abject.", "c": "卑躬屈膝的", "s": "His groveling apology fooled no one in the room.", "t": "他卑躬屈膝的道歉沒有騙過房裡任何一個人。", "as": "She despised his groveling attempts to win favor.", "at": "她鄙視他卑躬屈膝討好人的企圖。", "a": 1}, {"w": "ingratiating", "p": "adj.", "d": "Capable of winning favor.", "c": "討好的/諂媚的", "s": "His ingratiating smile made the customers feel instantly comfortable.", "t": "他討喜的笑容讓顧客們立刻感到自在。", "as": "She found his ingratiating compliments a little too obvious to be sincere.", "at": "她覺得他那些討好的讚美顯得太過刻意,不像是真心的。", "a": 1}, {"w": "minion", "p": "n.", "d": "A servile follower or subordinate.", "c": "走狗;下屬", "s": "The villain ordered his minion s to capture the hero.", "t": "這位反派命令他的走狗們去抓住這位英雄。", "as": "He surrounded himself with loyal minion s who never questioned him.", "at": "他身邊圍繞著從不質疑他的忠實部下。", "a": 1}]}, {"unit": 16, "theme": "Enthusiasm and Passion", "themeZh": "熱情與狂熱", "antonymLessons": [13, 14], "cards": [{"w": "ebullient", "p": "adj.", "d": "Overflowing with cheerful excitement and enthusiasm.", "c": "熱情洋溢的；興高采烈的", "s": "Although the mission scientists had braced themselves for a failed landing, they were ebullient when the rover's first panoramic images arrived intact, hugging one another, cheering across the control room, and staying long past midnight to pore over every crater and ridge.", "t": "儘管任務科學家們早已做好登陸失敗的心理準備，但當探測車傳回的第一批全景影像完好無損地抵達時，他們仍興高采烈，在控制室裡相互擁抱、歡呼，並一直待到午夜過後，仔細端詳每一座隕石坑與每一道山脊。", "as": "The usually taciturn conductor became surprisingly ebullient after the premiere, abandoning his aloof manner to greet the musicians with jocular praise, though critics later found the symphony itself disappointingly derivative of Mahler.", "at": "平時沉默寡言的指揮家在首演後出乎意料地興高采烈，一改冷漠疏離的態度，以詼諧的讚美向樂手們致意；不過，評論家後來認為這首交響曲本身過度模仿馬勒，令人失望。"}, {"w": "effervescent", "p": "adj.", "d": "Lively, bubbly, and full of high spirits.", "c": "活潑的；興高采烈的；冒泡的", "s": "Reviewers agreed that the actress's effervescent performance was the production's saving grace; whenever she bounded onto the stage, her sparkling wit and infectious laughter revived an audience that had been nodding off through the play's long, ponderous philosophical monologues.", "t": "評論家一致認為，那位女演員活潑洋溢的演出是整齣戲的救星；每當她輕快地跳上舞台，她妙語如珠的機智與富感染力的笑聲，總能喚醒那些在冗長沉悶的哲學獨白中打瞌睡的觀眾。", "as": "Unlike her taciturn predecessor, the new museum director was effervescent and gregarious, and her convivial gala dinners quickly mollified donors who had grown indifferent to the institution's long run of lackluster exhibitions.", "at": "與沉默寡言的前任不同，新任博物館館長活潑開朗、喜好交際，她所舉辦的歡樂晚宴很快就安撫了那些因長期乏善可陳的展覽而變得漠不關心的捐款人。"}, {"w": "exuberant", "p": "adj.", "d": "Full of energy, excitement, and cheerful high spirits.", "c": "熱情奔放的；精力充沛的", "s": "The anthropologist described the harvest festival as the village's most exuberant event of the year: after months of austere rationing, residents danced through the streets until dawn, sang improvised songs, and showered one another with flower petals and rice.", "t": "那位人類學家形容，豐收祭是村裡一年中最熱情奔放的盛事：在經歷數月的嚴格配給後，村民們在街上跳舞直到天亮，即興高歌，並彼此拋撒花瓣與米粒。", "as": "The coach's exuberant celebration after the upset victory struck some reporters as ostentatious, yet it helped dispel the lethargic mood and pervasive animosity that had plagued the locker room throughout a season of adversity.", "at": "教練在爆冷勝利後熱情奔放的慶祝，在部分記者看來過於張揚，但這確實驅散了整個逆境賽季中籠罩更衣室的萎靡氣氛與普遍的敵意。"}, {"w": "impassioned", "p": "adj.", "d": "Filled with or showing intense, strong feeling.", "c": "慷慨激昂的；充滿激情的", "s": "In her impassioned address to the United Nations, the climate scientist abandoned the cautious language of her published papers, pounding the lectern as she warned delegates that their grandchildren would judge them harshly for every year of delay in cutting carbon emissions.", "t": "在對聯合國發表的慷慨激昂演說中，這位氣候科學家拋開了她學術論文中謹慎的措辭，一邊捶打講台，一邊警告各國代表：他們的孫輩將會為減碳行動每拖延一年而嚴厲批判他們。", "as": "Frederick Douglass's impassioned oratory did not merely castigate slaveholders; his eloquence also shamed the complacent Northerners who claimed to oppose slavery in principle while remaining indifferent to its daily cruelties.", "at": "弗雷德里克・道格拉斯慷慨激昂的演說不僅嚴厲譴責了奴隸主；他的雄辯也讓那些自滿的北方人無地自容——他們聲稱原則上反對奴隸制，卻對奴隸每日所受的殘酷對待漠不關心。"}, {"w": "avid", "p": "adj.", "d": "Extremely eager and enthusiastic about an interest or pursuit.", "c": "熱衷的；渴望的", "s": "Thomas Jefferson was so avid a collector of books that after the British burned the Library of Congress in 1814, he was able to replace its holdings by selling the nation more than six thousand volumes from his personal library at Monticello.", "t": "湯瑪斯・傑佛遜是一位極為熱衷的藏書家，以至於英軍在1814年焚毀國會圖書館後，他能將蒙蒂塞洛私人圖書館中六千多冊藏書賣給國家，以補足館藏。", "as": "An avid birdwatcher, the retired judge was usually reticent and somewhat aloof at dinner parties, but any mention of migratory warblers made him so voluble that guests struggled to steer the conversation elsewhere.", "at": "這位退休法官是熱衷的賞鳥人，在晚宴上通常沉默寡言、有些疏離，但只要一提到遷徙的林鶯，他就變得滔滔不絕，讓賓客們難以把話題轉到別處。"}, {"w": "zealous", "p": "adj.", "d": "Showing intense, sometimes excessive, devotion to a cause.", "c": "熱心的；狂熱的", "s": "The prosecutor was so zealous in pursuing the corruption case that she worked through holidays, personally reviewed tens of thousands of bank records, and was eventually reprimanded by the court for pressing witnesses too aggressively in her determination to secure a conviction.", "t": "那位檢察官在追查這起貪腐案時極為狂熱，連假日都在工作，親自審閱了數萬筆銀行紀錄，最後甚至因一心想將被告定罪、過度強硬地逼問證人而遭法院申誡。", "as": "Zealous reformers of the Progressive Era did not merely deprecate the nefarious practices of urban political machines; they also censured the complacent voters whose apathetic acceptance of bribery allowed corruption to flourish.", "at": "進步時代熱忱的改革者不僅抨擊城市政治機器的卑劣行徑，也譴責那些自滿的選民——正是他們對賄賂漠然接受的態度，讓貪腐得以猖獗。"}, {"w": "ardent", "p": "adj.", "d": "Intensely enthusiastic, devoted, or passionate.", "c": "熱烈的；熱心的", "s": "Although she was an ardent supporter of women's suffrage from her teenage years, the novelist refused to march in public demonstrations, preferring instead to channel her passion into pamphlets and fiction that she believed would change more minds than any parade.", "t": "儘管這位小說家從青少年時期就是婦女參政權的熱烈支持者，她卻拒絕參加公開遊行，寧願將熱情投注於小冊子與小說的創作，她相信這些作品比任何遊行都更能改變人心。", "as": "Even ardent admirers of the senator conceded that his speeches had grown verbose and his arguments increasingly hackneyed, though few dared to rebuke him openly, given his belligerent reaction to earlier critics.", "at": "即使是這位參議員最熱烈的仰慕者也承認，他的演講變得冗長，論點也愈來愈陳腐；不過，鑑於他先前對批評者的好鬥反應，很少有人敢公開指責他。"}, {"w": "fanatical", "p": "adj.", "d": "Filled with extreme, unreasoning enthusiasm or devotion.", "c": "狂熱的；盲信的", "s": "According to the sociologist's case study, the cult's leader demanded fanatical loyalty from his followers, insisting that they cut off all contact with relatives, surrender their savings to the group, and accept without question his increasingly bizarre predictions about the imminent end of the world.", "t": "根據那位社會學家的個案研究，該邪教領袖要求追隨者展現狂熱的忠誠，堅持要他們斷絕與親人的一切聯繫、將積蓄全數交給團體，並毫不質疑地接受他對世界末日即將來臨所做出、愈來愈離奇的預言。", "as": "The historian argues that the regime's fanatical propaganda thrived on animosity toward outsiders, transforming ordinary citizens into belligerent zealots and rendering moderate voices so subservient that no one dared to impugn official policy.", "at": "這位歷史學家認為，該政權狂熱的宣傳靠煽動對外人的敵意而壯大，把普通百姓變成好戰的狂熱分子，並使溫和派變得唯唯諾諾，沒有人敢質疑官方政策。"}, {"w": "fervent", "p": "adj.", "d": "Showing intense, sincere, and passionate feeling.", "c": "熱切的；熱誠的", "s": "Despite repeated failures, the Wright brothers maintained a fervent belief that powered flight was achievable, and that conviction sustained them through years of crashed gliders, ridicule from the press, and painstaking wind-tunnel experiments in their modest Dayton bicycle shop.", "t": "儘管一再失敗，萊特兄弟始終熱切地相信動力飛行是可以實現的；正是這份信念，支撐他們熬過多年來滑翔機墜毀、媒體嘲諷，以及在代頓那間簡樸自行車店裡進行的艱辛風洞實驗。", "as": "Despite her fervent plea for compromise, the mediator could not placate either delegation, and the contentious negotiations soon collapsed into a debacle that left both nations in a precarious position.", "at": "儘管調解人熱切呼籲雙方妥協，她仍無法安撫任何一方代表團；這場爭議不斷的談判很快就徹底破局，讓兩國都陷入岌岌可危的處境。"}, {"w": "vibrant", "p": "adj.", "d": "Full of energy, life, and activity.", "c": "充滿活力的；生氣勃勃的", "s": "Urban planners credit the conversion of abandoned warehouses into studios, cafés, and music venues with transforming the once-deserted riverfront into a vibrant neighborhood where street markets, festivals, and late-night crowds now fill sidewalks that were empty only a decade ago.", "t": "都市規劃者認為，將廢棄倉庫改建為工作室、咖啡館和音樂表演場地，使曾經冷清的河濱地區轉變為充滿活力的街區；如今，街頭市集、節慶活動和深夜人潮擠滿了十年前還空無一人的人行道。", "as": "Once stagnant and sluggish, the port city's economy has become vibrant again, though critics warn that the lavish spending fueling its revival could prove detrimental if interest rates rise sharply.", "at": "這座港口城市的經濟曾經停滯不前、萎靡不振，如今再度充滿活力；不過批評者警告，若利率急遽上升，推動其復甦的大手筆支出可能會帶來不利影響。"}, {"w": "passionate", "p": "adj.", "d": "Showing strong feelings or enthusiasm.", "c": "熱情的;充滿激情的", "s": "She has always been passionate about protecting endangered species.", "t": "她一直對保護瀕危物種充滿熱情。", "as": "His passionate speech moved the entire audience to tears.", "at": "他充滿激情的演講讓全場觀眾都感動落淚。", "a": 1}, {"w": "energetic", "p": "adj.", "d": "Showing or involving great activity or vitality.", "c": "精力充沛的;充滿活力的", "s": "The energetic puppy ran circles around the yard.", "t": "這隻精力充沛的小狗在院子裡繞圈奔跑。", "as": "Her energetic leadership revitalized the struggling team.", "at": "她充滿活力的領導讓這支陷入困境的隊伍重新振作。", "a": 1}, {"w": "exhilarated", "p": "adj.", "d": "Filled with joy or excitement.", "c": "興奮的/振奮的", "s": "She felt exhilarated after completing her first marathon.", "t": "完成她的第一場馬拉松後,她感到振奮不已。", "as": "The children were exhilarated by their first roller coaster ride.", "at": "孩子們因第一次搭乘雲霄飛車而興奮不已。", "a": 1}, {"w": "gusto", "p": "n.", "d": "Enthusiasm, enjoyment, zest.", "c": "熱情/津津有味", "s": "He dug into the meal with great gusto.", "t": "他津津有味地大快朵頤這頓飯。", "as": "She sang the old folk song with tremendous gusto.", "at": "她以無比的熱情演唱了這首古老的民謠。", "a": 1}, {"w": "zeal", "p": "n.", "d": "Great energy or enthusiasm in pursuit of a cause or goal.", "c": "熱忱;熱情", "s": "She pursued her research with remarkable zeal .", "t": "她以驚人的熱忱投入她的研究。", "as": "His zeal for the cause inspired an entire generation of activists.", "at": "他對這項理念的熱忱激勵了整整一代的社運人士。", "a": 1}, {"w": "rapturous", "p": "adj.", "d": "Characterized by intense pleasure or enthusiasm.", "c": "狂喜的;興高采烈的", "s": "The performance received a rapturous standing ovation from the crowd.", "t": "這場表演贏得了觀眾狂喜的起立喝彩。", "as": "Her rapturousedescription of the vacation made everyone want to visit.", "at": "她對這趟假期興高采烈的描述讓每個人都想去那裡看看。", "a": 1}]}, {"unit": 17, "theme": "Stubbornness and Determination", "themeZh": "固執與堅定", "antonymLessons": [15, 88], "cards": [{"w": "intractable", "p": "adj.", "d": "Hard to control, manage, or solve.", "c": "難處理的；難駕馭的；棘手的", "s": "For more than three centuries, Fermat's Last Theorem remained one of the most intractable problems in mathematics, defeating generations of brilliant scholars until Andrew Wiles finally produced a proof in 1994 that drew on branches of the field Fermat himself could never have imagined.", "t": "三個多世紀以來，費馬最後定理一直是數學界最棘手的難題之一，難倒了一代又一代的傑出學者，直到1994年安德魯・懷爾斯才終於提出證明，而他所運用的數學分支是費馬本人當年無法想像的。", "as": "The border dispute proved intractable: each attempt to mediate collapsed amid mutual animosity, and even the most conciliatory proposals were rebuffed by delegates too belligerent to accept any compromise, however modest.", "at": "這場邊界爭端證明極為棘手：每一次調停嘗試都在雙方的敵意中破局，即使是最具和解誠意的提案，也被那些過於好戰、不願接受任何妥協（無論多麼微小）的代表斷然拒絕。"}, {"w": "recalcitrant", "p": "adj.", "d": "Stubbornly refusing to obey authority or rules.", "c": "桀驁不馴的；頑抗的", "s": "When several recalcitrant provinces refused to collect the new imperial tax and openly ignored repeated summonses to the capital, the emperor dispatched troops to enforce compliance, a decision that historians believe accelerated the dynasty's eventual collapse.", "t": "當數個頑抗的省份拒絕徵收新的帝國稅，並公然無視朝廷一再召見時，皇帝派遣軍隊強制他們服從；歷史學家認為，這項決定加速了王朝最終的覆滅。", "as": "The headmaster tried to placate the recalcitrant students with concessions, but his conciliatory tone only emboldened them, and their insolent defiance soon gave way to open turmoil throughout the school.", "at": "校長試圖以讓步來安撫那些桀驁不馴的學生，但他和解的語氣反而助長了他們的氣焰；他們傲慢無禮的反抗很快演變成全校的公開騷亂。"}, {"w": "resolve", "p": "n.", "d": "Firm determination to do something.", "c": "決心；堅定", "s": "During the Blitz, German planners assumed that months of nightly bombing would break British resolve, yet surveys of Londoners revealed the opposite: civilians who had lost their homes often became more determined than ever to continue the war.", "t": "在倫敦大轟炸期間，德國的策劃者認為，連續數月的夜間轟炸將會擊垮英國人的決心，然而對倫敦市民的調查卻顯示了相反的結果：失去家園的平民往往比以往更加堅定地要將戰爭打下去。", "as": "Facing adversity that would have left most explorers listless and apathetic, Shackleton's crew drew strength from his quiet resolve, and his stoical leadership helped quell the despair that threatened to overwhelm them on the ice.", "at": "面對足以讓大多數探險家萎靡不振、心灰意冷的逆境，沙克爾頓的船員從他沉靜的決心中汲取力量；他堅忍的領導平息了那股幾乎在冰原上將他們吞噬的絕望。"}, {"w": "unwavering", "p": "adj.", "d": "Steady and firm; not changing or weakening.", "c": "堅定不移的；不動搖的", "s": "Marie Curie's unwavering commitment to her research sustained her through years of grinding labor in a leaky shed, where she processed tons of pitchblende by hand to isolate a fraction of a gram of radium, despite poverty, illness, and the skepticism of colleagues.", "t": "瑪麗・居禮對研究堅定不移的投入，支撐她在一間漏水的棚屋裡度過多年辛苦的勞動；她在那裡以人工處理數噸瀝青鈾礦，只為分離出不到一公克的鐳，儘管她當時面臨貧困、疾病與同僚的質疑。", "as": "Throughout the contentious three-week trial, the defense attorney showed unwavering composure, refusing to be provoked by the prosecutor's pugnacious questioning and calmly allaying the jury's doubts about her client's character.", "at": "在為期三週、爭議激烈的審判中，辯護律師展現出堅定不移的沉著，拒絕被檢察官咄咄逼人的質詢激怒，並冷靜地消除了陪審團對她當事人品格的疑慮。"}, {"w": "unyielding", "p": "adj.", "d": "Firm and inflexible; refusing to give way.", "c": "不屈服的；堅硬的", "s": "Although the striking miners offered to accept a smaller wage increase, the company's directors remained unyielding, insisting that no concessions of any kind would be made until every worker had returned to the pits and signed the original contract.", "t": "儘管罷工的礦工願意接受較小幅度的加薪，公司董事們仍毫不讓步，堅持在每位工人都回到礦坑並簽下原合約之前，絕不做出任何形式的讓步。", "as": "The magistrate's unyielding opposition to clemency dismayed reformers, who had hoped that a more benevolent approach would ameliorate overcrowded prisons, but who instead found their appeals rebuffed with disdainful brevity.", "at": "這位法官對寬恕毫不讓步的反對態度令改革者們失望；他們原本希望以較仁慈的方式改善監獄擁擠的問題，結果他們的請求卻被以輕蔑的簡短回應斷然拒絕。"}, {"w": "obdurate", "p": "adj.", "d": "Stubbornly refusing to change one's opinion or feelings.", "c": "執拗的；冷酷無情的", "s": "In Dickens's novel, Ebenezer Scrooge remains obdurate in the face of every appeal to his conscience, rejecting charity collectors, his nephew's warm invitations, and his clerk's modest needs, until a series of ghostly visitors finally softens his hardened heart.", "t": "在狄更斯的小說中，艾比尼澤・史古基面對每一次對他良心的呼喚都冷酷不為所動，拒絕了慈善募款人、他外甥熱情的邀請以及他書記員微薄的需求，直到一連串幽靈來訪，才終於軟化了他那顆冷硬的心。", "as": "No amount of eloquence from the community's advocates could sway the obdurate committee chair, whose disdainful dismissal of the report's findings struck observers as both arrogant and detrimental to the agency's credibility.", "at": "社區倡議者再怎麼雄辯，也無法動搖那位執拗的委員會主席；他對報告結論的輕蔑否定，在旁觀者看來既傲慢，又有損該機構的公信力。"}, {"w": "obstinate", "p": "adj.", "d": "Stubbornly refusing to change one's opinion or course.", "c": "固執的；頑固的", "s": "Historians often fault the general's obstinate refusal to retreat; even after his scouts reported that the enemy outnumbered his forces three to one, he insisted on holding the exposed ridge, a choice that cost thousands of lives in a single afternoon.", "t": "歷史學家常常歸咎於那位將軍固執地拒絕撤退；即使他的斥候回報敵軍兵力是己方的三倍，他仍堅持死守那道毫無掩護的山脊，這個決定在一個下午就斷送了數千條性命。", "as": "The obstinate patient refused to modify his sedentary habits, dismissing his cardiologist's repeated warnings as banal platitudes, even though, by every measure, his indolent lifestyle was detrimental to his failing heart.", "at": "那位固執的病人拒絕改變久坐不動的習慣，把心臟科醫師一再的警告當作陳腔濫調而不予理會，儘管從各方面看來，他懶散的生活方式顯然對他日漸衰弱的心臟有害。"}, {"w": "adamant", "p": "adj.", "d": "Refusing to be persuaded or to change one's mind.", "c": "堅決的；堅定不移的", "s": "Although her editor urged her to soften the controversial final chapter, the biographer was adamant that it remain unchanged, arguing that removing evidence of the statesman's private cruelty would betray both the historical record and the readers who trusted her scholarship.", "t": "儘管編輯力勸她緩和爭議性的最後一章，這位傳記作家仍堅決不讓它有任何更動，她認為刪除那位政治家私下殘酷行為的證據，既背叛了歷史記錄，也辜負了信任她學術研究的讀者。", "as": "The chief engineer was adamant that the bridge was unsafe, and her terse report castigated managers whose complacent neglect of routine inspections had left the structure in a precarious state.", "at": "總工程師堅稱這座橋並不安全，她簡短的報告嚴厲指責管理階層，正是他們自滿而疏於例行檢查，才讓這座結構處於岌岌可危的狀態。"}, {"w": "dogged", "p": "adj.", "d": "Showing persistent, tenacious determination despite difficulty.", "c": "頑強的；堅持不懈的", "s": "The investigative reporters' dogged pursuit of the story lasted nearly two years; they filed hundreds of public-records requests, tracked down former employees in four countries, and persisted even after the company threatened lawsuits, until their articles finally exposed the fraud.", "t": "那幾位調查記者頑強地追查這則新聞將近兩年；他們提出數百件公開資料申請，在四個國家追查前員工的下落，即使公司威脅提告也不罷休，直到他們的報導終於揭露了這起詐欺案。", "as": "Through dogged archival research, the historian unraveled the enigma of the cryptic letters, revealing that a devious official had used coded messages to conceal his nefarious dealings with foreign agents.", "at": "憑藉頑強不懈的檔案研究，這位歷史學家解開了那些神祕信件之謎，揭示一名狡詐的官員曾利用密碼訊息來掩飾他與外國特務之間的不法勾當。"}, {"w": "hidebound", "p": "adj.", "d": "Narrow-minded and stubbornly resistant to new ideas.", "c": "守舊的；墨守成規的", "s": "The Impressionists were rejected by the Paris Salon, a hidebound institution whose judges insisted that serious art must depict historical or mythological subjects in smooth, polished brushwork and dismissed loose, sunlit scenes of everyday life as unfinished sketches.", "t": "印象派畫家遭到巴黎沙龍拒絕；這是一個墨守成規的機構，其評審堅持嚴肅的藝術必須以平滑精緻的筆觸描繪歷史或神話題材，並將描繪日常生活、筆觸鬆散、灑滿陽光的畫面貶斥為未完成的草稿。", "as": "Critics castigated the hidebound academy for its supercilious contempt toward young composers, arguing that its rigid insistence on hackneyed forms had made its concerts as insipid as they were predictable.", "at": "評論家嚴厲抨擊這所守舊的學院對年輕作曲家抱持傲慢的輕視，認為它死守陳腐的形式，使得其音樂會既乏味又可預料。"}, {"w": "willful", "p": "adj.", "d": "Stubbornly determined to do as one wishes, ignoring others.", "c": "任性的；固執己見的", "s": "Historians of the Tudor court describe the young Henry VIII as a willful prince who ignored the counsel of his father's experienced ministers, insisted on lavish tournaments the treasury could not afford, and punished anyone who dared to question his personal wishes.", "t": "研究都鐸宮廷的歷史學家形容，年輕的亨利八世是一位任性的君主，他無視父王身邊經驗豐富的大臣們的勸告，堅持舉辦國庫負擔不起的奢華比武大會，並懲罰任何膽敢質疑他個人意願的人。", "as": "The willful heiress rebuffed every warning from the family's trustees, squandering her inheritance on ostentatious mansions and reacting with insolent contempt whenever advisers urged her to adopt a more frugal lifestyle.", "at": "那位任性的女繼承人斷然拒絕家族信託人的每一次警告，把遺產揮霍在浮誇的豪宅上，每當顧問勸她改採較節儉的生活方式時，她都以傲慢無禮的輕蔑回應。"}, {"w": "stubborn", "p": "adj.", "d": "Refusing to change one's mind or course of action.", "c": "頑固的;固執的", "s": "He remained stubbornedespite everyone's advice to reconsider.", "t": "儘管大家都建議他重新考慮,他仍然十分固執。", "as": "The stubborn stain refused to come out even after several washes.", "at": "這個頑固的污漬即使洗了好幾次也依然去不掉。", "a": 1}, {"w": "tenacious", "p": "adj.", "d": "Tending to keep a firm hold of something; persistent.", "c": "堅韌不拔的；頑強的", "s": "Thanks to her tenacious efforts, the investigative journalist uncovered the corporate fraud that others ignored.", "t": "多虧了她「堅韌不拔的（頑強的）」努力，這位調查記者揭露了其他人忽略的企業詐欺行為。", "as": "", "at": "", "a": 1}, {"w": "relentless", "p": "adj.", "d": "Continuing without pause or weakening; persistent.", "c": "無情的;不懈的", "s": "The relentless rain flooded streets throughout the entire city.", "t": "這場無情的大雨淹沒了整座城市的街道。", "as": "Her relentless pursuit of justice eventually exposed the fraud.", "at": "她不懈的追求正義最終揭露了這起詐欺案。", "a": 1}, {"w": "inexorable", "p": "adj.", "d": "Inflexible, unrelenting.", "c": "無情的/不可阻擋的", "s": "The inexorable march of time cannot be stopped by anyone.", "t": "時間無情的腳步無人能夠阻擋。", "as": "Despite their efforts, the inexorable rise in prices continued.", "at": "儘管他們努力設法,物價無情的上漲仍舊持續。", "a": 1}, {"w": "indomitable", "p": "adj.", "d": "Not capable of being conquered.", "c": "不屈不撓的/難以征服的", "s": "Her indomitable spirit carried her through years of hardship.", "t": "她不屈不撓的精神支撐她度過了多年的艱難歲月。", "as": "The small nation's indomitable resistance surprised the invading army.", "at": "這個小國不屈不撓的抵抗讓入侵的軍隊大感意外。", "a": 1}, {"w": "headstrong", "p": "adj.", "d": "Stubbornly determined to have one's own way.", "c": "固執的;任性的", "s": "The headstrong teenager refused to listen to any advice.", "t": "這位固執的青少年拒絕聽取任何建議。", "as": "Her headstrong nature made negotiation difficult.", "at": "她任性固執的性格讓談判變得困難。", "a": 1}, {"w": "intransigent", "p": "adj.", "d": "Refusing to compromise, often on an extreme opinion.", "c": "不妥協的/頑固的", "s": "Negotiations stalled because both sides remained completely intransigent.", "t": "由於雙方都堅持不肯妥協,談判陷入了僵局。", "as": "Her intransigent stance on the issue frustrated even her closest allies.", "at": "她在這個議題上不肯讓步的立場,讓連她最親近的盟友都感到沮喪。", "a": 1}, {"w": "resolute", "p": "adj.", "d": "Firm, determined.", "c": "堅定的/果決的", "s": "She remained resolute in her decision despite pressure from her family.", "t": "儘管家人施壓,她仍對自己的決定堅定不移。", "as": "His resolute leadership helped the team through its most difficult season.", "at": "他堅定果決的領導,帶領球隊度過了最艱難的一個賽季。", "a": 1}]}, {"unit": 18, "theme": "Sound and Noise", "themeZh": "聲音與噪音", "antonymLessons": [], "cards": [{"w": "discordant", "p": "adj.", "d": "Harsh and inharmonious in sound; lacking agreement.", "c": "不和諧的；不一致的", "s": "When Stravinsky's The Rite of Spring premiered in Paris in 1913, many listeners found its clashing harmonies and jagged rhythms so discordant that they jeered, whistled, and shouted until the dancers could barely hear the orchestra over the uproar.", "t": "1913年史特拉汶斯基的《春之祭》在巴黎首演時，許多聽眾覺得它衝突的和聲與參差的節奏極不和諧，於是噓聲、口哨聲與叫喊聲此起彼落，喧鬧到舞者幾乎聽不見樂團的演奏。", "as": "The panel's final report was a discordant document, with each chapter reflecting the contentious views of a different faction, and reviewers complained that its verbose prose and cryptic conclusions only deepened the public's turmoil.", "at": "該小組的最終報告是一份內容互相矛盾的文件，每一章都反映了不同派系的爭議性觀點；審閱者抱怨其冗長的文字與晦澀的結論，只加深了大眾的混亂。"}, {"w": "euphony", "p": "n.", "d": "A pleasing, harmonious combination of sounds.", "c": "悅耳的聲音；和諧音調", "s": "Linguists have long debated why Italian is so often praised for its euphony, with many pointing to its abundance of open vowels, its avoidance of harsh consonant clusters, and the way most words end on a soft, singable syllable.", "t": "語言學家長期爭論，為何義大利語常因其悅耳的音韻而備受讚譽；許多人指出，這是因為它擁有大量開口母音、避免刺耳的子音連綴，而且大多數單字都以柔和、易於吟唱的音節結尾。", "as": "Tennyson's verse was widely admired for its euphony, yet some Modernist critics deprecated it as vapid and grandiloquent, arguing that the poet's sonorous lines often disguised trite sentiments beneath their polished music.", "at": "丁尼生的詩作以音韻和諧而廣受讚賞，但部分現代主義評論家批評其空洞浮誇，認為這位詩人鏗鏘悅耳的詩句常常以精緻的音樂性掩飾老套的情感。"}, {"w": "cacophony", "p": "n.", "d": "A harsh, jarring mixture of loud sounds.", "c": "刺耳的噪音；不和諧音", "s": "Marine biologists warn that the cacophony produced by cargo ships, sonar systems, and offshore drilling now drowns out the low-frequency songs whales use to locate mates across hundreds of kilometers of open ocean, potentially disrupting entire breeding populations.", "t": "海洋生物學家警告，貨輪、聲納系統和離岸鑽探所產生的刺耳噪音，如今已淹沒了鯨魚用來在數百公里開闊海域中尋找配偶的低頻歌聲，可能擾亂整個繁殖族群。", "as": "The trading floor's cacophony seemed to mirror the turmoil in global markets, as brokers who were usually nonchalant shouted frantic orders, and even the most phlegmatic analysts struggled to stay detached.", "at": "交易大廳的嘈雜喧囂似乎正映照出全球市場的動盪；平時從容自若的經紀人大聲喊出慌亂的指令，即使是最沉著冷靜的分析師也難以保持超然。"}, {"w": "vociferous", "p": "adj.", "d": "Expressing opinions loudly and forcefully.", "c": "大聲疾呼的；喧嚷的", "s": "The proposal to build a highway through the wetlands met vociferous opposition from local residents, who packed every public hearing, chanted slogans outside city hall, and flooded council members' offices with thousands of angry letters and phone calls.", "t": "在濕地上興建高速公路的提案遭到當地居民大聲疾呼的反對；他們擠滿每一場公聽會，在市政廳外高喊口號，並以成千上萬封憤怒的信件和電話淹沒市議員的辦公室。", "as": "The vociferous critic, notorious for his pugnacious reviews, berated the playwright for relying on hackneyed plots, though readers increasingly found his own rants as predictable as the dramas he condemned.", "at": "這位以好鬥書評聞名、大聲疾呼的評論家，痛斥那位劇作家依賴陳腐的情節；然而讀者愈來愈覺得，他自己的咆哮就和他所譴責的戲劇一樣老套可預測。"}, {"w": "strident", "p": "adj.", "d": "Loud, harsh, and grating; forcefully assertive.", "c": "刺耳的；尖銳強硬的", "s": "Historians note that the abolitionist newspaper's strident tone, which denounced slaveholders as criminals and refused any gradual compromise, alienated many moderate Northern readers even as it energized activists who believed polite persuasion had already failed.", "t": "歷史學家指出，這份廢奴主義報紙尖銳強硬的語氣——將奴隸主斥為罪犯並拒絕任何漸進式的妥協——疏遠了許多溫和的北方讀者，但同時也激勵了那些認為禮貌勸說早已失敗的運動人士。", "as": "The candidate's strident attacks on her rivals struck many voters as belligerent, and her advisers urged her to adopt a more cordial tone to mollify the moderates she had alienated.", "at": "這位候選人對對手的尖銳攻擊讓許多選民覺得太過好鬥，她的顧問們力勸她採取較為親切友善的語氣，以安撫那些被她疏遠的溫和派選民。"}, {"w": "raucous", "p": "adj.", "d": "Making a harsh, loud, and disorderly noise.", "c": "喧鬧的；沙啞刺耳的", "s": "Shakespeare's original audiences at the Globe were famously raucous: the groundlings who paid a penny to stand near the stage cracked nuts, heckled the actors, cheered sword fights, and shouted insults at villains throughout the performance.", "t": "莎士比亞在環球劇場的原始觀眾以喧鬧著稱：那些付一便士站在舞台旁的平民觀眾，在整場演出中嗑堅果、起鬨嘲弄演員、為劍鬥喝采，並對劇中的反派大聲咒罵。", "as": "The once raucous tavern had become quiescent, its gregarious regulars replaced by a few lethargic patrons who sat in silence, a change the owner blamed on the town's economic adversity.", "at": "那家曾經喧鬧不已的酒館如今變得一片沉寂，原本愛交際的常客被幾位無精打采、默默坐著的客人所取代；老闆將這樣的改變歸咎於小鎮的經濟困境。"}, {"w": "acoustics", "p": "n.", "d": "The qualities of a room that determine how sound carries.", "c": "音響效果；聲學", "s": "Architects designing the new concert hall consulted physicists for two years, testing the curved ceiling panels and adjustable wall baffles until the acoustics allowed a single violin to be heard clearly from the farthest seat in the upper balcony.", "t": "設計新音樂廳的建築師花了兩年時間諮詢物理學家，測試弧形天花板面板與可調式牆面隔音板，直到音響效果好到讓樓上包廂最遠的座位也能清楚聽見一把小提琴的聲音。", "as": "Despite the cathedral's superb acoustics, the visiting choir gave a lackluster, insipid performance, and the organist's ostentatious solos only underscored how little the singers seemed to care about the music they were performing.", "at": "儘管大教堂的音響效果絕佳，來訪的合唱團卻演出得平淡乏味，而管風琴手炫技的獨奏更凸顯出歌手們似乎對自己演唱的音樂有多麼不用心。"}, {"w": "clamor", "p": "n.", "d": "A loud, confused noise, especially of shouting voices.", "c": "喧鬧聲；強烈要求", "s": "As word spread that the Bastille had fallen, the clamor in the streets of Paris grew so loud that residents miles away reported hearing church bells, musket fire, and thousands of voices shouting for liberty throughout the night of July 14, 1789.", "t": "隨著巴士底監獄陷落的消息傳開，巴黎街頭的喧鬧聲愈來愈大，數英里外的居民都表示，在1789年7月14日整夜聽見教堂鐘聲、火槍聲，以及成千上萬人高呼自由的聲音。", "as": "Amid the clamor of protest, the governor tried to placate demonstrators with vague promises, but his evasive circumlocution only intensified their animosity toward an administration they considered both arrogant and remote.", "at": "在一片抗議的喧囂聲中，州長試圖以含糊的承諾來安撫示威者，但他閃爍其詞的拐彎抹角只加深了他們對這個既傲慢又疏離的政府的敵意。"}, {"w": "din", "p": "n.", "d": "A loud, continuous, and unpleasant noise.", "c": "持續的喧囂聲；嘈雜聲", "s": "Researchers studying classrooms located near major airports found that the constant din of jet engines overhead reduced students' reading comprehension scores significantly, since teachers were repeatedly forced to pause lessons until each passing plane had faded into the distance.", "t": "研究位於大型機場附近教室的學者發現，頭頂上噴射引擎持續不斷的轟鳴聲大幅降低了學生的閱讀理解成績，因為老師一再被迫暫停授課，直到每架飛過的飛機聲音逐漸遠去。", "as": "Above the din of the crowded night market, a garrulous vendor prattled on about the virtues of his wares, while his taciturn partner simply waited, unperturbed by the turmoil around them.", "at": "在擁擠夜市的嘈雜聲中，一位多話的小販喋喋不休地介紹他貨品的優點，而他沉默寡言的夥伴只是靜靜等候，絲毫不受周遭混亂的影響。"}, {"w": "mellifluous", "p": "adj.", "d": "Sweet, smooth, and pleasing to hear.", "c": "悅耳流暢的；甜美的", "s": "Radio producers in the 1940s prized announcers with mellifluous voices, believing that a warm, smooth, honeyed tone could hold listeners' attention through long news bulletins and persuade them to trust the sponsors whose products were advertised between broadcasts.", "t": "1940年代的廣播製作人非常看重嗓音甜美流暢的播音員，他們相信溫暖、圓潤、如蜜般的音色能在冗長的新聞播報中抓住聽眾的注意力，並說服他們信任節目間所廣告產品的贊助商。", "as": "The diplomat's mellifluous voice and affable manner charmed his hosts at the summit, though skeptics noted that his eloquence often masked evasive answers and that his speeches were laced with banal platitudes.", "at": "這位外交官悅耳的嗓音與和藹的舉止讓高峰會的東道主為之著迷，但懷疑者指出，他的雄辯往往掩飾了閃爍的答覆，而他的演講也充斥著陳腔濫調。"}, {"w": "dissonant", "p": "adj.", "d": "Lacking harmony; discordant.", "c": "不和諧的;刺耳的", "s": "The composer used dissonant chords to create tension.", "t": "這位作曲家使用不和諧的和弦來營造張力。", "as": "Their dissonant opinions made compromise difficult.", "at": "他們不和諧的意見讓妥協變得困難。", "a": 1}, {"w": "clamorous", "p": "adj.", "d": "Making a loud and confused noise; demanding attention noisily.", "c": "喧鬧的;吵嚷的", "s": "The clamorous crowd outside the courthouse demanded to hear the verdict immediately.", "t": "法院外喧鬧的群眾,要求立刻聽到判決結果。", "as": "A clamorous flock of geese passed overhead just before sunset.", "at": "日落前,一群喧鬧的雁群從空中飛過。", "a": 1}, {"w": "boisterous", "p": "adj.", "d": "Loud and full of energy.", "c": "喧鬧的/精力旺盛的", "s": "The boisterous children ran wild through the playground.", "t": "這群精力旺盛的孩子們在遊樂場裡橫衝直撞。", "as": "A boisterous cheer erupted from the crowd when the home team scored.", "at": "當地主隊得分時,群眾中爆出一陣喧鬧的歡呼聲。", "a": 1}, {"w": "cacophonous", "p": "adj.", "d": "Having an unpleasant sound.", "c": "刺耳的/不和諧的", "s": "The construction site produced a cacophonous mix of drills and hammers all morning.", "t": "整個早上,這處工地發出電鑽和鐵鎚交雜的刺耳噪音。", "as": "The band's first rehearsal was a cacophonous mess of mismatched instruments.", "at": "這個樂團第一次排練時,各種樂器不協調地發出刺耳的噪音。", "a": 1}, {"w": "sonorous", "p": "adj.", "d": "Producing a deep, rich, and impressively loud sound.", "c": "洪亮的；渾厚的；響亮的", "s": "The cathedral's sonorous brass bells rang across the valley, their deep, echoing tones signaling the beginning of the morning ceremony.", "t": "大教堂洪亮的黃銅鐘聲傳遍山谷，其深沉迴盪的音調宣告晨禮開始。", "as": "The actor used his powerful, sonorous voice to command the outdoor amphitheater, ensuring that every line reached the audience without amplification.", "at": "演員以強而有力且渾厚洪亮的嗓音吸引整座戶外圓形劇場的注意，使每句台詞不用擴音也能傳到觀眾耳中。", "a": 1}, {"w": "grating", "p": "adj.", "d": "Unpleasantly harsh in sound.", "c": "刺耳的/惱人的", "s": "The grating sound of chalk on the blackboard made students wince.", "t": "粉筆刮過黑板發出的刺耳聲讓學生們皺起眉頭。", "as": "His grating laugh could be heard throughout the entire office.", "at": "他刺耳的笑聲響徹整間辦公室。", "a": 1}, {"w": "harmonious", "p": "adj.", "d": "Forming a pleasing or consistent whole; free from conflict.", "c": "和諧的", "s": "The two nations enjoyed a harmonious relationship for decades.", "t": "這兩個國家數十年來享有和諧的關係。", "as": "The colors in the painting created a harmonious effect.", "at": "這幅畫中的色彩營造出一種和諧的效果。", "a": 1}, {"w": "melodious", "p": "adj.", "d": "Pleasant to hear, like music.", "c": "悅耳的;旋律優美的", "s": "Her melodious voice captivated the entire audience.", "t": "她悅耳動聽的嗓音迷住了全場觀眾。", "as": "The birds' melodious song filled the morning air.", "at": "鳥兒悅耳的鳴唱聲充滿了清晨的空氣。", "a": 1}]}, {"unit": 19, "theme": "Praise and Honor", "themeZh": "讚美與尊崇", "antonymLessons": [12], "cards": [{"w": "acclaim", "p": "v.", "d": "To praise enthusiastically and publicly.", "c": "稱讚；喝采；公開讚揚", "s": "Although her early novels sold poorly, critics now acclaim Zora Neale Hurston as one of the most important voices of the Harlem Renaissance, and Their Eyes Were Watching God is taught in thousands of university literature courses around the world.", "t": "儘管柔拉・涅爾・賀絲頓早期的小說銷量不佳，評論家如今公認並讚揚她是哈林文藝復興時期最重要的聲音之一，而《他們眼望上蒼》也在全世界數千門大學文學課程中被講授。", "as": "Critics acclaimed the debut album for its exuberant energy, contrasting it with the lackluster, derivative records that had dominated the charts, though a few captious reviewers dismissed its lyrics as trite.", "at": "評論家盛讚這張首張專輯熱情奔放的活力，並將它與當時稱霸排行榜那些平淡乏味、模仿成風的唱片相比；不過，少數吹毛求疵的評論者認為其歌詞陳腐老套。"}, {"w": "extol", "p": "v.", "d": "To praise someone or something with great enthusiasm.", "c": "頌揚；極力讚美", "s": "In his travel journals, the eighteenth-century naturalist repeatedly extols the beauty of the Scottish Highlands, devoting page after page to the misty lochs, heather-covered hills, and soaring eagles that he believed rivaled any landscape in the Alps.", "t": "在他的旅行日誌中，這位十八世紀的博物學家一再頌揚蘇格蘭高地之美，用了一頁又一頁的篇幅描寫霧氣繚繞的湖泊、長滿石楠的山丘與翱翔的老鷹，他認為這些景致足以媲美阿爾卑斯山的任何風光。", "as": "Nutritionists extol the Mediterranean diet, yet they also warn that sedentary habits can be as detrimental to health as poor eating, and that even the most frugal meals cannot offset a lethargic lifestyle.", "at": "營養學家大力推崇地中海飲食，但他們也警告，久坐不動的習慣對健康的危害不亞於不良飲食，即使是最簡樸的餐點也無法抵消懶散的生活方式所帶來的影響。"}, {"w": "esteem", "p": "v.", "d": "To respect and admire someone highly.", "c": "尊重；敬重；推崇", "s": "Medieval Islamic scholars so highly esteemed the works of Aristotle that they translated, copied, and wrote extensive commentaries on them, preserving texts that might otherwise have been lost and later transmitting them to the universities of Europe.", "t": "中世紀的伊斯蘭學者極為推崇亞里斯多德的著作，因此翻譯、抄寫並為之撰寫大量評註，保存了那些原本可能失傳的文本，日後更將它們傳入歐洲的大學。", "as": "Colleagues esteemed the physician not only for her diagnostic skill but also for her altruistic devotion to indigent patients, and even her most cantankerous rivals conceded that her benevolent work was exemplary.", "at": "同事們敬重這位醫師，不只因為她高超的診斷能力，也因為她無私地照顧貧困病患；就連她最難相處的對手也承認，她仁慈的工作堪稱典範。"}, {"w": "exalt", "p": "v.", "d": "To praise highly or raise in rank or dignity.", "c": "頌揚；提升地位", "s": "Romantic poets such as Wordsworth sought to exalt the lives of ordinary rural people, portraying shepherds, farmers, and wanderers not as crude peasants but as figures of quiet dignity whose closeness to nature gave them a wisdom that city dwellers lacked.", "t": "華茲華斯等浪漫主義詩人試圖頌揚鄉間平凡百姓的生活，將牧羊人、農夫與流浪者描繪成不是粗俗的鄉巴佬，而是帶著沉靜尊嚴的人物，他們親近大自然，因而擁有城市居民所欠缺的智慧。", "as": "Propaganda posters exalted the dictator as a benevolent father of the nation, but historians argue that such ostentatious imagery merely concealed a regime that was both iniquitous and pernicious to the citizens it claimed to protect.", "at": "宣傳海報將那位獨裁者頌揚為國家仁慈的父親，但歷史學家認為，這種浮誇的形象只是掩蓋了一個既邪惡、又對其聲稱要保護的人民有害的政權。"}, {"w": "revere", "p": "v.", "d": "To feel deep respect or admiration for.", "c": "尊崇；敬畏", "s": "More than a decade after his death, Nelson Mandela is revered by South Africans of every background, and each year on his birthday millions of citizens honor his memory by spending sixty-seven minutes performing community service, one minute for each year of his public life.", "t": "即使在曼德拉逝世十多年後，南非各種背景的人民依然尊崇他；每年在他生日那天，數百萬公民會花六十七分鐘從事社區服務來紀念他，每一分鐘代表他投身公共事務的一年。", "as": "Villagers revered the elderly healer, whose taciturn manner and austere way of life lent her an air of quiet wisdom, and who remained magnanimous toward even the most cantankerous neighbors.", "at": "村民們敬重那位年長的醫者；她沉默寡言的舉止和簡樸的生活方式，讓她散發出一種沉靜的智慧，而且她對最難相處的鄰居也始終寬宏大量。"}, {"w": "eulogize", "p": "v.", "d": "To praise highly, especially in a speech honoring someone who has died.", "c": "頌揚；致悼詞讚美", "s": "At the state funeral, the former president was eulogized by leaders from both parties, who set aside years of bitter rivalry to recall his courage during the economic crisis and his willingness to compromise when the nation needed unity most.", "t": "在國葬典禮上，兩黨領袖都為這位前總統致詞頌揚；他們擱下多年來激烈的競爭，回顧他在經濟危機期間的勇氣，以及在國家最需要團結時願意妥協的胸襟。", "as": "Speakers eulogized the late scientist as a magnanimous mentor, recalling how she had alleviated her students' anxieties and remained humble despite acclaim that would have made a lesser person arrogant.", "at": "致詞者頌揚這位已故科學家是一位寬宏大量的良師，回憶她如何減輕學生的焦慮，以及她雖獲得足以讓一般人變得傲慢的盛名，卻依然謙遜。"}, {"w": "panegyrize", "p": "v.", "d": "To praise someone formally and elaborately in speech or writing.", "c": "公開頌揚；撰文讚頌", "s": "Court poets in Renaissance Florence were paid handsomely to panegyrize the Medici family, composing elaborate verses that compared Lorenzo de' Medici to ancient emperors and praised his patronage of artists as proof of his almost divine wisdom.", "t": "文藝復興時期佛羅倫斯的宮廷詩人領取優渥的報酬來頌揚麥地奇家族，他們創作華麗的詩篇，將羅倫佐・德・麥地奇比作古代皇帝，並讚揚他對藝術家的贊助是他近乎神聖智慧的明證。", "as": "Rather than panegyrizing the general, the honest biographer exposed his arrogant disregard for soldiers' lives and his contemptuous treatment of subordinates, refusing to repeat the grandiloquent myths of earlier accounts.", "at": "這位誠實的傳記作者沒有頌揚那位將軍，反而揭露他對士兵性命的傲慢漠視，以及他對部屬的輕蔑對待，拒絕重複早期記述中那些浮誇的神話。"}, {"w": "adulate", "p": "v.", "d": "To praise or admire someone excessively; to flatter.", "c": "過度奉承；諂媚吹捧", "s": "Psychologists studying celebrity culture have found that fans who adulate pop stars often attribute moral virtues to them that have no basis in evidence, treating the singers' casual remarks as profound wisdom and defending them fiercely against any criticism.", "t": "研究名人文化的心理學家發現，過度崇拜流行歌星的粉絲常把一些毫無根據的道德美德套在偶像身上，將歌手隨口說出的話視為深刻的智慧，並激烈地為他們抵擋任何批評。", "as": "The courtiers who adulated the king were obsequious and servile, and their fawning flattery left him so complacent that he ignored the ominous signs of rebellion spreading through his realm.", "at": "那些對國王百般奉承的朝臣卑躬屈膝、奴顏婢膝，他們諂媚的吹捧讓國王自滿到忽視了在他國土上蔓延的不祥叛亂徵兆。"}, {"w": "laud", "p": "v.", "d": "To praise highly, especially in public.", "c": "稱讚；讚美", "s": "Environmental groups lauded the city's decision to convert three abandoned rail lines into elevated parks, noting that the project not only provided green space to neighborhoods that had long lacked it but also reduced summer temperatures in nearby streets.", "t": "環保團體大力讚揚市府將三條廢棄鐵路改建為高架公園的決定，並指出這項計畫不僅為長期缺乏綠地的社區提供綠色空間，也降低了周邊街道的夏季氣溫。", "as": "The committee lauded the mediator for her ability to conciliate the rival factions, praising her affable manner and noting that her patient diplomacy had quelled tensions that once seemed intractable.", "at": "委員會讚揚這位調解人能夠化解敵對派系之間的分歧，稱讚她和藹可親的態度，並指出她耐心的斡旋平息了曾經看似棘手難解的緊張局勢。"}, {"w": "venerate", "p": "v.", "d": "To regard with deep, often religious, respect.", "c": "崇敬；尊崇", "s": "For more than a thousand years, pilgrims have traveled hundreds of kilometers on foot to venerate the relics believed to belong to Saint James at the cathedral in Santiago de Compostela, a journey that continues to draw over three hundred thousand walkers each year.", "t": "一千多年來，朝聖者徒步跋涉數百公里，前往聖地牙哥－德孔波斯特拉大教堂，崇敬據信屬於聖雅各的聖髑；這條朝聖之路至今每年仍吸引超過三十萬名步行者。", "as": "Generations of European scholars venerated the ancient philosopher, though modern critics argue that such reverence made academics complacent and strangely indifferent to the banal platitudes buried in his later writings.", "at": "一代又一代的歐洲學者崇敬這位古代哲學家，但現代評論家認為，這樣的崇敬讓學者們變得自滿，對他晚期著作中那些陳腐的老生常談出奇地漠不關心。"}, {"w": "glorify", "p": "v.", "d": "To praise or honor highly.", "c": "讚揚/美化", "s": "The team was glorify for their historic championship win.", "t": "這支球隊因贏得歷史性的冠軍而備受讚揚。", "as": "The film has been criticized for seeming to glorify violence.", "at": "這部電影因似乎美化暴力行為而受到批評。", "a": 1}, {"w": "commend", "p": "v.", "d": "To praise formally or officially; to recommend.", "c": "稱讚;推薦", "s": "The principal commended the students for their perfect attendance record.", "t": "校長表揚了這些出席率完美的學生。", "as": "I can commend this restaurant without hesitation to anyone visiting the city.", "at": "我毫不猶豫地推薦這家餐廳給任何造訪這座城市的人。", "a": 1}, {"w": "lionize", "p": "v.", "d": "To treat someone as a celebrity or an object of great interest.", "c": "把……捧為名人", "s": "The press began to lionize the young scientist after her discovery.", "t": "在這位年輕科學家做出這項發現後,媒體開始把她捧成名人。", "as": "Society tends to lionize athletes while ignoring quieter achievements.", "at": "社會往往把運動員捧為名人,卻忽略了較低調的成就。", "a": 1}, {"w": "deify", "p": "v.", "d": "To worship or regard as a god.", "c": "神化;奉為神明", "s": "Ancient civilizations often deify ied their rulers.", "t": "古代文明常常將他們的統治者神化。", "as": "The media tends to deify celebrities beyond their true achievements.", "at": "媒體往往把名人的成就過度神化。", "a": 1}, {"w": "applaud", "p": "v.", "d": "To show approval by clapping; to praise.", "c": "鼓掌;讚揚", "s": "The audience stood to applaud the orchestra's flawless performance.", "t": "觀眾起立鼓掌,讚賞管弦樂團完美無瑕的演出。", "as": "Critics applaud the film's bold approach to a difficult subject.", "at": "評論家讚揚這部電影對這個艱難主題的大膽處理方式。", "a": 1}, {"w": "exult", "p": "v.", "d": "To rejoice greatly.", "c": "歡欣鼓舞/狂喜", "s": "Fans began to exult as their team scored the winning goal.", "t": "當球隊踢進致勝一球時,球迷們開始歡欣鼓舞。", "as": "She could not help but exult over her daughter's acceptance to medical school.", "at": "她忍不住為女兒被醫學院錄取而欣喜若狂。", "a": 1}, {"w": "tribute", "p": "n.", "d": "An act or statement of respect or gratitude; payment made to acknowledge submission.", "c": "致敬;貢品", "s": "The concert served as a moving tribute to the late musician.", "t": "這場演唱會成為向這位已故音樂家致敬的動人時刻。", "as": "Conquered kingdoms were often forced to pay tribute to the empire.", "at": "被征服的王國經常被迫向這個帝國進貢。", "a": 1}, {"w": "accolade", "p": "n.", "d": "High praise, special distinction.", "c": "讚譽/殊榮", "s": "The young chef received numerous accolades for her innovative menu.", "t": "這位年輕主廚因她創新的菜單而獲得無數讚譽。", "as": "Winning the award was the greatest accolade of his career.", "at": "贏得這項獎項是他職業生涯中最大的殊榮。", "a": 1}, {"w": "kudos", "p": "n.", "d": "Praise for an achievement.", "c": "讚譽/榮耀", "s": "The team received kudos from critics for their innovative design.", "t": "這支團隊因其創新的設計獲得評論家的讚譽。", "as": "She deserves kudos for organizing the entire charity event by herself.", "at": "她獨自籌辦了整場慈善活動,值得所有的讚譽。", "a": 1}]}, {"unit": 20, "theme": "Abundance and Excess", "themeZh": "豐富與過量", "antonymLessons": [92], "cards": [{"w": "surfeit", "p": "n.", "d": "An excessive amount of something; an oversupply.", "c": "過量；過剩", "s": "Economists explain that the sudden collapse in oil prices in 2020 resulted from a surfeit of crude: as lockdowns slashed demand for fuel, storage tanks around the world filled to capacity, and some producers briefly had to pay buyers to take barrels off their hands.", "t": "經濟學家解釋，2020年油價突然崩跌是原油過剩所致：由於封城措施使燃料需求大減，全球的儲油槽都已滿載，部分生產商甚至一度必須付錢請買家把一桶桶原油運走。", "as": "A surfeit of lavish banquets left the prodigal prince lethargic and indolent, and his worried advisers warned that such ostentatious extravagance would prove detrimental to the kingdom's already depleted treasury.", "at": "過多的奢華宴席讓那位揮霍無度的王子變得昏沉懶散，他憂心的顧問們警告，如此張揚的鋪張浪費將會損害王國早已空虛的國庫。"}, {"w": "profuse", "p": "adj.", "d": "Plentiful, abundant, or pouring out freely.", "c": "大量的；豐富的；毫不吝惜的", "s": "Doctors treating heat stroke watch carefully for a sudden end to profuse sweating, since a patient who stops perspiring despite a soaring body temperature may be losing the ability to cool down, a sign that organ damage could soon follow.", "t": "治療中暑的醫師會密切留意大量出汗是否突然停止，因為若患者在體溫飆升時卻不再流汗，可能代表身體正在失去散熱能力，這是器官即將受損的徵兆。", "as": "The executive's profuse apologies failed to placate the angry shareholders, who considered his contrition insincere and censured him for squandering millions on ostentatious offices while the company's profits steadily declined.", "at": "那位高階主管連連道歉，卻未能安撫憤怒的股東；股東們認為他的悔意並不真誠，並譴責他在公司獲利持續下滑之際，仍將數百萬元揮霍在浮誇的辦公室上。"}, {"w": "plethora", "p": "n.", "d": "A very large or excessive amount of something.", "c": "過多；大量", "s": "Behavioral economists have shown that a plethora of options can actually discourage purchases: in one famous study, shoppers offered twenty-four varieties of jam were far less likely to buy any than shoppers offered only six, apparently overwhelmed by the difficulty of choosing.", "t": "行為經濟學家發現，過多的選擇反而會降低購買意願：在一項著名研究中，面對二十四種果醬的顧客，購買任何一種的可能性遠低於只面對六種的顧客，他們顯然被選擇的困難壓得喘不過氣。", "as": "The government report offered a plethora of statistics, but its verbose analysis and cryptic charts only confounded readers, and critics lamented that the authors seemed indifferent to clarity and accessibility.", "at": "這份政府報告提供了大量的統計數據，但其冗長的分析與晦澀的圖表只讓讀者更加困惑，評論者感嘆作者們似乎毫不在意內容是否清楚易懂。"}, {"w": "myriad", "p": "adj.", "d": "Countless or extremely great in number.", "c": "無數的；極多的", "s": "Using the James Webb Space Telescope, astronomers captured a single image of a patch of sky no larger than a grain of sand held at arm's length, yet it revealed myriad galaxies, some of them so distant that their light had traveled for over thirteen billion years to reach the telescope.", "t": "天文學家利用詹姆斯・韋伯太空望遠鏡拍攝了一張影像，畫面中的天空範圍不比伸直手臂時拿著的一粒沙大，卻揭示了無數個星系，其中有些極為遙遠，其光芒傳遞了超過一百三十億年才抵達望遠鏡。", "as": "The novelist's sprawling saga, a labyrinth of myriad characters, rival families, and intersecting subplots, may strike readers who prefer a succinct narrative as confounding rather than charming, though admirers praise its ambition.", "at": "這位小說家篇幅浩大的長篇作品，宛如一座由無數角色、敵對家族與交錯支線構成的迷宮；偏好簡潔敘事的讀者可能會覺得它令人困惑而非迷人，不過欣賞者則讚揚其雄心。"}, {"w": "copious", "p": "adj.", "d": "Abundant and plentiful in quantity.", "c": "大量的；豐富的", "s": "Charles Darwin kept copious notes throughout his five-year voyage on the Beagle, filling dozens of notebooks with sketches, measurements, and observations of finches, tortoises, and fossils that he would study for decades before publishing On the Origin of Species.", "t": "查爾斯・達爾文在乘坐小獵犬號的五年航程中做了大量筆記，數十本筆記本裡寫滿了對雀鳥、陸龜與化石的素描、測量與觀察紀錄，他在出版《物種起源》之前，花了數十年研究這些資料。", "as": "The austere monks politely rejected the copious offerings of wealthy pilgrims, believing that such lavish gifts would make them complacent and gradually undermine the frugal way of life their order demanded.", "at": "那些過著嚴格苦修生活的僧侶婉拒了富有朝聖者的大量供品，他們認為如此豐厚的禮物會讓他們變得自滿，並逐漸破壞修會所要求的簡樸生活方式。"}, {"w": "ample", "p": "adj.", "d": "Enough or more than enough; plentiful.", "c": "充裕的；足夠的", "s": "Although the defense attorneys argued that their client had been wrongly accused, the prosecution presented ample evidence of his guilt, including security footage, fingerprints on the stolen safe, and bank records showing large deposits made the morning after the robbery.", "t": "儘管辯護律師主張他們的當事人遭到誣告，檢方仍提出了充分的有罪證據，包括監視器畫面、遭竊保險箱上的指紋，以及顯示搶案隔天早上有大筆存款的銀行紀錄。", "as": "Even with ample and reliable funding from private donors, the project faltered under an apathetic manager whose lethargic leadership and indifferent attitude toward deadlines turned a promising initiative into a debacle.", "at": "即使有私人捐款者提供的充裕資金，這項計畫仍在一位冷漠的經理手下停滯不前；他萎靡的領導和對期限漠不關心的態度，讓一個前景看好的計畫淪為一場慘敗。"}, {"w": "teeming", "p": "adj.", "d": "Full of or swarming with something.", "c": "充滿的;熙攘的", "s": "The market was teeming with vendors selling fresh produce.", "t": "這座市場擠滿了販售新鮮農產品的攤商。", "as": "The coral reef was teeming with colorful fish.", "at": "這片珊瑚礁裡充滿了色彩繽紛的魚群。", "a": 1}, {"w": "prolific", "p": "adj.", "d": "Producing abundantly.", "c": "多產的/多產作家的", "s": "The author was remarkably prolific, publishing nearly a book a year.", "t": "這位作家異常多產,幾乎每年都出版一本書。", "as": "This variety of apple tree is especially prolific, yielding hundreds of fruits each season.", "at": "這種蘋果樹品種格外多產,每季能結出數百顆果實。", "a": 1}, {"w": "abounding", "p": "adj.", "d": "Existing in large numbers or amounts.", "c": "大量存在的;豐富的", "s": "The garden, abounding with roses, filled the whole street with fragrance.", "t": "這座玫瑰盛開的花園,讓整條街都瀰漫著香氣。", "as": "Opportunities were abounding for graduates with strong data skills.", "at": "對具備優秀數據能力的畢業生來說,機會俯拾皆是。", "a": 1}, {"w": "exorbitant", "p": "adj.", "d": "Excessive.", "c": "過度的/離譜的", "s": "Tourists were shocked by the exorbitant prices charged near the landmark.", "t": "遊客對這座地標附近離譜的高價感到震驚。", "as": "The lawyer's exorbitant fees forced the family to seek a different attorney.", "at": "這位律師收費過高,迫使這個家庭尋找另一位律師。", "a": 1}, {"w": "glut", "p": "n./v.", "d": "An excessive supply of something; to fill to excess.", "c": "供過於求;塞滿", "s": "A glut of oil on the market caused prices to fall.", "t": "市場上石油供過於求導致價格下跌。", "as": "He would glut himself on desserts every holiday.", "at": "他每逢節日都會大吃甜點吃到撐。", "a": 1}, {"w": "cornucopia", "p": "n.", "d": "An abundant supply of good things.", "c": "豐饒之角;豐富多樣", "s": "The market offered a cornucopia of fresh fruits and vegetables.", "t": "這座市場提供了豐富多樣的新鮮蔬果。", "as": "Her bookshelf was a cornucopia of rare first editions.", "at": "她的書架上擺滿了各式珍貴的初版書。", "a": 1}]}, {"unit": 21, "theme": "Food and Eating", "themeZh": "飲食", "antonymLessons": [], "cards": [{"w": "abstemious", "p": "adj.", "d": "Moderate or sparing in eating and drinking.", "c": "飲食有節制的；節制的", "s": "Longitudinal studies of centenarians in Okinawa suggest that their abstemious habits — rising from the table while still slightly hungry and rarely consuming alcohol — may contribute as much to their longevity as genetics, since chronic overeating accelerates the cellular damage associated with aging.", "t": "針對沖繩百歲人瑞的長期研究顯示，他們飲食有節制的習慣——吃到微飽便離開餐桌，且很少飲酒——對長壽的貢獻可能不亞於基因，因為長期暴飲暴食會加速與老化相關的細胞損傷。", "as": "The monk's abstemious diet struck visiting merchants as austere, even penurious, yet he insisted that his frugal meals of rice and boiled greens were a spiritual discipline rather than a sign of poverty, and he never presumed to extol such restraint to others.", "at": "這位僧侶飲食節制，在來訪商人眼中顯得簡樸，甚至貧寒；然而他堅稱自己以米飯和水煮青菜為主的儉樸餐食是一種修行，而非貧窮的象徵，而且他從不自以為是地向他人頌揚這種克制。"}, {"w": "delectable", "p": "adj.", "d": "Extremely delicious and pleasing to the taste.", "c": "美味可口的；令人愉快的", "s": "The tomato, now considered one of the most delectableingredients in Mediterranean cooking, was long regarded with suspicion in northern Europe, where botanists classified it alongside poisonous nightshades such as belladonna and many cooks refused to serve it for nearly two centuries.", "t": "番茄如今被視為地中海料理中最美味可口的食材之一，卻曾長期在歐洲北部遭人猜疑，因為植物學家將它與顛茄等有毒的茄科植物歸為同類，許多廚師將近兩個世紀都不肯以它入菜。", "as": "The food critic, usually so captious that chefs dreaded her visits, could only extol the lavish, delectable tasting menu, conceding in her review that even its humblest course was anything but insipid.", "at": "這位美食評論家向來吹毛求疵，令廚師們聞之色變，這次卻只能盛讚那套豐盛又美味可口的品嚐菜單，並在評論中承認，即使是其中最樸素的一道菜也絕不平淡無味。"}, {"w": "emaciated", "p": "adj.", "d": "Abnormally thin and weak, especially from hunger or illness.", "c": "憔悴的；瘦弱的；骨瘦如柴的", "s": "Photographs of emaciated prisoners released from wartime camps, their ribs visible beneath paper-thin skin, prompted physicians to study refeeding syndrome, a dangerous condition in which a starving patient's body is overwhelmed when nourishment is reintroduced too quickly after prolonged deprivation.", "t": "從戰時集中營獲釋、骨瘦如柴的囚犯照片中，他們的肋骨在薄如紙的皮膚下清晰可見，這促使醫師研究「再餵食症候群」——一種長期挨餓的患者在恢復進食過快時，身體因負荷不了而陷入險境的病症。", "as": "The emaciated polar bear, stranded on a shrinking ice floe, became an ominous emblem of climate change; even viewers who had found the science confounding conceded that the loss of sea ice was clearly detrimental to Arctic predators.", "at": "那隻困在日漸縮小的浮冰上、骨瘦如柴的北極熊，成了氣候變遷的不祥象徵；就連原本覺得相關科學令人困惑的觀眾也承認，海冰流失顯然對北極的掠食動物有害。"}, {"w": "alimentary", "p": "adj.", "d": "Relating to food, nourishment, or digestion.", "c": "營養的；飲食的；消化的", "s": "Because the alimentary canal stretches roughly nine meters through the human body and hosts trillions of microbes, gastroenterologists increasingly treat it not as a simple tube for processing food but as a complex ecosystem that influences immunity, metabolism, and even mood.", "t": "由於消化道在人體內綿延約九公尺，並寄居著數以兆計的微生物，腸胃科醫師越來越不把它視為單純處理食物的管道，而是一個會影響免疫、代謝甚至情緒的複雜生態系統。", "as": "Medieval physicians offered myriad remedies for alimentary complaints, but their cures were often deleterious rather than helpful: purging, bloodletting, and copious mercury tonics only compounded the turmoil in a patient's already ailing stomach.", "at": "中世紀的醫師針對消化方面的病痛提出了無數療法，但這些療法往往有害無益：催瀉、放血和大量的水銀藥劑，只會讓患者本已不適的腸胃更加翻騰。"}, {"w": "culinary", "p": "adj.", "d": "Relating to cooking or the kitchen.", "c": "烹飪的；廚藝的", "s": "When UNESCO added Japanese washoku to its list of intangible cultural heritage in 2013, it recognized not a single dish but an entire culinary tradition — seasonal ingredients, precise knife work, and rituals of presentation — that had been passed down through generations of home cooks.", "t": "聯合國教科文組織於2013年將日本「和食」列入非物質文化遺產名錄時，所肯定的不是單一菜餚，而是一整套烹飪傳統——當令食材、精準的刀工，以及擺盤的儀式——這些都由一代代家庭廚師傳承下來。", "as": "Critics once dismissed fusion cooking as derivative and banal, but the chef's culinary experiments, which paired Taiwanese night-market snacks with French technique, won acclaim from even the most disdainful gourmets in Paris.", "at": "評論家曾把融合料理貶為缺乏原創、陳腐乏味，但這位主廚將台灣夜市小吃與法式技法結合的烹飪實驗，卻連巴黎最不屑一顧的美食家都讚不絕口。"}, {"w": "epicurean", "p": "adj.", "d": "Devoted to refined pleasure, especially fine food and drink.", "c": "講究美食的；享樂主義的", "s": "The Gilded Age financier's epicurean tastes were legendary: his private railway car carried a French chef, a cellar of vintage Bordeaux, and crates of oysters packed in ice, so that he could dine on twelve-course feasts while crossing the most desolate stretches of the American West.", "t": "這位鍍金時代金融家講究美食的品味堪稱傳奇：他的私人鐵路車廂載著一位法國主廚、一整窖陳年波爾多葡萄酒，以及一箱箱冰鎮生蠔，讓他即使穿越美國西部最荒涼的地帶，也能享用十二道菜的盛宴。", "as": "Ironically, Epicurus himself favored frugal meals of bread and water; the epicurean lifestyle now associated with his name — lavish feasts, rare wines, and ostentatious dining rooms — would have struck the philosopher as a prodigal pursuit of pleasures that ultimately bring more pain than contentment.", "at": "諷刺的是，伊比鳩魯本人偏好以麵包和清水為主的簡樸餐食；如今與他名字連在一起的享樂式生活——奢華的盛宴、珍稀的美酒和炫耀的餐廳——在這位哲學家看來，只是揮霍無度地追求那些最終帶來的痛苦多於滿足的享樂。"}, {"w": "glutton", "p": "n.", "d": "A person who habitually eats and drinks too much.", "c": "貪吃的人；暴食者", "s": "In Dante's Inferno, the gluttons of the third circle lie in freezing, filthy slush beneath an endless rain, a punishment that mirrors their earthly sin: having made food and drink the center of their lives, they are reduced to wallowing in garbage like swine.", "t": "在但丁的《地獄篇》中，第三層地獄的暴食者躺在無盡冷雨下冰冷污穢的泥濘裡，這種懲罰呼應了他們生前的罪孽：他們把飲食當成生活的重心，如今便淪落到像豬一樣在穢物中打滾。", "as": "The Roman emperor Vitellius was a notorious glutton whose prodigal banquets squandered the treasury, and contemporary historians, never chary of moral judgment, did not hesitate to castigate him for his voracious appetite.", "at": "羅馬皇帝維特里烏斯是出了名的暴食者，他揮霍無度的盛宴耗盡了國庫；而同時代的史家向來不吝於道德評判，毫不猶豫地嚴厲抨擊他貪得無厭的胃口。"}, {"w": "palatable", "p": "adj.", "d": "Pleasant to taste; acceptable or agreeable.", "c": "可口的；美味的；可接受的", "s": "To make bitter quinine more palatable to British soldiers stationed in malaria-ridden India, colonial officers mixed the medicine with soda water, sugar, and gin, inadvertently inventing the gin and tonic, a cocktail that remains popular long after its medicinal purpose has been forgotten.", "t": "為了讓駐紮在瘧疾肆虐的印度的英國士兵更容易入口苦澀的奎寧，殖民地軍官將這種藥物與蘇打水、糖和琴酒混合，無意間發明了琴通寧——這款雞尾酒的藥用目的早已被遺忘，卻至今仍廣受歡迎。", "as": "To make the austere reform package more palatable to a vociferous opposition, the finance minister offered to mitigate the proposed tax increases, a conciliatory gesture that briefly allayed fears of a general strike.", "at": "為了讓這套緊縮改革方案更能被大聲疾呼的反對派接受，財政部長提議減輕擬議中的增稅幅度，這個和解姿態一度平息了外界對大罷工的憂慮。"}, {"w": "ravenous", "p": "adj.", "d": "Extremely hungry; eager for food.", "c": "極餓的；飢腸轆轆的；貪婪的", "s": "After emerging from months of hibernation having lost up to a third of their body weight, grizzly bears are ravenous and spend nearly every waking hour foraging for roots, carrion, and newborn elk calves to rebuild the fat reserves they will need before winter returns.", "t": "灰熊結束數個月的冬眠時，體重可能已減少多達三分之一，因此飢腸轆轆，幾乎每個清醒的時刻都在搜尋植物根莖、腐肉和剛出生的麋鹿幼崽，以重新累積冬天再度來臨前所需的脂肪。", "as": "The ravenous troops, exhausted by weeks of retreat through a frozen labyrinth of mountain passes, were too listless to forage, and their commander's precarious supply lines collapsed into a debacle that historians still study today.", "at": "飢腸轆轆的部隊在冰封如迷宮般的山間隘口撤退了數週，早已精疲力竭、無精打采，無力再去搜尋糧食；而指揮官岌岌可危的補給線最終崩潰，釀成一場至今仍為史家研究的慘敗。"}, {"w": "savory", "p": "adj.", "d": "Salty or spicy rather than sweet; appetizing.", "c": "鹹香的；美味的；可口的", "s": "Japanese chemist Kikunae Ikeda identified glutamate as the source of the rich, savory flavor in seaweed broth in 1908, naming this fifth basic taste umami and arguing that it was as fundamental to human perception as sweetness, sourness, saltiness, and bitterness.", "t": "日本化學家池田菊苗於1908年確認，麩胺酸是昆布高湯中濃郁鹹香風味的來源，並將這第五種基本味覺命名為「鮮味」，主張它與甜、酸、鹹、苦一樣，都是人類味覺的基本要素。", "as": "The aroma of savory dumplings drifted through the night market, and even the most phlegmatic passersby, who had seemed indifferent to the clamor of the vendors, paused to join the line that snaked past the stalls.", "at": "鹹香的餃子香氣在夜市中飄散，就連最冷靜淡漠、看似對攤販吆喝聲毫不在意的路人，也停下腳步，加入那條蜿蜒穿過攤位的排隊人龍。"}]}, {"unit": 22, "theme": "Caution and Care", "themeZh": "謹慎與細心", "antonymLessons": [57], "cards": [{"w": "circumspect", "p": "adj.", "d": "Careful to consider all risks before acting or speaking.", "c": "謹慎的；周到的；慎重的", "s": "Aware that a single careless remark could rattle global markets, the central bank governor remained circumspect throughout the press conference, weighing every phrase before answering and declining to speculate about future interest-rate decisions until the latest inflation data had been thoroughly analyzed.", "t": "這位央行總裁深知一句不經意的發言就可能撼動全球市場，因此在整場記者會中始終保持謹慎，每句話都先斟酌再回答，並且在最新的通膨數據經過徹底分析之前，拒絕臆測未來的利率決策。", "as": "Normally voluble in interviews, the novelist became circumspect when asked about her estranged brother, offering only terse, cryptic replies that left the assembled reporters more curious than before and fueled weeks of speculation in the literary press.", "at": "這位小說家平常在訪談中滔滔不絕，但被問到與她疏遠的哥哥時卻變得十分謹慎，只給出簡短而費解的回答，讓在場記者比先前更加好奇，也在文學媒體上引發了數週的揣測。"}, {"w": "conscientious", "p": "adj.", "d": "Careful to do one's work or duty thoroughly and well.", "c": "認真負責的；盡責的；本著良心的", "s": "Years before she developed one of the first compilers, Grace Hopper was known as a conscientious mathematician whose team kept detailed logbooks of every malfunction in the Harvard Mark II; in one of them, the team famously taped the moth that had short-circuited a relay in 1947.", "t": "在開發出最早的編譯器之一的數年前，葛麗絲・霍普就以認真負責的數學家著稱，她的團隊將哈佛馬克二號電腦的每一次故障都詳細記錄在日誌中；團隊曾在其中一本日誌裡，貼上一隻在1947年導致繼電器短路的飛蛾，此事廣為人知。", "as": "Unlike his indolent predecessor, the conscientious new curator scrutinized every single catalogue entry, and his meticulous research revealed that several of the museum's most prized paintings were spurious copies rather than genuine Renaissance works.", "at": "不同於怠惰的前任，這位認真負責的新任策展人仔細審查每一筆目錄資料，而他一絲不苟的研究揭露，博物館好幾幅最受珍視的畫作其實是贗品，而非真正的文藝復興時期作品。"}, {"w": "exacting", "p": "adj.", "d": "Demanding great effort, skill, or precision.", "c": "嚴格要求的；費力的；苛求的", "s": "The restoration of Notre-Dame's medieval timber roof proved extraordinarily exacting: carpenters had to shape each oak beam with hand axes, using only the tools and techniques available to thirteenth-century builders, so that the reconstructed frame would match the original in every structural detail.", "t": "巴黎聖母院中世紀木造屋頂的修復工程極為嚴苛：木匠必須只用十三世紀建築工匠所能使用的工具與技法，以手斧逐一削製每根橡木樑，好讓重建的屋架在每個結構細節上都與原貌相符。", "as": "The conductor's exacting standards made him seem cantankerous to many musicians, yet even those who chafed under his rebukes conceded that his rehearsals transformed a discordant student ensemble into a remarkably vibrant orchestra.", "at": "這位指揮家的嚴格標準讓許多樂手覺得他脾氣古怪難搞，但即使那些對他的斥責心懷不滿的人也承認，他的排練將一個不和諧的學生樂團，蛻變成一支極富活力的管弦樂團。"}, {"w": "gingerly", "p": "adj.", "d": "Showing great care and caution to avoid harm.", "c": "小心翼翼的；謹慎的", "s": "Because the two-thousand-year-old Herculaneum scrolls had been carbonized by the eruption of Vesuvius, early researchers' attempts to unroll them by hand had to be painfully gingerly, yet even the most delicate efforts often reduced the brittle papyrus to black flakes.", "t": "由於兩千年前的赫庫蘭尼姆古卷在維蘇威火山爆發時已被碳化，早期研究人員徒手展開古卷的嘗試必須極其小心翼翼，然而即使是最輕柔的動作，也常常使脆弱的莎草紙碎成黑色殘片。", "as": "After the earthquake, rescue workers made gingerly progress across the precarious rubble, mindful that any rash movement could prove detrimental to survivors trapped below, while an engineer watched for ominous movements of debris on the slope above.", "at": "地震過後，救援人員在搖搖欲墜的瓦礫堆上小心翼翼地緩慢前進，深知任何魯莽的舉動都可能危及受困在下方的倖存者，同時一位工程師留意著上方斜坡上碎石是否出現不祥的鬆動。"}, {"w": "vigilant", "p": "adj.", "d": "Keeping careful watch for possible danger or difficulty.", "c": "警惕的；警覺的；戒備的", "s": "Epidemiologists urged public-health agencies to remain vigilant even after case numbers had fallen, warning that the virus could mutate in animal reservoirs and re-emerge without warning, so wastewater testing and hospital surveillance should continue long after the immediate crisis appeared to have passed.", "t": "流行病學家呼籲公共衛生機構即使在病例數下降後仍應保持警覺，並警告病毒可能在動物宿主體內突變並毫無預警地再度出現，因此在眼前的危機看似過去之後，污水檢測與醫院監測仍應長期持續。", "as": "A vigilant auditor noticed a small discrepancy in the charity's annual accounts, and her persistent inquiry exposed a nefarious scheme in which devious executives had quietly funneled philanthropic donations into their own private offshore accounts.", "at": "一位警覺的稽核員發現這家慈善機構年度帳目中的一處小小差異，她鍥而不捨的調查揭露了一樁邪惡的陰謀：狡詐的高層主管悄悄把慈善捐款轉入了他們自己在海外的私人帳戶。"}, {"w": "meticulous", "p": "adj.", "d": "Showing extreme attention to every small detail.", "c": "一絲不苟的；極為細心的", "s": "Tycho Brahe's meticulous observations of planetary positions, recorded night after night for over twenty years without a telescope, were accurate enough that his assistant Johannes Kepler could later use them to prove that planets travel in elliptical rather than circular orbits.", "t": "第谷・布拉赫在沒有望遠鏡的情況下，二十多年來夜復一夜地記錄行星位置，這些一絲不苟的觀測精確到他的助手克卜勒後來得以藉此證明，行星沿橢圓軌道而非圓形軌道運行。", "as": "The forger's meticulous imitation of Vermeer's brushwork fooled even erudite critics, and the scandal that followed was a debacle for the museum, which had lavished praise and money on a spurious masterpiece.", "at": "這名偽造者一絲不苟地模仿維梅爾的筆觸，連學識淵博的評論家都被騙過；隨之而來的醜聞對博物館而言是一場慘敗，因為館方曾對這幅偽造的「傑作」大加讚揚、投入鉅資。"}, {"w": "wary", "p": "adj.", "d": "Cautious and alert to possible danger or problems.", "c": "機警的；謹慎的；提防的", "s": "Having watched several overhyped technologies collapse within a decade, many venture capitalists have grown wary of start-ups that promise revolutionary breakthroughs but cannot produce independent evidence that their products work, preferring to fund companies with modest claims and verifiable results.", "t": "眼見好幾項被過度炒作的科技在十年內垮台，許多創投業者已對那些宣稱能帶來革命性突破、卻拿不出獨立證據證明產品有效的新創公司心存戒心，寧可投資那些主張保守但成果可驗證的公司。", "as": "Wary of the senator's grandiloquent promises, the skeptical journalist suspected that his lavish praise for the education reform bill was merely a pretext for a pernicious plan to quietly defund the state's public schools.", "at": "這位抱持懷疑的記者對參議員浮誇的承諾心存戒心，她懷疑參議員對教育改革法案的大肆讚揚，只是為了掩護一項悄悄削減州立公立學校經費的有害計畫。"}, {"w": "chary", "p": "adj.", "d": "Cautiously reluctant to do or give something.", "c": "謹慎的；不輕易的；吝於給予的", "s": "Burned by a series of retracted studies, the editors of the medical journal became chary of publishing findings based on small samples, now requiring authors to share their raw data and to replicate key results before any article reporting a dramatic new treatment could appear in print.", "t": "在一連串研究遭撤稿後吃了苦頭，這本醫學期刊的編輯對刊登小樣本研究結果變得十分謹慎，如今要求作者公開原始數據，並在任何報導重大新療法的文章付印之前，先重複驗證關鍵結果。", "as": "The reclusive composer, always chary of praise and reticent in interviews, deeply distrusted music critics who would extol a new symphony one season and then castigate the very same work the next, depending on fashion.", "at": "這位隱居的作曲家向來不輕易稱讚他人，在訪談中也沉默寡言；他深深不信任那些隨潮流而變、這一季大肆頌揚某首新交響曲、下一季又嚴厲抨擊同一部作品的樂評家。"}, {"w": "heedful", "p": "adj.", "d": "Paying close attention to a warning or advice.", "c": "留心的；注意的；留意的", "s": "Mountaineers who are heedful of subtle changes in the weather, such as a sudden drop in barometric pressure or the appearance of lens-shaped clouds over the summit, often turn back before a storm strikes, while those who ignore such signs risk being trapped on exposed ridges.", "t": "對天氣細微變化保持留心的登山者——例如氣壓驟降，或山頂上方出現莢狀雲——往往能在暴風雨來襲前折返，而忽視這些徵兆的人則可能受困於毫無遮蔽的山脊上。", "as": "Heedful of the ominous cracks spreading across the dam, the engineer refused to remain complacent and urged officials to evacuate the valley, warning that any further delay could prove deleterious to thousands of residents.", "at": "這位工程師留意到大壩上不斷擴大、令人不安的裂縫，拒絕安於現狀，並敦促官員疏散河谷居民，警告任何進一步的延誤都可能對數千名居民造成傷害。"}, {"w": "scrupulous", "p": "adj.", "d": "Extremely careful, thorough, and honest about doing what is right.", "c": "一絲不苟的；嚴謹的；正直的", "s": "Historians praise the scrupulous record-keeping of Venetian merchants, whose double-entry account books, kept with careful honesty for every transaction from bolts of silk to sacks of pepper, allow modern economists to reconstruct Mediterranean trade networks with remarkable precision.", "t": "歷史學家讚揚威尼斯商人一絲不苟的記帳方式：他們以複式記帳法誠實而仔細地記錄每一筆交易，從一匹匹絲綢到一袋袋胡椒，使現代經濟學家得以極為精確地重建地中海的貿易網絡。", "as": "A scrupulous judge, she refused even modest gifts from litigants, and her unwavering integrity stood in stark contrast to the mercenary conduct of colleagues who had been censured for accepting bribes.", "at": "她是一位正直嚴謹的法官，連訴訟當事人送的小禮物都一概拒絕；她堅定不移的操守，與那些因收受賄賂而遭到譴責、唯利是圖的同僚形成強烈對比。"}, {"w": "cautious", "p": "adj.", "d": "Careful to avoid danger or mistakes.", "c": "謹慎的;小心的", "s": "Investors remained cautiousedespite the market's recent gains.", "t": "儘管市場近期上漲,投資人仍保持謹慎。", "as": "She took a cautious approach, testing the product on a small group first.", "at": "她採取謹慎的做法,先在小範圍測試這項產品。", "a": 1}, {"w": "discreet", "p": "adj.", "d": "Careful, cautious, prudent.", "c": "謹慎的", "s": "She made a discreet inquiry about the salary before accepting the offer.", "t": "在接受這份工作邀約前,她謹慎地詢問了薪資。", "as": "He was discreet about his relationship, telling only close friends.", "at": "他對這段感情十分謹慎,只告訴了幾位親近的朋友。", "a": 1}, {"w": "careful", "p": "adj.", "d": "Taking care to avoid harm or mistakes.", "c": "小心的;謹慎的", "s": "Be careful when crossing the busy intersection near the school.", "t": "經過學校附近繁忙的十字路口時要小心。", "as": "A careful review of the contract revealed a hidden fee.", "at": "仔細審閱這份合約後,發現了一項隱藏的費用。", "a": 1}, {"w": "deliberate", "p": "adj.", "d": "Done consciously and intentionally.", "c": "故意的/深思熟慮的", "s": "The deliberate actions of the protestors drew widespread attention.", "t": "抗議者刻意為之的行動引起了廣泛關注。", "as": "His silence was entirely deliberate, meant to make her uncomfortable.", "at": "他的沉默完全是故意的,目的是要讓她感到不自在。", "a": 1}]}, {"unit": 23, "theme": "Fleeting and Wandering", "themeZh": "短暫與漂泊", "antonymLessons": [60], "cards": [{"w": "evanescent", "p": "adj.", "d": "Quickly fading or vanishing from sight or memory.", "c": "瞬息即逝的；轉瞬消失的", "s": "Physicists at CERN must rely on sophisticated detectors to study the Higgs boson, an evanescent particle that decays into lighter particles less than a trillionth of a billionth of a second after it is created, leaving only indirect traces of its brief existence.", "t": "歐洲核子研究組織的物理學家必須仰賴精密的偵測器來研究希格斯玻色子；這種轉瞬即逝的粒子在生成後不到一兆分之一的十億分之一秒內就會衰變成較輕的粒子，只留下其短暫存在的間接痕跡。", "as": "The evanescent glow of bioluminescent plankton along the shore enthralled tourists, but marine biologists warned that pernicious runoff and stagnant coastal waters were threatening the delicate ecosystem that produced such a vibrant display.", "at": "海岸邊生物發光浮游生物那轉瞬即逝的光芒令遊客著迷，但海洋生物學家警告，有害的逕流與停滯的近岸海水，正威脅著孕育出如此絢麗景象的脆弱生態系統。"}, {"w": "transient", "p": "adj.", "d": "Lasting only a short time; staying briefly in a place.", "c": "短暫的；瞬息的；暫住的", "s": "Economists cautioned that the sudden spike in gasoline prices was likely transient, a temporary consequence of a refinery fire and a hurricane in the Gulf of Mexico, rather than a sign of the persistent, broad-based inflation that would justify raising interest rates.", "t": "經濟學家提醒，汽油價格的突然飆升很可能只是短暫的，是一場煉油廠火災和墨西哥灣颶風所造成的暫時後果，而非足以構成升息理由的持續性、全面性通膨的徵兆。", "as": "The reform movement's popularity proved transient; once its zealous leaders fell into acrimonious disputes, their vociferous rallies dwindled, and the public grew apathetic toward causes it had once ardently supported.", "at": "這場改革運動的聲勢只是曇花一現；一旦熱忱的領袖們陷入尖刻的爭執，他們大聲疾呼的集會便日漸冷清，民眾也對自己曾熱烈支持的理念變得漠不關心。"}, {"w": "transitory", "p": "adj.", "d": "Not permanent; lasting only a brief time.", "c": "短暫的；暫時的", "s": "Buddhist teachings emphasize that all worldly pleasures are transitory, arising and passing away like waves on the surface of the sea, and that suffering stems from clinging to wealth, fame, and comfort as though they could provide lasting security or happiness.", "t": "佛教教義強調，世間一切享樂都是短暫無常的，如同海面上的波浪般生滅起落；而痛苦正源於執著於財富、名聲與安逸，彷彿它們能帶來長久的安穩或幸福。", "as": "The pop star's fame turned out to be transitory: after a brief period of being lauded by critics and adulated by fans, her derivative second album was dismissed as hackneyed, and she quickly faded from public view.", "at": "這位流行歌手的名氣原來只是短暫的：在一段短暫受到評論家讚揚、歌迷崇拜的時期之後，她缺乏原創性的第二張專輯被斥為陳腔濫調，她也很快淡出了大眾視野。"}, {"w": "ephemeral", "p": "adj.", "d": "Lasting for a very short time.", "c": "短暫的；朝生暮死的", "s": "Mayflies are among the most ephemeral creatures on Earth: after spending up to two years as aquatic larvae, the adults emerge without functional mouths, mate within hours, and die before the following sunrise, their entire winged existence compressed into a single day.", "t": "蜉蝣是地球上壽命最短暫的生物之一：牠們以水生幼蟲的形態度過長達兩年的時間，羽化成蟲後卻沒有能進食的口器，在數小時內交配，並在隔天日出前死去，整個有翅膀的生命被壓縮在短短一天之內。", "as": "Social media trends are notoriously ephemeral, and marketers who chase every viral meme often produce banal, insipid campaigns built on hackneyed slogans that consumers forget almost as soon as they scroll past them.", "at": "社群媒體上的潮流出了名的短暫，追逐每一個爆紅迷因的行銷人員，往往做出建立在陳腔濫調標語上、平庸乏味的宣傳活動，消費者幾乎一滑過去就忘了。"}, {"w": "peripatetic", "p": "adj.", "d": "Traveling from place to place, especially for work.", "c": "巡迴的；漫遊的；四處奔走的", "s": "During the Renaissance, many painters led peripatetic careers, moving from one princely court to another in search of commissions, so that an artist like Leonardo da Vinci worked in Florence, Milan, Venice, and Rome before finally settling in France at the invitation of King Francis I.", "t": "文藝復興時期，許多畫家過著四處奔走的職業生涯，在各個王侯宮廷之間輾轉尋求委託案；因此像達文西這樣的藝術家，曾先後在佛羅倫斯、米蘭、威尼斯和羅馬工作，最後才應法王法蘭索瓦一世之邀定居法國。", "as": "The peripatetic journalist, never content to remain sedentary, roamed the world's war zones for three decades, and her ardent dispatches about turmoil and adversity in forgotten places earned acclaim from readers around the world.", "at": "這位四處奔走的記者從不甘於久坐不動，三十年來穿梭於世界各地的戰區，她對被遺忘之地的動盪與苦難所寫的熱切報導，贏得了世界各地讀者的讚譽。"}, {"w": "nomadic", "p": "adj.", "d": "Moving from place to place without a permanent home.", "c": "遊牧的；流浪的", "s": "For centuries, the Mongols maintained a nomadic way of life on the Central Asian steppe, moving their felt tents and herds of horses, sheep, and yaks between summer and winter pastures to prevent overgrazing in the harsh, arid grasslands.", "t": "數百年來，蒙古人在中亞草原上維持著遊牧的生活方式，在夏季與冬季牧場之間遷移他們的氈帳以及成群的馬、羊和犛牛，以避免在嚴酷乾旱的草原上過度放牧。", "as": "Colonial administrators, contemptuous of nomadic herders, tried to force them into sedentary villages, but the policy proved detrimental, as pastures became overgrazed and once-thriving communities sank into penurious dependence on aid.", "at": "殖民地官員輕視遊牧民族，試圖迫使他們遷入定居的村落，但這項政策證明是有害的：牧場遭到過度放牧，曾經興盛的社群也陷入仰賴援助的貧困處境。"}, {"w": "itinerant", "p": "adj.", "d": "Traveling from place to place to work.", "c": "巡迴的；流動的；四處奔波的", "s": "In nineteenth-century America, itinerant portrait painters traveled from town to town along rivers and turnpikes, offering to capture a family's likeness for a modest fee, and many of the anonymous works they left behind are now prized by folk-art collectors.", "t": "在十九世紀的美國，巡迴肖像畫家沿著河流與收費公路從一個城鎮走到另一個城鎮，以低廉的費用為人家畫像，他們留下的許多無名作品如今深受民俗藝術收藏家珍視。", "as": "The itinerant preacher was a gifted orator whose eloquence and impassioned sermons drew enormous crowds in every frontier town he visited, though some established clergy derided his rhetorical flourishes as mere grandiloquent showmanship.", "at": "這位巡迴傳教士是位天賦異稟的演說家，他的雄辯與激昂的布道在他造訪的每個邊疆小鎮都吸引大批群眾，儘管有些體制內的神職人員嘲笑他的修辭技巧只是浮誇的表演。"}, {"w": "fleeting", "p": "adj.", "d": "Passing swiftly; lasting only a moment.", "c": "稍縱即逝的；短暫的", "s": "Astronomers detected the gravitational waves produced by two colliding black holes as a fleeting signal lasting only a fifth of a second, yet that tiny ripple in spacetime confirmed a prediction Albert Einstein had made a century earlier in his general theory of relativity.", "t": "天文學家偵測到兩個碰撞黑洞所產生的重力波，那只是一個持續僅五分之一秒、稍縱即逝的訊號，然而這道時空中的微小漣漪，卻證實了愛因斯坦一個世紀前在廣義相對論中提出的預測。", "as": "The candidate's fleeting moment of levity during an otherwise contentious televised debate charmed millions of viewers, briefly softening his long-standing reputation as an aloof and haughty politician who rarely connected with ordinary voters.", "at": "在這場原本火藥味十足的電視辯論中，這位候選人短暫流露的幽默打動了數百萬觀眾，一時軟化了他長久以來冷漠高傲、很少與一般選民產生共鳴的政治人物形象。"}, {"w": "volatile", "p": "adj.", "d": "Liable to change rapidly and unpredictably.", "c": "易變的；不穩定的；揮發性的", "s": "Cryptocurrency prices have proved extraordinarily volatile, sometimes rising or falling by more than twenty percent in a single day in response to a celebrity's social media post or rumors of new government regulation, making them a risky choice for retirement savings.", "t": "加密貨幣的價格已證明極度不穩定，有時會因名人在社群媒體上的一則貼文或政府即將出台新規範的傳聞，而在一天之內漲跌超過百分之二十，因此用來作為退休儲蓄是一項風險很高的選擇。", "as": "The volatile political climate, inflamed by belligerent rhetoric and rancorous partisanship on both sides, left moderate legislators in a quandary about whether to mediate between the warring factions or simply stay silent until the election.", "at": "在雙方好戰的言論與充滿怨恨的黨派對立煽動下，這種動盪多變的政治氣候讓溫和派議員陷入兩難：究竟該在交戰的派系之間居中調停，還是乾脆保持沉默直到選舉結束。"}, {"w": "vagrant", "p": "n./adj.", "d": "A person without a settled home or job; wandering.", "c": "流浪者;漂泊的", "s": "Local police were tasked with relocating the vagrant s from the park.", "t": "當地警方被指派將這些流浪者從這座公園遷離。", "as": "He led a vagrant life, moving from city to city without roots.", "at": "他過著漂泊不定的生活,從一座城市輾轉到另一座城市,沒有根。", "a": 1}, {"w": "vagabond", "p": "n./adj.", "d": "A person who wanders without a fixed home; wandering.", "c": "流浪漢;流浪的", "s": "The old vagabond traveled from town to town, telling stories for food.", "t": "這位老流浪漢從一個城鎮輾轉到另一個城鎮,靠說故事換取食物。", "as": "He led a vagabond existence for years before finally settling down.", "at": "他過了好幾年流浪的生活,最終才安定下來。", "a": 1}, {"w": "migratory", "p": "adj.", "d": "Relating to seasonal movement from one region to another.", "c": "遷徙的;候鳥性的", "s": "The wetland provides critical habitat for migratory birds.", "t": "這片濕地為候鳥提供了關鍵的棲息地。", "as": "Many migratory workers followed the harvest seasons across the region.", "at": "許多流動遷徙的工人跟隨這個地區的收成季節四處遷移。", "a": 1}, {"w": "mutable", "p": "adj.", "d": "Able to change.", "c": "可變的/易變的", "s": "Human memory is far more mutable than most people realize.", "t": "人類的記憶遠比大多數人所意識到的更容易改變。", "as": "Laws are mutable, adapting over time to reflect society's changing values.", "at": "法律是可變的,隨著時間演變以反映社會不斷變化的價值觀。", "a": 1}]}, {"unit": 24, "theme": "New and Old", "themeZh": "新與舊", "antonymLessons": [], "cards": [{"w": "contemporary", "p": "adj.", "d": "Belonging to the present time; modern.", "c": "當代的；現代的；同時代的", "s": "Although Shakespeare's plays were written more than four centuries ago, directors continue to stage them in contemporary settings — corporate boardrooms, refugee camps, and social-media-obsessed high schools — to show audiences that his insights into ambition, jealousy, and power remain strikingly relevant today.", "t": "雖然莎士比亞的劇作寫於四百多年前，導演們仍不斷將它們搬上當代的場景——企業董事會議室、難民營，以及沉迷社群媒體的高中——藉此向觀眾展現，他對野心、嫉妒與權力的洞見至今依然切中時弊。", "as": "Critics who once derided contemporary architecture as banal and derivative were forced to reconsider their views when the museum's daring glass pavilion, praised by ardent admirers from Tokyo to Berlin, won international acclaim.", "at": "曾經嘲笑當代建築平庸又缺乏原創性的評論家，在這座博物館大膽的玻璃展館受到從東京到柏林的熱情擁護者讚賞、並贏得國際好評後，不得不重新思考自己的看法。"}, {"w": "inception", "p": "n.", "d": "The beginning or establishment of something.", "c": "開端；開始；創立", "s": "From its inception in 1901, the Nobel Prize has generated controversy, as critics have repeatedly questioned why certain groundbreaking scientists and writers were overlooked while others whose achievements now seem modest received the honor and its substantial financial award.", "t": "諾貝爾獎自1901年創立以來便爭議不斷，批評者一再質疑，為何某些具開創性的科學家與作家遭到忽視，而另一些如今看來成就平平的人卻獲得這項殊榮及其豐厚的獎金。", "as": "Since its inception, the philanthropic foundation has drawn on the munificent gifts of a few donors to alleviate poverty in rural villages, though skeptics have impugned its motives as self-promotion.", "at": "這個慈善基金會自創立以來，便仰賴少數捐款人的慷慨捐贈來減輕鄉村的貧困，儘管懷疑者質疑其動機只是為了自我宣傳。"}, {"w": "innovation", "p": "n.", "d": "A new idea, method, or invention.", "c": "創新；革新；新發明", "s": "Economic historians argue that the shipping container, a simple steel box standardized in the 1950s, was one of the most consequential innovations of the twentieth century, cutting the cost of loading cargo by more than ninety percent and making modern globalized supply chains possible.", "t": "經濟史學家認為，1950年代標準化的貨櫃——一個簡單的鋼製箱子——是二十世紀最具影響力的創新之一，它使裝貨成本降低了九成以上，也讓現代全球化的供應鏈成為可能。", "as": "Hidebound executives dismissed the engineer's innovation as a frivolous gadget, but its unprecedented success forced the company's obstinate board to abandon its antiquated product line and embrace the new technology.", "at": "守舊的高層主管把這位工程師的創新斥為無聊的小玩意，但它空前的成功迫使公司固執的董事會放棄過時的產品線，轉而擁抱這項新技術。"}, {"w": "unprecedented", "p": "adj.", "d": "Never done, seen, or known before.", "c": "空前的；史無前例的", "s": "When the Apollo 11 astronauts landed on the Moon in July 1969, the event drew an unprecedented television audience of roughly 650 million people, a number far larger than any previous broadcast had attracted and a testament to the global reach of the new medium.", "t": "1969年7月阿波羅11號太空人登陸月球時，這起事件吸引了約六億五千萬名電視觀眾，規模空前，遠遠超過以往任何一次轉播，也證明了這個新興媒體在全球的影響力。", "as": "The unprecedented flood unleashed turmoil across the river delta, and the government's lackluster response, combined with officials' strangely apathetic public statements, only deepened popular animosity toward the ruling party in the months before the election.", "at": "這場空前的洪水在河流三角洲各地造成動盪，而政府乏善可陳的應變，加上官員異常冷漠的公開發言，在選前幾個月只讓民眾對執政黨的敵意更加深重。"}, {"w": "relic", "p": "n.", "d": "An object or custom surviving from an earlier time.", "c": "遺物；遺跡；遺風", "s": "Linguists regard certain spellings in modern English, such as the silent k in knight and knee, as relics of a period when those letters were actually pronounced, preserving traces of Old English sounds that disappeared from speech many centuries ago.", "t": "語言學家認為，現代英語中的某些拼法，例如 knight 和 knee 中不發音的 k，是那些字母仍實際發音時代的遺跡，保存了早在數百年前就已從口語中消失的古英語發音痕跡。", "as": "To younger voters, the aging senator's bellicose speeches seemed a relic of the Cold War, and his pompous, grandiloquent style struck many of them as more pretentious than persuasive in an era of short videos.", "at": "對年輕選民而言，這位年邁參議員好戰的演說彷彿是冷戰時期的遺風；在短影音當道的時代，他浮誇、華而不實的風格在許多人看來，矯揉造作多於說服力。"}, {"w": "obsolete", "p": "adj.", "d": "No longer used or needed; out of date.", "c": "過時的；淘汰的；廢棄的", "s": "The rapid spread of smartphones in the 2010s made a range of once-essential devices nearly obsolete within a single decade, as consumers abandoned standalone cameras, GPS units, alarm clocks, and music players in favor of one pocket-sized machine that could perform all of their functions.", "t": "2010年代智慧型手機的迅速普及，使得一系列曾經不可或缺的裝置在短短十年內幾乎遭到淘汰，因為消費者紛紛捨棄獨立的相機、衛星導航裝置、鬧鐘和音樂播放器，改用一台能執行所有功能的口袋型機器。", "as": "The textile factory's obsolete machinery, sluggish and prone to frequent breakdowns, had become a detrimental burden, yet the parsimonious owner refused to replace it, preferring to squander money on constant repairs that never solved the problem.", "at": "這家紡織廠過時的機器運轉遲緩又常常故障，已成為一大負擔，然而吝嗇的老闆卻拒絕更換，寧可把錢浪費在始終解決不了問題的不斷維修上。"}, {"w": "novel", "p": "adj.", "d": "New and original; unlike anything seen before.", "c": "新穎的；新奇的", "s": "Rather than relying on conventional antibiotics, researchers at the university developed a novel treatment for drug-resistant infections that uses specially engineered viruses to attack harmful bacteria while leaving the patient's own cells and beneficial microbes completely unharmed.", "t": "研究人員並未仰賴傳統抗生素，而是開發出一種治療抗藥性感染的新穎療法，利用經過特殊改造的病毒攻擊有害細菌，同時完全不傷害病患自身的細胞與有益的微生物。", "as": "Rather than repeating the trite platitudes of her rivals, the candidate offered a novel proposal to mitigate housing costs, and even her most captious critics admitted that the plan was ingenious.", "at": "這位候選人沒有重複對手那些陳腐的老生常談，而是提出了一項減輕住房成本的新穎方案，就連最吹毛求疵的批評者都承認這項計畫十分巧妙。"}, {"w": "archaic", "p": "adj.", "d": "Very old or old-fashioned; no longer in common use.", "c": "古老的；過時的；古體的", "s": "Students reading the King James Bible often stumble over its archaic vocabulary — words such as thee, thou, and wherefore, along with verb endings like -eth — which reflect English as it was spoken in the early seventeenth century rather than the language used today.", "t": "閱讀《欽定版聖經》的學生常被其中古老的詞彙絆住——例如 thee、thou、wherefore 等字，以及 -eth 之類的動詞字尾——這些反映的是十七世紀初期所說的英語，而非今日使用的語言。", "as": "Reformers castigated the state's archaic voting rules as iniquitous, arguing that the hidebound system allowed a small, complacent elite to retain power for generations while ordinary citizens grew increasingly indignant at being shut out.", "at": "改革者嚴厲抨擊該州過時的投票規則極不公平，認為這套守舊的制度讓一小撮自滿的菁英得以世代掌權，而被排除在外的一般公民則越來越憤慨。"}, {"w": "antiquated", "p": "adj.", "d": "Old-fashioned or outdated, no longer suitable.", "c": "過時的；陳舊的；老式的", "s": "Investigators concluded that the air-traffic control center's antiquated computer system, which still relied on floppy disks and software written in the 1980s, had contributed to the nationwide flight delays, and they urged Congress to fund a long-overdue modernization program.", "t": "調查人員認定，這個航管中心老舊的電腦系統——仍仰賴磁碟片和1980年代編寫的軟體——是造成全國航班延誤的原因之一，並敦促國會撥款推動一項早該進行的現代化計畫。", "as": "The school's antiquated curriculum, filled with mundane grammar drills and soporific lectures, left even the brightest students listless and disengaged, until a zealous new principal introduced project-based learning and invited local scientists into the classroom.", "at": "這所學校陳舊的課程充斥著枯燥的文法練習和令人昏昏欲睡的講課，連最聰明的學生都無精打采、提不起興趣，直到一位熱忱的新校長引進專題式學習，並邀請當地科學家走進教室。"}, {"w": "antediluvian", "p": "adj.", "d": "Extremely old or ridiculously old-fashioned.", "c": "遠古的；極其古老的；老掉牙的", "s": "The editorial mocked the club's antediluvian membership rules, which still barred women from the main dining room and required gentlemen to wear tailcoats on Sundays, as practices so ancient they seemed to predate not only the twentieth century but recorded history itself.", "t": "這篇社論嘲諷該俱樂部那些老掉牙的會員規定——仍禁止女性進入主餐廳，並要求男士週日必須穿燕尾服——說這些做法古老得似乎不僅早於二十世紀，甚至早於有文字記載的歷史本身。", "as": "The professor's antediluvian views on women in science struck many of his students as odious, and their vociferous protests outside the lecture hall eventually led the university's board to censure him publicly and suspend his teaching duties.", "at": "這位教授對女性從事科學的老掉牙觀點，令許多學生覺得可憎，他們在演講廳外的激烈抗議最終促使大學董事會公開譴責他，並暫停他的授課職務。"}, {"w": "antiquity", "p": "n.", "d": "The distant past, especially before the Middle Ages.", "c": "古代；上古時期；古物", "s": "The Antikythera mechanism, a bronze device recovered from a Greek shipwreck, has astonished scholars because it used interlocking gears to predict eclipses and planetary motions, proving that engineers in antiquity possessed a mechanical sophistication not seen again in Europe for over a thousand years.", "t": "安提基特拉機械是從一艘希臘沉船中打撈出的青銅裝置，它令學者大感驚奇，因為它利用相互嚙合的齒輪預測日月食與行星運行，證明古代的工程師擁有歐洲此後一千多年都未再見過的精密機械技術。", "as": "Since antiquity, philosophers from Confucius to Aristotle have extolled the virtue of moderation, warning that avarice and prodigal living are pernicious to both individuals and states, since unchecked desire erodes character and drains public treasuries.", "at": "自古以來，從孔子到亞里斯多德的哲學家都頌揚節制的美德，並警告貪婪與揮霍的生活對個人和國家都有害，因為不受約束的慾望會腐蝕品格、耗盡國庫。"}]}, {"unit": 25, "theme": "Secret and Stealthy", "themeZh": "隱密與偷偷摸摸", "antonymLessons": [90], "cards": [{"w": "inconspicuous", "p": "adj.", "d": "Not easily noticed; not attracting attention.", "c": "不顯眼的；不引人注意的", "s": "Many of the most dangerous invasive species arrive in a new ecosystem in inconspicuous ways — as tiny seeds lodged in the treads of hikers' boots or as larvae hidden in the ballast water of cargo ships — so that by the time biologists notice them, eradication is nearly impossible.", "t": "許多最危險的外來入侵物種都是以不顯眼的方式進入新的生態系——例如卡在登山客鞋底紋路中的微小種子，或藏在貨輪壓艙水中的幼蟲——等到生物學家發現時，往往已幾乎不可能根除。", "as": "Though inconspicuous in a crowd, the reticent archivist proved remarkably astute, and her quiet discovery of a forged deed exposed a devious land grab that a more ostentatious investigator, eager for headlines, had completely overlooked.", "at": "這位沉默寡言的檔案管理員在人群中毫不起眼，卻展現出非凡的敏銳；她悄悄發現一份偽造的地契，揭穿了一樁狡詐的土地掠奪，而一位愛出風頭、急於搶占頭條的調查員卻完全忽略了這件事。"}, {"w": "surreptitious", "p": "adj.", "d": "Done secretly because it would not be approved of.", "c": "暗中的；鬼鬼祟祟的；偷偷的", "s": "Historians discovered that the nineteenth-century botanist Robert Fortune made surreptitious journeys into China's tea-growing regions disguised as a Chinese merchant, secretly collecting seeds and plants that the British East India Company later used to break China's monopoly on tea production.", "t": "歷史學家發現，十九世紀的植物學家羅伯特・福鈞曾喬裝成中國商人，暗中潛入中國的產茶區，偷偷採集種子與植株，英國東印度公司後來便利用這些植物打破了中國對茶葉生產的壟斷。", "as": "The chess grandmaster was accused of surreptitious cheating after officials noticed a tiny device in his sleeve, and the scandal led organizers to censure him and impose a ban that the arrogant player denounced as malicious and unjust.", "at": "這位西洋棋特級大師在官員發現他袖子裡藏有一個小裝置後，被指控暗中作弊；這樁醜聞導致主辦單位公開譴責他並對他施以禁賽，而這位傲慢的棋手則痛斥此舉是惡意且不公的。"}, {"w": "unobtrusive", "p": "adj.", "d": "Not conspicuous or attracting attention; quietly modest.", "c": "不張揚的；不顯眼的；不引人注目的", "s": "The best documentary filmmakers strive to be unobtrusive, using small cameras, natural light, and minimal crews so that their subjects gradually forget they are being filmed and begin to behave as they would in private, revealing emotions they would otherwise conceal.", "t": "最優秀的紀錄片導演都力求不引人注目，使用小型攝影機、自然光和精簡的團隊，讓拍攝對象逐漸忘記自己正在被拍攝，開始表現出私下的模樣，流露出他們原本會隱藏的情緒。", "as": "The museum's renovation added unobtrusive lighting and quiet climate controls to the antiquated galleries, a subtle approach that won acclaim from critics who had feared an ostentatious redesign and who now extolled the architect's restraint.", "at": "博物館的整修工程為老舊的展廳加裝了不顯眼的照明和安靜的空調系統，這種低調的做法贏得了評論家的好評；他們原本擔心會是一場炫耀浮誇的改造，如今則頌揚建築師的克制。"}, {"w": "furtive", "p": "adj.", "d": "Attempting to avoid notice, typically out of guilt.", "c": "偷偷摸摸的；鬼鬼祟祟的；心虛的", "s": "Security analysts reviewing the footage noticed the suspect's furtive behavior long before the theft occurred: he repeatedly glanced toward the cameras, lingered near the emergency exit, and quickly turned his face away whenever a guard walked through the gallery.", "t": "檢視監視畫面的保全分析人員早在竊案發生前，就注意到嫌犯鬼鬼祟祟的舉動：他一再瞄向攝影機，在緊急出口附近徘徊，而且每當警衛走過展廳時，便迅速把臉轉開。", "as": "The defendant's furtive glances toward his lawyer did little to help his case; the prosecutor, pugnacious and incisive, seized on his evasive answers and wove them into a damning portrait of a devious man.", "at": "被告頻頻偷瞄律師的心虛眼神，對他的案子毫無幫助；好鬥又犀利的檢察官緊抓住他閃爍其詞的回答，將之編織成一幅狡詐之人的致命畫像。"}, {"w": "clandestine", "p": "adj.", "d": "Kept secret or done secretly, often illicitly.", "c": "秘密的；暗中進行的；地下的", "s": "During the Second World War, members of the French Resistance operated clandestine printing presses in cellars and barns, producing underground newspapers that countered Nazi propaganda, though anyone caught distributing them faced arrest, deportation, or even execution.", "t": "第二次世界大戰期間，法國反抗軍成員在地窖和穀倉裡經營秘密印刷廠，印製反制納粹宣傳的地下報紙；然而任何人一旦被抓到散發這些報紙，就會面臨逮捕、驅逐出境，甚至處決。", "as": "The investigative journalists uncovered a clandestine network of mercenary customs officials who had colluded with nefarious smugglers for years, and their exposé prompted lawmakers to censure the agency and demand sweeping reforms.", "at": "調查記者們揭露了一個秘密網絡：一群唯利是圖的海關官員多年來與邪惡的走私集團勾結；他們的揭弊報導促使立法者譴責該機構，並要求進行全面改革。"}, {"w": "covert", "p": "adj.", "d": "Not openly shown or acknowledged; secret.", "c": "隱蔽的；秘密的；暗中的", "s": "Declassified documents later revealed that the government had funded a covert program in the 1950s to influence foreign elections, secretly channeling money to friendly newspapers and political parties while publicly insisting that it respected the sovereignty of every nation.", "t": "後來解密的文件揭露，政府在1950年代曾資助一項秘密計畫來影響外國選舉，暗中將資金輸送給友好的報社與政黨，同時卻公開堅稱自己尊重每個國家的主權。", "as": "The covert surveillance program, once exposed, provoked vociferous outrage, and civil-liberties groups castigated officials whose devious justifications seemed to rest on little more than vague, ominous warnings about unnamed threats.", "at": "這項秘密監控計畫一經曝光便引發強烈抗議，公民自由團體嚴厲抨擊官員，因為他們狡詐的辯解似乎只是建立在對不明威脅含糊又不祥的警告之上。"}, {"w": "sly", "p": "adj.", "d": "Cunning and deceitful, or playfully mischievous.", "c": "狡猾的；狡黠的；會心的", "s": "In West African folklore, Anansi the spider is a sly trickster who outwits far stronger animals, such as the python and the leopard, through clever schemes and deceptive bargains, and his stories taught generations of listeners that intelligence can triumph over brute force.", "t": "在西非民間傳說中，蜘蛛阿南西是一個狡猾的騙子，他用巧妙的計謀和騙人的交易智取比他強大得多的動物，例如巨蟒和豹；他的故事教導了一代又一代的聽眾：智慧能戰勝蠻力。", "as": "The sly negotiator feigned an affable, almost obsequious manner, flattering his rivals with lavish compliments over dinner while quietly maneuvering to exploit their complacent assumption that the deal was already settled.", "at": "這位狡猾的談判者假裝和藹可親、近乎諂媚，在晚宴上以大量的恭維話奉承對手，同時暗中設法利用他們自以為交易已成定局的自滿心態。"}, {"w": "stealthy", "p": "adj.", "d": "Moving or acting quietly and carefully to avoid notice.", "c": "偷偷摸摸的；悄悄的；隱密的", "s": "Owls are among the most stealthy hunters in the animal kingdom, because the comb-like edges of their flight feathers break up turbulent air and muffle the sound of their wings, allowing them to swoop down on mice and voles without making any audible noise.", "t": "貓頭鷹是動物界中最擅長悄然獵食的獵手之一，因為牠們飛羽邊緣的梳狀構造能打散亂流、消除翅膀拍動的聲音，讓牠們能在完全不發出可聞聲響的情況下俯衝捕捉老鼠和田鼠。", "as": "The stealthy predator crept through the tall grass toward the gazelles, and its patience contrasted sharply with the raucous, impetuous young lions whose clamor alerted the entire herd and ruined the hunt.", "at": "這隻悄無聲息的掠食者穿過高草叢，悄悄逼近瞪羚；牠的耐心與那些吵鬧、魯莽的年輕獅子形成強烈對比，後者的喧鬧聲驚動了整個羚群，壞了這場狩獵。"}, {"w": "sneaky", "p": "adj.", "d": "Marked by quiet and caution and secrecy.", "c": "偷偷摸摸的/鬼鬼祟祟的", "s": "The cat took a sneaky path along the fence to avoid the dog.", "t": "這隻貓沿著圍籬走了一條偷偷摸摸的路線,以避開那隻狗。", "as": "She caught him in the sneaky act of reading her diary.", "at": "她當場抓到他鬼鬼祟祟地在看她的日記。", "a": 1}, {"w": "wily", "p": "adj.", "d": "Crafty, sly.", "c": "狡猾的/機靈的", "s": "The wily fox managed to slip past the guard dogs once again.", "t": "這隻狡猾的狐狸再次成功溜過了看門狗的追捕。", "as": "Her wily negotiating tactics won her a much better contract.", "at": "她狡黠的談判手腕讓她爭取到一份好上許多的合約。", "a": 1}, {"w": "cunning", "p": "adj.", "d": "Sly, clever at being deceitful.", "c": "狡猾的/精明的", "s": "The cunning fox managed to escape the trap once again.", "t": "這隻狡猾的狐狸再度成功躲過了陷阱。", "as": "Her cunning plan fooled even her closest friends.", "at": "她狡猾的計畫甚至騙過了她最親近的朋友。", "a": 1}, {"w": "crafty", "p": "adj.", "d": "Cleverly cunning or deceitful.", "c": "狡猾的", "s": "The crafty fox slipped past the sleeping guard dog.", "t": "這隻狡猾的狐狸悄悄溜過了熟睡的看門狗。", "as": "Her crafty plan fooled even her closest friends.", "at": "她狡猾的計畫連最親近的朋友都被騙了。", "a": 1}, {"w": "artful", "p": "adj.", "d": "Clever or skillful, especially in a cunning way.", "c": "巧妙的;狡猾的", "s": "The negotiator's artful compromise satisfied both sides without either feeling defeated.", "t": "這位談判專家巧妙的折衷方案,讓雙方都感到滿意,不覺得自己輸了。", "as": "The con artist was known for his artful schemes targeting elderly investors.", "at": "這名詐騙犯以針對年長投資人的狡猾騙局而惡名昭彰。", "a": 1}, {"w": "latent", "p": "adj.", "d": "(of a quality or state) existing but not yet developed or manifest; hidden=potential; concealed.", "c": "潛在的；潛伏的", "s": "The teacher recognized the latent talent in the shy student, realizing that although he rarely spoke in class, his written essays demonstrated a profound understanding of literature that just needed encouragement to bloom.", "t": "老師認出了這位害羞學生身上潛伏的天賦，意識到雖然他很少在課堂上發言，但他的書面文章表現出對文學的深刻理解，只需要鼓勵就能綻放。", "as": "", "at": "", "a": 1}, {"w": "concealed", "p": "adj.", "d": "Kept hidden or out of sight.", "c": "隱藏的;隱蔽的", "s": "Security guards discovered a concealed weapon during the routine search.", "t": "保全人員在例行搜查中發現了一件隱藏的武器。", "as": "Her concealed resentment finally surfaced during the family dinner.", "at": "她隱藏的怨氣終於在這場家庭晚餐上爆發了出來。", "a": 1}]}, {"unit": 26, "theme": "Types of People", "themeZh": "人物類型", "antonymLessons": [], "cards": [{"w": "adversary", "p": "n.", "d": "An opponent or enemy in a contest or conflict.", "c": "對手；敵手", "s": "Although Douglas had been Lincoln's bitter adversary throughout the 1858 Senate campaign, trading accusations in seven heated debates across Illinois, he later stood beside the new president at his inauguration, holding Lincoln's hat as a public gesture of national unity.", "t": "雖然道格拉斯在1858年參議員選戰中一直是林肯的激烈對手，兩人在伊利諾州各地的七場激辯中互相指控，但道格拉斯後來在這位新總統的就職典禮上站在他身旁，替林肯拿著帽子，以公開表示國家團結。", "as": "Instead of trying to berate or intimidate his longtime adversary, the veteran negotiator adopted a cordial, conciliatory tone, a tactic that helped to mollify the opposing delegation and eventually produced an amicable settlement.", "at": "這位資深談判代表沒有試圖斥責或恐嚇他的老對手，而是採取親切、和解的語氣；這個策略有助於安撫對方代表團，最終達成了友好的和解。"}, {"w": "raconteur", "p": "n.", "d": "A person who tells anecdotes and stories with skill and wit.", "c": "善於講故事的人；健談者", "s": "Mark Twain was celebrated not only as a novelist but as a gifted raconteur whose lecture tours drew packed halls across America and Europe, where audiences laughed for hours at his meandering anecdotes, perfectly timed pauses, and deadpan delivery of absurd frontier tales.", "t": "馬克·吐溫不僅以小說家聞名，也是一位才華洋溢、善於說故事的人；他的巡迴演講在美國和歐洲場場爆滿，觀眾聽著他曲折的軼事、拿捏精準的停頓，以及面無表情講述的荒誕邊疆故事，常常笑上好幾個小時。", "as": "A born raconteur, the retired diplomat kept his convivial dinner guests enthralled with pithy anecdotes, though he was careful never to digress so far that his stories became verbose or lost their comic brevity.", "at": "這位退休外交官天生善於說故事，以精闢的軼事讓歡樂的晚宴賓客聽得入迷；不過他總是小心不扯得太遠，以免故事變得冗長，失去簡潔帶來的喜感。"}, {"w": "ascetic", "p": "n.", "d": "A person who practices severe self-denial, often for religious reasons.", "c": "苦行者；禁慾者", "s": "The early Christian ascetic Simeon Stylites reportedly spent thirty-seven years living atop a stone pillar in the Syrian desert, renouncing comfort, possessions, and most food in the belief that extreme physical deprivation would bring him closer to spiritual purity.", "t": "早期基督教苦行者柱頂聖西門據說在敘利亞沙漠中的一根石柱頂上生活了三十七年，摒棄舒適、財物與大部分食物，相信極端的肉體匱乏能讓他更接近靈性上的純淨。", "as": "Unlike the epicurean courtiers around him, the young prince Siddhartha left the palace to become an ascetic, adopting a diet so austere and abstemious that his followers feared he would grow fatally emaciated before attaining enlightenment.", "at": "年輕的悉達多王子不同於身邊講究享樂的朝臣，離開王宮成為苦行者，飲食極其簡樸節制，以致追隨者擔心他在悟道之前就會瘦弱致死。"}, {"w": "charlatan", "p": "n.", "d": "A person who falsely claims special knowledge or skill.", "c": "江湖郎中；騙子", "s": "In the nineteenth century, traveling salesmen peddled 'snake oil' tonics that supposedly cured everything from baldness to tuberculosis; when chemists finally analyzed one popular brand in 1917, they found mostly mineral oil and turpentine, exposing its seller as a charlatan who had profited from the desperation of the sick.", "t": "十九世紀，巡迴推銷員兜售「蛇油」補藥，聲稱能治好從禿頭到肺結核的各種病症；1917年化學家終於分析了一個熱門品牌，發現其成分主要是礦物油和松節油，揭穿了其賣家是個利用病人絕望心理牟利的江湖騙子。", "as": "The so-called psychic was eventually exposed as a charlatan whose cryptic predictions were nothing more than banal platitudes, delivered with a pretentious air to credulous clients who mistook his vague prattle for profound insight.", "at": "這位所謂的靈媒最終被揭穿是個騙子，他那些隱晦的預言不過是陳腐的老生常談，以故作高深的姿態說給輕信的客戶聽，而他們卻把他含糊的胡扯誤認為深刻的洞見。"}, {"w": "artisan", "p": "n.", "d": "A skilled worker who makes things by hand.", "c": "工匠；手藝人", "s": "In medieval Europe, each artisan belonged to a guild that regulated prices, protected trade secrets, and required apprentices to spend up to seven years learning to forge, weave, or carve by hand before they could submit a 'masterpiece' and open a workshop of their own.", "t": "在中世紀歐洲，每位工匠都隸屬於一個行會；行會規範價格、保護行業機密，並要求學徒花上長達七年的時間學習以手工鍛造、編織或雕刻，之後才能提交一件「傑作」，開設自己的作坊。", "as": "Though mass production has made many handicrafts obsolete, a meticulous artisan in Kyoto still spends weeks lacquering a single bowl, a scrupulous devotion to antiquated techniques that discerning collectors esteem far above any factory-made novelty.", "at": "儘管大量生產已讓許多手工藝過時，京都一位一絲不苟的工匠仍會花上數週為單一個碗上漆；這種對古老技法的嚴謹投入，深受有眼光的收藏家推崇，遠勝任何工廠製造的新奇商品。"}, {"w": "diva", "p": "n.", "d": "A celebrated female opera singer; a prima donna.", "c": "歌劇女伶；首席女歌手", "s": "Maria Callas, perhaps the most famous operatic diva of the twentieth century, transformed roles such as Norma and Tosca by combining a voice of extraordinary range with intense dramatic acting, and her reputation for temperamental outbursts only added to her legend among devoted opera fans.", "t": "瑪麗亞·卡拉絲或許是二十世紀最著名的歌劇女伶，她將音域非凡的嗓音與強烈的戲劇表演結合，徹底改變了《諾瑪》與《托斯卡》等角色；而她喜怒無常、脾氣火爆的名聲，更讓她在忠實歌劇迷心中成為傳奇。", "as": "Critics who had expected an ostentatious, haughty diva were surprised when the celebrated soprano proved affable and modest backstage, though onstage her mellifluous voice and ardent performance drew vociferous acclaim from the sold-out audience.", "at": "評論家原本預期會見到一位愛炫耀、高傲的女伶，沒想到這位知名女高音在後台親切又謙虛；而在台上，她甜美圓潤的歌聲與熱情洋溢的演出，贏得滿場觀眾熱烈的喝采。"}, {"w": "hedonist", "p": "n.", "d": "A person devoted to the pursuit of pleasure.", "c": "享樂主義者", "s": "The Roman emperor Elagabalus earned a reputation as a reckless hedonist, staging extravagant banquets where guests were showered with rose petals and served delicacies such as flamingo tongues, while he neglected the empire's finances in his relentless pursuit of sensual delight.", "t": "羅馬皇帝埃拉伽巴路斯以肆無忌憚的享樂主義者著稱，他舉辦奢華的宴會，讓賓客沐浴在玫瑰花瓣雨中，並享用紅鶴舌等珍饈，同時在不斷追求感官享受的過程中忽略了帝國的財政。", "as": "The prodigal heir, an unrepentant hedonist, continued to squander his vast inheritance on lavish parties and epicurean feasts in Monaco, ignoring the frugal advice of his parsimonious uncle until the family fortune had all but vanished.", "at": "這位揮霍無度的繼承人是個毫無悔意的享樂主義者，不斷把龐大的遺產揮霍在摩納哥的奢華派對與美食盛宴上，對吝嗇叔叔的節儉忠告置若罔聞，直到家族財富幾乎消失殆盡。"}, {"w": "pariah", "p": "n.", "d": "A person rejected and despised by society; an outcast.", "c": "被排斥者；社會棄兒", "s": "After Galileo published his defense of a sun-centered universe in 1632, the Inquisition placed him under house arrest, banned his book, and forbade him to publish any further works, so that one of Europe's most brilliant minds spent his final years as an intellectual pariah.", "t": "伽利略於1632年發表為日心說辯護的著作後，宗教裁判所將他軟禁、查禁他的書，並禁止他再出版任何著作；於是，這位歐洲最傑出的頭腦之一，在遭學術界排斥的處境中度過了晚年。", "as": "Once the scandal revealed his nefarious accounting schemes, the former tycoon quickly became a pariah; former allies began to censure him publicly, and even his most obsequious employees grew aloof and detached.", "at": "醜聞揭露他卑劣的做帳手法後，這位前大亨很快淪為眾人唾棄的對象；昔日盟友開始公開譴責他，就連最阿諛奉承的員工也變得冷淡疏離。"}, {"w": "skeptic", "p": "n.", "d": "A person who questions or doubts accepted beliefs.", "c": "懷疑論者；持懷疑態度者", "s": "When Alfred Wegener proposed in 1912 that the continents had once formed a single landmass, nearly every leading geologist was a skeptic, dismissing his theory because he could not explain what force might move such enormous masses of rock; only the discovery of seafloor spreading decades later vindicated him.", "t": "1912年魏格納提出各大陸曾經是一整塊陸地時，幾乎每位頂尖地質學家都抱持懷疑態度，因為他無法解釋是什麼力量能移動如此龐大的岩塊而否定了他的理論；直到數十年後海底擴張被發現，他才得以平反。", "as": "A seasoned skeptic, the science journalist was wary of the startup's grandiloquent claims and demanded rigorous data, refusing to be swayed by the founder's eloquence or the investors' fervent enthusiasm.", "at": "這位科學記者是個老練的懷疑論者，對這家新創公司浮誇的說法保持戒心，要求提出嚴謹的數據，不為創辦人的雄辯或投資人狂熱的興奮所動搖。"}, {"w": "virtuoso", "p": "n.", "d": "A person with outstanding technical skill, especially in music.", "c": "演奏名家；大師", "s": "Niccolò Paganini was such a dazzling virtuoso on the violin that rumors spread across nineteenth-century Europe claiming he had sold his soul to the devil, for audiences could not otherwise explain how one man could play such rapid, intricate passages with apparently effortless precision.", "t": "帕格尼尼的小提琴技藝如此令人目眩，以致十九世紀的歐洲謠傳他把靈魂賣給了魔鬼，因為觀眾無法用其他理由解釋，一個人如何能以看似毫不費力的精準度，演奏出如此快速又繁複的樂段。", "as": "The young piano virtuoso played with such exuberant brilliance that critics who usually disparage child prodigies were moved to extol her technique, and the audience's clamor for an encore echoed through a hall famous for its superb acoustics.", "at": "這位年輕的鋼琴大師演奏得如此活力四射、才華洋溢，連平常愛貶低神童的評論家都忍不住讚揚她的技巧；觀眾要求安可的喧鬧聲，迴盪在這座以絕佳音響效果聞名的音樂廳中。"}]}, {"unit": 27, "theme": "Unimportant and Irrelevant", "themeZh": "無關緊要與不相干", "antonymLessons": [], "cards": [{"w": "inconsequential", "p": "adj.", "d": "Not important or significant; having no real effect.", "c": "無關緊要的；微不足道的", "s": "Early critics dismissed the Wright brothers' twelve-second flight at Kitty Hawk as an inconsequential stunt, a curiosity that covered barely 120 feet and seemed to have no practical value, yet within two decades powered aircraft were carrying mail across continents and reshaping modern warfare.", "t": "早期的批評者把萊特兄弟在小鷹鎮那十二秒的飛行斥為無關緊要的特技表演，只是一個飛不到120英尺、看似毫無實用價值的新奇玩意兒；然而不到二十年，動力飛機就已跨越各大洲運送郵件，並重塑了現代戰爭。", "as": "The senator tried to dismiss the leaked memo as inconsequential, but his verbose, evasive circumlocution only made reporters more wary, and soon even his complacent allies began to censure him for concealing it.", "at": "這位參議員試圖把外洩的備忘錄說成無關緊要，但他冗長、閃爍其詞的拐彎抹角反而讓記者更加警惕；很快地，連他那些自滿的盟友也開始譴責他隱瞞此事。"}, {"w": "extraneous", "p": "adj.", "d": "Not belonging to or directly related to the matter at hand.", "c": "無關的；外來的", "s": "To ensure that the experiment measured only the effect of the new fertilizer, the researchers controlled every extraneous variable, keeping light, temperature, soil composition, and watering schedules identical for all two hundred seedlings throughout the twelve-week trial.", "t": "為了確保實驗只測量新肥料的效果，研究人員控制了所有無關的變因，在為期十二週的試驗中，讓全部兩百株幼苗的光照、溫度、土壤成分和澆水時間都保持一致。", "as": "A good editor ruthlessly deletes extraneous material, trimming verbose passages and hackneyed phrases from a manuscript until the prose is concise and every remaining sentence carries the pithy force that discriminating readers expect.", "at": "優秀的編輯會毫不留情地刪去稿件中多餘的內容，修剪冗長的段落和陳腐的詞句，直到文字簡潔有力，每個留下來的句子都具備挑剔的讀者所期待的精闢力量。"}, {"w": "irrelevant", "p": "adj.", "d": "Not connected with or applicable to the subject.", "c": "不相關的；不切題的", "s": "The judge sustained the prosecutor's objection, ruling that the defendant's charitable donations, however generous, were irrelevant to the question before the jury, which concerned only whether he had knowingly falsified the company's financial statements in 2019.", "t": "法官裁定檢察官的異議成立，認為被告的慈善捐款無論多麼慷慨，都與陪審團面前的問題無關，因為該問題只涉及他是否在2019年蓄意偽造公司的財務報表。", "as": "During the televised debate, the candidate would digress into irrelevant anecdotes about his childhood whenever a question became contentious, a habit that his adversary mocked as rhetorical evasion rather than genuine eloquence.", "at": "在電視辯論中，每當問題變得具爭議性，這位候選人就會岔開話題，講些與主題無關的童年軼事；他的對手譏諷這種習慣是修辭上的迴避，而非真正的口才。"}, {"w": "incidental", "p": "adj.", "d": "Occurring as a minor accompaniment to something more important.", "c": "附帶的；次要的", "s": "The Rosetta Stone was carved to record a routine priestly decree honoring King Ptolemy V; its value as a key to Egyptian hieroglyphs was purely incidental, a by-product of the scribes' decision to repeat the same text in three different scripts.", "t": "羅塞塔石碑原本是為了記錄一份向托勒密五世致敬的例行祭司詔令而刻製；它作為破解埃及象形文字之鑰的價值純屬附帶，是書吏決定用三種不同文字重複刻寫同一段內容所帶來的副產品。", "as": "For the itinerant scholar, the comfort of hotels was incidental; she was a frugal traveler who tolerated sedentary days in archives only because they yielded the relics and records she coveted.", "at": "對這位四處奔走的學者而言，旅館的舒適只是次要的；她是個節儉的旅人，之所以忍受在檔案館裡久坐不動的日子，只因那裡能找到她夢寐以求的文物與紀錄。"}, {"w": "trivial", "p": "adj.", "d": "Of little value or importance.", "c": "瑣碎的；微不足道的", "s": "Engineers initially regarded the loss of a few foam fragments during shuttle launches as a trivial maintenance issue, but in 2003 a briefcase-sized piece struck Columbia's wing, breaching its heat shield and causing the orbiter to disintegrate during re-entry.", "t": "工程師起初認為太空梭發射時掉落幾片泡沫碎片只是微不足道的維修問題，但在2003年，一塊公事包大小的碎片擊中哥倫比亞號的機翼，破壞了它的隔熱罩，導致太空梭在重返大氣層時解體。", "as": "The cantankerous critic would berate young novelists over trivial errors of punctuation, yet his own weekly reviews were riddled with banal clichés and so verbose that many readers found them nearly soporific.", "at": "這位脾氣暴躁的評論家會因為標點符號上的瑣碎錯誤而痛斥年輕小說家，然而他自己每週的書評卻充斥著平庸的陳腔濫調，而且冗長到許多讀者覺得幾乎催人入睡。"}, {"w": "peripheral", "p": "adj.", "d": "Of minor importance; not central to the main issue.", "c": "邊緣的；次要的", "s": "In Tom Stoppard's play Rosencrantz and Guildenstern Are Dead, two peripheral characters from Hamlet, who appear in only a few scenes of Shakespeare's tragedy, become the protagonists, while the prince himself is pushed to the margins of the action.", "t": "在湯姆·斯托帕德的劇作《君臣人子小命嗚呼》中，兩個在莎士比亞悲劇《哈姆雷特》裡只出現寥寥幾場戲的邊緣人物成了主角，而哈姆雷特王子本人反倒被推到劇情的邊緣。", "as": "The committee chair, anxious to quell a contentious dispute over the budget, steered discussion away from peripheral issues and urged members to mediate their differences rather than rant about every disputatious detail.", "at": "委員會主席急於平息一場關於預算、爭議激烈的爭端，將討論從次要議題上引開，並敦促委員們調解彼此的分歧，而不是針對每個有爭議的細節大聲咆哮。"}, {"w": "negligible", "p": "adj.", "d": "So small or unimportant as to be not worth considering.", "c": "可忽略的；微不足道的", "s": "Because air resistance has a negligible effect on a dense steel ball dropped from a few meters, physics students can safely ignore it when calculating the ball's acceleration, though the same assumption would produce wildly inaccurate results for a falling feather.", "t": "由於空氣阻力對從幾公尺高處落下的高密度鋼球影響小到可以忽略，物理系學生在計算鋼球加速度時可以放心不予考慮；然而同樣的假設若套用在落下的羽毛上，就會得出極不準確的結果。", "as": "The parsimonious company claimed that the cost of replacing its antiquated equipment would be prohibitive, yet auditors found the expense negligible compared with the copious profits it had hoarded with such avarice.", "at": "這家吝嗇的公司聲稱汰換老舊設備的成本高得令人卻步，但稽核人員發現，與它貪婪囤積的豐厚利潤相比，這筆支出微不足道。"}, {"w": "frivolous", "p": "adj.", "d": "Lacking seriousness or purpose; silly and unimportant.", "c": "輕浮的；無聊的", "s": "To discourage frivolous lawsuits, several states allow judges to fine plaintiffs who file claims with no legal merit, such as suits filed solely to harass a business rival or to pressure a defendant into paying a quick settlement rather than facing costly litigation.", "t": "為了遏止無聊的訴訟，有幾個州允許法官對提出毫無法律依據之訴訟的原告處以罰款；例如純粹為了騷擾商業對手而提起的訴訟，或是逼迫被告為了避免昂貴的官司而迅速付錢和解的訴訟。", "as": "Critics deprecated the minister's frivolous remarks about the flood as callous and insolent, arguing that his jocular levity during the press briefing showed an indifferent attitude toward the thousands of families left homeless.", "at": "批評者指責部長對水災所發表的輕率言論冷酷無禮，認為他在記者會上詼諧輕佻的態度，顯示出對數千個無家可歸家庭的漠不關心。"}, {"w": "petty", "p": "adj.", "d": "Of small importance; also, small-minded or spiteful.", "c": "瑣碎的；小心眼的", "s": "Historians argue that the Renaissance city-states of Italy squandered their wealth and military strength on petty rivalries over border villages and trade privileges, leaving the peninsula divided and vulnerable when the far larger armies of France and Spain invaded in the 1490s.", "t": "歷史學家認為，文藝復興時期的義大利城邦把財富與軍力浪費在為邊境村莊和貿易特權而起的瑣碎爭鬥上，導致半島四分五裂，在1490年代法國與西班牙更龐大的軍隊入侵時毫無抵抗之力。", "as": "The petty quarrels among the history faculty, fueled by mutual animosity and rancorous gossip, finally escalated into an open feud so contentious that the dean had to intervene and mediate.", "at": "歷史系教職員之間的瑣碎爭吵，在彼此的敵意與充滿怨恨的八卦推波助瀾下，最終升級為一場公開的激烈紛爭，使得院長不得不介入調解。"}, {"w": "trifling", "p": "adj.", "d": "Trivial; of little value or importance.", "c": "瑣碎的；微不足道的", "s": "The Dutch reportedly acquired the island of Manhattan in 1626 for goods worth about sixty guilders, a trifling sum even then, though historians caution that the Lenape probably understood the exchange as a temporary sharing agreement rather than a permanent sale of land.", "t": "據說荷蘭人在1626年以價值約六十荷蘭盾的貨物取得曼哈頓島，即使在當時也是微不足道的金額；不過歷史學家提醒，雷納佩人很可能把這場交易理解為暫時的共享協議，而非永久出售土地。", "as": "The miserly landlord would berate tenants over trifling damages such as a scuffed doorframe, yet he remained apathetic and indifferent when they reported the deleterious mold spreading through the building.", "at": "這位吝嗇的房東會因為門框刮痕這類微不足道的損壞而痛斥房客，但當房客回報大樓裡蔓延的有害黴菌時，他卻始終冷漠、漠不關心。"}, {"w": "insignificant", "p": "adj.", "d": "Too small or unimportant to matter.", "c": "微不足道的", "s": "The difference in price between the two ice creams was insignificant.", "t": "這兩種冰淇淋的價差微不足道。", "as": "He felt insignificant compared to the other, more experienced employees.", "at": "與其他更資深的員工相比,他覺得自己微不足道。", "a": 1}, {"w": "immaterial", "p": "adj.", "d": "Unimportant under the circumstances; irrelevant to a subject (Not material/not relevant).", "c": "不重要的、無關緊要的、非物質的", "s": "The judge sustained the objection, ruling that the witness's personal hobbies were entirely immaterial to the criminal case.", "t": "法官確認反對有效，裁定證人的個人愛好與這起刑事案件完全無關（不重要）。", "as": "Whether the office supplies cost a few dollars more or less is immaterial given our multimillion-dollar corporate revenue.", "at": "鑑於我們數百萬美元的公司營收，辦公用品的成本多幾美元或少幾美元都是微不足道的。", "a": 1}, {"w": "paltry", "p": "adj.", "d": "Petty, worthless.", "c": "微不足道的", "s": "He was offered a paltry sum for his years of hard work.", "t": "他多年來的辛勞只換得一筆微不足道的酬勞。", "as": "The company's donation seemed paltry compared to its massive profits.", "at": "與這家公司龐大的利潤相比,它的捐款顯得微不足道。", "a": 1}, {"w": "marginal", "p": "adj.", "d": "Relating to or at the edge or margin; minor; not central.", "c": "邊緣的；次要的", "s": "The scribes wrote comments in the marginal space of the manuscript, adding notes and explanations around the main text without altering the original author's words.", "t": "抄寫員在手稿的邊緣空白處寫下評論，在正文周圍添加注釋和解釋，而沒有改動原作者的文字。", "as": "", "at": "", "a": 1}, {"w": "tangential", "p": "adj.", "d": "Incidental, peripheral, divergent.", "c": "離題的/邊緣的", "s": "His comment was only tangential to the main topic of the meeting.", "t": "他的評論只是與這場會議的主題稍微沾邊而已。", "as": "The professor often goes off on tangential stories before returning to the lecture.", "at": "這位教授經常先扯些離題的故事,再回到正題繼續講課。", "a": 1}, {"w": "superficial", "p": "adj.", "d": "On the surface, slight.", "c": "表面的/膚淺的", "s": "Her knowledge of the subject turned out to be quite superficial.", "t": "她對這個主題的了解其實相當膚淺。", "as": "The wound was only superficial and healed within a few days.", "at": "這道傷口只是表皮的,幾天內就痊癒了。", "a": 1}]}, {"unit": 28, "theme": "Wise and Perceptive", "themeZh": "睿智與敏銳", "antonymLessons": [4], "cards": [{"w": "discerning", "p": "adj.", "d": "Showing good judgment and the ability to perceive fine distinctions.", "c": "有識別力的；有眼光的", "s": "Although Han van Meegeren's fake Vermeer, Supper at Emmaus, fooled leading Dutch experts in 1937, more discerning modern viewers quickly spot what those scholars missed: its heavy-lidded faces resemble 1930s film stars far more than the people Vermeer painted in seventeenth-century Delft.", "t": "雖然范·米格倫偽造的維梅爾畫作《以馬忤斯的晚餐》在1937年騙過了荷蘭頂尖的專家，但更有眼光的現代觀者很快就能看出那些學者所忽略的破綻：畫中眼皮厚重的臉孔，比起維梅爾在十七世紀台夫特所畫的人物，更像1930年代的電影明星。", "as": "A discerning reader quickly sees past the pretentious, grandiloquent prose of the celebrity memoir and recognizes that beneath its ostentatious vocabulary lie only trite observations, hackneyed sentiments, and a remarkably shallow understanding of history.", "at": "有眼光的讀者很快就能看穿這本名人回憶錄矯揉造作、浮誇的文字，發現在那些炫耀的辭藻底下，只有陳腐的觀察、老套的情感，以及對歷史極為膚淺的理解。"}, {"w": "erudite", "p": "adj.", "d": "Having or showing great knowledge gained from study.", "c": "博學的；學識淵博的", "s": "Jorge Luis Borges filled his short stories with references to medieval theology, Arabic philosophy, and obscure encyclopedias, an erudite style that delighted scholars but sometimes left general readers wondering which of his learned citations were real and which he had invented.", "t": "波赫士在短篇小說中充滿了對中世紀神學、阿拉伯哲學和冷僻百科全書的引用；這種博學的風格令學者著迷，卻有時讓一般讀者納悶，他那些學術性引文哪些是真的、哪些是他虛構的。", "as": "The erudite historian was neither haughty nor supercilious; her lectures, delivered with affable levity and vivid examples, made even the most labyrinthine debates of antiquity accessible to curious undergraduates with no background in classics.", "at": "這位博學的歷史學家既不傲慢也不目中無人；她以親切幽默的方式並搭配生動的例子授課，即使是古代最錯綜複雜的爭論，沒有古典學背景的好奇大學生也能理解。"}, {"w": "incisive", "p": "adj.", "d": "Intelligently analytical, clear, and direct.", "c": "一針見血的；犀利的", "s": "Rachel Carson's 1962 book Silent Spring offered an incisive critique of pesticide use, cutting through industry claims with precise scientific evidence and clear prose that showed exactly how DDT accumulated in food chains and thinned the eggshells of predatory birds.", "t": "瑞秋·卡森1962年的著作《寂靜的春天》對農藥使用提出了一針見血的批判，以精確的科學證據和清晰的文字戳破業界的說法，具體說明了DDT如何在食物鏈中累積，並使猛禽的蛋殼變薄。", "as": "Unlike the verbose, diffuse reports submitted by her colleagues, the analyst's incisive memo was succinct and direct, exposing the pernicious flaws in the proposed merger plan in fewer than two pages.", "at": "不同於同事們提交的冗長而鬆散的報告，這位分析師一針見血的備忘錄簡明扼要，用不到兩頁的篇幅就揭露了擬議合併計畫中的致命缺陷。"}, {"w": "ingenious", "p": "adj.", "d": "Clever, original, and inventive.", "c": "巧妙的；有創意的", "s": "To cool their homes without electricity, ancient Persian builders developed an ingenious system of wind-catching towers that funneled breezes over underground water channels, lowering indoor temperatures by as much as fifteen degrees even in the scorching summers of the desert.", "t": "為了在沒有電的情況下讓房屋降溫，古代波斯建築工匠發展出一套巧妙的捕風塔系統，將微風引導經過地下水道，即使在沙漠炙熱的夏季，也能使室內溫度降低多達十五度。", "as": "Faced with a precarious water supply, the frugal engineers devised an ingenious method of recycling water aboard the station, an innovation that was soon acclaimed as unprecedented by the space agency.", "at": "面對不穩定的供水，這些節儉的工程師設計出一套在太空站上回收水的巧妙方法，這項創新很快就被太空總署讚譽為前所未有的成就。"}, {"w": "perspicacious", "p": "adj.", "d": "Having a keen understanding and insight; mentally sharp.", "c": "有洞察力的；敏銳的", "s": "Alexis de Tocqueville, a perspicacious observer who toured the United States in 1831, predicted with startling accuracy that tensions over slavery would threaten the union and that America and Russia would one day each hold sway over half the world.", "t": "托克維爾是一位深具洞察力的觀察家，他於1831年遊歷美國，以驚人的準確度預言奴隸制度的緊張關係將威脅聯邦，而美國與俄國終有一天會各自主宰半個世界。", "as": "A perspicacious diplomat, she recognized early on that the rival delegation's cordial manner masked deep animosity toward her country, and she therefore remained vigilant and circumspect throughout the protracted and often tense negotiations.", "at": "她是一位洞察力敏銳的外交官，很早就看出對手代表團親切的態度掩飾著對她國家的深刻敵意，因此在冗長且經常緊張的談判過程中始終保持警覺與謹慎。"}, {"w": "astute", "p": "adj.", "d": "Quick to understand situations and turn them to advantage.", "c": "機敏的；精明的", "s": "Recognizing that the gold rush would enrich suppliers more reliably than miners, the astute merchant Levi Strauss opened a dry-goods business in San Francisco that supplied miners with clothing, fabric, and tools, building a fortune while most of his customers left California with empty pockets.", "t": "精明的商人李維·史特勞斯看出淘金熱帶給供應商的財富比給礦工的更可靠，於是在舊金山開設乾貨批發生意，供應礦工衣物、布料與工具；當大多數顧客兩手空空離開加州時，他卻累積了一大筆財富。", "as": "An astute investor, she avoided the volatile market's transient fads and refused to squander capital on novel schemes, preferring a prudent strategy that her more impetuous partners derided as overly wary.", "at": "她是一位精明的投資人，避開了動盪市場中曇花一現的風潮，拒絕把資金浪費在新奇的計畫上，寧可採取審慎的策略，雖然她那些較衝動的合夥人嘲笑這種做法過於謹慎。"}, {"w": "acute", "p": "adj.", "d": "Sharp and perceptive; keenly sensitive.", "c": "敏銳的；靈敏的", "s": "Bats compensate for their poor eyesight with remarkably acute hearing; by emitting high-frequency calls and analyzing the returning echoes, they can detect an insect as thin as a human hair and judge its distance and direction in complete darkness.", "t": "蝙蝠以極為靈敏的聽覺彌補視力的不足；牠們發出高頻叫聲並分析返回的回聲，能在一片漆黑中偵測到像人類頭髮一樣細的昆蟲，並判斷其距離與方向。", "as": "The critic's acute ear could detect the slightest discordant note in a performance, so her rare praise for the young cellist's mellifluous phrasing was esteemed far above the effusive acclaim of less exacting reviewers.", "at": "這位評論家敏銳的耳朵能察覺演出中最細微的不和諧音，因此她對這位年輕大提琴家甜美流暢的樂句罕見的讚美，遠比其他標準較寬鬆的評論者熱情洋溢的讚譽更受重視。"}, {"w": "prudent", "p": "adj.", "d": "Acting with care and thought for the future.", "c": "謹慎的；審慎的", "s": "After the devastating 1755 earthquake destroyed much of Lisbon, the Marquis of Pombal made the prudentedecision to rebuild with flexible wooden frames inside masonry walls, one of the earliest examples of earthquake-resistant construction in European history.", "t": "1755年的毀滅性大地震摧毀里斯本大半之後，龐巴爾侯爵作出了審慎的決定，在磚石牆內加入有彈性的木構架來重建城市，這是歐洲史上最早的抗震建築範例之一。", "as": "A prudent government stockpiles grain during years of ample harvests, a thrifty policy that can alleviate famine and mitigate the social turmoil that inevitably follows a catastrophic drought or a sudden collapse in food imports.", "at": "審慎的政府會在豐收的年份儲備糧食，這種節約的政策能緩解饑荒，並減輕嚴重乾旱或糧食進口驟減後必然隨之而來的社會動盪。"}, {"w": "judicious", "p": "adj.", "d": "Having or showing sound judgment; wise and sensible.", "c": "明智的；審慎的", "s": "Rather than rewriting the damaged fresco entirely, the conservators made judicious use of reversible pigments, filling only the cracks and missing fragments so that future restorers could distinguish clearly between Giotto's original brushwork and modern repairs.", "t": "修復師沒有全面重繪受損的濕壁畫，而是明智地使用可逆的顏料，只填補裂痕和缺失的碎片，好讓日後的修復者能清楚區分喬托的原始筆觸與現代的修補。", "as": "The judicious mediator listened impassively to both factions for hours, refused to castigate either side, and finally offered a compromise that managed to placate even the most recalcitrant and obstinate delegates.", "at": "這位明智的調解人面無表情地聆聽雙方陣營長達數小時，拒絕嚴厲斥責任何一方，最後提出一個折衷方案，甚至安撫了最頑固、最執拗的代表。"}, {"w": "sagacious", "p": "adj.", "d": "Having deep wisdom and sound judgment.", "c": "睿智的；有遠見的", "s": "Benjamin Franklin, then over eighty and the oldest delegate, offered the Constitutional Convention a sagacious warning in 1787: no assembly of fallible men could produce a perfect document, so delegates should accept the compromise rather than let their pride destroy the union.", "t": "1787年，年過八十、身為最年長代表的班傑明·富蘭克林向制憲會議提出睿智的忠告：任何由會犯錯的凡人組成的會議，都不可能產生完美的文件，因此代表們應該接受這項妥協，而不是讓自尊毀了聯邦。", "as": "The sagacious elder was revered by the nomadic tribe, for she could foresee ominous changes in the weather long before others noticed them and offer counsel that helped her people endure adversity without despair.", "at": "這位睿智的長者深受這個遊牧部落的敬重，因為她能比別人早得多預見天氣中不祥的變化，並提出建言，幫助族人度過逆境而不陷入絕望。"}, {"w": "savvy", "p": "adj.", "d": "Shrewd and knowledgeable, especially in practical matters.", "c": "精明的；懂行的", "s": "Long before social media existed, the circus promoter P. T. Barnum proved himself remarkably savvy about publicity, planting anonymous letters in newspapers that questioned his own exhibits so that the resulting controversy would draw even larger crowds to his museum.", "t": "早在社群媒體出現之前，馬戲團經紀人巴納姆就展現出他對宣傳極為精明的手腕：他在報紙上匿名投書，質疑自己的展品，讓隨之而來的爭議吸引更多人潮湧入他的博物館。", "as": "The savvy campaign manager knew that a candidate's vapid platitudes would not appease skeptical voters, so she urged him to abandon his banal slogans and speak candidly about the debacle.", "at": "這位精明的競選經理知道，候選人空洞的陳腔濫調無法平息心存懷疑的選民，於是敦促他拋棄平庸的口號，坦率地談論那場慘敗。"}, {"w": "shrewd", "p": "adj.", "d": "Having sharp practical judgment; clever in a practical way.", "c": "精明的；機靈的", "s": "In 1803 the United States made a shrewd bargain when it paid France about fifteen million dollars for the Louisiana Territory, doubling the nation's size for roughly three cents an acre at a moment when Napoleon urgently needed money for his wars in Europe.", "t": "1803年，美國以約一千五百萬美元向法國購得路易斯安那領地，做了一筆精明的交易：在拿破崙急需資金應付歐洲戰事之際，以每英畝約三美分的代價讓國土面積加倍。", "as": "The shrewd negotiator recognized that the mercenary contractors were motivated by avarice alone, so he offered a modest bonus that proved enough to mollify them and avert a costly debacle.", "at": "這位精明的談判者看出那些唯利是圖的承包商只受貪婪驅使，於是提供了一筆不多的獎金，結果足以安撫他們，避免了一場代價高昂的慘敗。"}, {"w": "perceptive", "p": "adj.", "d": "Having insight or good understanding.", "c": "有洞察力的；敏銳的", "s": "She is incredibly perceptive and notices even the smallest changes in people's emotions.", "t": "她非常敏銳，連人們情緒最細微的變化都能察覺。", "as": "", "at": "", "a": 1}, {"w": "insightful", "p": "adj.", "d": "Having or showing deep understanding.", "c": "有洞察力的;深刻的", "s": "Her insightful comments helped the team see the problem differently.", "t": "她深刻的見解幫助團隊以不同的角度看待這個問題。", "as": "The book offers insightful analysis of modern economics.", "at": "這本書提供了對現代經濟學深刻的分析。", "a": 1}, {"w": "trenchant", "p": "adj.", "d": "Keen, incisive.", "c": "銳利的/一針見血的", "s": "Her trenchant critique of the policy left the officials with no response.", "t": "她對這項政策一針見血的批評讓官員們啞口無言。", "as": "The columnist is famous for his trenchant wit and sharp observations.", "at": "這位專欄作家以他犀利的機智與敏銳的觀察聞名。", "a": 1}, {"w": "canny", "p": "adj.", "d": "Shrewd, careful.", "c": "精明的/謹慎的", "s": "The canny investor sold her stocks just before the market crashed.", "t": "這位精明的投資人在市場崩盤前就賣掉了她的股票。", "as": "A canny negotiator, he always knew when to walk away from the table.", "at": "身為一位精明的談判者,他總是知道何時該離開談判桌。", "a": 1}, {"w": "clever", "p": "adj.", "d": "Quick to understand or devise ingenious solutions.", "c": "聰明的;機智的", "s": "Her clever solution saved the company thousands of dollars.", "t": "她機智的解決方案,為公司省下了數千美元。", "as": "The fox in the fable is portrayed as clever but untrustworthy.", "at": "寓言中的狐狸被描繪成聰明卻不可信賴的角色。", "a": 1}, {"w": "keen", "p": "adj.", "d": "Having or showing eagerness or enthusiasm.", "c": "熱切的/敏銳的", "s": "She was keen to learn everything about the new software program.", "t": "她非常熱切地想要學習關於這套新軟體程式的一切。", "as": "He has a keen eye for spotting fake antiques.", "at": "他有著敏銳的眼光,能辨識出仿冒的古董。", "a": 1}, {"w": "sophisticated", "p": "adj.", "d": "Developed to a high degree of complexity and refinement.", "c": "先進的；精密的；世故的", "s": "Modern weather forecasting relies on sophisticated satellite systems and supercomputers to project storm paths.", "t": "現代天氣預報依賴「先進的（精密的）」衛星系統和超級電腦來預測風暴路徑。", "as": "", "at": "", "a": 1}]}, {"unit": 29, "theme": "Confusable Words I", "themeZh": "易混淆字詞（一）", "antonymLessons": [], "cards": [{"w": "allusion", "p": "n.", "d": "An indirect or passing reference, often to literature or history.", "c": "暗指；典故", "s": "The title of Aldous Huxley's novel Brave New World is an ironic allusion to Shakespeare's The Tempest, in which the sheltered Miranda exclaims at the sight of strangers, so readers who recognize the source understand from the first page that the 'new world' will prove far from admirable.", "t": "赫胥黎小說《美麗新世界》的書名，諷刺地暗指莎士比亞的《暴風雨》——劇中涉世未深的米蘭達一見到陌生人便驚嘆不已；因此認出出處的讀者從第一頁就明白，這個「新世界」絕非令人嚮往。", "as": "The poet's erudite allusion to Homer was lost on most of the audience, yet the discerning critics in attendance were quick to laud its subtlety and to extol the pithy elegance of the closing stanza.", "at": "詩人對荷馬的博學引典，大多數聽眾都沒聽出來，但在場有眼光的評論家很快就稱讚其精妙，並讚揚最後一節精煉優雅。"}, {"w": "coalesce", "p": "v.", "d": "To come together to form one mass or whole.", "c": "結合；融合", "s": "Astronomers believe that about 4.6 billion years ago, countless grains of dust and ice orbiting the young sun gradually coalesced into small rocky bodies called planetesimals, which collided and merged over millions of years to form the planets we observe today.", "t": "天文學家認為，大約46億年前，環繞年輕太陽運行的無數塵埃與冰粒逐漸結合成稱為微行星的小型岩質天體，這些天體在數百萬年間不斷碰撞、合併，形成了我們今天所觀察到的行星。", "as": "In the turbulence of 1848, contentious factions that had long nursed mutual animosity began to coalesce into a single movement, united by their indignant opposition to the monarchy's harsh taxes.", "at": "在1848年的動盪中，長久以來彼此敵視、爭執不休的派系開始結合成單一運動，因共同憤慨地反對君主政體嚴苛的稅收而團結起來。"}, {"w": "convalesce", "p": "v.", "d": "To recover health and strength gradually after illness.", "c": "康復；療養", "s": "After contracting tuberculosis in 1899, the young physician was sent to a sanatorium in the Swiss Alps to convalesce, where doctors prescribed months of bed rest, mountain air, and nourishing meals, the standard treatment for the disease before the discovery of antibiotics.", "t": "這位年輕醫師在1899年感染肺結核後，被送往瑞士阿爾卑斯山的一間療養院休養康復；在那裡，醫生開立了數月的臥床休息、山間空氣和營養餐點，這是抗生素問世前治療此病的標準療法。", "as": "While she was convalescing after surgery, the listless patient grew sluggish and lethargic, and her doctors warned that too many weeks of sedentary rest in bed could actually weaken her muscles and slow her recovery.", "at": "她在手術後休養康復期間變得無精打采、行動遲緩又昏昏欲睡，醫生警告她，連續數週久坐久臥不動的休息，其實會削弱肌肉，拖慢復原的速度。"}, {"w": "delusion", "p": "n.", "d": "A firmly held false belief despite clear evidence otherwise.", "c": "妄想；錯覺", "s": "Cervantes's Don Quixote reads so many chivalric romances that he falls under the delusion that he is a knight errant; convinced that ordinary windmills are menacing giants, he charges them with his lance, and the novel uses his madness to satirize the literature that inspired it.", "t": "塞萬提斯筆下的唐吉訶德讀了太多騎士傳奇，以致陷入自己是遊俠騎士的妄想；他深信平凡的風車是兇惡的巨人，便持矛衝向它們，而這部小說正是藉他的瘋狂來諷刺啟發他的那類文學。", "as": "The arrogant emperor lived under the delusion that his subjects adored him, for his obsequious courtiers were too servile to tell him that his lavish spending had provoked widespread turmoil.", "at": "這位傲慢的皇帝活在臣民愛戴他的妄想中，因為他那些阿諛奉承的朝臣太過卑躬屈膝，不敢告訴他，他的奢侈揮霍已引發廣泛的動盪。"}, {"w": "illusion", "p": "n.", "d": "Something that deceives the senses by appearing real.", "c": "幻覺；錯覺", "s": "In the famous Müller-Lyer figure, two lines of exactly equal length appear dramatically different because of the arrowheads at their ends, an optical illusion that persists even after viewers have measured the lines and know perfectly well that they are identical.", "t": "在著名的繆勒-萊爾圖形中，兩條長度完全相同的線段因兩端箭頭的方向不同而看起來差異懸殊；這種視錯覺即使在觀者測量過線段、清楚知道兩者等長之後，依然存在。", "as": "The ostentatious marble lobby and lavish quarterly parties created an illusion of prosperity, but auditors soon discovered that the firm's precarious finances were a looming debacle concealed by years of devious accounting.", "at": "那座炫耀的大理石大廳和奢華的季度派對營造出繁榮的假象，但稽核人員很快發現，這家公司岌岌可危的財務狀況是一場被多年狡詐會計手法掩蓋、迫在眉睫的災難。"}, {"w": "ambiguous", "p": "adj.", "d": "Open to more than one interpretation; unclear in meaning.", "c": "模稜兩可的；含糊的", "s": "Because the Second Amendment's opening clause about a 'well regulated Militia' is grammatically ambiguous, legal scholars have argued for more than two centuries over whether it limits the right to bear arms or merely explains one reason for protecting it.", "t": "由於美國憲法第二修正案開頭關於「管理良好的民兵」的子句在文法上模稜兩可，兩個多世紀以來，法學學者一直爭論它究竟是限制了持有武器的權利，還是僅說明保障此權利的理由之一。", "as": "The diplomat's cryptic, ambiguous reply to the ultimatum only deepened the quandary, and the reticent foreign minister refused to clarify it, leaving reporters and rival governments alike to speculate about what the enigma might mean.", "at": "這位外交官對最後通牒隱晦、模稜兩可的回覆只讓困境更加棘手，而沉默寡言的外交部長又拒絕澄清，讓記者和敵對國政府都只能揣測這個謎團究竟代表什麼意思。"}, {"w": "acrid", "p": "adj.", "d": "Unpleasantly sharp or bitter to the smell or taste.", "c": "刺鼻的；辛辣的", "s": "During the Great Smog of 1952, a thick layer of coal smoke settled over London for five days, filling the streets with an acrid yellow haze that stung residents' eyes and throats and was later linked to at least four thousand deaths.", "t": "1952年倫敦大霧霾期間，一層厚厚的煤煙籠罩倫敦長達五天，街道上瀰漫著刺鼻的黃色煙霧，刺痛居民的眼睛和喉嚨，事後被認為與至少四千人的死亡有關。", "as": "Long after the conflagration was extinguished, the acrid smoke lingered over the rubble, and residents were indignant that officials had dismissed warnings about the volatile chemicals stored in the warehouse.", "at": "大火撲滅許久之後，刺鼻的濃煙仍在瓦礫上方久久不散；居民十分憤慨，因為官員先前對倉庫中存放易揮發化學物質的警告置之不理。"}, {"w": "aesthetic", "p": "adj.", "d": "Concerned with beauty or the appreciation of beauty.", "c": "美學的；審美的", "s": "When the Eiffel Tower was proposed for the 1889 World's Fair, many prominent Parisian artists objected on aesthetic grounds, condemning the iron lattice as a monstrous eyesore, although the structure has since become one of the most admired works of architecture in the world.", "t": "艾菲爾鐵塔被提議作為1889年世界博覽會的建築時，許多巴黎知名藝術家基於美學理由加以反對，斥責這座鐵格結構是醜陋的礙眼之物；然而此後它已成為全世界最受讚賞的建築作品之一。", "as": "Critics who had dismissed the architect's aesthetic vision as derivative and banal were forced to revise their opinion when the museum's innovative design, with its curving glass galleries, drew acclaim from visitors around the world.", "at": "那些曾把這位建築師的美學理念斥為缺乏原創、平淡無奇的評論家，在博物館擁有弧形玻璃展廳的創新設計贏得全球參觀者讚譽之後，不得不修正自己的看法。"}, {"w": "ambivalent", "p": "adj.", "d": "Having mixed or conflicting feelings about something.", "c": "矛盾的；猶豫不決的", "s": "Although Thomas Jefferson called slavery a 'moral depravity' and drafted language condemning the slave trade, he remained deeply ambivalent about emancipation, enslaving more than six hundred people over his lifetime and freeing only a handful of them.", "t": "雖然湯瑪斯·傑佛遜稱奴隸制度為「道德敗壞」，並起草了譴責奴隸貿易的文字，但他對解放奴隸始終深感矛盾，一生奴役了六百多人，卻只釋放了其中寥寥數人。", "as": "The novelist was ambivalent about her sudden fame; she enjoyed the critical acclaim, but she found the effusive praise of sycophants vapid and the endless obligatory interviews both banal and exhausting.", "at": "這位小說家對自己突如其來的名氣感到矛盾：她享受評論界的讚譽，卻覺得馬屁精的熱情吹捧空洞無味，而那些沒完沒了、不得不接受的訪談則既平淡又令人疲憊。"}, {"w": "arid", "p": "adj.", "d": "Having little or no rain; too dry to support vegetation.", "c": "乾旱的；乾燥的", "s": "Chile's Atacama Desert is so arid that some weather stations there have never recorded measurable rainfall, and NASA scientists test Mars rovers in its barren soil because the conditions resemble those on the red planet more closely than any other place on Earth.", "t": "智利的阿塔卡馬沙漠乾旱至極，當地有些氣象站從未記錄到可測量的降雨；美國太空總署的科學家在其貧瘠的土壤上測試火星探測車，因為那裡的環境比地球上任何其他地方都更接近火星。", "as": "Nomadic herders have endured the adversity of the arid Mongolian steppe for centuries, relying on frugal habits, sturdy horses, and a meticulous knowledge of hidden wells to survive its harsh and precarious seasons.", "at": "數百年來，遊牧民族在乾旱的蒙古大草原上忍受艱困，依靠節儉的生活習慣、強健的馬匹，以及對隱密水井一絲不苟的了解，熬過那裡嚴酷又變幻莫測的季節。"}, {"w": "atheistic", "p": "adj.", "d": "Denying or lacking belief in the existence of God.", "c": "無神論的", "s": "Because Soviet ideology was officially atheistic, the government closed thousands of churches, mosques, and synagogues in the 1920s and 1930s, converting some into museums of scientific materialism and replacing religious holidays with state celebrations of labor and revolution.", "t": "由於蘇聯的意識形態官方立場是無神論的，政府在1920至1930年代關閉了數以千計的教堂、清真寺和猶太會堂，將其中一些改建為科學唯物主義博物館，並以國家慶祝勞動與革命的節日取代宗教節日。", "as": "The philosopher's atheistic essays provoked a vociferous outcry among the clergy, who sought to censure and castigate him from their pulpits, yet he remained stoical, calmly rebutting each polemical attack in print.", "at": "這位哲學家的無神論文章在神職人員之間引發強烈的抗議聲浪，他們試圖在講壇上譴責並嚴厲斥責他，但他始終堅忍沉著，冷靜地以文字反駁每一篇論戰式的攻擊。"}]}, {"unit": 30, "theme": "Confusable Words II", "themeZh": "易混淆字詞（二）", "antonymLessons": [], "cards": [{"w": "impudent", "p": "adj.", "d": "Shamelessly rude and disrespectful.", "c": "無禮的；厚顏無恥的", "s": "When the young journalist interrupted the prime minister's press conference to ask whether he had ever read the bill he was promoting, aides dismissed the question as impudent, though many viewers privately admired her refusal to show the deference that officials usually expected.", "t": "這位年輕記者在總理的記者會上插話，質問他是否讀過自己正在推動的法案；幕僚們斥這個問題為無禮，但許多觀眾私下欣賞她拒絕表現出官員通常期待的那種恭敬。", "as": "The impudent apprentice was insolent and presumptuous toward the master craftsman who had trained him, and his contemptuous remarks in front of customers soon led the guild to rebuke him and threaten to expel him.", "at": "這個無禮的學徒對一手栽培他的師傅傲慢放肆、自以為是，他在顧客面前發表的輕蔑言論，很快就讓行會對他加以斥責，並威脅要將他除名。"}, {"w": "intimidate", "p": "v.", "d": "To frighten or threaten someone into doing what one wants.", "c": "恐嚇；威嚇", "s": "During the Reconstruction era, armed groups such as the Ku Klux Klan used night raids, arson, and public violence to intimidate newly enfranchised Black citizens, hoping to keep them away from the polls and reverse the political gains guaranteed by the Fifteenth Amendment.", "t": "在重建時期，三K黨等武裝團體以夜間突襲、縱火和公開暴力來恐嚇剛獲得投票權的黑人公民，企圖讓他們遠離投票所，並推翻第十五修正案所保障的政治成果。", "as": "The belligerent landlord tried to intimidate the indigent tenants with threats of eviction, but their adamant refusal to leave and their vociferous protests eventually drew the attention of city officials.", "at": "這位好鬥的房東企圖以驅逐威脅恐嚇貧困的房客，但他們堅決拒絕搬走，加上大聲疾呼的抗議，最終引起了市府官員的注意。"}, {"w": "imprudent", "p": "adj.", "d": "Not showing care for the consequences of an action; rash.", "c": "輕率的；不明智的", "s": "Economists widely agree that it was imprudent for many banks in the early 2000s to issue mortgages to borrowers with no verified income, a reckless practice that inflated the housing bubble and contributed directly to the financial crisis of 2008.", "t": "經濟學家普遍認為，2000年代初期許多銀行向收入未經查核的借款人發放房貸是不明智的；這種魯莽的做法使房市泡沫膨脹，並直接導致了2008年的金融危機。", "as": "The prodigal heir's imprudent decision to squander his fortune on lavish yachts left him penurious within a decade, forcing him to rely on the largess of the very relatives he had once scorned.", "at": "這位揮霍無度的繼承人輕率地把財富揮霍在豪華遊艇上，不到十年就窮困潦倒，被迫仰賴那些他曾經瞧不起的親戚慷慨接濟。"}, {"w": "indignant", "p": "adj.", "d": "Angry because of something unjust or unfair.", "c": "憤慨的；義憤填膺的", "s": "Readers were indignant when Upton Sinclair's 1906 novel The Jungle revealed that Chicago meatpackers routinely ground diseased carcasses and even rats into sausage, and their outrage pressured Congress to pass the Pure Food and Drug Act within months.", "t": "厄普頓·辛克萊1906年的小說《魔鬼的叢林》揭露芝加哥肉品加工廠經常把病死的屍體甚至老鼠絞碎做成香腸，讀者們義憤填膺，他們的憤怒迫使國會在數月內通過了《純淨食品與藥物法》。", "as": "The indignant citizens staged a vociferous protest outside city hall, denouncing the council as callous and apathetic toward the plight of indigent families and demanding that it rebuke the developers who had evicted them.", "at": "憤慨的市民在市政廳外發起大聲疾呼的抗議，譴責市議會對貧困家庭的困境冷酷又漠不關心，並要求議會斥責那些驅逐他們的開發商。"}, {"w": "obscure", "p": "adj.", "d": "Not well known; also, unclear or hard to understand.", "c": "默默無聞的；晦澀的", "s": "Gregor Mendel, an obscure Augustinian friar working in a monastery garden in Brno, published his groundbreaking experiments on pea plants in 1866, but his findings were ignored for over thirty years until scientists rediscovered them and recognized him as the founder of genetics.", "t": "孟德爾是一位默默無聞的奧斯定會修士，在布爾諾一座修道院的花園裡工作；他在1866年發表了具開創性的豌豆實驗，但其研究成果被忽視了三十多年，直到科學家重新發現，才尊他為遺傳學之父。", "as": "Though the poet died obscure and penurious in a rented room, later critics came to revere her work, and today scholars extol the cryptic, laconic verses that her contemporaries had dismissed as trivial.", "at": "雖然這位詩人在租來的房間裡默默無聞、窮困潦倒地離世，後來的評論家卻開始崇敬她的作品；如今學者們讚揚那些曾被同時代人斥為瑣碎的隱晦、簡練詩句。"}, {"w": "obtuse", "p": "adj.", "d": "Slow to understand or perceive; insensitive.", "c": "遲鈍的；愚鈍的", "s": "In Jane Austen's Pride and Prejudice, Mr. Collins is so obtuse that he fails to notice Elizabeth's obvious distaste for him, interpreting each of her firm refusals of his marriage proposal as the modest hesitation that he believes all elegant young ladies are expected to display.", "t": "在珍·奧斯汀的《傲慢與偏見》中，柯林斯先生遲鈍到察覺不出伊莉莎白對他明顯的厭惡，把她每一次堅決拒絕他求婚的回答，都解讀為他認為所有優雅年輕女士都應表現出的矜持猶豫。", "as": "The obtuse manager remained oblivious to the animosity growing among his staff for months, and his complacent, nonchalant attitude toward their complaints allowed petty quarrels to escalate into open antagonism that eventually split the department.", "at": "這位遲鈍的經理數月來始終沒有察覺員工之間日益滋長的敵意，他對員工抱怨自滿又漫不經心的態度，讓瑣碎的爭吵升級為公開的對立，最終使整個部門分裂。"}, {"w": "indigenous", "p": "adj.", "d": "Originating or occurring naturally in a particular place; native.", "c": "本土的；原住民的", "s": "Long before European ships arrived, the indigenous peoples of Taiwan, including the Amis, Atayal, and Paiwan, had developed distinct languages belonging to the Austronesian family, and linguists now believe the island may have been the original homeland of that vast language group.", "t": "早在歐洲船隻抵達之前，臺灣的原住民族，包括阿美族、泰雅族和排灣族，就已發展出屬於南島語系的各種獨特語言；語言學家如今認為，臺灣可能就是這個龐大語系的發源地。", "as": "Conservationists warn that invasive rats and cats pose a pernicious threat to the indigenous birds of New Zealand, whose populations have already been devastated by deleterious pesticides and increasingly precarious habitats.", "at": "保育人士警告，外來的老鼠和貓對紐西蘭的本土鳥類構成嚴重的威脅，而這些鳥類的族群數量早已因有害的農藥和日益岌岌可危的棲地而遭受重創。"}, {"w": "indigent", "p": "adj.", "d": "Extremely poor; lacking the basic necessities of life.", "c": "貧困的；窮苦的", "s": "In the landmark 1963 case Gideon v. Wainwright, the Supreme Court ruled that states must provide free legal counsel to indigentedefendants accused of serious crimes, recognizing that a fair trial is impossible when a person cannot afford a lawyer.", "t": "在1963年具里程碑意義的「吉迪恩訴溫賴特案」中，最高法院裁定各州必須為被控重罪的貧困被告提供免費律師，承認一個人若請不起律師，就不可能得到公平的審判。", "as": "The philanthropic foundation, known for its munificent grants, funded a clinic for indigent patients, an altruistic gesture that stood in stark contrast to the avarice of the city's miserly landlords.", "at": "這個以慷慨捐助聞名的慈善基金會資助了一間為貧困病患服務的診所；這種利他的義舉，與市內吝嗇房東的貪婪形成鮮明對比。"}, {"w": "intimate", "p": "v.", "d": "To suggest or hint at something indirectly.", "c": "暗示；透露", "s": "In his final letters from the Arctic, the explorer did not openly admit that the expedition was failing, but he intimated as much by describing dwindling food supplies, frostbitten crew members, and his growing hope that a rescue ship might reach them before winter.", "t": "這位探險家在北極寫下的最後幾封信中，並未公開承認探險隊正陷入失敗，但他描述日漸減少的糧食、凍傷的隊員，以及他越來越盼望救援船能在冬天之前抵達，已暗示了這一點。", "as": "The reticent minister would only intimate his disapproval of the treaty through cryptic, laconic remarks at press conferences, leaving journalists to puzzle for weeks over the enigma of his ambiguous silence.", "at": "這位沉默寡言的部長只在記者會上透過隱晦、簡短的評論暗示他對條約的不滿，讓記者們連續數週對他那模稜兩可的沉默之謎百思不解。"}, {"w": "ponderable", "p": "adj.", "d": "Worthy of careful thought; capable of being weighed or assessed.", "c": "值得考慮的；可衡量的", "s": "Before approving the dam, the commission listed every ponderable consequence it could identify, from the number of villages that would be flooded to the expected gain in electricity, while acknowledging that some cultural losses could never be measured at all.", "t": "在核准興建水壩之前，委員會列出了它所能辨識的每一項值得衡量的後果，從將被淹沒的村莊數量到預期增加的發電量，同時也承認有些文化上的損失根本無從衡量。", "as": "The review panel dismissed the critic's contentious objections as trivial, yet several scrupulous scientists insisted that the ponderable risks of the mining project were anything but negligible and deserved meticulous study.", "at": "審查小組把這位批評者具爭議性的反對意見斥為瑣碎，但幾位嚴謹的科學家堅持，這項採礦計畫中值得考量的風險絕非微不足道，應該加以縝密研究。"}, {"w": "ponderous", "p": "adj.", "d": "Slow and clumsy because of great weight; dull and laborious.", "c": "笨重的；沉悶冗長的", "s": "The earliest computers, such as the 1945 ENIAC, were ponderous machines that weighed nearly thirty tons, filled an entire room with thousands of vacuum tubes, and required teams of technicians to rewire them by hand whenever a new calculation was needed.", "t": "最早期的電腦，例如1945年的ENIAC，是重達近三十噸的笨重機器，數千根真空管塞滿了整個房間，每當需要進行新的計算時，就得由技術人員團隊以手工重新接線。", "as": "The professor's ponderous lectures on medieval tax law, filled with verbose digressions and banal platitudes, proved so soporific that even the most avid students grew listless before the hour ended.", "at": "這位教授講授中世紀稅法的課程沉悶冗長，充斥著冗長的離題和平庸的陳腔濫調，令人昏昏欲睡，連最熱衷的學生也在下課前變得無精打采。"}]}, {"unit": 31, "theme": "Aspiration and Outlook", "themeZh": "抱負與心態", "antonymLessons": [], "cards": [{"w": "aspire", "p": "v.", "d": "To direct one's hopes and efforts toward achieving something.", "c": "渴望；立志", "s": "Barred from Russian-controlled universities in Warsaw because she was a woman, the young Marie Skłodowska had long aspired to study physics in Paris, working for years as a governess to fund her sister's medical degree before she could finally enroll at the Sorbonne herself.", "t": "由於身為女性而被拒於俄國控制下的華沙大學門外，年輕的瑪麗．斯克沃多夫斯卡長久以來一直立志到巴黎攻讀物理；她當了好幾年家庭教師，資助姊姊完成醫學學位，之後才終於得以進入索邦大學就讀。", "as": "Many young scientists aspire to make unprecedented discoveries, yet the most astute among them recognize that meticulous, often mundane laboratory work, rather than ostentatious claims, is what ultimately earns the esteem of their peers.", "at": "許多年輕科學家渴望做出前所未有的發現，但其中最精明的人明白，最終贏得同儕敬重的，是一絲不苟、往往平凡乏味的實驗室工作，而非浮誇炫耀的宣稱。"}, {"w": "accessible", "p": "adj.", "d": "Easy to reach, enter, use, or understand.", "c": "易取得的；易接近的；易懂的", "s": "By digitizing thousands of fragile medieval manuscripts and posting high-resolution images online free of charge, the national library made documents that had once been available only to credentialed scholars visiting its reading room accessible to students and amateur historians around the world.", "t": "國家圖書館將數千份脆弱的中世紀手稿數位化，並免費在網路上公開高解析度影像，使這些過去只開放給親赴閱覽室、具備資格的學者查閱的文獻，如今全世界的學生和業餘歷史愛好者都能取得。", "as": "Although the physicist's research was undeniably erudite, her popular book was remarkably accessible, replacing cryptic equations with lucid analogies and avoiding the pretentious jargon that makes so many scientific texts seem insipid to general readers.", "at": "雖然這位物理學家的研究無疑十分博學精深，她的科普著作卻出奇地平易近人：以清晰的比喻取代晦澀難解的方程式，並避開許多科學文本中那種讓一般讀者覺得枯燥乏味的矯飾術語。"}, {"w": "antidote", "p": "n.", "d": "A remedy that counteracts a poison or a harmful influence.", "c": "解毒劑；矯正方法", "s": "Because the venom of the inland taipan can kill an adult within hours, researchers at the Australian institute spent years immunizing horses with tiny doses so that the animals' blood would produce antibodies, which were then purified into an antidote for distribution to remote hospitals.", "t": "由於內陸太攀蛇的毒液可在數小時內致成人於死，這所澳洲研究機構的研究人員花了多年時間，以極少劑量為馬匹進行免疫，讓馬的血液產生抗體，再將抗體純化製成解毒劑，分送至偏遠地區的醫院。", "as": "Some educators argue that close reading of primary sources is the best antidote to the pernicious spread of online misinformation, because students who learn to be wary of unsupported claims become less susceptible to the hackneyed slogans and spurious statistics that circulate on social media.", "at": "有些教育工作者認為，細讀第一手史料是對抗網路假訊息有害擴散的最佳解藥，因為學會對缺乏根據的說法保持警覺的學生，比較不容易受到社群媒體上流傳的陳腔濫調口號與虛假統計數據所影響。"}, {"w": "autonomous", "p": "adj.", "d": "Self-governing; independent of outside control.", "c": "自主的；自治的", "s": "Under the 1979 home-rule agreement, Greenland became an autonomous territory within the Danish realm, gaining the authority to run its own schools, health system, and fisheries while the government in Copenhagen retained control over foreign policy and national defense.", "t": "根據1979年的地方自治協議，格陵蘭成為丹麥王國內的自治領地，獲得自行管理學校、醫療體系與漁業的權力，而哥本哈根的中央政府則保留外交與國防的主導權。", "as": "Engineers designing autonomous delivery robots must be meticulous about safety, since even a negligible software error could make a machine behave in volatile ways on crowded sidewalks, and regulators remain wary of approving them for public use.", "at": "設計自動送貨機器人的工程師必須對安全性一絲不苟，因為即使是微不足道的軟體錯誤，也可能讓機器在擁擠的人行道上出現難以預測的行為，而主管機關對於核准這類機器人上路仍抱持戒慎態度。"}, {"w": "gratify", "p": "v.", "d": "To give pleasure or satisfaction; to indulge a desire.", "c": "使滿足；使高興", "s": "Economists studying consumer behavior have found that people who can gratify their desires instantly through one-click online shopping often report less lasting satisfaction than those who must save for months, suggesting that anticipation itself contributes significantly to the pleasure of a purchase.", "t": "研究消費行為的經濟學家發現，能透過一鍵網購立即滿足欲望的人，所感受到的滿足感往往不如必須存錢數月的人來得持久，這顯示期待本身就大大增添了購物的樂趣。", "as": "Instead of seeking to gratify the egotistical demands of the temperamental diva, the conductor remained stoical, calmly insisting that every soloist, however acclaimed, follow the same rehearsal schedule as the rest of the orchestra.", "at": "指揮並未設法滿足那位喜怒無常的女主角自我中心的要求，而是保持沉著，平靜地堅持每位獨奏者無論多麼備受讚譽，都必須和樂團其他成員遵守相同的排練時程。"}, {"w": "candor", "p": "n.", "d": "Openness and honesty in expression; frankness.", "c": "坦率；直率", "s": "In her memoir, the former finance minister discussed her own policy mistakes with surprising candor, admitting that she had underestimated the risks of rapid deregulation and acknowledging that her optimistic public forecasts had sometimes contradicted the warnings her own advisers delivered privately.", "t": "在回憶錄中，這位前財政部長以令人意外的坦率態度討論自己的政策失誤，承認她低估了快速解除管制的風險，也坦言她公開發表的樂觀預測，有時與她自己的顧問私下提出的警告相互矛盾。", "as": "The new CEO's candor was a welcome change from the evasive circumlocution of her predecessor; rather than hiding behind platitudes, she admitted that the company's lackluster products had failed to keep pace with its more savvy competitors.", "at": "新任執行長的坦率，與前任閃爍其詞、拐彎抹角的作風形成令人欣喜的對比；她沒有躲在空洞的陳腔濫調背後，而是坦承公司平庸乏味的產品已跟不上更精明的競爭對手。"}, {"w": "fastidious", "p": "adj.", "d": "Very attentive to accuracy and detail; hard to please.", "c": "挑剔的；講究的", "s": "The novelist Gustave Flaubert was notoriously fastidious about language, sometimes spending an entire week revising a single paragraph of Madame Bovary because he refused to accept any word that was merely adequate rather than exactly right.", "t": "小說家福樓拜對語言的講究是出了名的，有時會花上整整一星期修改《包法利夫人》中的一個段落，因為他不肯接受任何只是「堪用」而非「恰到好處」的字詞。", "as": "The fastidious editor was meticulous about every comma, yet her scrupulous attention to detail never became captious; authors appreciated that she ignored trivial matters of taste and focused on errors that genuinely obscured meaning.", "at": "這位講究的編輯對每個逗號都一絲不苟，但她對細節的嚴謹從未流於吹毛求疵；作者們很欣賞她略過無關緊要的品味問題，專注於真正使文意晦澀的錯誤。"}, {"w": "abridge", "p": "v.", "d": "To shorten a text while keeping its essential content.", "c": "刪節；縮短", "s": "To fit the radio broadcast into a single evening, the producers abridged the nine-hundred-page novel to a ninety-minute script, cutting several minor subplots entirely while preserving the central courtroom scenes that critics regarded as the heart of the book.", "t": "為了讓廣播劇能在一個晚上播完，製作人將這部九百頁的小說刪節成九十分鐘的劇本，完全刪去幾條次要情節，同時保留了評論家視為全書核心的法庭場景。", "as": "Although the abridged edition was easier for young readers, scholars complained that its editors had excised the novel's most incisive passages, leaving a prosaic summary that reduced a nuanced satire to a series of trite moral lessons.", "at": "雖然這個節本對年輕讀者來說較容易閱讀，學者卻抱怨編輯刪去了小說中最犀利的段落，只留下平淡無奇的摘要，把一部細膩的諷刺作品簡化成一連串陳腐的道德教訓。"}, {"w": "bolster", "p": "v.", "d": "To support or strengthen something.", "c": "支持；加強", "s": "The discovery of nearly identical fossil plants in South America, Africa, India, and Antarctica bolstered Alfred Wegener's controversial theory of continental drift, since the plants' heavy seeds could not plausibly have crossed vast oceans unless the landmasses had once been joined.", "t": "在南美洲、非洲、印度與南極洲發現幾乎相同的植物化石，強化了韋格納頗具爭議的大陸漂移學說，因為這些植物沉重的種子不可能橫渡遼闊的海洋，除非這些陸塊曾經相連。", "as": "To bolster her case, the prosecutor presented copious financial records and the testimony of a scrupulous accountant, hoping that such ample evidence would refute the defense's claim that the discrepancies were merely inconsequential clerical errors.", "at": "為了強化論點，檢察官提出大量財務紀錄，以及一位嚴謹會計師的證詞，希望藉由如此充分的證據，駁斥辯方所稱這些差異只是無關緊要的文書錯誤的說法。"}, {"w": "cynical", "p": "adj.", "d": "Distrustful of others' motives; believing people act only selfishly.", "c": "憤世嫉俗的；懷疑他人動機的", "s": "After decades of watching politicians abandon their campaign promises within months of taking office, many voters in the survey had grown deeply cynical, assuming that every new reform proposal was merely a strategy to attract donations rather than a sincere attempt to improve public services.", "t": "數十年來眼看政治人物在上任數月內就背棄競選承諾，調查中的許多選民已變得極為憤世嫉俗，認定每一項新的改革提案都只是吸引捐款的手段，而非真心想改善公共服務。", "as": "The novelist's cynical narrator views every act of philanthropic generosity as a disguise for avarice, dismissing even the most altruistic characters as shrewd opportunists who merely seek public acclaim in a society he regards as hopelessly corrupt.", "at": "這位小說家筆下憤世嫉俗的敘事者，把每一項慈善慷慨之舉都視為貪婪的偽裝，甚至將最無私的角色也貶為只想博取公眾讚揚的精明投機者；在他眼中，這個社會已經無可救藥地腐敗。"}]}, {"unit": 32, "theme": "Character and Growth", "themeZh": "品格與成長", "antonymLessons": [], "cards": [{"w": "intrepid", "p": "adj.", "d": "Fearless and adventurous, especially in the face of danger.", "c": "無畏的；勇敢的", "s": "In 1873, the intrepid travel writer Isabella Bird rode through the Rocky Mountains largely alone on horseback, enduring blizzards, grizzly bears, and nights in remote log cabins at a time when most of her contemporaries considered such journeys far too dangerous for any woman to attempt.", "t": "1873年，無畏的旅行作家伊莎貝拉．博德幾乎獨自一人騎馬穿越洛磯山脈，熬過暴風雪、灰熊，以及在偏遠小木屋中度過的夜晚；而在當時，她同時代的大多數人都認為這種旅程對任何女性來說都太危險了。", "as": "The intrepid journalist exposed a clandestine network of officials whose nefarious schemes had diverted relief funds, and she remained unwavering even when anonymous critics tried to intimidate her with threats.", "at": "這位無畏的記者揭發了一個秘密的官員網絡，他們以邪惡的手法挪用救災款項；即使匿名批評者以威脅試圖恫嚇她，她仍毫不動搖。"}, {"w": "opportunist", "p": "n.", "d": "A person who exploits circumstances for selfish gain, disregarding principles.", "c": "投機者；機會主義者", "s": "Historians have long debated whether the general was a principled patriot or merely an opportunist who switched sides three times during the civil war, each time aligning himself with whichever faction seemed most likely to reward him with land and political office.", "t": "歷史學家長久以來爭論，這位將軍究竟是一位有原則的愛國者，還是只是一個投機者——他在內戰期間三度倒戈，每次都投靠看似最有可能以土地和官職回報他的派系。", "as": "During the epidemic, a mercenary opportunist hoarded medical masks and resold them at exorbitant prices, and the public censured his avarice so fiercely that he became a pariah in his own community.", "at": "疫情期間，一名唯利是圖的投機者囤積醫療口罩，再以天價轉售；大眾強烈譴責他的貪婪，使他在自己的社區裡成了人人唾棄的人。"}, {"w": "homogeneous", "p": "adj.", "d": "Of the same kind; uniform in composition throughout.", "c": "同質的；均勻的", "s": "Because the glacier's ice had formed from snow that fell over thousands of years under varying climatic conditions, researchers were surprised to find that the core sample was almost entirely homogeneous, showing virtually no variation in its chemical composition from top to bottom.", "t": "由於冰河的冰是由數千年來在不同氣候條件下降下的雪所形成，研究人員驚訝地發現，這段冰芯樣本幾乎完全均質，從頂端到底部的化學成分幾乎沒有任何變化。", "as": "Critics argued that the festival's lineup had become dull and homogeneous, filled with derivative bands whose banal lyrics and hackneyed melodies made it hard to distinguish one act from another.", "at": "評論家認為，這個音樂節的演出陣容已變得單調而同質化，充斥著模仿他人的樂團，那些平庸的歌詞和陳腐的旋律讓人難以分辨各組表演的差別。"}, {"w": "nurture", "p": "v.", "d": "To care for and encourage the growth or development of.", "c": "養育；培育", "s": "Rather than demanding immediate profits, the venture fund nurtured its young biotechnology firms for nearly a decade, providing laboratory space, mentoring, and patient capital until their experimental therapies were finally ready for clinical trials.", "t": "這家創投基金並未要求立即獲利，而是用了將近十年培育旗下年輕的生技公司，提供實驗室空間、輔導與耐心資本，直到它們的實驗性療法終於準備好進入臨床試驗。", "as": "Good mentors nurture students' curiosity with ample encouragement, yet they remain conscientious enough to rebuke careless reasoning, knowing from long experience that unwavering standards, applied patiently and fairly over many years, ultimately produce more discerning and independent thinkers.", "at": "優秀的導師以充分的鼓勵培育學生的好奇心，但也盡責地糾正粗率的推理，因為他們從長年經驗中明白，多年來耐心而公正地堅守毫不動搖的標準，最終能培養出更具洞察力、更能獨立思考的人。"}, {"w": "proximity", "p": "n.", "d": "Nearness in space, time, or relationship.", "c": "接近；鄰近", "s": "Medieval Venice owed much of its commercial power to its proximity to both Byzantine and Islamic ports, which allowed its merchants to transport spices, silk, and glass between East and West far more quickly than rivals located farther inland.", "t": "中世紀的威尼斯之所以擁有強大的商業實力，很大程度歸功於它鄰近拜占庭與伊斯蘭的港口，使其商人能夠在東西方之間運送香料、絲綢與玻璃，速度遠勝位於內陸較遠處的對手。", "as": "The proximity of the chemical plant to the village alarmed residents, who feared that its acrid fumes might have deleterious effects on their health, and they found the company's indifferent response to their complaints especially odious.", "at": "化工廠緊鄰村莊，讓居民憂心忡忡，擔心刺鼻的廢氣可能危害他們的健康；而公司對他們的抱怨漠不關心的回應，更讓他們深感可憎。"}, {"w": "hamper", "p": "v.", "d": "To hinder or obstruct the progress of something.", "c": "阻礙；妨礙", "s": "Persistent sandstorms and failing solar panels severely hampered the Mars rover's exploration of the crater, forcing mission scientists to cancel several planned drilling operations and to spend weeks waiting for winds strong enough to clear dust from its instruments.", "t": "持續的沙塵暴與故障的太陽能板嚴重阻礙了火星探測車對隕石坑的探勘，迫使任務科學家取消數項預定的鑽探作業，並花了好幾週等待強風將儀器上的灰塵吹散。", "as": "Rescue efforts after the flood were badly hampered by turbulence in the swollen river, precarious debris from collapsed bridges, and contentious disputes between government agencies that refused to share boats, helicopters, and other essential equipment with one another.", "at": "洪災後的救援行動，嚴重受到暴漲河水的湍急亂流、倒塌橋梁所留下岌岌可危的殘骸，以及各政府機關之間爭執不下、彼此拒絕共享船隻、直升機與其他必要設備的糾紛所阻礙。"}, {"w": "hardy", "p": "adj.", "d": "Robust and able to endure difficult conditions.", "c": "強健的；耐寒的；能吃苦的", "s": "Tardigrades, microscopic animals barely half a millimeter long, are so hardy that they can survive being frozen near absolute zero, heated beyond the boiling point of water, and even exposed to the vacuum and radiation of outer space.", "t": "水熊蟲是體長僅約半毫米的微小動物，生命力極為強韌，能在接近絕對零度的冰凍中、超過水沸點的高溫下存活，甚至能承受外太空的真空與輻射。", "as": "Only hardy, austere settlers survived the arid frontier, where frugal habits were essential and adversity was so constant that many newcomers became disillusioned and abandoned their claims within a year.", "at": "只有強健而刻苦的移居者才能在乾旱的邊疆存活下來；在那裡，節儉的習慣不可或缺，困境接連不斷，許多新來者在一年內就幻滅並放棄了他們的土地。"}, {"w": "integrity", "p": "n.", "d": "Firm adherence to moral principles; honesty.", "c": "正直；誠信；完整", "s": "The auditor's integrity was widely praised after she refused a substantial bribe from company executives and instead reported the falsified earnings to regulators, even though her decision cost her a lucrative position and years of legal battles.", "t": "這位審計員拒絕公司高層的大筆賄賂，轉而向主管機關舉報造假的盈餘，她的正直因而廣受讚揚，儘管這個決定讓她失去了一份待遇優渥的職位，並陷入多年的法律纏訟。", "as": "Voters admired the senator's integrity because she refused to placate wealthy donors, censured corrupt colleagues, and remained scrupulous about disclosing every gift, never allowing a devious lobbyist to sway her vote.", "at": "選民欽佩這位參議員的正直，因為她拒絕討好富有的捐款人、譴責貪腐的同僚，並且一絲不苟地申報每一份餽贈，從不讓狡詐的說客左右她的投票。"}, {"w": "linger", "p": "v.", "d": "To remain or persist longer than expected.", "c": "逗留；徘徊；揮之不去", "s": "Long after the factory closed in the 1970s, toxic solvents continued to linger in the groundwater beneath the neighborhood, and environmental engineers estimated that complete cleanup of the contaminated aquifer would require at least another thirty years.", "t": "這座工廠在1970年代關閉許久之後，有毒溶劑仍持續殘留在社區地底的地下水中，環境工程師估計，要完全清除受汙染的含水層，至少還需要三十年。", "as": "Although the actual fire was fleeting, its consequences lingered for decades: the conflagration had reduced the archive to a single charred relic, and historians still regret the obscure manuscripts lost forever.", "at": "雖然這場火災本身轉瞬即逝，影響卻延續了數十年：大火將檔案館燒得只剩下一件焦黑的遺物，歷史學家至今仍惋惜那些永遠失傳、鮮為人知的手稿。"}, {"w": "lofty", "p": "adj.", "d": "Of imposing height; noble or elevated in character.", "c": "崇高的；高聳的", "s": "The founders of the new university articulated lofty ideals in their charter, promising to admit students regardless of wealth or religion and to pursue knowledge for the benefit of all humanity, though limited funding soon forced them to compromise on several of these goals.", "t": "這所新大學的創辦人在章程中闡述了崇高的理想，承諾不論貧富或宗教皆招收學生，並為全人類的福祉追求知識；然而，有限的經費很快迫使他們在其中幾項目標上妥協。", "as": "The charity's lofty mission statement was replete with grandiloquent promises to end hunger within a decade, but skeptics noted a glaring discrepancy between this soaring rhetoric and the organization's frugal spending on the actual food programs it claimed to support.", "at": "這個慈善機構的崇高使命宣言滿是要在十年內終結飢餓的浮誇承諾，但懷疑論者指出，這番高調言辭與該組織在其宣稱支持的實際糧食計畫上吝嗇的支出之間，存在明顯的落差。"}, {"w": "mock", "p": "v.", "d": "To ridicule someone or something, often by imitation.", "c": "嘲笑；模仿取笑", "s": "When Ignaz Semmelweis argued in the 1840s that doctors should wash their hands between patients to prevent fatal infections, many prominent physicians openly mocked his theory, dismissing as absurd the suggestion that their own hands could transmit disease.", "t": "1840年代，塞麥爾維斯主張醫師在診治不同病患之間應洗手以預防致命感染，許多知名醫師卻公開嘲笑他的理論，認為「自己的雙手可能傳播疾病」這種說法荒謬至極。", "as": "The satirist mocked the haughty aristocrats in his plays, exposing their pretentious manners and supercilious attitudes so incisively that his work offended the very audiences who flocked to see it.", "at": "這位諷刺作家在劇作中嘲弄傲慢的貴族，如此犀利地揭露他們矯揉造作的舉止與目中無人的態度，以至於他的作品冒犯了那些蜂擁而來觀賞的觀眾。"}]}, {"unit": 33, "theme": "Judgment and Temperament", "themeZh": "評斷與性情", "antonymLessons": [], "cards": [{"w": "recount", "p": "v.", "d": "To tell or narrate events in detail.", "c": "敘述；詳述", "s": "In oral-history interviews conducted decades after the war, former factory workers recounted how they had built aircraft parts during twelve-hour night shifts, providing historians with vivid details about daily wartime labor that official government records had largely ignored.", "t": "在戰後數十年進行的口述歷史訪談中，昔日的工廠工人詳述他們如何在十二小時的夜班中製造飛機零件，為歷史學家提供了政府官方紀錄大多忽略的戰時日常勞動生動細節。", "as": "The memoir recounts the author's peripatetic childhood with remarkable candor, describing how her nomadic family endured adversity in a series of austere mining towns across the Andes, where her father searched for work and her mother taught the children to read by candlelight.", "at": "這本回憶錄以驚人的坦率敘述作者四處漂泊的童年，描寫她那居無定所的家庭如何在安地斯山區一連串簡陋清苦的礦業小鎮中熬過重重困境；父親在那裡四處找工作，母親則在燭光下教孩子們識字。"}, {"w": "surpass", "p": "v.", "d": "To exceed or go beyond in quality or amount.", "c": "超越；勝過", "s": "By 2010, China's economy had surpassed Japan's to become the second largest in the world, an achievement that economists attributed to three decades of rapid industrialization, massive infrastructure investment, and an export sector that supplied manufactured goods to nearly every global market.", "t": "到了2010年，中國經濟已超越日本，成為全球第二大經濟體；經濟學家將這項成就歸功於三十年的快速工業化、大規模的基礎建設投資，以及供應製造品給幾乎所有全球市場的出口產業。", "as": "The young virtuoso's audacious interpretation of the concerto surpassed even the most lofty expectations, and critics who had dismissed her as a mere novelty began to extol her ingenious phrasing.", "at": "這位年輕演奏名家對協奏曲大膽的詮釋，甚至超越了最崇高的期待；那些曾把她視為一時新奇的評論家，也開始盛讚她巧妙的樂句處理。"}, {"w": "saturate", "p": "v.", "d": "To soak thoroughly or fill completely.", "c": "浸透；使飽和", "s": "Within a few years of the smartphone's introduction, competing manufacturers had so thoroughly saturated the market with nearly identical models that analysts warned profits would soon decline as companies were forced to cut prices simply to attract customers.", "t": "智慧型手機問世後短短幾年內，競爭廠商就以幾乎一模一樣的機型讓市場達到飽和，分析師警告，由於企業被迫降價才能吸引顧客，獲利很快就會下滑。", "as": "During the final weeks of the campaign, advertisements saturated the airwaves with vapid slogans and trite platitudes, leaving many voters so apathetic that they ignored even the few incisive debates that addressed real issues such as housing costs and public health.", "at": "在選戰最後幾週，廣告以空洞的口號與陳腐的老生常談充斥電波，讓許多選民變得冷漠麻木，甚至忽略了少數真正探討住房成本與公共衛生等實際議題、犀利深入的辯論。"}, {"w": "scrutinize", "p": "v.", "d": "To examine closely and critically.", "c": "仔細檢查；詳細審查", "s": "Before awarding the prize, the committee scrutinized the physicist's raw data for nearly a year, recalculating each measurement and consulting independent experts, because an earlier claim of a similar discovery had collapsed after other laboratories failed to replicate the results.", "t": "在頒獎之前，委員會花了將近一年仔細審查這位物理學家的原始數據，重新計算每一項測量並諮詢獨立專家，因為先前一項類似發現的宣稱，在其他實驗室無法重現結果後便宣告瓦解。", "as": "Investors who scrutinized the company's reports found a troubling discrepancy between its ostentatious claims and its actual revenue, and the more astute among them sold their shares before the debacle.", "at": "仔細檢視這家公司財報的投資人發現，其浮誇的宣稱與實際營收之間存在令人不安的落差，其中較精明的人在這場慘敗發生前就賣出了持股。"}, {"w": "whimsical", "p": "adj.", "d": "Playfully quaint or fanciful, often in an amusing way.", "c": "異想天開的；奇趣的；古怪的", "s": "Antoni Gaudí's Park Güell in Barcelona is famous for its whimsical architecture, featuring gingerbread-like gatehouses, a winding bench covered in colorful broken tiles, and a giant mosaic lizard that seems to belong more to a fairy tale than to a public garden.", "t": "高第在巴塞隆納設計的奎爾公園，以充滿奇趣的建築聞名：宛如薑餅屋的門房、鋪滿彩色碎瓷磚的蜿蜒長椅，以及一隻巨大的馬賽克蜥蜴，看起來更像屬於童話故事，而不是公共花園。", "as": "Unlike the ponderous, hackneyed fantasy novels that dominated the market at the time, her whimsical stories delighted readers of all ages with jocular dialogue and eccentric characters, offering a welcome levity that never became trivial or condescending toward young audiences.", "at": "不同於當時充斥市場、冗長沉悶又陳腔濫調的奇幻小說，她那些異想天開的故事以詼諧的對話和古怪的角色取悅各年齡層的讀者，帶來令人歡迎的輕鬆幽默，卻從不流於膚淺，也不對年輕讀者居高臨下。"}, {"w": "vilify", "p": "v.", "d": "To speak or write about someone in an abusively disparaging way.", "c": "誹謗；詆毀", "s": "During the 1950s, newspapers and congressional committees began to vilify several Hollywood screenwriters as dangerous traitors, even though investigators produced little credible evidence, and many of the accused were unable to work in the film industry for more than a decade.", "t": "1950年代，報紙與國會委員會開始把數名好萊塢編劇詆毀為危險的叛國者，儘管調查人員幾乎提不出可信的證據，許多被控者仍有十多年無法在電影業工作。", "as": "Rather than engaging her carefully documented arguments, the senator's malicious allies vilified the whistle-blower in a series of rancorous editorials, impugning her motives, questioning her loyalty, and spreading spurious rumors about her personal finances and her past employment.", "at": "這位參議員心懷惡意的盟友並未正面回應她那些證據充分的論點，而是在一連串充滿敵意的社論中詆毀這名吹哨者，質疑她的動機與忠誠，並散播關於她個人財務與過去工作經歷的不實謠言。"}, {"w": "querulous", "p": "adj.", "d": "Habitually complaining in a whining or petulant manner.", "c": "愛抱怨的；發牢騷的", "s": "The letters of the aging composer reveal an increasingly querulous man who grumbled endlessly about drafty apartments, incompetent copyists, and ungrateful publishers, a striking contrast to the serene, joyful music he continued to write during the same years.", "t": "這位年邁作曲家的書信顯示，他變得越來越愛發牢騷，無止盡地抱怨漏風的公寓、無能的抄譜員與忘恩負義的出版商，與他同一時期仍持續創作的那些寧靜而歡愉的音樂形成鮮明對比。", "as": "The querulous restaurant critic complained about every trivial detail of the meal, from the temperature of the plates to the font on the menu, berating waiters over petty issues and dismissing even the chef's most delectable dishes as insipid.", "at": "這位愛抱怨的美食評論家對餐點的每個微不足道的細節都有怨言，從餐盤的溫度到菜單上的字體無一倖免；他為了雞毛蒜皮的小事痛罵服務生，甚至把主廚最美味的菜餚也貶為索然無味。"}, {"w": "rigor", "p": "n.", "d": "Strict precision and thoroughness; also harshness or severity.", "c": "嚴謹；嚴格；嚴酷", "s": "Reviewers praised the economist's study for its methodological rigor: she tracked more than ten thousand households over twenty years, controlled carefully for income and education, and published her complete data set so that other researchers could test her conclusions independently.", "t": "審查者稱讚這位經濟學家的研究在方法上極為嚴謹：她追蹤一萬多個家庭長達二十年，審慎控制收入與教育等變因，並公開完整的資料集，讓其他研究者能獨立檢驗她的結論。", "as": "The medical journal is known for its rigor: its exacting reviewers demand meticulous methodology, insist that authors share their raw data, and routinely refuse to accept studies whose conclusions rest on ambiguous measurements or a negligible number of participants.", "at": "這份醫學期刊以嚴謹著稱：嚴格的審查者要求一絲不苟的研究方法，堅持作者公開原始數據，並經常拒絕接受結論建立在模稜兩可的測量或微不足道的受試人數上的研究。"}, {"w": "tentative", "p": "adj.", "d": "Not certain or fixed; hesitant or provisional.", "c": "試探性的；暫定的；猶豫的", "s": "After months of negotiations, the two nations announced a tentative agreement to share water from the river, but officials cautioned that the terms still required approval from both parliaments and could change significantly if new drought forecasts proved accurate.", "t": "經過數月談判，兩國宣布了一項分享河水的暫定協議，但官員提醒，協議條款仍須經兩國國會批准，而且若新的乾旱預測屬實，內容可能大幅變動。", "as": "Confronted with the enigma of the star's irregular dimming, the astronomer offered only a tentative explanation, acknowledging that the data were ambiguous and that a more prudent conclusion would require several more years of careful observation from multiple telescopes.", "at": "面對這顆恆星不規則變暗的謎團，這位天文學家只提出試探性的解釋，並承認數據模稜兩可，要得出較審慎的結論，還需要以多座望遠鏡再仔細觀測好幾年。"}, {"w": "thrive", "p": "v.", "d": "To grow vigorously; to flourish or prosper.", "c": "茁壯成長；興旺", "s": "Although most coral species are dying as ocean temperatures rise, researchers discovered several reefs in the Red Sea that continue to thrive in unusually warm water, raising hopes that their heat-resistant genes might help scientists restore damaged reefs elsewhere.", "t": "雖然大多數珊瑚物種隨著海水溫度上升而逐漸死亡，研究人員卻在紅海發現數個珊瑚礁，在異常溫暖的海水中仍持續茁壯生長，這讓人期待其耐熱基因或許能幫助科學家復育其他地方受損的珊瑚礁。", "as": "Some hardy desert species thrive in arid regions by being remarkably frugal with water, storing moisture in thick stems or roots, and their ingenious adaptations allow them to endure a level of adversity that would quickly kill more delicate plants.", "at": "有些強健的沙漠物種在乾旱地區蓬勃生長，靠的是極度節約用水，將水分儲存在粗厚的莖或根中；它們巧妙的適應方式，讓它們能熬過足以迅速殺死較嬌弱植物的逆境。"}, {"w": "tranquility", "p": "n.", "d": "A state of peace, quiet, and calm.", "c": "平靜；寧靜", "s": "Japanese Zen gardens were designed to promote tranquility, using carefully raked gravel, a few moss-covered stones, and the absence of bright flowers to quiet the mind and help visiting monks concentrate during long hours of meditation.", "t": "日本的禪意庭園旨在營造寧靜，運用細心耙出紋路的砂石、幾塊覆滿青苔的石頭，以及刻意不用鮮豔花朵的設計，來沉澱心靈，幫助來訪的僧侶在漫長的冥想時間中專注。", "as": "Seeking tranquility after the turmoil of the lengthy trial, the exhausted lawyer retreated to a remote mountain cabin without internet access, where the gentle euphony of birdsong and flowing water gradually replaced the cacophony of the city in her memory.", "at": "在冗長審判的混亂紛擾之後，筋疲力盡的律師為了尋求平靜，退隱到一間沒有網路的偏遠山間小屋；在那裡，鳥鳴與流水輕柔悅耳的和聲，逐漸取代了她記憶中城市的嘈雜喧囂。"}, {"w": "uniformity", "p": "n.", "d": "The quality of being the same throughout; lack of variation.", "c": "一致性；均一", "s": "Critics of the national curriculum argued that its emphasis on uniformity — requiring every school to teach the same textbooks in the same sequence on the same schedule — left teachers little freedom to adapt lessons to the interests and needs of their particular students.", "t": "國家課綱的批評者認為，課綱過度強調一致性——要求每所學校依相同進度、相同順序教授相同的課本——讓教師幾乎沒有空間依照自己學生的興趣與需求調整課程。", "as": "Critics of suburban sprawl lament the dreary uniformity of its identical houses and shopping centers, arguing that such mundane, derivative architecture reflects a complacent culture that prizes conformity and convenience over innovation, history, and a genuine sense of place.", "at": "郊區擴張的批評者感嘆那些一模一樣的房屋與購物中心單調一致，認為這種平凡無奇、缺乏原創性的建築，反映出一種自滿的文化——重視從眾與便利，勝過創新、歷史與真正的地方感。"}]}, {"unit": 34, "theme": "Evidence and Variety", "themeZh": "證據與多元", "antonymLessons": [], "cards": [{"w": "aggregate", "p": "n.", "d": "A whole formed by combining several separate elements.", "c": "總和；總計；集合體", "s": "Although no single household's carbon emissions seem significant, climate economists emphasize that the aggregate of millions of small daily choices — commuting by car, heating poorly insulated homes, and discarding food — accounts for a substantial share of a nation's total greenhouse gases.", "t": "雖然單一家庭的碳排放看似微不足道，氣候經濟學家強調，數百萬個日常小選擇的總和——開車通勤、為隔熱不良的房屋供暖、丟棄食物——占了一個國家溫室氣體總排放量的相當大比例。", "as": "Individually, each donation seemed negligible, but the aggregate of thousands of small gifts amounted to a munificent sum, proving that the town's frugal residents could be remarkably altruistic when a neighbor faced adversity.", "at": "單獨來看，每一筆捐款似乎都微不足道，但數千筆小額捐款的總和卻是一筆慷慨可觀的金額，證明這個小鎮節儉的居民在鄰居遭逢困境時，也能展現非凡的無私精神。"}, {"w": "complementary", "p": "adj.", "d": "Combining to complete or enhance each other.", "c": "互補的；相輔相成的", "s": "The partnership between the two founders succeeded because their talents were complementary: one was a brilliant engineer who could design efficient batteries but disliked public speaking, while the other was a persuasive negotiator who understood investors yet knew little about chemistry.", "t": "兩位創辦人的合作之所以成功，是因為他們的才能互補：一位是能設計高效電池、卻不喜歡公開演講的傑出工程師；另一位則是懂得投資人心理、卻對化學所知甚少的說服力十足的談判高手。", "as": "The museum's curators believe that ancient artifacts and contemporary art can be complementary, so the eclectic exhibition pairs a weathered relic from antiquity with an innovative sculpture, inviting visitors to discern unexpected connections.", "at": "博物館策展人相信古代文物與當代藝術能夠相輔相成，因此這場兼容並蓄的展覽將一件來自古代、飽經風霜的遺物與一件創新的雕塑並置，邀請觀眾察覺意想不到的關聯。"}, {"w": "debunk", "p": "v.", "d": "To expose a claim or belief as false.", "c": "揭穿；駁斥", "s": "Through a series of careful experiments with swan-necked flasks of broth, Louis Pasteur debunked the ancient theory of spontaneous generation, demonstrating that microorganisms arose from other living microbes carried in the air rather than from nonliving matter itself.", "t": "巴斯德透過一系列以鵝頸燒瓶盛裝肉湯的嚴謹實驗，揭穿了古老的自然發生說，證明微生物是由空氣中所攜帶的其他活微生物產生，而非由無生命的物質本身生成。", "as": "The skeptic devoted her entire career to debunking charlatans who claimed psychic powers, scrutinizing their spurious claims with meticulous controlled experiments and exposing the cynical tricks they used to deceive gullible audiences and extract money from grieving families.", "at": "這位懷疑論者畢生致力於揭穿那些自稱擁有超能力的江湖騙子，以一絲不苟的對照實驗仔細檢驗他們虛假的宣稱，並揭露他們用來欺騙輕信觀眾、向悲傷家屬騙取錢財的那些冷血伎倆。"}, {"w": "discrepancy", "p": "n.", "d": "A lack of agreement between facts that should match.", "c": "差異；不一致", "s": "Auditors became suspicious when they noticed a discrepancy of nearly two million dollars between the hospital's reported equipment purchases and the actual inventory in its storerooms, prompting a federal investigation that eventually uncovered an elaborate kickback scheme.", "t": "審計人員注意到，醫院申報的設備採購金額與倉庫中的實際庫存之間有將近兩百萬美元的差異，因而起了疑心，並促使聯邦展開調查，最終揭發了一套精心策劃的回扣陰謀。", "as": "The astute reporter noticed a glaring discrepancy between the senator's frugal public image and his lavish private spending on yachts and vacation homes, and her incisive article ultimately debunked the reputation for integrity that he had so carefully cultivated for decades.", "at": "精明的記者注意到，這位參議員節儉的公眾形象與他私下在遊艇和度假別墅上的揮霍開銷之間有明顯的落差，而她犀利的報導最終揭穿了他數十年來精心經營的正直聲譽。"}, {"w": "excerpt", "p": "n.", "d": "A short passage taken from a longer text or work.", "c": "摘錄；節錄", "s": "On the Digital SAT, each reading question is paired with a brief excerpt of only a few sentences, drawn from novels, scientific journals, or historical speeches, so test takers must interpret the author's argument without the surrounding context a full text would provide.", "t": "在數位SAT考試中，每道閱讀題都搭配一段只有幾句話的簡短節錄，選自小說、科學期刊或歷史演說，因此考生必須在缺乏完整文本上下文的情況下解讀作者的論點。", "as": "The teacher chose an excerpt from the novel replete with archaic vocabulary and subtle allusions, hoping her erudite students would appreciate its ambiguous imagery rather than dismiss it as obscure.", "at": "老師從這部小說中選了一段充滿古雅詞彙與微妙典故的節錄，希望她那些博學的學生能欣賞其意蘊含糊的意象，而不是把它斥為晦澀難懂。"}, {"w": "audacious", "p": "adj.", "d": "Showing a willingness to take bold, daring risks.", "c": "大膽的；無畏的", "s": "The Apollo program's goal of landing astronauts on the Moon within a decade was remarkably audacious, since at the time of President Kennedy's 1961 announcement, the United States had sent only a single astronaut on a brief suborbital flight lasting fifteen minutes.", "t": "阿波羅計畫要在十年內讓太空人登陸月球的目標極為大膽，因為甘迺迪總統在1961年宣布這項計畫時，美國只送過一名太空人進行為時十五分鐘的短暫次軌道飛行。", "as": "The audacious young architect proposed an unprecedented design for the waterfront that many critics called imprudent and impractical, yet her innovative tower ultimately surpassed every rival plan in the competition and was later acclaimed as a triumph of modern engineering.", "at": "這位大膽的年輕建築師為濱水區提出了前所未有的設計，許多評論家斥之為輕率又不切實際，但她創新的高塔最終在競圖中勝過所有對手的方案，後來更被譽為現代工程學的勝利。"}, {"w": "eclectic", "p": "adj.", "d": "Drawing ideas or styles from a broad range of sources.", "c": "兼容並蓄的；多元的", "s": "The architect's eclectic style combined Gothic arches, traditional Japanese timber joinery, and sleek modern glass walls in a single building, and although some critics found the mixture confusing, many visitors admired the way it reflected the city's diverse cultural history.", "t": "這位建築師兼容並蓄的風格，在同一棟建築中結合了哥德式拱門、傳統日式木作榫接，以及簡潔的現代玻璃牆；雖然有些評論家覺得這種混搭令人困惑，許多參觀者卻欣賞它反映出這座城市多元文化歷史的方式。", "as": "The chef's eclectic menu blends culinary traditions from five continents, pairing Peruvian ceviche with Korean kimchi and Ethiopian spices, and even the most discerning epicurean diners find her savory fusion dishes delectable rather than pretentious or merely fashionable.", "at": "這位主廚兼容並蓄的菜單融合了五大洲的烹飪傳統，將祕魯檸汁醃魚與韓國泡菜、衣索比亞香料搭配在一起，就連最挑剔的美食家也認為她那些鹹香的融合料理美味可口，而非矯揉造作或只是趕流行。"}, {"w": "aviary", "p": "n.", "d": "A large enclosure or building for keeping birds.", "c": "鳥舍；鳥園", "s": "To protect the critically endangered Hawaiian crow, which had disappeared from the wild by 2002, conservationists raised the remaining birds in a mountain aviary that imitated their native forest, complete with native fruit trees, misty humidity, and protection from invasive predators.", "t": "為了保護在2002年已於野外絕跡、極度瀕危的夏威夷烏鴉，保育人員將剩下的鳥飼養在一座模擬其原生森林的山區鳥舍中，裡面有原生果樹、霧氣般的濕度，並能防範外來掠食者。", "as": "The vast glass aviary at the botanical garden offers city workers a welcome respite from the cacophony of traffic and construction, and many visitors linger for hours among exotic birds whose mellifluous songs blend into a soothing euphony.", "at": "植物園中寬廣的玻璃鳥園，讓城市上班族得以暫時遠離車流與工地的嘈雜喧囂，許多遊客在珍奇鳥類之間流連數小時，牠們悅耳的歌聲交融成令人放鬆的和諧樂音。"}, {"w": "glacial", "p": "adj.", "d": "Extremely slow, like a glacier; also icy cold.", "c": "極緩慢的；冰冷的；冰河的", "s": "Reform of the nation's patent system proceeded at a glacial pace, with proposed legislation stalling in committee year after year, so that by the time the law was finally passed, many of the technologies it was meant to regulate had already become obsolete.", "t": "這個國家的專利制度改革進展極其緩慢，提出的法案年復一年卡在委員會中，以至於等到法律終於通過時，許多原本要規範的技術早已過時。", "as": "Progress on the new bridge was glacial: sluggish bureaucrats, contentious lawsuits filed by neighboring towns, and a myriad of permit delays left the project stagnant for nearly a decade, until frustrated commuters finally organized protests demanding immediate action.", "at": "新橋的工程進度極其緩慢：拖拖拉拉的官僚、鄰近城鎮提起的爭議訴訟，以及無數的許可延宕，讓計畫停滯了將近十年，直到不滿的通勤族終於組織抗議，要求立即採取行動。"}]}, {"unit": 35, "theme": "Obstacles and Deception", "themeZh": "阻礙與虛假", "antonymLessons": [], "cards": [{"w": "insuperable", "p": "adj.", "d": "Impossible to overcome or surmount.", "c": "難以克服的；不可逾越的", "s": "For centuries, engineers regarded the Isthmus of Panama as an insuperable barrier to a canal: French attempts in the 1880s collapsed after mudslides, financial scandal, and yellow fever killed more than twenty thousand workers before the excavation was even half complete.", "t": "幾個世紀以來，工程師都把巴拿馬地峽視為開鑿運河難以克服的障礙：1880年代法國的嘗試，在土石流、金融醜聞與黃熱病奪走兩萬多名工人性命之後宣告失敗，當時開挖工程甚至還不到一半。", "as": "For decades the granite ridge seemed an insuperable obstacle to the railway, but a dogged, unwavering team of engineers eventually devised an ingenious method to tunnel safely beneath the precarious mountain without triggering the landslides that had doomed earlier attempts.", "at": "數十年來，這道花崗岩山脊似乎是興建鐵路無法克服的障礙，但一群堅持不懈、毫不動搖的工程師最終設計出一種巧妙的方法，安全地從岌岌可危的山體下方開鑿隧道，而不會引發先前導致嘗試失敗的山崩。"}, {"w": "replete", "p": "adj.", "d": "Filled or well supplied with something.", "c": "充滿的；充足的", "s": "Charles Darwin's notebooks from the voyage of the Beagle are replete with detailed sketches of finches, barnacles, and fossilized bones, along with tentative questions in the margins that reveal how his ideas about the variation of species gradually developed.", "t": "達爾文乘坐小獵犬號航行時的筆記本中，滿是雀鳥、藤壺與骨骼化石的詳細素描，頁邊還有一些試探性的疑問，顯示他對物種變異的想法是如何逐步發展的。", "as": "The candidate's victory speech was replete with hackneyed platitudes and grandiloquent promises about a brighter future, but the more discerning listeners noticed that it offered no specific plan for addressing the economic turmoil that had driven so many families from the city.", "at": "這位候選人的勝選演說充斥著陳腔濫調和有關光明未來的浮誇承諾，但較有眼光的聽眾注意到，演說中並未提出任何具體方案，來解決那場迫使許多家庭離開這座城市的經濟混亂。"}, {"w": "respite", "p": "n.", "d": "A short period of rest or relief from difficulty.", "c": "喘息；暫緩；短暫休息", "s": "For the exhausted doctors working through the city's worst influenza season in decades, the brief respite provided by a volunteer medical team from a neighboring province allowed them to sleep for the first time in days before the next wave of patients arrived.", "t": "對於在這座城市數十年來最嚴重的流感季中疲於奔命的醫師而言，鄰省志工醫療團隊帶來的短暫喘息，讓他們在下一波病患湧入之前，得以在數天以來首次好好睡上一覺。", "as": "The brief truce offered the besieged city only a fleeting respite from the turmoil of war, and residents knew that the volatile peace could collapse into another conflagration at any moment.", "at": "短暫的停火只讓被圍困的城市從戰爭的混亂中獲得片刻喘息，居民們都知道，這種動盪不穩的和平隨時可能再度演變成一場大火般的戰禍。"}, {"w": "raze", "p": "v.", "d": "To completely destroy or level a building or town.", "c": "夷為平地；徹底摧毀", "s": "After defeating Carthage in 146 BCE, Roman forces razed the city so thoroughly that archaeologists today struggle to identify more than a few scattered foundations, although the later legend that the Romans also salted the earth has no basis in ancient sources.", "t": "西元前146年擊敗迦太基之後，羅馬軍隊將這座城市徹底夷為平地，以至於今日的考古學家只能辨識出少數零散的地基；不過，後世所謂羅馬人還在土地上撒鹽的傳說，在古代文獻中並無根據。", "as": "When developers announced plans to raze the historic market, indignant residents, outraged by the plan's callous disregard for their heritage, launched a vociferous campaign of petitions and public hearings that bolstered support for preserving the century-old building.", "at": "當開發商宣布計畫拆除這座歷史悠久的市場時，憤慨的居民對該計畫冷酷無視他們的文化遺產深感憤怒，發起了一場透過請願與公聽會進行、聲勢浩大的運動，強化了民眾對保存這棟百年建築的支持。"}, {"w": "lithe", "p": "adj.", "d": "Flexible, supple, and graceful in movement.", "c": "柔軟的；輕盈的；敏捷的", "s": "Snow leopards are remarkably lithe predators, able to twist their long, muscular bodies in midair while leaping across rocky ravines and using their thick tails for balance on cliffs so steep that few other mammals can follow them.", "t": "雪豹是身手極為矯健柔軟的掠食者，能在躍過岩石峽谷時於半空中扭轉修長而結實的身軀，並在陡峭到少有其他哺乳動物能跟上的懸崖上，利用粗厚的尾巴保持平衡。", "as": "Unlike the sluggish, sedentary courtiers who populate the rest of the play, the lithe acrobat cast as the trickster brought a vibrant, effervescent energy to the stage, and audiences acclaimed her tumbling performance as the highlight of the entire production.", "at": "不同於劇中其他那些行動遲緩、久坐不動的朝臣，飾演搗蛋鬼的身段輕盈的雜技演員為舞臺帶來充滿活力、熱情洋溢的能量，觀眾盛讚她的翻滾表演是整齣戲的最大亮點。"}, {"w": "spurious", "p": "adj.", "d": "False or fake, though appearing genuine.", "c": "虛假的；偽造的；謬誤的", "s": "Statisticians warn that analyzing huge data sets without a clear hypothesis can produce spurious correlations, such as the widely shared chart showing that national cheese consumption tracked closely with deaths from tangled bedsheets, even though neither trend could plausibly cause the other.", "t": "統計學家警告，在沒有明確假說的情況下分析龐大的資料集，可能產生虛假的相關性，例如那張廣為流傳的圖表顯示全國起司消費量與被床單纏繞致死的人數密切相關，儘管兩者都不可能是對方的成因。", "as": "The charlatan's spurious cure for arthritis was promoted with ostentatious advertisements and fabricated testimonials, but skeptical scientists debunked his claims in a controlled trial, revealing that his nefarious scheme preyed chiefly on desperate, indigent patients who could least afford it.", "at": "這名江湖郎中號稱能治療關節炎的假藥，以浮誇的廣告和捏造的見證大肆宣傳，但抱持懷疑態度的科學家在對照試驗中揭穿了他的說法，揭露他那邪惡的詐騙手法主要剝削的是最負擔不起的、走投無路的貧困病患。"}, {"w": "misanthrope", "p": "n.", "d": "A person who dislikes and avoids humankind.", "c": "厭世者；憎惡人類的人", "s": "Literary critics often describe Alceste, the title character of Molière's 1666 comedy, as a misanthrope who despises the flattery and hypocrisy of Parisian society so intensely that he ultimately resolves to abandon civilization altogether and live in solitude.", "t": "文學評論家常把莫里哀1666年喜劇的主角阿爾賽斯特形容為一個厭世者，他對巴黎上流社會的阿諛與虛偽深惡痛絕，最終決定完全拋棄文明、離群索居。", "as": "The reclusive poet was often dismissed by critics as a cynical misanthrope, yet her recently published letters reveal an affable, magnanimous woman who quietly supported struggling young writers, and whose aloof public manner merely concealed a lifelong and painful shyness.", "at": "這位離群索居的詩人常被評論家貶為憤世嫉俗的厭世者，但她最近出版的書信顯示，她是一位和藹可親、寬宏大量的女性，曾默默資助困頓的年輕作家；她在公開場合冷淡疏離的態度，只不過是掩飾她終生為之所苦的害羞。"}, {"w": "pitfall", "p": "n.", "d": "A hidden or unsuspected danger or difficulty.", "c": "陷阱；隱患", "s": "One common pitfall in historical research is presentism, the tendency to judge people of earlier centuries entirely by modern moral standards, which can prevent scholars from understanding why past societies made the decisions they did.", "t": "歷史研究中一個常見的陷阱是「現今主義」，也就是完全以現代道德標準評斷過去幾世紀的人，這可能使學者無法理解過去的社會為何做出那些決定。", "as": "The financial adviser warned that the most common pitfall for novice investors is not excessive caution but complacent overconfidence after a few early gains, which often leads them to abandon prudent diversification and make imprudent bets on volatile technology stocks.", "at": "這位理財顧問警告，新手投資人最常見的陷阱並非過度謹慎，而是在幾次初期獲利後產生的自滿與過度自信，這往往使他們放棄審慎的分散投資，輕率地押注在波動劇烈的科技股上。"}, {"w": "vaporize", "p": "v.", "d": "To turn into vapor; to disappear suddenly and completely.", "c": "使蒸發；使汽化；消失", "s": "In mass spectrometry, scientists first vaporize a tiny sample of the substance being studied, converting it into a gas whose charged particles can then be sorted by mass, allowing researchers to identify even trace amounts of a chemical compound.", "t": "在質譜分析中，科學家會先將所研究物質的極少量樣本汽化，使其轉變為氣體，其中帶電的粒子接著可依質量加以分類，讓研究人員即使是微量的化合物也能辨識出來。", "as": "The company's lofty profits seemed to vaporize overnight once auditors exposed its spurious accounting practices, and the ensuing debacle left once-complacent shareholders indignant at the charismatic executives whom they had foolishly esteemed as visionary leaders.", "at": "一旦審計人員揭發這家公司造假的會計手法，其原本高得驚人的利潤彷彿一夜之間蒸發殆盡；隨之而來的慘敗，讓曾經自滿的股東們對那些他們曾愚蠢地敬重為遠見領袖、魅力十足的高層主管憤慨不已。"}]}, {"unit": 36, "theme": "Deceit and Trickery", "themeZh": "欺騙與詭計", "antonymLessons": [37], "cards": [{"w": "duplicity", "p": "n.", "d": "Cunning, trickery.", "c": "表裡不一/欺騙", "s": "Her duplicity was revealed when she was caught lying to both sides.", "t": "當她被發現對雙方都撒謊時,她的表裡不一便暴露無遺。", "as": "The spy's duplicity allowed him to work for two governments at once.", "at": "這名間諜的兩面手法讓他能同時為兩個政府工作。"}, {"w": "guile", "p": "n.", "d": "Deceitful, cunning, sly behavior.", "c": "狡詐/詭計", "s": "He used guile rather than force to gain access to the vault.", "t": "他靠狡詐而非武力進入了這座金庫。", "as": "Despite her innocent appearance, she was full of guile.", "at": "儘管外表天真無邪,她內心卻充滿了狡詐。"}, {"w": "subterfuge", "p": "n.", "d": "Ruse, trick.", "c": "詭計/遁詞", "s": "He used subterfuge to avoid answering the reporter's difficult questions.", "t": "他用詭計來迴避記者提出的棘手問題。", "as": "The spy relied on subterfuge rather than force to gather information.", "at": "這名間諜靠詭計而非武力來蒐集情報。"}, {"w": "beguile", "p": "v.", "d": "To trick, deceive.", "c": "欺騙/迷惑", "s": "The con artist managed to beguile several elderly victims out of their savings.", "t": "這名騙子成功欺騙了好幾位年長的受害者,騙走了他們的積蓄。", "as": "Her charming smile beguiled everyone at the party.", "at": "她迷人的微笑迷惑了派對上的每一個人。"}, {"w": "dupe", "p": "n.", "d": "Person easily tricked.", "c": "易受騙的人", "s": "He felt like a complete dupe after realizing the deal was a scam.", "t": "發現這筆交易是騙局後,他覺得自己完全是個受騙的傻瓜。", "as": "The con artist looked for a dupe who would believe his outrageous story.", "at": "這名騙子在尋找一個會相信他離譜謊言的易受騙者。"}, {"w": "swindle", "p": "v./n.", "d": "To cheat someone out of money or property.", "c": "詐騙;騙局", "s": "The con artist managed to swindle several elderly investors.", "t": "這位騙子成功詐騙了好幾位年長的投資人。", "as": "The pyramid scheme turned out to be an elaborate swindle .", "at": "這個老鼠會後來被發現是一場精心策劃的騙局。"}, {"w": "feign", "p": "v.", "d": "To pretend to feel or be affected by something.", "c": "假裝;佯裝", "s": "He tried to feign surprise at the news.", "t": "他試圖對這個消息佯裝驚訝。", "as": "She would feign illness to avoid unwanted social events.", "at": "她會假裝生病來躲避不想參加的社交活動。"}, {"w": "dissemble", "p": "v.", "d": "To conceal, fake.", "c": "掩飾/偽裝", "s": "He tried to dissemble his true feelings behind a calm smile.", "t": "他試圖用一抹平靜的微笑掩飾自己真實的情緒。", "as": "Politicians sometimes dissemble to avoid answering a difficult question.", "at": "政治人物有時會裝糊塗,以避免回答棘手的問題。"}, {"w": "equivocate", "p": "v.", "d": "To use ambiguous language to avoid committing to a position.", "c": "含糊其辭;搪塞", "s": "The witness began to equivocate when asked direct questions.", "t": "被問到直接問題時,這位證人開始含糊其辭。", "as": "Politicians often equivocate to avoid controversy.", "at": "政治人物經常含糊其辭以避免爭議。"}, {"w": "prevaricate", "p": "v.", "d": "To speak evasively to avoid telling the truth.", "c": "支吾其詞;含糊其辭", "s": "The witness continued to prevaricate rather than answer directly.", "t": "這位證人持續支吾其詞,而非直接回答問題。", "as": "Politicians often prevaricate when asked about controversial policies.", "at": "政治人物在被問及具爭議性的政策時經常含糊其辭。"}, {"w": "mendacious", "p": "adj.", "d": "Lying, untrue.", "c": "虛假的/撒謊的", "s": "The politician was known for making mendacious statements to the press.", "t": "這位政治人物以向媒體發表虛假言論聞名。", "as": "His mendacious excuse fooled no one in the office.", "at": "他那虛假的藉口沒能騙過辦公室裡的任何人。"}, {"w": "disingenuous", "p": "adj.", "d": "Not candid or sincere, typically by pretending to know less than one does.", "c": "虛偽的;不誠懇的", "s": "It seemed disingenuous of him to claim he had no idea about the plan.", "t": "他聲稱對這項計畫毫不知情,顯得相當虛偽。", "as": "Her disingenuous apology fooled no one.", "at": "她不誠懇的道歉沒有騙過任何人。"}, {"w": "specious", "p": "adj.", "d": "Appearing true or plausible but actually false.", "c": "似是而非的;貌似有理的", "s": "The lawyer dismantled the witness's specious reasoning point by point.", "t": "這位律師逐點拆解了這位證人似是而非的推理。", "as": "Her argument sounded convincing but was ultimately specious .", "at": "她的論點聽起來很有說服力,但終究是貌似有理的。"}, {"w": "fraudulent", "p": "adj.", "d": "Obtained or done by deception.", "c": "詐欺的;欺詐性的", "s": "The bank flagged several fraudulent transactions on her account.", "t": "銀行標記了她帳戶中好幾筆詐欺性的交易。", "as": "He was accused of using fraudulentedocuments to secure the loan.", "at": "他被指控使用詐欺性的文件來取得這筆貸款。"}, {"w": "artifice", "p": "n.", "d": "Strategy, trickery.", "c": "詭計/欺騙", "s": "Through clever artifice, the con man convinced them he was a doctor.", "t": "這名詐騙犯憑藉巧妙的詭計,讓他們相信他是一名醫生。", "as": "Her seemingly natural charm was actually a carefully practiced artifice.", "at": "她那看似天然的魅力,其實是經過精心設計的詭計。", "a": 1}, {"w": "defraud", "p": "v.", "d": "To illegally obtain money from someone by deception.", "c": "詐騙", "s": "He was convicted of trying to defraud elderly investors.", "t": "他因試圖詐騙年長投資人而遭定罪。", "as": "The scheme was designed to defraud the government of tax revenue.", "at": "這個騙局是為了詐取政府的稅收而設計的。", "a": 1}, {"w": "trickery", "p": "n.", "d": "The use of deceptive tactics to deceive someone.", "c": "詭計;欺騙手段", "s": "He obtained the signature through outright trickery .", "t": "他透過徹底的欺騙手段取得了這份簽名。", "as": "The magician's performance relied on skillful trickery rather than real magic.", "at": "這位魔術師的表演靠的是巧妙的騙術,而非真正的魔法。", "a": 1}, {"w": "delude", "p": "v.", "d": "To fool.", "c": "欺騙/蠱惑", "s": "He tried to delude himself into thinking the relationship could still be saved.", "t": "他試圖欺騙自己,認為這段感情仍有挽回的可能。", "as": "The scammer managed to deludedozens of investors with false promises.", "at": "這名詐騙犯用虛假的承諾成功欺騙了數十名投資者。", "a": 1}, {"w": "ruse", "p": "n.", "d": "A trick.", "c": "詭計/花招", "s": "The escape was nothing more than an elaborate ruse to distract the guards.", "t": "這場逃脫不過是為了轉移守衛注意力所設計的一場精心詭計。", "as": "She saw through his ruse and refused to hand over the documents.", "at": "她識破了他的詭計,拒絕交出這些文件。", "a": 1}, {"w": "stratagem", "p": "n.", "d": "A plan or scheme, especially to outwit an opponent.", "c": "計謀;策略", "s": "The general devised a clever stratagem to divide the enemy forces.", "t": "這位將軍設計了一項巧妙的計謀來分散敵軍兵力。", "as": "Her business stratagem involved undercutting competitors' prices temporarily.", "at": "她的商業策略包括暫時削價來打擊競爭對手。", "a": 1}, {"w": "hoax", "p": "n.", "d": "Deception, fraud.", "c": "騙局/惡作劇", "s": "The viral video turned out to be an elaborate hoax created for attention.", "t": "這段爆紅的影片結果是為了博取關注而精心策劃的騙局。", "as": "Scientists quickly exposed the claim as a hoax.", "at": "科學家很快就揭穿這項說法是個騙局。", "a": 1}, {"w": "deceptive", "p": "adj.", "d": "Misleading or giving a false impression.", "c": "有欺騙性的/誤導性的", "s": "The advertisement was deceptive, leading customers to believe the product was free.", "t": "這則廣告具有誤導性,讓顧客誤以為這項產品是免費的。", "as": "The advertisement was deceptive in its claims of weight loss.", "at": "這則廣告在減重功效的宣稱上具有欺騙性。", "a": 1}, {"w": "fraud", "p": "n.", "d": "Wrongful or criminal deception for financial gain.", "c": "詐欺;欺詐", "s": "He was arrested for committing insurance fraud .", "t": "他因涉嫌保險詐欺而遭到逮捕。", "as": "The company faced charges of accounting fraud .", "at": "這家公司面臨會計詐欺的指控。", "a": 1}, {"w": "pretext", "p": "n.", "d": "An excuse.", "c": "藉口", "s": "He used a doctor's appointment as a pretext to leave the meeting early.", "t": "他以看醫生為藉口提早離開會議。", "as": "The soldiers invaded the town under the pretext of restoring order.", "at": "士兵們以恢復秩序為藉口入侵了這座城鎮。", "a": 1}, {"w": "fabricate", "p": "v.", "d": "To make up a false story.", "c": "捏造；編造", "s": "The student tried to fabricate an excuse for missing the test but was caught.", "t": "這名學生試圖捏造缺考的藉口，但被抓到了。", "as": "", "at": "", "a": 1}]}, {"unit": 37, "theme": "Honesty and Sincerity", "themeZh": "誠實與真誠", "antonymLessons": [36], "cards": [{"w": "candid", "p": "adj.", "d": "Frank, open, honest.", "c": "坦白的/直率的", "s": "The interviewer asked for a candid opinion about the company's future.", "t": "訪談者要求對方坦率說出對公司未來的看法。", "as": "Her candid remarks about her struggles surprised many fans.", "at": "她坦率談及自身掙扎的言論讓許多粉絲感到驚訝。"}, {"w": "frank", "p": "adj.", "d": "Open and honest in expression; candid.", "c": "坦率的;直言的", "s": "She gave a frank assessment of the company's problems.", "t": "她對這家公司的問題給出了坦率的評估。", "as": "He was refreshingly frank about his own mistakes.", "at": "他對自己的錯誤坦率得令人耳目一新。"}, {"w": "forthright", "p": "adj.", "d": "Direct and outspoken.", "c": "直率的;坦率的", "s": "She gave a forthright answer to the difficult question.", "t": "她對這個困難的問題給出了直率的答案。", "as": "His forthright manner sometimes came across as blunt.", "at": "他直率的態度有時給人一種生硬的感覺。"}, {"w": "veracity", "p": "n.", "d": "Truthfulness, accuracy.", "c": "真實性/誠實", "s": "Journalists questioned the veracity of the anonymous source's claims.", "t": "記者質疑這位匿名消息來源說法的真實性。", "as": "Her reputation for veracity made her testimony highly credible in court.", "at": "她以誠實可信著稱,這讓她在法庭上的證詞極具公信力。"}, {"w": "integrity", "p": "n.", "d": "Holding firmly to values, such as honesty; completeness.", "c": "正直；完整", "s": "She is known for her integrity and refuses to cut corners, even under pressure.", "t": "她以正直聞名,即使在壓力之下也拒絕偷工減料。", "as": "The scandal called into question the integrity of the entire organization.", "at": "這起醜聞讓整個組織的操守受到質疑。"}, {"w": "ingenuous", "p": "adj.", "d": "Not devious; innocent and candid.", "c": "率真的/天真無邪的", "s": "The child's ingenuous questions about death caught her parents off guard.", "t": "這個孩子率真地問起關於死亡的問題,讓父母措手不及。", "as": "His ingenuous honesty about his mistakes won over the skeptical committee.", "at": "他坦率承認自己的錯誤,贏得了原本存疑的委員會的信任。"}, {"w": "straightforward", "p": "adj.", "d": "Uncomplicated and easy to understand; honest.", "c": "簡單明瞭的;坦率的", "s": "The instructions were straightforward and easy to follow.", "t": "這些說明簡單明瞭又容易遵循。", "as": "She gave a straightforward account of what had happened.", "at": "她坦率地敘述了事情發生的經過。"}, {"w": "genuine", "p": "adj.", "d": "Authentic or real.", "c": "真誠的/真正的", "s": "His apology seemed genuine.", "t": "他的道歉聽起來相當真誠。", "as": "The store guarantees that every product is a genuine leather item.", "at": "這家商店保證每件產品都是真皮製品。"}, {"w": "scrupulous", "p": "adj.", "d": "Showing great care and honesty, based on what is right.", "c": "一絲不苟的", "s": "The accountant was scrupulous in recording every transaction accurately.", "t": "這位會計師一絲不苟地精確記錄每一筆交易。", "as": "Her scrupulous attention to detail made her the best editor on staff.", "at": "她一絲不苟地注重細節,讓她成為員工中最優秀的編輯。"}, {"w": "upright", "p": "adj./adv.", "d": "Vertical or erect; strictly honest and moral.", "c": "直立的;正直的", "s": "He sat perfectly upright throughout the entire interview.", "t": "他在整場面試中始終坐得筆直。", "as": "She was known as an upright citizen who always followed the rules.", "at": "她以正直守法、始終遵守規定的公民聞名。"}, {"w": "guileless", "p": "adj.", "d": "Innocent and honest; without deception.", "c": "天真無邪的;誠實的", "s": "The child's guileless smile melted everyone's heart.", "t": "這個孩子天真無邪的笑容融化了每個人的心。", "as": "He remained guilelessedespite years in the cutthroat industry.", "at": "儘管在這個殘酷的產業中打滾多年,他仍保持著純真誠實。"}, {"w": "outspoken", "p": "adj.", "d": "Expressing opinions directly and honestly, even when they may offend people.", "c": "直言不諱的；坦率的", "s": "She is an outspoken critic of the government's environmental policy and often organizes protests.", "t": "她是政府環境政策的直言不諱的批評者，經常組織抗議活動。", "as": "Some managers found his outspoken nature rude, while others appreciated his honest feedback.", "at": "有些經理認為他坦率的性格很無禮，另一些人則欣賞他的誠實回饋。", "a": 1}, {"w": "blunt", "p": "adj.", "d": "Plainspoken:candid=honest.", "c": "直率的/遲鈍的", "s": "Her blunt criticism of the project hurt his feelings, though it was honest.", "t": "她對這個計畫直言不諱的批評雖然誠實,卻傷了他的感情。", "as": "The doctor gave a blunt assessment of the patient's chances of recovery.", "at": "醫生對病人的康復機率給出了直白坦率的評估。", "a": 1}, {"w": "artless", "p": "adj.", "d": "Naive, innocent.", "c": "天真的/單純的", "s": "Her artless honesty charmed everyone at the dinner party.", "t": "她那份天真無邪的坦率讓晚宴上的每個人都為之著迷。", "as": "The child's artlessedrawing was simple but full of joy.", "at": "這個孩子單純稚拙的畫作雖然簡單,卻充滿了喜悅。", "a": 1}, {"w": "honorable", "p": "adj.", "d": "Deserving respect for honesty and integrity.", "c": "值得尊敬的;正直的", "s": "He made the honorable choice to admit his mistake.", "t": "他做出了坦承錯誤這個值得尊敬的選擇。", "as": "The soldier received an honorabledischarge after years of service.", "at": "這位士兵在多年服役後獲得了光榮退伍。", "a": 1}, {"w": "truthful", "p": "adj.", "d": "Telling or expressing the truth; honest.", "c": "誠實的;真實的", "s": "She gave a truthful account of what had happened at the scene.", "t": "她對現場發生的事情做出了真實的陳述。", "as": "He was always truthful , even when honesty was uncomfortable.", "at": "即使誠實會讓人感到不自在,他也總是保持誠實。", "a": 1}, {"w": "trustworthy", "p": "adj.", "d": "Deserving of trust and confidence.", "c": "值得信賴的", "s": "She hired only trustworthy employees to manage the company's finances.", "t": "她只聘用值得信賴的員工來管理公司的財務。", "as": "He proved himself trustworthy by keeping every promise he made.", "at": "他信守自己許下的每一個承諾,證明了自己值得信賴。", "a": 1}]}, {"unit": 38, "theme": "Courage and Boldness", "themeZh": "勇敢與大膽", "antonymLessons": [39], "cards": [{"w": "intrepid", "p": "adj.", "d": "Brave.", "c": "無畏的", "s": "The intrepid explorer crossed the desert alone with only a small amount of water.", "t": "這位無畏的探險家僅帶著少量的水,獨自穿越了沙漠。", "as": "It took an intrepid firefighter to run into the burning building to save the child.", "at": "需要一位無畏的消防員衝進燃燒的大樓才能救出那個孩子。"}, {"w": "audacious", "p": "adj.", "d": "Showing a willingness to take bold risks, sometimes in a shocking or disrespectful way.", "c": "大膽的；無畏的；放肆的", "s": "The startup launched an audacious plan to build a commercial space station within two years, a daring gamble that skeptics dismissed as unrealistic given the company's tight budget.", "t": "這家新創公司推出一項大膽計畫，要在兩年內建造商業太空站；懷疑者認為，以該公司的有限預算來看，這場豪賭完全不切實際。", "as": "In a characteristically audacious move, the young chess grandmaster sacrificed his queen early in the match, stunning his opponent and securing a brilliant victory.", "at": "這位年輕的西洋棋特級大師做出典型的大膽之舉，在比賽初期便犧牲皇后，震驚對手並取得精彩勝利。"}, {"w": "valiant", "p": "adj.", "d": "Possessing or showing courage, especially in battle.", "c": "英勇的;勇敢的", "s": "The soldiers made a valiant stand against overwhelming odds.", "t": "這些士兵在敵眾我寡的情況下英勇地奮戰到底。", "as": "Despite her illness, she made a valiant effort to finish the race.", "at": "儘管身患疾病,她仍英勇地努力完成了這場比賽。"}, {"w": "valor", "p": "n.", "d": "Courage:bravery.", "c": "英勇/勇氣", "s": "The soldier was awarded a medal for his valor on the battlefield.", "t": "這名士兵因在戰場上的英勇表現而獲頒獎章。", "as": "Stories of the firefighters' valor spread throughout the city.", "at": "消防員英勇事蹟的故事傳遍了整座城市。"}, {"w": "fortitude", "p": "n.", "d": "Strength, guts.", "c": "堅忍/毅力", "s": "She faced the illness with remarkable fortitude and grace.", "t": "她以驚人的堅忍與從容面對這場疾病。", "as": "It took great fortitude for the soldiers to endure the harsh winter.", "at": "士兵們需要極大的毅力才能撐過這個嚴酷的冬天。"}, {"w": "stalwart", "p": "adj./n.", "d": "Loyal, reliable, and hardworking; a strong supporter.", "c": "堅定的;忠實支持者", "s": "She remained a stalwart supporter of the cause for decades.", "t": "她數十年來始終是這項理念堅定不移的支持者。", "as": "The team relied on their stalwartedefense to secure the win.", "at": "這支隊伍依靠他們堅實可靠的防守來確保勝利。"}, {"w": "gallant", "p": "adj.", "d": "Brave, heroic, or exceptionally polite and attentive.", "c": "英勇的/殷勤的", "s": "The gallant knight ventured into the dangerous forest.", "t": "這位英勇的騎士冒險踏入了危險的森林。", "as": "He made a gallant effort to rescue the drowning child.", "at": "他英勇地嘗試救出那個溺水的孩子。"}, {"w": "mettle", "p": "n.", "d": "A person's ability to cope well with difficulties; spirit and resilience.", "c": "勇氣;毅力", "s": "The crisis truly tested the young leader's mettle .", "t": "這場危機真正考驗了這位年輕領袖的毅力與勇氣。", "as": "She proved her mettle by finishing the race despite the injury.", "at": "儘管受了傷,她仍完成了這場比賽,證明了自己的毅力。"}, {"w": "courageous", "p": "adj.", "d": "Able to face danger or fear with bravery.", "c": "勇敢的", "s": "The courageous firefighter ran back into the burning building.", "t": "這位勇敢的消防員衝回了燃燒中的建築物。", "as": "It was a courageousedecision to speak out against her boss.", "at": "挺身反對她的上司是一項勇敢的決定。", "a": 1}, {"w": "bold", "p": "adj.", "d": "Courageous or striking.", "c": "大膽的", "s": "Elsie made a bold move by quitting her job.", "t": "艾爾希辭去工作是一個大膽的舉動。", "as": "The artist used bold colors to make the painting stand out.", "at": "這位藝術家使用大膽鮮明的色彩讓這幅畫更加突出。", "a": 1}, {"w": "chivalrous", "p": "adj.", "d": "Attentive and honorable like an ideal knight.", "c": "騎士風度的/俠義的", "s": "He held the door open in a chivalrous gesture that impressed everyone.", "t": "他為人開門的俠義舉動讓在場所有人都印象深刻。", "as": "The knight's chivalrous conduct earned him the admiration of the entire court.", "at": "這位騎士的俠義行為贏得了整個宮廷的敬佩。", "a": 1}]}, {"unit": 39, "theme": "Fear and Cowardice", "themeZh": "恐懼與膽小", "antonymLessons": [38], "cards": [{"w": "timid", "p": "adj.", "d": "Showing a lack of courage or confidence.", "c": "膽怯的;羞怯的", "s": "The timid new student barely spoke during her first week.", "t": "這位膽怯的新生在她第一週幾乎沒開口說話。", "as": "He gave a timid knock before entering the office.", "at": "他怯生生地敲了敲門才走進這間辦公室。"}, {"w": "timorous", "p": "adj.", "d": "Fearful.", "c": "膽怯的/怯懦的", "s": "The timorous new student barely spoke a word during her first week of class.", "t": "這位膽怯的新同學在開學第一週幾乎不曾開口說話。", "as": "He gave a timorous knock on the door before slowly stepping inside.", "at": "他怯生生地敲了敲門,才緩緩走進屋內。"}, {"w": "craven", "p": "adj.", "d": "Contemptibly cowardly.", "c": "懦弱的;卑怯的", "s": "The soldier's craven retreat shamed his entire unit.", "t": "這名士兵卑怯的撤退讓整個部隊蒙羞。", "as": "It was a craven act to blame an innocent colleague.", "at": "把過錯推給無辜的同事是個懦弱的行為。"}, {"w": "trepidation", "p": "n.", "d": "A feeling of fear or anxiety about something that may happen.", "c": "恐懼/憂慮", "s": "The thought of speaking in front of a large crowd filled him with trepidation.", "t": "一想到要在一大群觀眾面前演講,他就充滿了忐忑不安的恐懼。", "as": "She approached the interview with a mix of excitement and trepidation.", "at": "她帶著興奮與忐忑交織的心情去參加這場面試。"}, {"w": "apprehensive", "p": "adj.", "d": "Anxious or fearful about something that may happen.", "c": "憂慮的;擔心的", "s": "He felt apprehensive about presenting in front of the entire board.", "t": "在整個董事會面前簡報,讓他感到十分緊張。", "as": "Parents were apprehensive about sending their kids back to school after the outbreak.", "at": "疫情爆發後,家長對送孩子回學校感到憂心忡忡。"}, {"w": "diffident", "p": "adj.", "d": "Shy, quiet, modest.", "c": "缺乏自信的/靦腆的", "s": "The diffident new student rarely spoke up in class.", "t": "這位缺乏自信的新生在課堂上很少發言。", "as": "Despite her talent, she remained diffident about sharing her artwork.", "at": "儘管才華洋溢,她對分享自己的作品仍顯得十分靦腆。"}, {"w": "fainthearted", "p": "adj.", "d": "Lacking courage or determination.", "c": "膽怯的;懦弱的", "s": "This challenging trail is not for the fainthearted .", "t": "這條充滿挑戰的步道不適合膽怯的人。", "as": "He was too fainthearted to confront his boss about the issue.", "at": "他太過膽怯,不敢就這個問題與老闆對質。", "a": 1}, {"w": "spineless", "p": "adj.", "d": "Lacking courage or determination; invertebrate.", "c": "懦弱的;無脊椎的", "s": "Critics called the senator spineless for refusing to take a stand.", "t": "評論家指責這位參議員因拒絕表態而顯得懦弱無能。", "as": "Jellyfish are spineless creatures that drift with ocean currents.", "at": "水母是隨著洋流漂浮的無脊椎生物。", "a": 1}, {"w": "phobia", "p": "n.", "d": "Persistent fear, strong dislike.", "c": "恐懼症", "s": "His phobia of heights kept him from ever climbing a ladder.", "t": "他對高處的恐懼症讓他從不敢爬梯子。", "as": "A phobia of public speaking can be overcome with practice.", "at": "對公開演講的恐懼症可以透過練習來克服。", "a": 1}, {"w": "recoil", "p": "v.", "d": "To draw back.", "c": "退縮", "s": "She couldn't help but recoil in disgust at the smell.", "t": "聞到那股氣味,她忍不住嫌惡地退縮。", "as": "The soldier felt the rifle recoil against his shoulder as he fired.", "at": "士兵開槍時感覺步槍在他肩上產生後座力。", "a": 1}]}, {"unit": 40, "theme": "Anger and Irritation", "themeZh": "憤怒與惱怒", "antonymLessons": [41], "cards": [{"w": "irate", "p": "adj.", "d": "Angry, incensed.", "c": "暴怒的", "s": "The irate customer demanded to speak with the manager immediately.", "t": "這位暴怒的顧客要求立刻與經理談話。", "as": "Irate fans booed loudly when the referee made the final call.", "at": "裁判做出最終判決時,暴怒的球迷們大聲發出噓聲。"}, {"w": "indignant", "p": "adj.", "d": "Angry.", "c": "憤慨的", "s": "She grew indignant when she was accused of cheating.", "t": "她被指控作弊時,顯得十分憤慨。", "as": "The residents were indignant about the sudden increase in property taxes.", "at": "居民們對財產稅突然調漲感到十分憤慨。"}, {"w": "wrath", "p": "n.", "d": "Vengeful anger, punishment.", "c": "憤怒/天譴", "s": "The villagers feared the wrath of the volcano god after the eruption.", "t": "火山爆發後,村民們畏懼著火山之神的憤怒天譴。", "as": "Her father's wrath was terrifying whenever she broke curfew.", "at": "每次她違反門禁時,父親的震怒總是令人畏懼。"}, {"w": "ire", "p": "n.", "d": "Intense anger.", "c": "憤怒;怒火", "s": "The decision provoked the ire of local residents.", "t": "這項決定激起了當地居民的怒火。", "as": "He struggled to contain his ireduring the meeting.", "at": "他在這場會議上努力抑制自己的怒氣。"}, {"w": "livid", "p": "adj.", "d": "Pale (usually from anger).", "c": "狂怒的/鐵青的", "s": "She turned livid when she discovered he had lied to her.", "t": "當她發現他對她說謊時,她氣得臉色鐵青。", "as": "He was livid after finding his car had been towed.", "at": "發現自己的車被拖走後,他氣得暴跳如雷。"}, {"w": "exasperate", "p": "v.", "d": "To irritate, irk.", "c": "激怒/使惱火", "s": "The constant delays began to exasperate even the most patient passengers.", "t": "不斷的延誤開始激怒了即使最有耐心的乘客。", "as": "Her refusal to apologize only served to exasperate her coworkers further.", "at": "她拒絕道歉,只是讓她的同事們更加惱火。"}, {"w": "irascible", "p": "adj.", "d": "Irritable.", "c": "易怒的", "s": "The irascible old man yelled at the children for playing near his yard.", "t": "這位易怒的老人因孩子們在他院子附近玩耍而對他們大吼大叫。", "as": "His irascible temper made him difficult to work with.", "at": "他易怒的脾氣讓他很難與人共事。"}, {"w": "petulant", "p": "adj.", "d": "Easily irritated or annoyed.", "c": "任性易怒的/暴躁的", "s": "The petulant child threw his toy across the room when told it was bedtime.", "t": "被告知該睡覺時,這個任性的孩子把玩具扔到了房間另一頭。", "as": "Her petulant response to the minor criticism surprised her editor.", "at": "她對這個小小批評的暴躁反應讓她的編輯感到意外。"}, {"w": "peevish", "p": "adj.", "d": "Easily irritated, especially over trivial matters.", "c": "易怒的;暴躁的", "s": "The tired toddler grew peevisheduring the long car ride.", "t": "這個疲累的幼兒在這趟漫長的車程中變得易怒暴躁。", "as": "His peevish complaints about the weather annoyed everyone at the picnic.", "at": "他對天氣暴躁易怒的抱怨讓野餐上的每個人都感到厭煩。"}, {"w": "vex", "p": "v.", "d": "To annoy or worry someone; to cause distress.", "c": "使煩惱/使苦惱", "s": "The constant noise began to vex the students trying to concentrate.", "t": "不斷的噪音開始讓試圖專心的學生們感到煩躁。", "as": "It continues to vex him that he never got an apology.", "at": "他始終沒有得到一句道歉,這件事仍然讓他耿耿於懷。"}, {"w": "fury", "p": "n.", "d": "Wild or violent anger.", "c": "狂怒;暴怒", "s": "She could barely contain her fury at the betrayal.", "t": "她幾乎無法抑制對這場背叛的狂怒。", "as": "The storm struck the coast with tremendous fury .", "at": "這場暴風雨以驚人的猛烈力道襲擊了海岸。"}, {"w": "cranky", "p": "adj.", "d": "Irritable or easily annoyed.", "c": "易怒的;脾氣壞的", "s": "The baby gets cranky when he misses his nap.", "t": "這個嬰兒錯過午睡時間就會變得易怒。", "as": "Her cranky grandfather complained about everything.", "at": "她脾氣壞的祖父對任何事都抱怨連連。", "a": 1}, {"w": "testy", "p": "adj.", "d": "Easily irritated; impatient.", "c": "易怒的;暴躁的", "s": "He grew testy after being kept waiting for over an hour.", "t": "他被晾在一旁等了一個多小時之後便開始變得暴躁易怒。", "as": "The testy manager snapped at the intern over a minor mistake.", "at": "這位暴躁的經理因一個小失誤而對這位實習生發了脾氣。", "a": 1}, {"w": "grouchy", "p": "adj.", "d": "Irritable and bad-tempered.", "c": "脾氣暴躁的", "s": "He gets grouchy if he doesn't have his morning coffee.", "t": "他若沒喝到早晨的咖啡就會變得脾氣暴躁。", "as": "The grouchy old man yelled at the kids playing outside.", "at": "這位脾氣暴躁的老人對著在外面玩耍的孩子們大吼。", "a": 1}, {"w": "surly", "p": "adj.", "d": "Bad-tempered and unfriendly.", "c": "乖戾的;粗魯的", "s": "The surly clerk barely acknowledged the customers.", "t": "這位態度乖戾的店員幾乎不理會顧客。", "as": "He grew surly whenever anyone questioned his decisions.", "at": "每當有人質疑他的決定時,他就會變得粗魯不耐。", "a": 1}, {"w": "indignation", "p": "n.", "d": "Anger sparked by something unjust or unfair.", "c": "憤慨/義憤", "s": "Public indignation grew after the details of the scandal emerged.", "t": "隨著這起醜聞細節浮出檯面,公眾的憤慨情緒日益高漲。", "as": "She could barely contain her indignation at the unfair verdict.", "at": "面對這項不公的判決,她幾乎無法抑制心中的憤慨。", "a": 1}, {"w": "bristle", "p": "v./n.", "d": "To react with anger or indignation; a short, stiff hair.", "c": "生氣;豎毛;鬃毛", "s": "She began to bristle at the suggestion that her work was careless.", "t": "有人暗示她的工作粗心大意時,她開始感到憤慨。", "as": "The toothbrush's bristle had worn down after months of daily use.", "at": "這支牙刷的刷毛在每天使用了好幾個月後已經磨損。", "a": 1}]}, {"unit": 41, "theme": "Calm and Composure", "themeZh": "平靜與沉著", "antonymLessons": [40], "cards": [{"w": "serene", "p": "adj.", "d": "Calm, peaceful, and untroubled.", "c": "寧靜的/安詳的", "s": "The serene landscape provided the perfect setting for a quiet afternoon.", "t": "這片寧靜的景色為一個悠閒的午後提供了完美的場景。", "as": "Despite the chaos around her, she remained perfectly serene.", "at": "儘管周遭一片混亂,她依然保持完全的沉著寧靜。"}, {"w": "placid", "p": "adj.", "d": "Calm, peaceful.", "c": "平靜的/安詳的", "s": "The lake's placid surface reflected the mountains perfectly at dawn.", "t": "黎明時分,這座湖泊平靜的水面完美地映照出群山的倒影。", "as": "Despite the chaos around her, she remained remarkably placid.", "at": "儘管周遭一片混亂,她仍保持著驚人的平靜。"}, {"w": "tranquil", "p": "adj.", "d": "Calm, peaceful, and free from disturbance or anxiety.", "c": "平靜的；安寧的", "s": "The lake remained perfectly tranquil before the morning wind began.", "t": "晨風開始前，湖面保持完全平靜。", "as": "She moved to a tranquil village to escape the noise of the city.", "at": "她搬到安寧村莊，以逃離城市喧囂。"}, {"w": "composure", "p": "n.", "d": "Calmness of mind or manner.", "c": "鎮定;沉著", "s": "She regained her composure before stepping back onto the stage.", "t": "她重新恢復鎮定後,才再次走上舞台。", "as": "His unshakable composure under pressure earned him a reputation as an excellent negotiator.", "at": "他在壓力下堅定不移的沉著,讓他贏得了優秀談判者的名聲。"}, {"w": "equanimity", "p": "n.", "d": "Evenness of mind, composure.", "c": "平靜/鎮定", "s": "She faced the criticism with remarkable equanimity.", "t": "她以驚人的鎮定態度面對這些批評。", "as": "Despite the chaos around him, he maintained his equanimity.", "at": "儘管周遭一片混亂,他依然保持著平靜的心態。"}, {"w": "imperturbable", "p": "adj.", "d": "Calm, steady, serene.", "c": "鎮定的/冷靜的", "s": "Even during the crisis, the CEO remained imperturbable.", "t": "即使在這場危機當中,執行長依然保持鎮定自若。", "as": "Her imperturbable calm reassured the nervous passengers during the turbulence.", "at": "在遭遇亂流時,她那種泰然自若的鎮定安撫了緊張的乘客。"}, {"w": "sedate", "p": "adj.", "d": "Quiet, still, undisturbed, sober.", "c": "安詳的/莊重的", "s": "The doctor gave the patient a sedate to help him rest before surgery.", "t": "醫生給了病人一劑鎮靜劑,好讓他在手術前休息。", "as": "She led a sedate life in the quiet countryside.", "at": "她在寧靜的鄉間過著安詳平靜的生活。"}, {"w": "unruffled", "p": "adj.", "d": "Not disturbed or agitated; calm.", "c": "不慌亂的;鎮靜的", "s": "She stayed unruffled even as the presentation technology failed.", "t": "即使簡報的技術設備出了問題,她依然鎮定不慌。", "as": "His unrufflededemeanor reassured the anxious passengers during turbulence.", "at": "他鎮定自若的態度安撫了在亂流中焦慮不安的乘客。"}, {"w": "poise", "p": "n./v.", "d": "Graceful and composed behavior; to balance or hold steady.", "c": "沉著;優雅平衡", "s": "She handled the difficult question with remarkable poise .", "t": "她以驚人的沉著優雅應對了這個棘手的問題。", "as": "The dancer began to poise herself perfectly on one foot.", "at": "這位舞者開始以單腳完美地保持平衡。"}, {"w": "unperturbed", "p": "adj.", "d": "Not disturbed or agitated; calm.", "c": "不受干擾的;鎮靜的", "s": "She remained unperturbededespite the chaos unfolding around her.", "t": "儘管周圍一片混亂,她依然保持鎮靜。", "as": "The captain stayed unperturbed as the storm intensified.", "at": "隨著這場暴風雨加劇,這位船長依然鎮定自若。", "a": 1}, {"w": "composed", "p": "adj.", "d": "Calm and in control of one's emotions.", "c": "鎮定的;沉著的", "s": "Despite the chaos backstage, the performer remained perfectly composed.", "t": "儘管後台一片混亂,這位表演者依然保持著完美的鎮定。", "as": "She stayed remarkably composed while answering the reporters' aggressive questions.", "at": "面對記者咄咄逼人的提問,她依然表現得出奇地沉著。", "a": 1}, {"w": "peaceable", "p": "adj.", "d": "Inclined to avoid conflict; peaceful.", "c": "愛好和平的;平和的", "s": "The tribe was known for its peaceable relations with neighboring settlements.", "t": "這個部落以與鄰近聚落和平共處聞名。", "as": "He resolved the dispute in a calm, peaceable manner.", "at": "他以平和冷靜的方式解決了這場爭端。", "a": 1}, {"w": "self-possessed", "p": "adj.", "d": "Calm, confident, and in control of oneself.", "c": "鎮定自若的;沉著的", "s": "The young speaker seemed remarkably self-possessededespite her age.", "t": "這位年輕的講者儘管年紀輕輕,卻表現得異常鎮定自若。", "as": "He remained self-possessed throughout the tense cross-examination.", "at": "在這場緊張的交叉詰問中,他始終保持鎮定沉著。", "a": 1}, {"w": "repose", "p": "n.", "d": "State of rest.", "c": "休息/睡眠", "s": "After the long journey, she finally found a moment of repose by the fireplace.", "t": "經過漫長的旅程,她終於在壁爐旁找到片刻的休息。", "as": "The garden offered a peaceful place of repose away from the city's noise.", "at": "這座花園是遠離城市喧囂、寧靜休憩的地方。", "a": 1}]}, {"unit": 42, "theme": "Sadness and Gloom", "themeZh": "悲傷與憂鬱", "antonymLessons": [43], "cards": [{"w": "melancholy", "p": "adj.", "d": "A deep, persistent sadness or sorrow.", "c": "憂鬱的/悲傷的", "s": "The melancholy mood of the film left the audience reflecting on their own lives.", "t": "這部電影憂鬱的氛圍讓觀眾反思起自己的人生。", "as": "A melancholy silence fell over the room after the announcement.", "at": "宣布消息之後,房間裡籠罩著一片憂傷的寂靜。"}, {"w": "morose", "p": "adj.", "d": "Gloomy or sullen.", "c": "陰鬱的/悶悶不樂的", "s": "He grew increasingly morose after losing his job.", "t": "失業後,他變得越來越陰鬱悶悶不樂。", "as": "Her morose expression made it clear something was troubling her.", "at": "她陰沉的表情清楚顯示出有什麼事情正困擾著她。"}, {"w": "despondent", "p": "adj.", "d": "Feeling depressed, discouraged, hopeless.", "c": "沮喪的/絕望的", "s": "After losing the championship, the whole team felt despondent.", "t": "在輸掉冠軍賽後,整支球隊都感到十分沮喪。", "as": "He grew increasingly despondent as job rejection after job rejection arrived.", "at": "隨著一次又一次被拒絕求職,他變得越來越絕望。"}, {"w": "dejected", "p": "adj.", "d": "Sad and depressed; disheartened.", "c": "沮喪的;意氣消沉的", "s": "He looked dejected after losing the championship game.", "t": "他在輸掉冠軍賽後看起來十分沮喪。", "as": "Her dejected expression revealed her disappointment.", "at": "她意氣消沉的表情透露出失望之情。"}, {"w": "disconsolate", "p": "adj.", "d": "Unable to be comforted; deeply unhappy.", "c": "無法安慰的;悲傷絕望的", "s": "She was disconsolate after losing her beloved pet.", "t": "失去心愛的寵物後,她悲傷得無法安慰。", "as": "The disconsolate widow sat silently through the ceremony.", "at": "這位悲傷絕望的寡婦在整場儀式中靜默不語。"}, {"w": "doleful", "p": "adj.", "d": "Sad, melancholy.", "c": "悲哀的", "s": "The dog gave a doleful look as its owner walked out the door.", "t": "當主人走出門時,那隻狗露出悲哀的眼神。", "as": "She sang a doleful song about lost love.", "at": "她唱了一首關於失戀的悲哀歌曲。"}, {"w": "somber", "p": "adj.", "d": "Gloomy, sad.", "c": "憂鬱的/昏暗的", "s": "A somber mood fell over the room after the announcement.", "t": "宣布消息後,整個房間籠罩在一片憂鬱的氣氛中。", "as": "The funeral was held under a somber gray sky.", "at": "這場葬禮是在陰沉灰暗的天空下舉行的。"}, {"w": "woeful", "p": "adj.", "d": "Characterized by or expressing great sorrow; very bad.", "c": "悲哀的;糟糕透頂的", "s": "The team's woeful performance disappointed even their most loyal fans.", "t": "這支隊伍糟糕透頂的表現讓他們最忠實的球迷都感到失望。", "as": "He described his woeful tale of misfortune to anyone who would listen.", "at": "他向任何願意聆聽的人講述了自己悲慘的不幸遭遇。"}, {"w": "forlorn", "p": "adj.", "d": "Sad, pitiful, distressed.", "c": "孤苦伶仃的/絕望的", "s": "The abandoned puppy looked forlorn standing in the rain.", "t": "這隻被遺棄的小狗站在雨中,看起來十分可憐孤單。", "as": "She wandered the empty house with a forlorn expression.", "at": "她帶著絕望孤寂的表情在這棟空蕩蕩的房子裡遊蕩。"}, {"w": "lament", "p": "v.", "d": "To express grief or sorrow.", "c": "哀悼/悲嘆", "s": "He lament the loss of his childhood home after the storm.", "t": "在這場暴風雨過後,他為失去童年的家而哀嘆不已。", "as": "Fans continue to lament the cancellation of their favorite show.", "at": "粉絲們仍持續為他們最愛的節目遭到取消而感到惋惜。"}, {"w": "mournful", "p": "adj.", "d": "Feeling, expressing, or causing sorrow.", "c": "悲傷的;哀悼的", "s": "A mournful melody drifted from the old piano upstairs.", "t": "一段悲傷的旋律從樓上那台老鋼琴飄了下來。", "as": "Her mournful eyes revealed the grief she tried to hide.", "at": "她哀傷的眼神洩露了她試圖隱藏的悲痛。"}, {"w": "sullen", "p": "adj.", "d": "Grim, ill-humored.", "c": "慍怒的/沉悶的", "s": "The teenager gave a sullen shrug and left the room without a word.", "t": "這個青少年悶悶不樂地聳了聳肩,一言不發地離開了房間。", "as": "A sullen silence fell over the table after the argument.", "at": "爭吵過後,餐桌上陷入了一片陰沉的沉默。"}, {"w": "sorrowful", "p": "adj.", "d": "Feeling or showing deep sadness.", "c": "悲傷的;哀痛的", "s": "A sorrowful expression crossed her face as she read the letter.", "t": "她讀信時,臉上掠過一抹悲傷的神情。", "as": "The community gathered for a sorrowful memorial service.", "at": "這個社區聚集在一起,舉行了一場哀痛的追思會。", "a": 1}, {"w": "dismal", "p": "adj.", "d": "Depressing or gloomy.", "c": "陰鬱的;悲慘的", "s": "The team's performance this season has been dismal .", "t": "這支隊伍本季的表現一直很悲慘。", "as": "Rain fell steadily under a dismal gray sky.", "at": "雨在陰鬱灰暗的天空下持續下著。", "a": 1}, {"w": "gloomy", "p": "adj.", "d": "Dark or dismal; depressed in spirit.", "c": "陰暗的;憂鬱的", "s": "The gloomy weather matched her somber mood.", "t": "陰沉的天氣與她憂鬱的心情相符。", "as": "He offered a gloomy forecast for the company's future.", "at": "他對這家公司的未來提出了悲觀陰鬱的預測。", "a": 1}, {"w": "dreary", "p": "adj.", "d": "Dull, bleak, and depressing.", "c": "沉悶的;陰鬱的", "s": "The dreary weather kept everyone indoors all weekend.", "t": "陰鬱的天氣讓大家整個週末都待在室內。", "as": "He described his job as dreary and repetitive.", "at": "他形容自己的工作沉悶又一成不變。", "a": 1}, {"w": "cheerless", "p": "adj.", "d": "Gloomy; lacking joy or warmth.", "c": "陰鬱的;毫無生氣的", "s": "The abandoned factory stood cheerless against the gray winter sky.", "t": "這座廢棄的工廠在灰暗的冬日天空下顯得毫無生氣。", "as": "Her cheerless office lacked even a single window or plant.", "at": "她那間陰鬱的辦公室,連一扇窗戶或一盆植物都沒有。", "a": 1}, {"w": "plaintive", "p": "adj.", "d": "Expressing sadness or sorrow.", "c": "哀傷的;悲切的", "s": "A plaintive melody drifted from the violin in the empty hall.", "t": "一段哀傷的旋律從這座空蕩大廳裡的小提琴聲中飄出。", "as": "The child's plaintive cries brought her mother running.", "at": "這個孩子悲切的哭聲讓她的母親立刻跑了過來。", "a": 1}, {"w": "miserable", "p": "adj.", "d": "Extremely unhappy or uncomfortable.", "c": "悲慘的;痛苦的", "s": "He felt miserable after losing his job so suddenly.", "t": "他在突然失業之後感到十分痛苦。", "as": "The hikers were miserable in the freezing rain.", "at": "這群健行者在冰冷的雨中感到十分悲慘。", "a": 1}, {"w": "grievous", "p": "adj.", "d": "Injurious, hurtful; serious or grave in nature.", "c": "嚴重的/悲痛的", "s": "The accident left the driver with grievous injuries.", "t": "這場事故讓這名駕駛遭受嚴重的傷害。", "as": "Betraying her closest friend was a grievous mistake she regretted for years.", "at": "背叛她最親密的朋友是個她懊悔多年的嚴重錯誤。", "a": 1}, {"w": "anguish", "p": "n.", "d": "Extreme sadness, torment.", "c": "極度痛苦/苦惱", "s": "She was filled with anguish after hearing the tragic news.", "t": "聽到這則悲慘的消息後,她心中充滿了極度的痛苦。", "as": "His face showed the anguish of a man who had lost everything.", "at": "他臉上流露出一個失去一切的人所承受的痛苦。", "a": 1}, {"w": "pensive", "p": "adj.", "d": "Thoughtful, reflective.", "c": "沉思的/憂鬱的", "s": "He sat by the window, looking pensive and distant.", "t": "他坐在窗邊,神情沉思、若有所思。", "as": "She wore a pensive expression as she reread the old letter.", "at": "重讀那封舊信時,她臉上流露出沉思的表情。", "a": 1}]}, {"unit": 43, "theme": "Joy and Cheerfulness", "themeZh": "喜悅與開朗", "antonymLessons": [42], "cards": [{"w": "elated", "p": "adj.", "d": "Overjoyed, thrilled.", "c": "興高采烈的/欣喜的", "s": "She felt elated after finally passing her driving test.", "t": "終於通過駕照考試後,她感到欣喜若狂。", "as": "The whole family was elated when they heard the good news.", "at": "全家人聽到這個好消息時都興高采烈。"}, {"w": "jubilant", "p": "adj.", "d": "Joyful, in high spirits.", "c": "歡呼的/喜悅的", "s": "The jubilant crowd cheered as the team lifted the trophy.", "t": "當球隊高舉獎盃時,興高采烈的群眾歡呼了起來。", "as": "She felt jubilant after receiving her acceptance letter.", "at": "收到錄取通知後,她感到欣喜若狂。"}, {"w": "euphoric", "p": "adj.", "d": "Elated, uplifted.", "c": "興高采烈的/狂喜的", "s": "The team felt euphoric after winning the championship for the first time.", "t": "首次奪冠讓這支球隊感到欣喜若狂。", "as": "She was euphoric when she opened the acceptance letter.", "at": "打開這封錄取通知信時,她感到興高采烈。"}, {"w": "blithe", "p": "adj.", "d": "Cheerful and carefree, often to the point of thoughtlessness.", "c": "無憂無慮的;輕率的", "s": "His blithedisregard for the deadline frustrated the entire team.", "t": "他對截止日期輕率的漠視,讓整個團隊都感到沮喪。", "as": "She approached the difficult exam with surprisingly blithe confidence.", "at": "她以出乎意料的輕鬆自信,面對這場艱難的考試。"}, {"w": "buoyant", "p": "adj.", "d": "Able to float; cheerful and optimistic.", "c": "有浮力的;樂觀的", "s": "The life jacket kept even the heaviest swimmer buoyant in the water.", "t": "這件救生衣讓即使是體重最重的游泳者也能浮在水面上。", "as": "Despite the setback, she remained buoyant about the project's future.", "at": "儘管遭遇挫折,她對這項計畫的未來仍保持樂觀。"}, {"w": "jovial", "p": "adj.", "d": "Cheerful and friendly.", "c": "快樂的;和藹可親的", "s": "The jovial host welcomed every guest with a warm smile.", "t": "這位和藹可親的主人以溫暖的笑容迎接每位賓客。", "as": "His jovial laugh could be heard across the room.", "at": "他快樂爽朗的笑聲整個房間都聽得到。"}, {"w": "gleeful", "p": "adj.", "d": "Feeling or showing great delight.", "c": "欣喜的;興高采烈的", "s": "The children let out a gleeful shout upon seeing the snow.", "t": "看到雪的時候,孩子們發出了欣喜的歡呼聲。", "as": "She wore a gleeful expression after winning the contest.", "at": "贏得比賽後,她臉上露出了興高采烈的表情。"}, {"w": "exuberant", "p": "adj.", "d": "Overflowing with vitality and good spirits.", "c": "熱情奔放的", "s": "The children were exuberant after their first day at the amusement park.", "t": "在遊樂園玩了第一天後,孩子們興奮得活力四射。", "as": "Her exuberant enthusiasm for the project inspired the entire team.", "at": "她對這項計畫熱情奔放的投入激勵了整個團隊。"}, {"w": "sanguine", "p": "adj.", "d": "Optimistic.", "c": "樂觀的/紅潤的", "s": "Despite the bad news, she remained sanguine about the company's future.", "t": "儘管消息不好,她對公司的未來依然保持樂觀。", "as": "He gave a sanguine prediction that sales would double next year.", "at": "他樂觀地預測明年銷售額將翻倍。"}, {"w": "ecstatic", "p": "adj.", "d": "Intensely and overpoweringly happy.", "c": "狂喜的/欣喜若狂的", "s": "She was ecstatic when she learned she had been accepted into her dream school.", "t": "得知自己被夢想中的學校錄取時,她欣喜若狂。", "as": "The fans grew ecstatic as their team scored the winning goal.", "at": "當他們支持的球隊踢進致勝球時,球迷們陷入狂喜。"}, {"w": "merry", "p": "adj.", "d": "Cheerful and lighthearted.", "c": "歡樂的;愉快的", "s": "The children sang merry songs around the holiday tree.", "t": "孩子們圍著這棵節慶樹唱著歡樂的歌曲。", "as": "Their merry laughter echoed throughout the old house.", "at": "他們歡樂的笑聲迴盪在這棟老房子裡。", "a": 1}, {"w": "mirthful", "p": "adj.", "d": "Full of joy and laughter.", "c": "歡樂的;愉悅的", "s": "The room filled with mirthful laughter during the reunion.", "t": "在這場團聚中,整個房間都充滿了歡樂的笑聲。", "as": "Her mirthful spirit lifted everyone's mood at the party.", "at": "她愉悅歡樂的精神提振了派對上每個人的心情。", "a": 1}, {"w": "jaunty", "p": "adj.", "d": "Sprightly.", "c": "輕鬆活潑的", "s": "He walked down the street with a jaunty step, whistling a tune.", "t": "他邁著輕快活潑的步伐走在街上,吹著口哨。", "as": "She wore a jaunty hat tilted slightly to one side.", "at": "她戴著一頂略微歪斜、看起來輕鬆俏皮的帽子。", "a": 1}, {"w": "cheerful", "p": "adj.", "d": "Noticeably happy and optimistic.", "c": "開朗的;愉快的", "s": "Her cheerful attitude made even the longest shifts feel bearable.", "t": "她開朗的態度,讓即使是最漫長的班次也變得可以忍受。", "as": "He greeted every customer with a cheerful smile, no matter how his day was going.", "at": "無論那天過得如何,他都以開朗的笑容迎接每一位顧客。", "a": 1}, {"w": "delight", "p": "n./v.", "d": "Great pleasure; to please greatly.", "c": "喜悅;使愉快", "s": "The children squealed with delight at the surprise party.", "t": "孩子們在驚喜派對上開心地尖叫。", "as": "The magician's tricks delight ed the audience.", "at": "魔術師的把戲讓觀眾大為愉悅。", "a": 1}, {"w": "bliss", "p": "n.", "d": "Happiness, pleasure.", "c": "極樂/狂喜", "s": "Sitting by the fire with a good book was pure bliss to her.", "t": "坐在爐火邊看一本好書,對她來說是純粹的幸福。", "as": "The couple's wedding day was filled with bliss.", "at": "這對新人的婚禮當天充滿了幸福快樂。", "a": 1}, {"w": "felicity", "p": "n.", "d": "Intense happiness; a pleasing manner of expression.", "c": "幸福;巧妙", "s": "The couple wished each other a lifetime of felicity .", "t": "這對新人互相祝福能擁有一生的幸福。", "as": "The author writes with remarkable felicity of phrase.", "at": "這位作者的措辭運用得極為巧妙。", "a": 1}, {"w": "optimistic", "p": "adj.", "d": "Hopeful and confident about the future.", "c": "樂觀的", "s": "Despite the setback, she remained optimistic about her recovery.", "t": "儘管遭遇挫折,她對自己的康復仍保持樂觀。", "as": "Analysts gave an optimistic forecast for next year's economy.", "at": "分析師對明年的經濟給出了樂觀的預測。", "a": 1}]}, {"unit": 44, "theme": "Increase and Growth", "themeZh": "增加與成長", "antonymLessons": [45], "cards": [{"w": "augment", "p": "v.", "d": "To make something greater by adding to it; increase.", "c": "增加；擴充", "s": "The company hired seasonal workers to augment its regular workforce during the peak holiday shopping period.", "t": "該公司雇用季節性員工，以在購物高峰期「擴充（增加）」其正規勞動力。", "as": "", "at": ""}, {"w": "amplify", "p": "v.", "d": "To increase the volume or intensity of something.", "c": "放大/增強", "s": "The speaker amplify his voice to address the large crowd.", "t": "這位講者提高音量,以便向這一大群聽眾發言。", "as": "The microphone will amplify your voice so everyone can hear.", "at": "這支麥克風會放大你的聲音,讓每個人都能聽見。"}, {"w": "swell", "p": "v./n.", "d": "To increase in size or intensity; a large wave.", "c": "膨脹;湧起;巨浪", "s": "Her ankle began to swell after the fall.", "t": "她跌倒後,腳踝開始腫脹起來。", "as": "Surfers waited eagerly for the next swell to arrive.", "at": "衝浪者們熱切地等待著下一波巨浪的到來。"}, {"w": "magnify", "p": "v.", "d": "To make something appear larger than it is; to exaggerate.", "c": "放大;誇大", "s": "The lens can magnify objects up to a hundred times.", "t": "這片鏡片能將物體放大到一百倍。", "as": "He tended to magnify minor problems into major crises.", "at": "他傾向於把小問題誇大成重大危機。"}, {"w": "flourish", "p": "v.", "d": "To grow or develop in a healthy, vigorous, or successful way.", "c": "繁榮；茁壯成長", "s": "Small businesses can flourish in local neighborhoods when municipal governments reduce burdensome tax requirements.", "t": "當地方政府減少沉重的稅收要求時，小型企業就能在當地社區「繁榮（茁壯）發展」。", "as": "", "at": ""}, {"w": "wax", "p": "v./n.", "d": "To increase gradually, as the moon does; a substance used for polishing.", "c": "漸增;蠟", "s": "The moon will wax over the coming week until it becomes full.", "t": "接下來這一週,月亮將逐漸盈滿,直到成為滿月。", "as": "He applied a fresh coat of wax to protect the car's finish.", "at": "他為這輛車的烤漆塗上一層新的蠟,以保護車身。"}, {"w": "increase", "p": "v.", "d": "To become larger or more.", "c": "增加", "s": "Regular exercise can increase your energy levels and improve your overall mood.", "t": "規律運動可以增加你的活力並改善整體心情。", "as": "", "at": "", "a": 1}, {"w": "inflate", "p": "v.", "d": "To fill with air or gas; to exaggerate.", "c": "充氣;誇大", "s": "Please inflate the tires before the long drive.", "t": "長途開車前請把輪胎充氣。", "as": "He tended to inflate his own accomplishments during interviews.", "at": "他在面試中往往會誇大自己的成就。", "a": 1}, {"w": "intensify", "p": "v.", "d": "To become or make more intense.", "c": "加劇;強化", "s": "The conflict began to intensify after the failed negotiations.", "t": "談判失敗後,這場衝突開始加劇。", "as": "Rescuers worked to intensify their search efforts before nightfall.", "at": "救援人員在天黑前努力加強搜索行動。", "a": 1}, {"w": "enhance", "p": "v.", "d": "To intensify, heighten.", "c": "提高/增強", "s": "Regular exercise can enhance both your physical and mental health.", "t": "規律運動能夠提升你的身心健康。", "as": "The new lighting was added to enhance the beauty of the garden at night.", "at": "增設新的燈光是為了在夜晚增添花園的美感。", "a": 1}, {"w": "extend", "p": "v.", "d": "To make something longer or larger; to offer.", "c": "延伸;延長;給予", "s": "The city voted to extend the subway line further north.", "t": "這座城市投票決定將地鐵線向北延伸。", "as": "She decided to extend an invitation to her old rival.", "at": "她決定向她昔日的對手發出邀請。", "a": 1}, {"w": "grow", "p": "v.", "d": "To increase in size or develop over time.", "c": "成長;生長", "s": "The company plans to grow its market share overseas.", "t": "這家公司計畫擴大其在海外的市場占有率。", "as": "Sunflowers grow quickly in warm, sunny weather.", "at": "向日葵在溫暖陽光充足的天氣下生長迅速。", "a": 1}, {"w": "accelerate", "p": "v.", "d": "To begin to move more quickly.", "c": "加速", "s": "The tech company decided to massively accelerate its research and development timeline to beat their main competitor to market. Employees were asked to work overtime to finish the prototype months ahead of schedule.", "t": "這家科技公司決定大幅加速其研發時間表，以擊敗主要競爭對手搶先上市。員工被要求加班，以便提前幾個月完成原型。", "as": "", "at": "", "a": 1}, {"w": "surge", "p": "v.", "d": "To rush suddenly.", "c": "湧動", "s": "Crowds began to surge toward the exits when the fire alarm went off.", "t": "當火災警報響起時,人群開始朝出口湧去。", "as": "Electricity prices surgeduring the summer heat wave.", "at": "電價在夏季熱浪期間急遽飆升。", "a": 1}]}, {"unit": 45, "theme": "Decrease and Decline", "themeZh": "減少與衰退", "antonymLessons": [44], "cards": [{"w": "dwindle", "p": "v.", "d": "To become gradually smaller or less.", "c": "逐漸減少;萎縮", "s": "The company's profits began to dwindleduring the recession.", "t": "在這場經濟衰退期間,這家公司的利潤開始逐漸減少。", "as": "Their savings dwindled after years of medical bills.", "at": "多年的醫療費用讓他們的積蓄逐漸萎縮。"}, {"w": "abate", "p": "v.", "d": "To become less active, intense, or great.", "c": "減弱/緩和", "s": "As I began my speech, my feelings of nervousness quickly abate.", "t": "我開始演講時,緊張的情緒很快就減弱消退了。", "as": "The storm is expected to abate by early morning.", "at": "預計這場暴風雨將在清晨前逐漸減弱。"}, {"w": "wane", "p": "n.", "d": "Decrease, decline.", "c": "衰退/減弱", "s": "Public interest in the fad began to wane after a few months.", "t": "幾個月後,大眾對這股風潮的興趣開始逐漸消退。", "as": "The moon will wane over the next two weeks.", "at": "接下來兩週,月亮將逐漸虧缺。"}, {"w": "diminish", "p": "v.", "d": "To decrease in size or importance.", "c": "減少/削弱", "s": "The politician's influence has diminish over time.", "t": "這位政治人物的影響力隨著時間逐漸削弱。", "as": "Nothing could diminish her enthusiasm for the project.", "at": "沒有任何事能削減她對這項計畫的熱情。"}, {"w": "ebb", "p": "v./n.", "d": "To gradually decrease; the outward flow of the tide.", "c": "衰退;退潮", "s": "His enthusiasm began to ebb after months of setbacks.", "t": "經過數月的挫折,他的熱情開始逐漸消退。", "as": "The boats waited for the ebb before setting sail.", "at": "這些船隻等待退潮後才啟航。"}, {"w": "subside", "p": "v.", "d": "To become less intense or violent; to sink to a lower level.", "c": "平息;沉降", "s": "The storm began to subside after several hours.", "t": "這場暴風雨經過數小時後開始平息。", "as": "Her anger gradually began to subside as she calmed down.", "at": "隨著她逐漸冷靜下來,她的怒氣也漸漸平息了。"}, {"w": "curtail", "p": "v.", "d": "To reduce in extent or quantity; impose a restriction on.", "c": "縮減；限制", "s": "In response to rising inflation, the municipal council voted to curtail non-essential capital expenditure projects.", "t": "因應通膨上升，市議會投票通過「縮減」非必要的資本支出項目。", "as": "", "at": ""}, {"w": "deplete", "p": "v.", "d": "To use up the supply or resources of something.", "c": "耗盡;使枯竭", "s": "The drought began to deplete the region's water reserves.", "t": "這場乾旱開始使該地區的水資源逐漸枯竭。", "as": "Overfishing has depleted the local fish population.", "at": "過度捕撈已使當地魚群數量耗盡。"}, {"w": "decrease", "p": "v./n.", "d": "To become or make smaller in size or amount.", "c": "減少", "s": "Sales began to decrease after the holiday season ended.", "t": "假期季結束後,銷售量開始減少。", "as": "The report showed a steady decrease in crime rates.", "at": "這份報告顯示犯罪率持續穩定下降。", "a": 1}, {"w": "decline", "p": "v./n.", "d": "To refuse politely; to gradually decrease.", "c": "婉拒;衰退", "s": "She had to decline the invitation due to a scheduling conflict.", "t": "由於行程衝突,她不得不婉拒這個邀請。", "as": "The industry saw a sharp decline over the past decade.", "at": "這個產業在過去十年間急遽衰退。", "a": 1}, {"w": "depreciate", "p": "v.", "d": "To diminish in value over time.", "c": "貶值;跌價", "s": "New cars depreciate quickly within the first year.", "t": "新車在第一年內會迅速貶值。", "as": "The currency began to depreciate against the dollar.", "at": "這種貨幣開始對美元貶值。", "a": 1}, {"w": "wither", "p": "v.", "d": "To become dry and shriveled, especially from lack of water.", "c": "枯萎;凋謝", "s": "The flowers began to wither after just a few days without water.", "t": "這些花朵僅僅幾天沒有澆水便開始枯萎了。", "as": "His enthusiasm for the project began to wither after repeated setbacks.", "at": "他對這項計畫的熱情在歷經多次挫折後開始逐漸消退。", "a": 1}, {"w": "flag", "p": "n./v.", "d": "A piece of cloth used as a symbol; to become tired or weak.", "c": "旗幟;變得疲憊", "s": "The flag waved proudly above the town hall.", "t": "這面旗幟在市政廳上方驕傲地飄揚著。", "as": "His energy began to flag toward the end of the marathon.", "at": "在馬拉松接近尾聲時,他的體力開始逐漸衰退。", "a": 1}, {"w": "slacken", "p": "v.", "d": "To become or make less active, tight, or fast.", "c": "放鬆;減緩", "s": "The captain ordered the crew to slacken the sails before the storm hit.", "t": "船長下令船員在暴風雨來襲前放鬆帆索。", "as": "Sales began to slacken once the holiday season ended.", "at": "節慶季節結束後,銷售額開始逐漸減緩。", "a": 1}]}, {"unit": 46, "theme": "Strengthen and Support", "themeZh": "加強與支持", "antonymLessons": [47], "cards": [{"w": "bolster", "p": "v.", "d": "To support, strengthen, or reinforce.", "c": "支持；鼓勵；增強", "s": "The government announced new tax incentives to bolster small business recovery following the economic downturn.", "t": "政府宣布了新的稅收優惠政策，以在經濟不景氣後「增強（支持）」小企業的復甦。", "as": "", "at": ""}, {"w": "buttress", "p": "v./n.", "d": "To strengthen, support, or reinforce an argument or structure.", "c": "支持；加強；支撐", "s": "The defense attorney presented sworn expert witness testimonies to buttress her client's alibi during the trial.", "t": "辯護律師提出了經過宣誓的專家證人證言，以「加強（支持）」其當事人在審判期間的缺席證明。", "as": "", "at": ""}, {"w": "fortify", "p": "v.", "d": "To strengthen a place against attack; to strengthen mentally or physically.", "c": "強化;加固", "s": "Engineers worked to fortify the levee before the flood.", "t": "工程師在洪水來臨前努力加固這座堤防。", "as": "A good breakfast can fortify you for a long day.", "at": "一頓豐盛的早餐能為漫長的一天強化體力。"}, {"w": "corroborate", "p": "v.", "d": "To confirm, support.", "c": "證實/確證", "s": "Two independent witnesses were able to corroborate her account of the accident.", "t": "兩名獨立目擊者能夠證實她對這場意外的描述。", "as": "New evidence has emerged to corroborate the scientist's original theory.", "at": "新的證據出現,證實了這位科學家最初的理論。"}, {"w": "substantiate", "p": "v.", "d": "To provide evidence to support or prove the truth of.", "c": "證實；證明", "s": "The researcher gathered historical documents and statistical evidence to substantiate her hypothesis about economic cycles.", "t": "研究人員收集了歷史文獻和統計數據，以「證實（證明）」她關於經濟週期的假設。", "as": "", "at": ""}, {"w": "invigorate", "p": "v.", "d": "To give strength or energy to.", "c": "使充滿活力;振奮", "s": "A cold shower can invigorate you first thing in the morning.", "t": "一場冷水澡能在早晨第一時間讓你精神振奮。", "as": "The team's win seemed to invigorate the entire town.", "at": "這支隊伍的勝利似乎讓整座小鎮充滿了活力。"}, {"w": "galvanize", "p": "v.", "d": "To shock or inspire someone into taking action, or to coat metal with protective zinc.", "c": "激勵；促使採取行動；電鍍；鍍鋅", "s": "The environmental disaster served to galvanize the community, shocking residents out of apathy and driving them to demand strict safety laws.", "t": "這場環境災難激起地方社群，使居民擺脫冷漠並要求制定嚴格安全法規。", "as": "The coach delivered an impassioned speech designed to galvanize his exhausted team before the final quarter of the championship game.", "at": "教練發表慷慨激昂的演說，旨在冠軍賽最後一節前激勵精疲力竭的球隊。"}, {"w": "affirm", "p": "v.", "d": "To state as a fact; to declare strongly.", "c": "肯定/確認", "s": "The witness affirm that she saw the suspect at the scene.", "t": "這名證人確認她曾在現場看見嫌疑人。", "as": "The court decided to affirm the lower court's ruling.", "at": "法院決定維持下級法院的判決。", "a": 1}, {"w": "validate", "p": "v.", "d": "To confirm or verify as being true, accurate, or acceptable.", "c": "證實/驗證", "s": "The results were validate by an independent review panel before publication.", "t": "這些結果在發表前經過一個獨立審查小組的驗證。", "as": "The test results validate his hypothesis.", "at": "這些測試結果證實了他的假設。", "a": 1}, {"w": "verify", "p": "v.", "d": "To confirm the truth or accuracy of something.", "c": "核實;驗證", "s": "The editor asked the reporter to verify every fact before publishing.", "t": "這位編輯要求這名記者在發表前核實每一項事實。", "as": "Officials worked to verify the identity of the recovered remains.", "at": "官員們努力核實這些尋獲遺骸的身分。", "a": 1}, {"w": "authenticate", "p": "v.", "d": "To prove or confirm something is genuine.", "c": "證明真實性;鑑定", "s": "Experts were called in to authenticate the signature on the historical document.", "t": "專家被請來鑑定這份歷史文件上簽名的真偽。", "as": "The app uses a fingerprint scan to authenticate each user.", "at": "這款應用程式透過指紋掃描來驗證每位使用者的身分。", "a": 1}, {"w": "attest", "p": "v.", "d": "To certify.", "c": "證明/證實", "s": "Several employees can attest to his honesty and hard work.", "t": "幾位員工都能證明他的誠實與努力。", "as": "The document was signed by a notary to attest its authenticity.", "at": "這份文件由公證人簽署以證實其真實性。", "a": 1}, {"w": "certify", "p": "v.", "d": "To formally confirm or attest to something.", "c": "證明;認證", "s": "The inspector had to certify that the building met all fire safety codes.", "t": "檢查員必須證明這棟建築符合所有消防安全規範。", "as": "A licensed electrician must certify the wiring before the house can be sold.", "at": "在房子出售前,必須由合格的電工認證電線配置。", "a": 1}, {"w": "vindicate", "p": "v.", "d": "To absolve, justify.", "c": "證明清白/維護", "s": "New evidence eventually vindicated him of the crime.", "t": "新證據最終證明了他的清白。", "as": "Her decision to leave the company was vindicated when it went bankrupt.", "at": "當這家公司破產時,她離職的決定得到了證明是對的。", "a": 1}]}, {"unit": 47, "theme": "Weaken and Undermine", "themeZh": "削弱與破壞", "antonymLessons": [46], "cards": [{"w": "undermine", "p": "v.", "d": "To weaken or damage something gradually or covertly.", "c": "逐漸削弱/暗中破壞", "s": "The constant criticism undermine her confidence.", "t": "不斷的批評逐漸削弱了她的自信心。", "as": "Leaking the plan to the press could undermine the entire negotiation.", "at": "把這項計畫洩漏給媒體可能會破壞整場談判。"}, {"w": "enervate", "p": "v.", "d": "To weaken, exhaust.", "c": "使衰弱/使無力", "s": "The tropical heat began to enervate even the most seasoned travelers.", "t": "熱帶酷暑逐漸讓即使最有經驗的旅行者也感到疲憊無力。", "as": "Years of overwork had left him thoroughly enervated.", "at": "多年的過度工作讓他徹底精疲力竭。"}, {"w": "debilitate", "p": "v.", "d": "To weaken.", "c": "使衰弱", "s": "The chronic illness continued to debilitate her over the years.", "t": "這種慢性疾病多年來持續讓她的身體日漸衰弱。", "as": "Years of drought have debilitated the region's farming industry.", "at": "多年的乾旱已使這個地區的農業日漸衰弱。"}, {"w": "sap", "p": "n.", "d": "A watery fluid that circulates in a plant.", "c": "樹液", "s": "Maple sap is collected each spring to make syrup.", "t": "每年春天都會採集楓樹的樹液來製作糖漿。", "as": "The tree's sticky sap coated the bark near the fresh cut.", "at": "這棵樹黏稠的樹液覆蓋在新切口附近的樹皮上。"}, {"w": "enfeeble", "p": "v.", "d": "To make weak or feeble.", "c": "使衰弱;削弱", "s": "Years of illness began to enfeeble him.", "t": "多年的疾病開始使他日漸衰弱。", "as": "The scandal enfeebled the once-powerful institution.", "at": "這場醜聞削弱了這個曾經強大的機構。"}, {"w": "impair", "p": "v.", "d": "To weaken or damage the function of something.", "c": "損害;削弱", "s": "Lack of sleep can impair concentration and memory.", "t": "缺乏睡眠可能會損害專注力與記憶力。", "as": "The accident permanently impair ed his vision.", "at": "這場意外永久損害了他的視力。"}, {"w": "subvert", "p": "v.", "d": "To undermine or overthrow the power or authority of.", "c": "顛覆;破壞", "s": "The spies worked secretly to subvert the government from within.", "t": "這些間諜暗中運作,企圖從內部顛覆這個政府。", "as": "Critics argued the policy would subvert the very rights it claimed to protect.", "at": "評論家主張這項政策會破壞它聲稱要保護的權利本身。"}, {"w": "mar", "p": "v.", "d": "To damage or spoil the appearance or perfection of.", "c": "損壞;玷污", "s": "A single scratch began to mar the otherwise flawless painting.", "t": "一道刮痕開始破壞了這幅原本完美無瑕的畫作。", "as": "The scandal would mar his reputation for years to come.", "at": "這場醜聞將在往後多年損害他的名聲。", "a": 1}, {"w": "exhaust", "p": "v./n.", "d": "To use up completely; the fumes from an engine.", "c": "耗盡;排氣", "s": "The team continued until they had exhaust ed every option.", "t": "這支團隊持續嘗試,直到用盡了每一個選項。", "as": "Black smoke poured from the truck's exhaust pipe.", "at": "黑煙從這輛卡車的排氣管中冒出。", "a": 1}]}, {"unit": 48, "theme": "Clear and Obvious", "themeZh": "清楚與明顯", "antonymLessons": [49], "cards": [{"w": "lucid", "p": "adj.", "d": "Clear, easily understandable.", "c": "清晰的/明晰的", "s": "Her lucid explanation made the difficult concept easy to grasp.", "t": "她清晰的解釋讓這個困難的概念變得容易理解。", "as": "Despite his illness, the old man remained remarkably lucid until the end.", "at": "儘管身患疾病,這位老人直到最後都保持著驚人的清醒神智。"}, {"w": "manifest", "p": "adj. / v.", "d": "Clear or obvious to the eye or mind; to display or show.", "c": "明顯的；顯現；證實", "s": "The artist's rejection of industrial mass production was manifest in his careful reliance on medieval handcrafted binding techniques.", "t": "這位藝術家對工業化量產的反感，在其對中世紀手工裝訂技術的用心依賴中「顯現（表現得很明顯）」。", "as": "", "at": ""}, {"w": "patent", "p": "adj.", "d": "Readily seen or understood, clear.", "c": "明顯的/顯而易見的", "s": "It was patent from her expression that she disagreed with the plan.", "t": "從她的表情就能明顯看出她不贊同這項計畫。", "as": "The judge called the contract's unfair terms patently obvious.", "at": "法官指出這份合約中不公平的條款顯而易見。"}, {"w": "palpable", "p": "adj.", "d": "Able to be touched or felt; tangible; clear to the mind or senses.", "c": "明顯的/可感知的", "s": "The tension in the room was palpable as everyone awaited the decision.", "t": "在大家等待決定的過程中,房間裡的緊張氣氛清晰可感。", "as": "There was a palpable sense of relief once the exam ended.", "at": "考試結束後,大家都感受到一股明顯的如釋重負感。"}, {"w": "overt", "p": "adj.", "d": "Open:obvious.", "c": "公開的/明顯的", "s": "There was no overt sign of conflict, but tension filled the room.", "t": "雖然沒有公開的衝突跡象,但房間裡瀰漫著緊張氣氛。", "as": "The company faced overt criticism for its handling of the scandal.", "at": "這家公司因處理醜聞的方式而面臨公開的批評。"}, {"w": "unequivocal", "p": "adj.", "d": "Leaving no doubt; clear and unambiguous.", "c": "明確的/毫不含糊的", "s": "His response was unequivocal, leaving no room for misinterpretation.", "t": "他的回應非常明確,絲毫不留誤解的餘地。", "as": "The board gave an unequivocal endorsement of the new CEO.", "at": "董事會對這位新任執行長給予了明確無疑的支持。"}, {"w": "evident", "p": "adj.", "d": "Clearly seen or understood; obvious.", "c": "明顯的;顯而易見的", "s": "It was evident from her smile that she was pleased.", "t": "從她的笑容明顯可以看出她很高興。", "as": "The damage to the roof was immediately evident .", "at": "屋頂的損壞立刻就顯而易見。"}, {"w": "conspicuous", "p": "adj.", "d": "Standing out so as to be clearly visible; noticeable.", "c": "顯眼的；引人注目的", "s": "Her bright yellow jacket made her highly conspicuous among the crowd of commuters dressed in dark winter coats.", "t": "她鮮豔的黃色夾克使她在身穿深色冬季大衣的通勤人群中非常「顯眼（引人注目）」。", "as": "", "at": ""}, {"w": "salient", "p": "adj.", "d": "Important, prominent.", "c": "顯著的", "s": "The professor summarized the most salient points of the lecture.", "t": "教授總結了這場演講中最顯著的重點。", "as": "One salient feature of the new phone is its incredibly long battery life.", "at": "這款新手機一項顯著的特色就是電池續航力極長。"}, {"w": "blatant", "p": "adj.", "d": "Obvious, very showy:flagrant.", "c": "明目張膽的", "s": "The referee ignored the player's blatant foul.", "t": "裁判無視了那名球員明目張膽的犯規。", "as": "It was a blatant lie, and everyone in the room knew it.", "at": "那是一個明目張膽的謊言,房間裡的每個人都心知肚明。"}, {"w": "obvious", "p": "adj.", "d": "Easily seen, recognized, or understood.", "c": "明顯的;顯而易見的", "s": "It was obvious from her expression that she disagreed.", "t": "從她的表情就能明顯看出她不同意。", "as": "The solution to the puzzle turned out to be surprisingly obvious .", "at": "這道謎題的解答結果出乎意料地顯而易見。", "a": 1}, {"w": "unmistakable", "p": "adj.", "d": "Clearly recognizable.", "c": "明確無誤的/顯而易見的", "s": "Morgan Freeman's voice is unmistakable.", "t": "摩根·費里曼的嗓音是絕不會認錯的。", "as": "There was an unmistakable smell of smoke coming from the kitchen.", "at": "廚房傳來一股明顯無誤的煙味。", "a": 1}, {"w": "apparent", "p": "adj.", "d": "Clearly visible or understood; seeming real but not necessarily so.", "c": "明顯的;表面上的", "s": "It was immediately apparent that the machine needed repair.", "t": "很明顯地,這台機器需要維修。", "as": "Her apparent calm hid a great deal of inner anxiety.", "at": "她表面上的鎮定,掩藏著內心極大的焦慮。", "a": 1}, {"w": "glaring", "p": "adj.", "d": "Extremely obvious or conspicuous.", "c": "顯而易見的/刺眼的", "s": "The glaring mistake on the report was impossible to overlook.", "t": "報告中那個顯而易見的錯誤讓人不可能忽略。", "as": "There is a glaring inconsistency between his two statements.", "at": "他前後兩次的說法之間存在著明顯的矛盾。", "a": 1}, {"w": "distinct", "p": "adj.", "d": "Clearly different or separate.", "c": "截然不同的/獨特的", "s": "My twin sons have distinct personalities.", "t": "我的雙胞胎兒子有著截然不同的個性。", "as": "Each region of the country has its own distinctedialect.", "at": "這個國家的每個地區都有自己獨特的方言。", "a": 1}, {"w": "prominent", "p": "adj.", "d": "Important; famous.", "c": "著名的；顯著的", "s": "She is a highly prominent figure in the field of artificial intelligence, frequently invited to give keynote speeches at international tech summits. Her groundbreaking research is widely cited by scholars globally.", "t": "她是人工智慧領域非常著名的人物，經常受邀在國際科技高峰會上發表主題演講。她的開創性研究被全球學者廣泛引用。", "as": "", "at": "", "a": 1}, {"w": "definite", "p": "adj.", "d": "Clearly stated or decided; certain.", "c": "明確的;確定的", "s": "She gave a definite answer without any hesitation.", "t": "她毫不猶豫地給出了明確的答案。", "as": "There is no definitedate yet for the product launch.", "at": "產品發表目前還沒有確定的日期。", "a": 1}, {"w": "plain", "p": "adj./n.", "d": "Clear and simple; a large area of flat land.", "c": "簡樸的;平原", "s": "She preferred plain , unadorned clothing over flashy fashion.", "t": "她偏好簡樸不加修飾的服裝,而非華麗的時尚穿搭。", "as": "Herds of bison once roamed the vast plain s of the Midwest.", "at": "野牛群曾經漫遊在美國中西部廣闊的平原上。", "a": 1}, {"w": "intelligible", "p": "adj.", "d": "Able to be understood.", "c": "可理解的;清楚的", "s": "The professor made the complex theory intelligible to beginners.", "t": "這位教授讓這套複雜的理論對初學者來說變得清楚易懂。", "as": "His mumbled speech was barely intelligible over the noise.", "at": "在這片嘈雜中,他喃喃的說話幾乎難以理解。", "a": 1}, {"w": "comprehensible", "p": "adj.", "d": "Able to be understood.", "c": "可理解的;易懂的", "s": "The teacher rewrote the instructions to make them more comprehensible for younger students.", "t": "老師重新改寫了說明,好讓年紀較小的學生更容易理解。", "as": "His explanation of the tax code was surprisingly comprehensible , even for a non-expert.", "at": "他對稅法的解釋出奇地易懂,即使對非專業人士來說也是如此。", "a": 1}]}, {"unit": 49, "theme": "Vague and Obscure", "themeZh": "模糊與難懂", "antonymLessons": [48], "cards": [{"w": "ambiguous", "p": "adj.", "d": "Open to more than one interpretation; unclear.", "c": "模稜兩可的；不明確的", "s": "Legal contracts containing ambiguous terminology often result in lengthy court battles between business partners.", "t": "包含「模稜兩可的」術語的法律合約，往往會導致商業夥伴之間漫長的法庭拉鋸戰。", "as": "", "at": ""}, {"w": "nebulous", "p": "adj.", "d": "Unclear, vague.", "c": "朦朧的/模糊的", "s": "His plans for the future remained nebulous, with no clear timeline.", "t": "他對未來的計畫依然模糊不清,沒有明確的時間表。", "as": "The company's mission statement was so nebulous that no one understood its actual goals.", "at": "這家公司的使命宣言太過模糊,沒有人能理解其真正目標。"}, {"w": "abstruse", "p": "adj.", "d": "Difficult to understand because it is complex, obscure, or highly theoretical.", "c": "深奧難懂的；晦澀的；玄奧的", "s": "The textbook contained such abstruse equations that even advanced students struggled with them.", "t": "教科書充滿深奧難懂的方程式，連高年級學生都難以理解。", "as": "The lecturer debated an abstruse philosophical theory with little relevance to daily life.", "at": "講者花時間辯論一套與日常生活關聯甚少的玄奧哲學理論。"}, {"w": "arcane", "p": "adj.", "d": "Mysterious or known by few.", "c": "神秘的/隱奧的", "s": "The ancient book contained arcane knowledge.", "t": "這本古書蘊藏著隱奧難解的知識。", "as": "Only a handful of scholars understood the arcane rituals described in the text.", "at": "只有少數學者能理解這篇文本中描述的神秘儀式。"}, {"w": "esoteric", "p": "adj.", "d": "Understood by only a select few.", "c": "深奧難懂的/小眾的", "s": "The lecture was filled with esoteric jargon that confused most of the audience.", "t": "這場演講充滿了艱澀難懂的專業術語,讓大多數聽眾感到困惑。", "as": "He collects esoteric books on ancient alchemy that few people have ever heard of.", "at": "他收藏一些幾乎沒人聽過、關於古代煉金術的冷僻書籍。"}, {"w": "opaque", "p": "adj.", "d": "Not able to be seen through; not transparent; hard to understand.", "c": "不透明的;難以理解的", "s": "The frosted glass door was completely opaque .", "t": "這扇霧面玻璃門完全不透明。", "as": "The company's financial statements remained frustratingly opaque .", "at": "這家公司的財務報表令人沮喪地依然晦澀難懂。"}, {"w": "cryptic", "p": "adj.", "d": "Puzzling.", "c": "神秘的/隱晦的", "s": "He left a cryptic note that no one could quite decipher.", "t": "他留下了一張沒有人能完全解讀的神秘字條。", "as": "Her cryptic smile gave nothing away about her true feelings.", "at": "她那神秘難解的微笑絲毫沒有透露她真正的感受。"}, {"w": "enigmatic", "p": "adj.", "d": "Mystifying, cryptic.", "c": "神秘難解的", "s": "The old man's enigmatic smile left the villagers wondering what he knew.", "t": "這位老人神秘難解的微笑,讓村民們猜不透他到底知道些什麼。", "as": "Her enigmatic message contained no clear explanation of what had happened.", "at": "她那則神秘難解的訊息,沒有清楚說明到底發生了什麼事。"}, {"w": "obscure", "p": "adj.", "d": "Not discovered or known about; uncertain.", "c": "默默無聞的；晦澀的", "s": "The researcher spent years digging through dusty archives to find information about an obscure 19th-century poet. Until her biography was published, his brilliant literary contributions were entirely forgotten.", "t": "研究人員花了數年時間在佈滿灰塵的檔案中尋找關於一位默默無聞的19世紀詩人的資訊。直到她的傳記出版，他卓越的文學貢獻才為人所知。", "as": "", "at": ""}, {"w": "equivocal", "p": "adj.", "d": "Ambiguous, uncertain, undecided.", "c": "模稜兩可的", "s": "His equivocal answer left reporters unsure whether he would run for office.", "t": "他模稜兩可的回答讓記者們無法確定他是否會參選。", "as": "The results of the study were frustratingly equivocal.", "at": "這項研究的結果令人沮喪地模稜兩可。"}, {"w": "inscrutable", "p": "adj.", "d": "Impossible to understand or interpret.", "c": "難以理解的;高深莫測的", "s": "Her inscrutable expression gave nothing away during negotiations.", "t": "她高深莫測的表情在談判過程中沒有透露任何訊息。", "as": "The ancient text remained inscrutable even to expert scholars.", "at": "這份古老的文獻即使對專家學者而言仍是難以理解的。"}, {"w": "murky", "p": "adj.", "d": "Dark, obscure.", "c": "昏暗的/陰晦的", "s": "The divers could barely see through the murky water of the lake.", "t": "潛水員在湖中昏暗的水裡幾乎看不清楚。", "as": "The company's finances remain murky, with few details made public.", "at": "這家公司的財務狀況依然模糊不清,鮮少公開細節。"}, {"w": "occult", "p": "adj.", "d": "Mysterious, supernatural.", "c": "神秘的/超自然的", "s": "The old book was filled with occult symbols and rituals.", "t": "這本古書裡充滿了神秘的符號和儀式。", "as": "He was fascinated by occult practices from a young age.", "at": "他從小就對神秘學的作法十分著迷。", "a": 1}, {"w": "vague", "p": "adj.", "d": "Not clear in meaning or expression; indefinite.", "c": "模糊的/含糊的", "s": "The instructions were vague, leaving us uncertain about the next step.", "t": "這些指示含糊不清,讓我們不確定下一步該怎麼做。", "as": "She gave only a vague answer when asked about her plans.", "at": "被問到她的計畫時,她只給了一個含糊的答案。", "a": 1}, {"w": "indistinct", "p": "adj.", "d": "Not clear or sharply defined.", "c": "模糊不清的", "s": "The figure in the distance was blurry and indistinct.", "t": "遠處的那個身影模糊不清,難以辨認。", "as": "Through the thick fog, the outline of the building remained indistinct.", "at": "在濃霧之中,這棟建築的輪廓依然模糊不清。", "a": 1}, {"w": "impenetrable", "p": "adj.", "d": "Impossible to pass through.", "c": "無法穿透的", "s": "The fortress was impenetrable to enemy attack.", "t": "這座堡壘固若金湯,無法被敵軍攻破。", "as": "The jungle's impenetrable undergrowth slowed the explorers to a crawl.", "at": "叢林裡密不可穿的灌木叢讓探險隊的行進速度慢如蝸牛。", "a": 1}, {"w": "indefinite", "p": "adj.", "d": "Not precisely determined; vague.", "c": "不確定的;無限期的", "s": "The trip was postponed for an indefinite period.", "t": "這趟旅行被無限期延後了。", "as": "Her answer remained frustratingly indefinite .", "at": "她的答案仍舊模糊不清,令人感到挫折。", "a": 1}, {"w": "mysterious", "p": "adj.", "d": "Difficult or impossible to understand or explain.", "c": "神秘的;難以理解的", "s": "A mysterious light appeared over the lake each night.", "t": "每天晚上,湖面上都會出現一道神秘的光。", "as": "His mysterious absence puzzled everyone at the office.", "at": "他神秘的缺席讓辦公室裡的每個人都感到困惑。", "a": 1}]}, {"unit": 50, "theme": "Flattery and Praise (excessive)", "themeZh": "過度諂媚與讚美", "antonymLessons": [51], "cards": [{"w": "adulation", "p": "n.", "d": "Extreme praise.", "c": "過度讚美/諂媚", "s": "The pop star basked in the adulation of her adoring fans.", "t": "這位流行歌手沉浸在崇拜她的粉絲們的讚美之中。", "as": "He grew uncomfortable with the constant adulation from his students.", "at": "他對學生們不斷的過度讚美感到不自在。"}, {"w": "flattery", "p": "n.", "d": "Excessive and insincere praise.", "c": "諂媚;奉承", "s": "He fell for her obvious flattery .", "t": "他中了她明顯的奉承之計。", "as": "The salesman relied heavily on flattery to close the deal.", "at": "這位業務員大量倚賴奉承來促成交易。"}, {"w": "fawn", "p": "v./n.", "d": "To display exaggerated flattery; a young deer.", "c": "諂媚;小鹿", "s": "Employees tended to fawn over the new executive.", "t": "員工們往往會對這位新任主管過度諂媚。", "as": "A fawn followed closely behind its mother through the meadow.", "at": "一隻小鹿緊緊跟在牠母親後面穿過草地。"}, {"w": "blandishment", "p": "n.", "d": "Flattering words or actions used to persuade someone.", "c": "諂媚;甜言蜜語", "s": "No amount of blandishment could convince her to change her final decision.", "t": "再多的甜言蜜語都無法讓她改變最終的決定。", "as": "The salesman's blandishment eventually wore down the skeptical customer.", "at": "業務員的花言巧語,最終磨掉了這位持懷疑態度顧客的防備。"}, {"w": "sycophantic", "p": "adj.", "d": "Behaving in an excessively flattering way to gain advantage.", "c": "阿諛奉承的;諂媚的", "s": "Employees grew tired of his sycophantic remarks to upper management.", "t": "員工們對他向高層管理階層說的那些諂媚言論感到厭煩。", "as": "The reviewer's sycophantic praise raised suspicions of a conflict of interest.", "at": "這位評論家阿諛奉承的讚美引發了利益衝突的懷疑。"}, {"w": "obsequious", "p": "adj.", "d": "Seeking favor, fawning.", "c": "諂媚的/奉承的", "s": "The obsequious waiter kept complimenting every dish the guests ordered.", "t": "這位諂媚的服務生不斷讚美客人點的每一道菜。", "as": "His obsequious behavior toward the boss made his coworkers uncomfortable.", "at": "他對老闆諂媚奉承的態度讓同事感到不自在。"}, {"w": "unctuous", "p": "adj.", "d": "Insincere, fawning.", "c": "諂媚的/油腔滑調的", "s": "The salesman's unctuous compliments made her uneasy.", "t": "這位業務員油腔滑調的恭維讓她感到很不自在。", "as": "His unctuous tone made it clear he wanted something from her.", "at": "他那諂媚的語氣清楚顯示他想從她那裡得到些什麼。"}, {"w": "toady", "p": "n.", "d": "A flatterer; a sycophant.", "c": "馬屁精", "s": "The manager's toady agreed with every decision, no matter how bad.", "t": "這位經理的馬屁精無論決策有多糟,總是全盤贊同。", "as": "He was mocked for being a corporate toady who never challenged authority.", "at": "他因為是個從不挑戰權威的企業馬屁精而遭到嘲笑。"}, {"w": "cajole", "p": "v.", "d": "To coax.", "c": "哄騙", "s": "She tried to cajole her brother into lending her his car for the weekend.", "t": "她試圖哄騙弟弟在週末把車借給她。", "as": "The salesman attempted to cajole the elderly couple into buying an expensive product.", "at": "這名推銷員試圖哄騙這對老夫婦購買昂貴的產品。"}, {"w": "wheedle", "p": "v.", "d": "To coax, persuade, cajole.", "c": "哄騙/誘騙", "s": "She tried to wheedle her way into a later curfew.", "t": "她試圖用甜言蜜語哄騙父母延後門禁時間。", "as": "He managed to wheedle a free upgrade out of the hotel clerk.", "at": "他成功哄騙飯店櫃檯人員給了他一次免費升等。"}, {"w": "fulsome", "p": "adj.", "d": "Excessive, insincere.", "c": "過度誇張的/令人作嘔的", "s": "The critic gave the film fulsome praise that seemed almost insincere.", "t": "這位影評人給了這部電影過度誇張、幾乎顯得不真誠的讚美。", "as": "His fulsome flattery made everyone at the table roll their eyes.", "at": "他過度浮誇的奉承讓餐桌上的每個人都翻了白眼。", "a": 1}, {"w": "sycophancy", "p": "n.", "d": "Excessive flattery toward someone important to gain advantage.", "c": "阿諛奉承;諂媚", "s": "His constant sycophancy toward the boss disgusted his coworkers.", "t": "他對老闆不斷的阿諛奉承讓同事們感到反感。", "as": "The court was rife with sycophancy , as advisors competed for the king's favor.", "at": "這座宮廷充斥著諂媚之風,顧問們競相討好國王。", "a": 1}, {"w": "ingratiate", "p": "v.", "d": "To win confidence, charm.", "c": "討好/迎合", "s": "He tried to ingratiate himself with his new boss by arriving early every day.", "t": "他試圖每天提早到班,以討好新上司。", "as": "She worked hard to ingratiate herself with her in-laws.", "at": "她努力討好公婆,希望贏得他們的好感。", "a": 1}]}, {"unit": 51, "theme": "Belittling and Slander", "themeZh": "貶低與誹謗", "antonymLessons": [50], "cards": [{"w": "disparage", "p": "v.", "d": "To discredit, belittle:relegate.", "c": "貶低", "s": "He often tries to disparage his rival's accomplishments in front of others.", "t": "他常常在別人面前試圖貶低對手的成就。", "as": "She refused to disparage her former employer, even after being fired.", "at": "即使被解僱了,她也拒絕貶損前雇主。"}, {"w": "belittle", "p": "v.", "d": "To make seem less important.", "c": "貶低", "s": "She always tries to belittle her coworkers' achievements in meetings.", "t": "她總是在會議中試圖貶低同事的成就。", "as": "Parents should never belittle their children's efforts, even when they fail.", "at": "即使孩子失敗了,父母也絕不該貶低他們的努力。"}, {"w": "denigrate", "p": "v.", "d": "To belittle, diminish the opinion of.", "c": "詆毀/貶低", "s": "He was quick to denigrate any idea that wasn't his own.", "t": "他總是急於貶低任何不是他自己提出的想法。", "as": "The article was criticized for trying to denigrate the scientist's decades of research.", "at": "這篇文章因試圖詆毀這位科學家數十年的研究而遭到批評。"}, {"w": "deride", "p": "v.", "d": "To ridicule, scoff at.", "c": "嘲笑", "s": "His classmates derided his old-fashioned clothes.", "t": "他的同學嘲笑他老派的穿著。", "as": "Critics derided the film as unoriginal and poorly written.", "at": "評論家嘲笑這部電影毫無新意、編劇拙劣。"}, {"w": "vilify", "p": "v.", "d": "To malign, slander.", "c": "誹謗/貶低", "s": "The tabloids continued to vilify the actress long after the scandal ended.", "t": "醜聞平息許久之後,這些八卦小報仍持續詆毀這位女演員。", "as": "He was unfairly vilifyied in the press for a decision he never made.", "at": "他因一項自己從未做過的決定,而在媒體上遭到不公平的詆毀。"}, {"w": "malign", "p": "v./adj.", "d": "To speak about someone in a spitefully critical or untruthful way; also harmful in nature.", "c": "誹謗；中傷；有害的", "s": "The actress sued the magazine for attempting to malign her character.", "t": "女演員控告雜誌企圖中傷她的人格。", "as": "Critics warned that leaders could malign peaceful protesters through false accusations.", "at": "批評者警告領導人可能透過虛假指控誹謗和平抗議者。"}, {"w": "slander", "p": "n./v.", "d": "A false spoken statement that damages a person's reputation.", "c": "誹謗;毀謗", "s": "He filed a lawsuit for slander after the false rumors spread.", "t": "在這些不實謠言傳開之後,他提起了誹謗訴訟。", "as": "She refused to slander her former business partner despite their falling out.", "at": "儘管雙方已鬧翻,她仍拒絕誹謗她的前生意夥伴。"}, {"w": "libel", "p": "n.", "d": "Degradation by writing or publishing.", "c": "誹謗/中傷", "s": "The magazine was sued for libel after publishing the false claims.", "t": "這家雜誌因刊登不實言論而遭到誹謗罪起訴。", "as": "He accused the blogger of libel for spreading the untrue rumor.", "at": "他指控這名部落客散布不實謠言,構成了文字誹謗。"}, {"w": "defame", "p": "v.", "d": "To damage the reputation of someone through false statements.", "c": "誹謗;中傷", "s": "The article attempted to defame the senator's character.", "t": "這篇文章試圖中傷這位參議員的人格。", "as": "She sued the blogger for trying to defame her online.", "at": "她控告這位部落客試圖在網路上誹謗她。"}, {"w": "derogatory", "p": "adj.", "d": "Belittling, disparaging.", "c": "貶低的/誹謗的", "s": "He was fired for making derogatory comments about his coworkers.", "t": "他因對同事發表貶低性的言論而遭解雇。", "as": "The term is considered highly derogatory and should be avoided.", "at": "這個詞被認為具有高度貶損性,應該避免使用。"}, {"w": "deprecate", "p": "v.", "d": "To express disapproval.", "c": "抨擊/反對", "s": "Critics deprecated the movie's shallow attempt at humor.", "t": "評論家對這部電影膚淺的幽默嘗試表示不以為然。", "as": "He tends to self-deprecate, joking about his own shortcomings.", "at": "他習慣自我貶抑,拿自己的缺點開玩笑。"}, {"w": "decry", "p": "v.", "d": "To criticize openly.", "c": "公開譴責/抨擊", "s": "Activists gathered to decry the government's new environmental policy.", "t": "行動人士聚集起來公開譴責政府這項新的環境政策。", "as": "The editorial decryed the lack of transparency in the election process.", "at": "這篇社論公開抨擊選舉過程缺乏透明度。"}, {"w": "discredit", "p": "v./n.", "d": "To damage the reputation of; disbelief.", "c": "使名譽受損;懷疑", "s": "The scandal threatened to discredit the entire institution.", "t": "這場醜聞可能會使整個機構名譽受損。", "as": "New evidence cast discredit on his testimony.", "at": "新的證據讓他的證詞遭到懷疑。"}, {"w": "aspersion", "p": "n.", "d": "A curse, expression of ill-will.", "c": "誹謗/中傷", "s": "The senator refused to cast aspersions on his opponent's character.", "t": "這位參議員拒絕對他對手的人格做出誹謗中傷。", "as": "She felt hurt by the unfair aspersions made against her reputation.", "at": "她對於這些對她名譽不公正的中傷感到十分受傷。"}, {"w": "smear", "p": "v./n.", "d": "To spread something greasy or dirty; to damage someone's reputation with false claims.", "c": "塗抹;抹黑", "s": "He accidentally smear ed paint across his sleeve.", "t": "他不小心把顏料抹到了袖子上。", "as": "The rival campaign launched a smear against the candidate.", "at": "對手的競選團隊發動了一場抹黑這位候選人的行動。", "a": 1}, {"w": "defamation", "p": "n.", "d": "The act of damaging someone's reputation through false statements.", "c": "誹謗", "s": "The celebrity sued the tabloid for defamation .", "t": "這位名人以誹謗罪起訴這家小報。", "as": "The false article resulted in a costly defamation lawsuit.", "at": "這篇不實的報導導致了一場代價高昂的誹謗訴訟。", "a": 1}, {"w": "sully", "p": "v.", "d": "To damage the purity or integrity of; to tarnish.", "c": "玷污;敗壞", "s": "The scandal threatened to sully the university's reputation.", "t": "這場醜聞可能玷污這所大學的名聲。", "as": "He refused to let one mistake sully his years of hard work.", "at": "他拒絕讓一個錯誤玷污他多年來的辛勤努力。", "a": 1}, {"w": "tarnish", "p": "v./n.", "d": "To lose or cause to lose luster; to damage a reputation.", "c": "失去光澤;玷污", "s": "Silver jewelry can tarnish over time if not properly stored.", "t": "銀飾如果沒有妥善保存,久了可能會失去光澤。", "as": "The scandal began to tarnish his once-stellar reputation.", "at": "這場醜聞開始玷污他曾經無可挑剔的名聲。", "a": 1}, {"w": "revile", "p": "v.", "d": "Hate:revoke=reprimand=casticate.", "c": "辱罵/斥責", "s": "The corrupt official was revile by the very citizens he had betrayed.", "t": "這名貪腐官員遭到他所背叛的人民辱罵斥責。", "as": "Historians continue to revile the dictator for the atrocities he committed.", "at": "史學家至今仍痛斥這位獨裁者所犯下的暴行。", "a": 1}, {"w": "abuse", "p": "v./n.", "d": "To use wrongly or harmfully; harmful or unfair treatment.", "c": "濫用;虐待", "s": "The manager was fired for his repeated abuse of company funds.", "t": "這位經理因反覆濫用公司資金而遭解雇。", "as": "The charity provides shelter for victims of domestic abuse.", "at": "這家慈善機構為家暴受害者提供庇護所。", "a": 1}, {"w": "demean", "p": "v.", "d": "To lower the status or stature of something.", "c": "貶低/羞辱", "s": "He refused to demean himself by begging for the job back.", "t": "他拒絕自貶身分,乞求對方讓他復職。", "as": "Her constant insults were meant to demean her coworkers.", "at": "她不斷的辱罵是為了貶低她的同事。", "a": 1}, {"w": "invective", "p": "n.", "d": "Insulting, abusive speech.", "c": "辱罵/猛烈抨擊", "s": "The senator's speech was full of invective against his opponent.", "t": "這位參議員的演說充滿了針對對手的猛烈抨擊。", "as": "He hurled a stream of invective at the referee after the call.", "at": "在那次判決之後,他對裁判連珠炮似地破口大罵。", "a": 1}, {"w": "diatribe", "p": "n.", "d": "A bitter, angry, and prolonged verbal or written attack.", "c": "謾罵；抨擊；惡毒的斥責", "s": "The candidate's speech became a bitter diatribe against the media.", "t": "該候選人的演講演變成對媒體的惡毒抨擊。", "as": "The critic wrote a harsh diatribe attacking the author's new novel.", "at": "評論家寫了一篇針對該作家新小說的嚴厲謾罵。", "a": 1}]}, {"unit": 52, "theme": "Flexible and Yielding", "themeZh": "靈活與順從", "antonymLessons": [53], "cards": [{"w": "malleable", "p": "adj.", "d": "Capable of being shaped or formed.", "c": "可塑的/易受影響的", "s": "Gold is a highly malleable metal that can be shaped into thin sheets.", "t": "黃金是一種延展性極高的金屬,可以被打造成薄片。", "as": "Children's minds are especially malleable, absorbing new ideas easily.", "at": "孩童的心智特別具有可塑性,很容易吸收新的觀念。"}, {"w": "pliable", "p": "adj.", "d": "Flexible.", "c": "柔軟的/易受影響的", "s": "The clay remained pliable enough to reshape even after an hour.", "t": "這塊黏土即使過了一個小時仍然柔軟到可以重新塑形。", "as": "Young minds tend to be more pliable and open to new ideas.", "at": "年輕的心智往往更具可塑性,也更能接受新的想法。"}, {"w": "pliant", "p": "adj.", "d": "Bending easily; adaptable or easily influenced.", "c": "柔韌的;易受影響的", "s": "The willow's pliant branches swayed gracefully in the wind.", "t": "這棵柳樹柔韌的枝條在風中優雅地擺動。", "as": "A pliant mind adapts more easily to unexpected changes.", "at": "一個柔韌易變的心智能更輕易地適應突如其來的變化。"}, {"w": "supple", "p": "adj.", "d": "Bending and moving easily and gracefully; flexible.", "c": "柔軟的;靈活的", "s": "Years of yoga kept her body remarkably supple .", "t": "多年的瑜珈練習讓她的身體格外柔軟靈活。", "as": "The leather became supple after being conditioned with oil.", "at": "這塊皮革經過上油保養後變得柔軟起來。"}, {"w": "tractable", "p": "adj.", "d": "Easily controlled.", "c": "易駕馭的/溫順的", "s": "The trained horse proved far more tractable than the wild one.", "t": "這匹受過訓練的馬遠比那匹野馬更容易駕馭。", "as": "Once she calmed down, the toddler became much more tractable.", "at": "這個幼兒冷靜下來後,變得容易配合許多。"}, {"w": "docile", "p": "adj.", "d": "Ready to accept control or instruction; submissive.", "c": "溫馴的/順從的", "s": "The dog was surprisingly dociledespite its large size.", "t": "儘管體型龐大,這隻狗卻異常溫馴聽話。", "as": "The new employee proved to be quiet and docile, rarely questioning instructions.", "at": "這位新進員工證實個性安靜溫順,鮮少對指示提出質疑。"}, {"w": "amenable", "p": "adj.", "d": "Willing, compliant.", "c": "順從的/願意配合的", "s": "The manager was amenable to adjusting the schedule for new parents.", "t": "這位經理很願意配合為新手父母調整班表。", "as": "He is usually amenable to reasonable requests from his employees.", "at": "他通常都很樂於配合員工合理的要求。"}, {"w": "acquiescent", "p": "adj.", "d": "Willing to accept something without protest, though not necessarily happily.", "c": "順從的;默許的", "s": "Her usually stubborn brother was surprisingly acquiescent about the new house rules.", "t": "她那向來固執的弟弟,對於新的家規竟出奇地順從。", "as": "The staff grew acquiescent after repeated warnings from management.", "at": "在管理層再三警告後,員工們變得順從許多。"}, {"w": "accommodating", "p": "adj.", "d": "Helpful, obliging, polite.", "c": "樂於助人的/隨和的", "s": "The hotel staff were extremely accommodating, upgrading our room at no extra cost.", "t": "飯店員工非常樂於配合,免費幫我們升等了房間。", "as": "Her accommodating nature made her a favorite among coworkers.", "at": "她隨和的個性讓她深受同事喜愛。"}, {"w": "flexible", "p": "adj.", "d": "Capable of bending without breaking; adaptable.", "c": "有彈性的;靈活的", "s": "The rubber hose is flexible enough to fit tight corners.", "t": "這條橡膠水管夠有彈性,可以彎進狹窄的角落。", "as": "Her flexible schedule allowed her to work from home.", "at": "她靈活的行程安排讓她可以在家工作。", "a": 1}, {"w": "resilient", "p": "adj.", "d": "Able to recoil or spring back into shape; strong.", "c": "適應力強的；有韌性的", "s": "Local communities showed how resilient they were by rebuilding homes quickly after the devastating hurricane.", "t": "當地社區在破壞性颶風過後迅速重建家園，展現出強大的「適應力（韌性）」。", "as": "", "at": "", "a": 1}, {"w": "limber", "p": "adj./v.", "d": "Flexible and supple; to warm up in preparation for exercise.", "c": "柔軟的;做暖身運動", "s": "Years of yoga kept her body remarkably limber .", "t": "多年的瑜伽練習讓她的身體保持著驚人的柔軟度。", "as": "The runners began to limber up before the race started.", "at": "跑者們在比賽開始前開始做暖身運動。", "a": 1}, {"w": "obliging", "p": "adj.", "d": "Accommodating, helpful.", "c": "樂於助人的/懇切的", "s": "The obliging waiter brought extra napkins without being asked.", "t": "這位樂於助人的服務生沒等人開口就主動送來了額外的餐巾紙。", "as": "Her neighbors were always obliging, willing to lend a hand whenever needed.", "at": "她的鄰居總是很樂於幫忙,一有需要就會伸出援手。", "a": 1}]}, {"unit": 53, "theme": "Rigid and Strict", "themeZh": "嚴格與僵硬", "antonymLessons": [52], "cards": [{"w": "stringent", "p": "adj.", "d": "Strict, precise, and exacting.", "c": "嚴格的;嚴厲的", "s": "The new regulations imposed stringent safety standards on the industry.", "t": "這項新法規對這個產業實施了嚴格的安全標準。", "as": "Admission to the program requires meeting stringent academic criteria.", "at": "申請這項課程需要符合嚴格的學術標準。"}, {"w": "austere", "p": "adj.", "d": "Simple, unadorned, hard.", "c": "嚴峻的/簡樸的", "s": "The monk lived an austere life, owning almost nothing.", "t": "這位僧侶過著簡樸嚴謹的生活,幾乎一無所有。", "as": "The office had an austeredesign with bare white walls.", "at": "這間辦公室的設計十分簡約樸素,牆面一片空白。"}, {"w": "rigorous", "p": "adj.", "d": "Strict and demanding, requiring a high level of effort and precision.", "c": "嚴格的/嚴謹的", "s": "The rigorous training schedule prepared the athletes for the competition.", "t": "這套嚴格的訓練計畫讓選手們為比賽做好了準備。", "as": "The university is known for its rigorous admissions process.", "at": "這所大學以其嚴謹的招生流程聞名。"}, {"w": "inflexible", "p": "adj.", "d": "Unwilling to change; rigid.", "c": "不知變通的;固執的", "s": "The manager's inflexible rules frustrated the entire staff.", "t": "這位經理不知變通的規定讓全體員工都感到挫折。", "as": "Her inflexible schedule left no room for emergencies.", "at": "她固定不變的行程完全沒有空間應付緊急狀況。"}, {"w": "dogmatic", "p": "adj.", "d": "Aggressively and arrogantly certain about unproved principles.", "c": "武斷的/教條式的", "s": "His dogmatic insistence on being right made compromise impossible.", "t": "他武斷地堅持自己是對的,使得妥協變得不可能。", "as": "The professor was too dogmatic to consider any opposing theory.", "at": "這位教授過於教條,無法考慮任何相反的理論。"}, {"w": "draconian", "p": "adj.", "d": "Excessively harsh or severe, especially of laws.", "c": "嚴苛的;殘酷的", "s": "The new regime imposed draconian restrictions on free speech.", "t": "這個新政權對言論自由施加了嚴苛的限制。", "as": "Critics called the punishment draconian for such a minor offense.", "at": "評論家認為對這種輕微違規施以如此嚴苛的懲罰過於嚴厲。"}, {"w": "uncompromising", "p": "adj.", "d": "Unwilling to make concessions; firm in one's position.", "c": "不妥協的;堅定不讓步的", "s": "The union took an uncompromising stance on the proposed wage cuts.", "t": "這個工會對這項提議的減薪方案採取了不妥協的立場。", "as": "Her uncompromisingededication to quality set the company apart from competitors.", "at": "她對品質不妥協的堅持讓這家公司在競爭對手中脫穎而出。"}, {"w": "exacting", "p": "adj.", "d": "Requiring a great deal of care or effort; painstaking.", "c": "嚴格要求的", "s": "Her exacting standards made it difficult for assistants to satisfy her.", "t": "她嚴格要求的標準讓助理很難讓她滿意。", "as": "The exacting editor demanded a rewrite of nearly every paragraph.", "at": "這位嚴格挑剔的編輯要求幾乎每一段都要重寫。"}, {"w": "puritanical", "p": "adj.", "d": "Practicing or affecting strict moral or religious discipline.", "c": "清教徒式的;拘謹嚴苛的", "s": "Her puritanical upbringing forbade any form of frivolous entertainment.", "t": "她清教徒式的家教禁止任何形式輕浮的娛樂。", "as": "The town's puritanical values shaped its strict local customs.", "at": "這座城鎮清教徒般的價值觀塑造了它嚴格的地方習俗。", "a": 1}, {"w": "implacable", "p": "adj.", "d": "Unable to be placated, calmed, or appeased; relentless and unstoppable in hostility (Not placable).", "c": "無法平息的、冷酷無情的、強硬無比的", "s": "The two warring families remained implacable foes, refusing to open a peace dialogue despite interventions from the king.", "t": "這兩個交戰家族依舊是無法和解的死敵，儘管有國王的干預，他們仍拒絕展開和平對話。", "as": "The army fell back before the implacable advance of the enemy's heavy armored tank division.", "at": "在敵方重裝甲坦克部隊勢不可擋的（冷酷無情的）推進面前，軍隊步步後退。", "a": 1}, {"w": "immovable", "p": "adj.", "d": "Not able to be moved; unyielding.", "c": "不可移動的;不動搖的", "s": "The ancient boulder remained immovabledespite the machinery.", "t": "儘管動用了機械,這塊古老的巨石依然紋絲不動。", "as": "He was immovable in his decision, no matter the pressure.", "at": "無論壓力多大,他在這項決定上始終不動搖。", "a": 1}]}, {"unit": 54, "theme": "Fake and Imitation", "themeZh": "虛假與仿造", "antonymLessons": [55], "cards": [{"w": "spurious", "p": "adj.", "d": "False, counterfeit.", "c": "虛假的/偽造的", "s": "The lawyer dismissed the claim as entirely spurious.", "t": "這位律師駁斥這項主張純屬虛假。", "as": "The website was selling spuriousedesigner handbags at suspiciously low prices.", "at": "這個網站以可疑的低價販售假冒的設計師手提包。"}, {"w": "bogus", "p": "adj.", "d": "Counterfeit, fake.", "c": "偽造的/假的", "s": "The email turned out to be a bogus request for personal information.", "t": "這封電子郵件結果是一個要求提供個人資訊的假訊息。", "as": "He was arrested for selling bogus concert tickets.", "at": "他因販賣偽造的演唱會門票而遭到逮捕。"}, {"w": "sham", "p": "n./adj.", "d": "Something false presented as genuine.", "c": "騙局;虛假的", "s": "The investigation revealed the charity to be a complete sham .", "t": "這項調查揭露這個慈善機構完全是個騙局。", "as": "Her sham enthusiasm didn't fool anyone at the meeting.", "at": "她虛假的熱情並沒有騙過這場會議上的任何人。"}, {"w": "apocryphal", "p": "adj.", "d": "Fictitious, false, wrong.", "c": "虛構的/來源可疑的", "s": "The story of the founder's midnight escape is likely apocryphal.", "t": "創辦人半夜逃脫的故事很可能只是虛構的傳說。", "as": "Historians consider the famous quote to be apocryphal, with no real evidence he said it.", "at": "歷史學家認為這句名言的真實性存疑,沒有確切證據顯示他真的說過。"}, {"w": "specious", "p": "adj.", "d": "Appearing true or plausible but actually false.", "c": "似是而非的;貌似有理的", "s": "The lawyer dismantled the witness's specious reasoning point by point.", "t": "這位律師逐點拆解了這位證人似是而非的推理。", "as": "Her argument sounded convincing but was ultimately specious .", "at": "她的論點聽起來很有說服力,但終究是貌似有理的。"}, {"w": "contrived", "p": "adj.", "d": "Artificial or overly planned.", "c": "做作的/牽強的", "s": "The movie's plot felt contrived and unrealistic.", "t": "這部電影的劇情讓人感覺牽強做作,不切實際。", "as": "Her apology sounded contrived rather than sincere.", "at": "她的道歉聽起來刻意做作,而非發自真心。"}, {"w": "ostensible", "p": "adj.", "d": "Outward, seeming.", "c": "表面的/假裝的", "s": "The ostensible reason for his visit was business, but he really wanted to see her.", "t": "他此行表面上的理由是公事,但其實他真正想見的是她。", "as": "The company's ostensible goal was efficiency, though layoffs were the real motive.", "at": "這家公司表面上的目標是效率,但真正的動機其實是裁員。", "a": 1}, {"w": "imitation", "p": "n.", "d": "A copy or replica of something.", "c": "模仿/仿製品", "s": "The purse was an imitation of a designer brand.", "t": "這個包包是名牌設計的仿製品。", "as": "The museum displayed both the original painting and a skillful imitation.", "at": "這座博物館同時展出了原作與一幅技藝精湛的仿作。", "a": 1}]}, {"unit": 55, "theme": "Genuine and Authentic", "themeZh": "真實與可靠", "antonymLessons": [54], "cards": [{"w": "authentic", "p": "adj.", "d": "Genuine and not a copy or fake.", "c": "真實的;道地的", "s": "The museum verified that the painting was authentic before purchasing it.", "t": "博物館在購入這幅畫之前,先確認了它的真偽。", "as": "She searched the city for an authentic bowl of the local noodle soup.", "at": "她在城裡四處尋找一碗道地的當地麵湯。"}, {"w": "veritable", "p": "adj.", "d": "Used to emphasize truth.", "c": "名副其實的/真正的", "s": "Einstein was a veritable genius.", "t": "愛因斯坦是名副其實的天才。", "as": "The buffet offered a veritable feast of international cuisine.", "at": "這場自助餐提供了名副其實的國際美食盛宴。"}, {"w": "legitimate", "p": "adj.", "d": "Conforming to the law or rules; valid or justifiable.", "c": "合法的/正當的", "s": "The company assured its customers that the transaction was legitimate and secure.", "t": "這家公司向顧客保證這筆交易是合法且安全的。", "as": "Because he was named in the will, John's claim to the property was legitimate.", "at": "由於約翰的名字出現在遺囑中,他對這筆財產的主張是合法的。"}, {"w": "credible", "p": "adj.", "d": "Able to be believed; convincing.", "c": "可信的", "s": "Her explanation seemed credible to the investigators.", "t": "她的解釋在調查人員看來似乎可信。", "as": "The company needs a credible plan to regain investor trust.", "at": "這家公司需要一個可信的計畫來重拾投資人的信任。"}, {"w": "valid", "p": "adj.", "d": "Having a sound basis; legally acceptable.", "c": "有效的;正當的", "s": "She raised a valid concern about the project's timeline.", "t": "她對這項計畫的時程提出了一個正當的疑慮。", "as": "His passport was no longer valid for international travel.", "at": "他的護照對於國際旅行來說已不再有效。"}, {"w": "unquestionable", "p": "adj.", "d": "Beyond doubt or dispute.", "c": "無可置疑的;確鑿的", "s": "Her dedication to the cause was unquestionable .", "t": "她對這項理念的奉獻是無可置疑的。", "as": "The data provided unquestionable proof of the drug's effectiveness.", "at": "這份數據提供了這種藥物療效無可置疑的證明。", "a": 1}, {"w": "pure", "p": "adj.", "d": "Not mixed with anything else; free from contamination.", "c": "純粹的;純淨的", "s": "The spring water was pure and refreshingly cold.", "t": "這口泉水純淨清涼,令人神清氣爽。", "as": "She spoke with pure conviction about her plans for the future.", "at": "她以純粹的信念談論她對未來的規劃。", "a": 1}]}, {"unit": 56, "theme": "Diligent and Hardworking", "themeZh": "勤奮與努力", "antonymLessons": [57], "cards": [{"w": "assiduous", "p": "adj.", "d": "Devoted, attentive.", "c": "勤勉的/刻苦的", "s": "Her assiduous study habits helped her earn top marks in every subject.", "t": "她刻苦勤勉的學習習慣讓她在每一科都拿到最高分。", "as": "The assiduous nurse checked on her patients every hour throughout the night.", "at": "這位盡職勤奮的護士整夜每小時都去查看她的病人。"}, {"w": "industrious", "p": "adj.", "d": "Diligent and hardworking.", "c": "勤勉的;勤奮的", "s": "The industrious ant collected food all summer long.", "t": "這隻勤奮的螞蟻整個夏天都在收集食物。", "as": "Her industrious nature helped her finish the project early.", "at": "她勤勉的天性幫助她提早完成了這項計畫。"}, {"w": "diligent", "p": "adj.", "d": "Showing care and effort in one's work or duties.", "c": "勤勉的/勤奮的", "s": "She is diligent in completing her assignments on time.", "t": "她做事勤奮,總是準時完成作業。", "as": "Thanks to his diligent research, the report was flawless.", "at": "多虧他勤奮認真的研究,這份報告才會如此完美無瑕。"}, {"w": "painstaking", "p": "adj.", "d": "Done with great care and thoroughness.", "c": "煞費苦心的;精心細緻的", "s": "Restoring the mural required painstaking attention to detail.", "t": "修復這幅壁畫需要煞費苦心的細節關注。", "as": "Her painstaking research took nearly ten years to complete.", "at": "她精心細緻的研究花了近十年才完成。"}, {"w": "indefatigable", "p": "adj.", "d": "Incapable of defeat, failure, decay.", "c": "不屈不撓的/不知疲倦的", "s": "Her indefatigable efforts finally led to the passage of the new law.", "t": "她不知疲倦的努力終於促成了這項新法的通過。", "as": "The indefatigable volunteers worked around the clock to help flood victims.", "at": "這些不屈不撓的志工日夜不停地工作,幫助受洪水影響的災民。"}, {"w": "persevering", "p": "adj.", "d": "Continuing steadily in a course of action despite difficulty.", "c": "堅持不懈的", "s": "Her persevering attitude eventually earned her the promotion she deserved.", "t": "她堅持不懈的態度最終為她贏得了應得的升遷。", "as": "The persevering athlete trained daily despite repeated setbacks.", "at": "這位堅持不懈的運動員儘管屢遭挫折,仍每天持續訓練。"}, {"w": "persistent", "p": "adj.", "d": "Continuing firmly or steadily in a course of action despite difficulties or opposition.", "c": "堅持不懈的/持續的", "s": "His persistent efforts to improve the system eventually paid off.", "t": "他堅持不懈地努力改善這套系統,最終有了回報。", "as": "After fifty years of buying lottery tickets, persistent efforts paid off when he won the jackpot.", "at": "在買了五十年彩券之後,他堅持不懈的努力終於得到回報,中了頭獎。", "a": 1}, {"w": "steady", "p": "adj./v.", "d": "Firmly fixed or supported; not likely to change.", "c": "穩定的;穩固的", "s": "The ladder felt steady once he braced it against the wall.", "t": "他把梯子靠在牆上撐穩後,感覺就穩固多了。", "as": "The company reported steady growth over the past five years.", "at": "這家公司報告過去五年來穩定的成長。", "a": 1}, {"w": "earnest", "p": "adj.", "d": "Resulting from or showing sincere and intense conviction.", "c": "真誠的；認真的", "s": "The young diplomat made an earnest attempt to mediate peace talks between warring factions, earning widespread respect for her dedication.", "t": "這位年輕的外交官進行了「真誠的（認真的）」嘗試以調解交戰各派之間的和平談判，她的奉獻贏得了廣泛尊重。", "as": "", "at": "", "a": 1}, {"w": "busy", "p": "adj.", "d": "Having a great deal to do; full of activity.", "c": "忙碌的", "s": "She's been too busy with exams to answer any messages this week.", "t": "這週她忙著準備考試,根本沒空回任何訊息。", "as": "The market square gets especially busy on Saturday mornings.", "at": "這座市集廣場在週六早上總是特別熱鬧忙碌。", "a": 1}]}, {"unit": 57, "theme": "Idle and Neglectful", "themeZh": "怠惰與疏忽", "antonymLessons": [56, 22], "cards": [{"w": "slothful", "p": "adj.", "d": "Lazy; disinclined to activity or exertion.", "c": "懶惰的;怠惰的", "s": "His slothful habits eventually cost him his job.", "t": "他懶惰的習慣最終讓他丟了工作。", "as": "The medieval sermon condemned slothful behavior as one of the seven deadly sins.", "at": "這篇中世紀的講道詞譴責怠惰的行為是七宗罪之一。"}, {"w": "remiss", "p": "adj.", "d": "Careless, negligent.", "c": "怠忽職守的", "s": "It would be remiss of me not to mention the risks involved.", "t": "如果我不提及其中涉及的風險,那將是我的怠忽職守。", "as": "He was remiss in checking the safety equipment before the climb.", "at": "他在攀登前未能盡責檢查安全裝備。"}, {"w": "negligent", "p": "adj.", "d": "Habitually careless, neglectful.", "c": "疏忽的/玩忽職守的", "s": "The company was found negligent in maintaining its safety equipment.", "t": "這家公司被查出在維護安全設備方面存在疏失。", "as": "A negligent babysitter left the children unattended near the pool.", "at": "一位疏忽大意的保姆讓孩子們在泳池邊無人看管。"}, {"w": "lax", "p": "adj.", "d": "Careless, negligent.", "c": "鬆懈的/馬虎的", "s": "The company was fined for having lax safety standards at the factory.", "t": "這家公司因工廠安全標準鬆懈而遭罰款。", "as": "Security at the old building had grown lax over the years.", "at": "這棟舊大樓的保全這些年來變得越來越鬆散。"}, {"w": "dilatory", "p": "adj.", "d": "Tending to delay, causing delay.", "c": "拖延的/延誤的", "s": "The company's dilatory response frustrated customers waiting for refunds.", "t": "這家公司拖延的回應讓等待退款的顧客感到十分不滿。", "as": "Lawyers accused the defense of using dilatory tactics to delay the trial.", "at": "律師指控辯方使用拖延戰術來延誤這場審判。"}, {"w": "lackadaisical", "p": "adj.", "d": "Lacking enthusiasm or determination.", "c": "懶散的;無精打采的", "s": "His lackadaisical attitude toward homework worried his teachers.", "t": "他對功課漫不經心的態度讓老師們感到擔憂。", "as": "The team's lackadaisical performance led to an embarrassing loss.", "at": "這支隊伍無精打采的表現導致了一場令人尷尬的失利。"}, {"w": "desultory", "p": "adj.", "d": "Occurring by chance, disconnected.", "c": "散漫的/斷斷續續的", "s": "Their desultory conversation drifted from topic to topic with no clear direction.", "t": "他們散漫的對話從一個話題飄到另一個話題,毫無明確方向。", "as": "He made only desultory efforts to finish the project on time.", "at": "他只斷斷續續地努力,並未認真想準時完成這項計畫。"}, {"w": "feckless", "p": "adj.", "d": "Lacking initiative or responsibility; ineffective.", "c": "無能的;不負責任的", "s": "The feckless manager never followed through on any promise.", "t": "這位不負責任的經理從未兌現過任何一項承諾。", "as": "Voters grew tired of the feckless leadership's constant excuses.", "at": "選民對這個無能領導層不斷的藉口感到厭倦。", "a": 1}, {"w": "neglect", "p": "v.", "d": "To fail to care for or pay proper attention to something.", "c": "忽視；疏忽", "s": "If home owners continuously neglect routine maintenance, minor structural problems can turn into extremely expensive repairs.", "t": "如果屋主持續「忽視」例行維護，小型的結構問題可能會演變成非常昂貴的維修工程。", "as": "", "at": "", "a": 1}, {"w": "cursory", "p": "adj.", "d": "Hasty, not thorough.", "c": "粗略的/草率的", "s": "He gave the report only a cursory glance before signing it.", "t": "他只草草瀏覽了一下報告就簽了名。", "as": "A cursory inspection failed to reveal the serious structural damage.", "at": "一次粗略的檢查未能發現嚴重的結構損壞。", "a": 1}]}, {"unit": 58, "theme": "Wealth and Luxury", "themeZh": "富有與奢華", "antonymLessons": [59], "cards": [{"w": "affluent", "p": "adj.", "d": "Rich.", "c": "富裕的", "s": "They live in an affluent neighborhood filled with large houses and expensive cars.", "t": "他們住在一個滿是豪宅與名車的富裕社區。", "as": "Her affluent parents paid for her entire college education.", "at": "她那富裕的父母支付了她全部的大學學費。"}, {"w": "opulent", "p": "adj.", "d": "Wealthy, luxurious, or lavish.", "c": "奢華的/富麗堂皇的", "s": "The opulent palace was filled with fine art and golden decor.", "t": "這座奢華的宮殿裡擺滿了精緻的藝術品與金色的裝飾。", "as": "The couple threw an opulent party to celebrate their anniversary.", "at": "這對夫妻舉辦了一場奢華的派對來慶祝他們的結婚週年。"}, {"w": "prosperous", "p": "adj.", "d": "Successful, especially financially.", "c": "繁榮的;興旺的", "s": "The town became increasingly prosperous after the railway was built.", "t": "這座城鎮在鐵路興建之後變得日益繁榮。", "as": "He built a prosperous business from a single small storefront.", "at": "他從一間小小的店面白手起家,建立了一份興旺的事業。"}, {"w": "lucrative", "p": "adj.", "d": "Producing a great deal of profit or monetary gain.", "c": "獲利豐厚的；有利可圖的", "s": "The software engineer received a highly lucrative job offer from a major silicon valley tech firm with attractive stock options.", "t": "這位軟體工程師收到了一家矽谷大型科技公司開出且附帶吸引人股票期權的「獲利豐厚的（高薪）」求職要約。", "as": "", "at": ""}, {"w": "sumptuous", "p": "adj.", "d": "Lavish:profligate=flamboyant=ostentatious.", "c": "奢華的/豪華的", "s": "The wedding featured a sumptuous feast with dishes from every continent.", "t": "這場婚禮準備了一場奢華的盛宴,菜色來自世界各大洲。", "as": "Guests were amazed by the hotel's sumptuousedecor and marble floors.", "at": "賓客們對這間飯店奢華的裝潢與大理石地板感到驚嘆。"}, {"w": "posh", "p": "adj.", "d": "Elegant and fashionable, especially associated with the upper class.", "c": "豪華的;上流的", "s": "They celebrated the anniversary at a poshedowntown restaurant.", "t": "他們在市中心一家豪華的餐廳慶祝這場週年紀念。", "as": "Her accent revealed she had attended a posh boarding school.", "at": "她的口音透露出她曾就讀一所上流的寄宿學校。"}, {"w": "abundance", "p": "n.", "d": "A very large quantity of something.", "c": "豐富；大量", "s": "The rainforest is home to an abundance of wildlife, with thousands of different species of birds, insects, and mammals living together in a relatively small area.", "t": "雨林是豐富野生動物的家園，成千上萬種不同的鳥類、昆蟲和哺乳動物生活在一個相對較小的區域內。", "as": "", "at": "", "a": 1}, {"w": "affluence", "p": "n.", "d": "The state of having a great deal of money; wealth.", "c": "富裕;財富", "s": "The neighborhood's sudden affluence was obvious from its newly paved streets and manicured lawns.", "t": "這個社區突然變得富裕,從新鋪的街道和修剪整齊的草坪就能看出來。", "as": "Despite his affluence , he still drove the same old car he had in college.", "at": "儘管他很富有,卻仍開著大學時代的那輛舊車。", "a": 1}, {"w": "opulence", "p": "n.", "d": "Wealth, riches.", "c": "財富/富裕", "s": "The palace was a stunning display of royal opulence.", "t": "這座宮殿展現出令人驚嘆的皇室富裕氣派。", "as": "Visitors were amazed by the sheer opulence of the ballroom's decorations.", "at": "訪客們對舞廳裝飾所展現的極致奢華感到驚嘆。", "a": 1}]}, {"unit": 59, "theme": "Poverty and Need", "themeZh": "貧窮與匱乏", "antonymLessons": [58], "cards": [{"w": "destitute", "p": "adj.", "d": "Impoverished, utterly lacking.", "c": "赤貧的/窮困潦倒的", "s": "The flood left thousands of families destitute and homeless.", "t": "這場洪水讓數千個家庭一貧如洗、無家可歸。", "as": "The charity provides food and shelter to the city's most destitute residents.", "at": "這個慈善機構為這座城市最貧困的居民提供食物與住所。"}, {"w": "indigent", "p": "adj.", "d": "Poor, needy.", "c": "貧困的", "s": "The charity provides free meals to indigent families in the community.", "t": "這個慈善機構為社區中的貧困家庭提供免費餐點。", "as": "The clinic offers free medical care to indigent patients.", "at": "這家診所為貧困的病患提供免費醫療服務。"}, {"w": "penury", "p": "n.", "d": "Poverty.", "c": "貧困/拮据", "s": "The family lived in penury after the factory closed.", "t": "工廠關閉後,這家人生活陷入了貧困。", "as": "He died in penury, despite once being one of the richest men in town.", "at": "儘管他曾是鎮上最富有的人之一,最終卻在貧困中去世。"}, {"w": "privation", "p": "n.", "d": "Lack of necessities.", "c": "匱乏", "s": "The soldiers endured great privationeduring the long, harsh winter.", "t": "士兵們在漫長嚴酷的冬天忍受著極大的匱乏。", "as": "Years of privation made the family especially careful with money.", "at": "多年的物資匱乏讓這個家庭在用錢方面格外謹慎。"}, {"w": "indigence", "p": "n.", "d": "A state of extreme poverty or destitution.", "c": "赤貧/窮困", "s": "The novel depicts the indigence of families living through the depression.", "t": "這部小說描繪了大蕭條時期家庭赤貧的生活景況。", "as": "The charity works to lift families out of indigence through job training.", "at": "這個慈善機構透過職業訓練,努力幫助家庭脫離赤貧。", "a": 1}, {"w": "deprivation", "p": "n.", "d": "The state of lacking basic necessities.", "c": "剝奪;匱乏", "s": "Years of deprivation left the refugees malnourished.", "t": "多年的匱乏使這些難民營養不良。", "as": "Sleep deprivation can seriously impair judgment.", "at": "睡眠剝奪會嚴重損害判斷力。", "a": 1}, {"w": "poverty-stricken", "p": "adj.", "d": "Poor enough to need help from others.", "c": "貧困潦倒的", "s": "Aid organizations rushed food and medicine to the poverty-stricken region.", "t": "救援組織急忙將糧食與藥品送往這個貧困地區。", "as": "She grew up in a poverty-stricken neighborhood but never lost her determination to succeed.", "at": "她在一個貧困的社區長大,卻從未失去成功的決心。", "a": 1}, {"w": "destitution", "p": "n.", "d": "Extreme poverty.", "c": "貧困/赤貧", "s": "The war left thousands of families in complete destitution.", "t": "這場戰爭讓數千個家庭陷入徹底的赤貧。", "as": "Charities are working to lift the region out of destitution.", "at": "慈善機構正努力使這個地區擺脫赤貧的境況。", "a": 1}, {"w": "squalid", "p": "adj.", "d": "Extremely dirty or unpleasant, especially due to poverty or neglect.", "c": "骯髒的;污穢不堪的", "s": "The inspectors found squalid conditions in the abandoned tenement.", "t": "這些檢查員在這棟廢棄的公寓裡發現了污穢不堪的環境。", "as": "Refugees were housed in squalid camps lacking basic sanitation.", "at": "難民們被安置在缺乏基本衛生設施、骯髒不堪的營區。", "a": 1}]}, {"unit": 60, "theme": "Permanent and Lasting", "themeZh": "永久與持久", "antonymLessons": [23], "cards": [{"w": "perennial", "p": "adj./n.", "d": "Lasting for a long or seemingly infinite time; recurring.", "c": "持久的;多年生的", "s": "Traffic remains a perennial problem in the growing city.", "t": "交通問題在這座日益發展的城市中始終是個長期難題。", "as": "She planted several perennial flowers that bloom every spring.", "at": "她種了好幾株每年春天都會開花的多年生植物。"}, {"w": "perpetual", "p": "adj.", "d": "Continuing forever or indefinitely.", "c": "永久的/不斷的", "s": "The con artist lived in perpetual fear of being arrested.", "t": "這名騙子一直活在隨時可能被逮捕的持續恐懼之中。", "as": "The city seems to be in a state of perpetual construction.", "at": "這座城市似乎永遠處於不斷施工的狀態。"}, {"w": "enduring", "p": "adj.", "d": "Continuing or lasting for a long time; durable.", "c": "持久的；長久的", "s": "Shakespeare's plays have maintained an enduring popularity across centuries due to their universal human themes.", "t": "莎士比亞的戲劇因其普世的人性主題，數世紀以來一直保持著「長久的（持久的）」受歡迎程度。", "as": "", "at": ""}, {"w": "immutable", "p": "adj.", "d": "Not changeable.", "c": "不可改變的/永恆的", "s": "The laws of physics are considered immutable across the universe.", "t": "物理定律被認為在整個宇宙中是不可改變的。", "as": "He believed his moral principles were immutable, regardless of circumstance.", "at": "他相信自己的道德原則無論在何種情況下都不可動搖。"}, {"w": "everlasting", "p": "adj.", "d": "Lasting forever; eternal.", "c": "永恆的;不朽的", "s": "They promised each other everlastingedevotion.", "t": "他們彼此承諾永恆不變的忠誠。", "as": "The monument was built as an everlasting tribute to the fallen soldiers.", "at": "這座紀念碑是為紀念陣亡將士而建的不朽致敬。"}, {"w": "eternal", "p": "adj.", "d": "Lasting or existing forever; without end.", "c": "永恆的", "s": "The couple vowed eternal love on their wedding day.", "t": "這對新人在婚禮上立下了永恆的愛的誓言。", "as": "Philosophers debated whether the soul was eternal .", "at": "哲學家們爭論靈魂是否永恆不朽。"}, {"w": "interminable", "p": "adj.", "d": "Unending.", "c": "無休止的", "s": "The meeting seemed interminable, dragging on for nearly four hours.", "t": "這場會議似乎沒完沒了,足足拖了將近四個小時。", "as": "The children complained about the interminable car ride to their grandparents' house.", "at": "孩子們抱怨著前往祖父母家那段無止盡的車程。"}, {"w": "timeless", "p": "adj.", "d": "Not affected by the passage of time; eternal.", "c": "永恆的;不受時間影響的", "s": "The novel explores timeless themes of love and loss.", "t": "這本小說探討了愛與失去這些永恆的主題。", "as": "Her classic design remains timelessedecades after it was created.", "at": "她的經典設計即使在創作數十年後,依然歷久彌新。", "a": 1}, {"w": "incessant", "p": "adj.", "d": "Continuing without pause or interruption.", "c": "不停的/持續不斷的", "s": "The incessant noise of the construction work made it hard to focus.", "t": "工地不停歇的噪音讓人難以專心。", "as": "Her incessant complaints eventually drove her roommate to move out.", "at": "她不停的抱怨最終讓她的室友決定搬走。", "a": 1}, {"w": "continual", "p": "adj.", "d": "Happening frequently, with intervals in between.", "c": "頻繁的;反覆的", "s": "The continual interruptions made it impossible to finish the report on time.", "t": "頻繁的打斷讓她根本不可能準時完成這份報告。", "as": "Their relationship was marked by continual arguments over money.", "at": "他們的關係因反覆為錢爭吵而蒙上陰影。", "a": 1}, {"w": "continuous", "p": "adj.", "d": "Without interruption; unbroken.", "c": "連續不斷的", "s": "The factory runs on a continuous production schedule, day and night.", "t": "這家工廠採用連續不斷的生產排程,日夜運作不停。", "as": "A continuous line of customers stretched around the block on opening day.", "at": "開幕當天,連綿不絕的排隊人潮繞了整個街區。", "a": 1}, {"w": "invariable", "p": "adj.", "d": "Never changing; constant.", "c": "不變的;固定的", "s": "His morning routine remained invariable for over a decade.", "t": "他早晨的例行程序十多年來始終不變。", "as": "The recipe calls for an invariable ratio of flour to water.", "at": "這份食譜要求麵粉與水維持固定不變的比例。", "a": 1}, {"w": "inveterate", "p": "adj.", "d": "Habitual, firmly established.", "c": "根深蒂固的/積習的", "s": "He is an inveterate gambler who can't resist a bet.", "t": "他是個積習難改的賭徒,無法抗拒下注的誘惑。", "as": "Her grandmother was an inveterate storyteller, always ready with a tale.", "at": "她的祖母是個說故事成癮的人,總是隨時準備好講一個故事。", "a": 1}, {"w": "stable", "p": "adj./n.", "d": "Firmly fixed or unlikely to change; a building for housing horses.", "c": "穩定的;馬廄", "s": "The doctor confirmed that the patient's condition was stable .", "t": "這位醫生確認這名病患的狀況已經穩定。", "as": "The old stable still housed three horses on the farm.", "at": "這座老舊的馬廄裡仍養著這座農場的三匹馬。", "a": 1}, {"w": "fixed", "p": "adj.", "d": "Firmly attached or established; not subject to change.", "c": "固定的", "s": "The shelf is fixed securely to the wall.", "t": "這個架子牢牢固定在牆上。", "as": "Prices remain fixed throughout the promotional period.", "at": "在這段促銷期間,價格維持固定不變。", "a": 1}, {"w": "constant", "p": "adj.", "d": "Occurring continuously.", "c": "持續不斷的", "s": "The criminal lived in constant fear that he'd be found out.", "t": "這名罪犯活在害怕被發現的持續恐懼中。", "as": "The engine produces a constant humming sound.", "at": "這台引擎會發出持續不斷的嗡嗡聲。", "a": 1}, {"w": "static", "p": "adj.", "d": "Not moving or changing; stationary.", "c": "靜態的;不變的", "s": "Sales figures remained static throughout the entire quarter.", "t": "銷售數字在整個季度中都維持不變。", "as": "The museum's staticedisplay contrasted with the interactive exhibits nearby.", "at": "這座博物館的靜態展示與附近的互動展覽形成對比。", "a": 1}, {"w": "chronic", "p": "adj.", "d": "Persisting for a long time or constantly recurring.", "c": "慢性的;長期的", "s": "She has managed her chronic back pain with physical therapy for years.", "t": "多年來,她靠物理治療控制自己慢性的背痛。", "as": "The city faces a chronic shortage of affordable housing.", "at": "這座城市長期面臨可負擔住房短缺的問題。", "a": 1}]}, {"unit": 61, "theme": "Rebellion and Disobedience", "themeZh": "反叛與違抗", "antonymLessons": [15], "cards": [{"w": "insurgent", "p": "n.", "d": "One who rebels.", "c": "叛亂分子/起義者", "s": "Government forces clashed with insurgents in the mountainous region.", "t": "政府軍與這些叛亂分子在這片山區發生衝突。", "as": "The former insurgent eventually became a respected member of parliament.", "at": "這位曾經的叛軍最終成為國會中受人尊敬的一員。"}, {"w": "seditious", "p": "adj.", "d": "Intended to incite rebellion against an established authority or government.", "c": "煽動叛亂的；煽動性的", "s": "The prosecutor argued that the posts were seditious and intended to spark an uprising.", "t": "檢察官主張這些貼文具有煽動叛亂性，意圖引發起義。", "as": "The regime banned printing presses to stop the spread of seditious pamphlets.", "at": "政權查禁印刷廠，以阻止煽動性小冊子流傳。"}, {"w": "defiant", "p": "adj.", "d": "Boldly resistant or challenging.", "c": "反抗的;挑釁的", "s": "The defiant teenager refused to follow the curfew.", "t": "這位反抗的青少年拒絕遵守門禁。", "as": "Workers took a defiant stand against the pay cuts.", "at": "工人們對減薪採取了強硬反抗的立場。"}, {"w": "renegade", "p": "n./adj.", "d": "A person who deserts a group or cause for another; rebellious.", "c": "叛徒;反叛的", "s": "The former officer became a renegade after exposing the agency's secrets.", "t": "這位前任軍官在揭露這個機構的秘密後成了一個叛徒。", "as": "A renegade faction split from the main political party.", "at": "一個反叛的派系從這個主要政黨中分裂了出去。"}, {"w": "dissident", "p": "n./adj.", "d": "A person who opposes official policy, especially in an authoritarian state.", "c": "異議人士;持不同政見的", "s": "The dissident was imprisoned for criticizing the regime.", "t": "這位異議人士因批評政權而遭到監禁。", "as": "Several dissident writers fled the country after the crackdown.", "at": "在這波鎮壓後,好幾位持不同政見的作家逃離了這個國家。"}, {"w": "iconoclast", "p": "n.", "d": "Image-breaker, attacker of beliefs.", "c": "反傳統者", "s": "The artist was known as an iconoclast who rejected traditional techniques.", "t": "這位藝術家以拒絕傳統技法、勇於打破常規而聞名。", "as": "He was seen as an iconoclast in a field that rarely welcomed new ideas.", "at": "在這個鮮少接納新想法的領域裡,他被視為一位打破傳統的革新者。"}, {"w": "recalcitrant", "p": "adj.", "d": "Stubborn; disobedient; defiant.", "c": "頑抗的", "s": "The recalcitrant student ignored every warning from the teacher.", "t": "這位頑抗的學生對老師的每一次警告都置之不理。", "as": "The recalcitrant committee blocked every proposed reform.", "at": "這個頑抗的委員會阻擋了每一項提出的改革方案。"}, {"w": "rebellious", "p": "adj.", "d": "Resisting authority or control.", "c": "反叛的;不服從的", "s": "The rebellious teenager refused to follow any of the house rules.", "t": "這個反叛的青少年拒絕遵守任何一項家規。", "as": "A rebellious faction broke away from the main political party.", "at": "一個反叛派系脫離了這個主要的政黨。", "a": 1}, {"w": "ungovernable", "p": "adj.", "d": "Impossible to control or restrain.", "c": "難以管束的;無法控制的", "s": "The toddler's ungovernable tantrums exhausted his parents.", "t": "這個幼兒難以管束的鬧脾氣讓他的父母筋疲力盡。", "as": "The region became increasingly ungovernable after the collapse of central authority.", "at": "在中央政府權威瓦解之後,這個地區變得越來越難以控制。", "a": 1}, {"w": "unmanageable", "p": "adj.", "d": "Difficult or impossible to control or handle.", "c": "難以管理的;難以駕馭的", "s": "The workload became unmanageable once two team members quit.", "t": "在兩名團隊成員離職後,這份工作量變得難以應付。", "as": "Her curly hair was unmanageable in the humid weather.", "at": "在這種潮濕的天氣裡,她的捲髮變得難以整理。", "a": 1}, {"w": "unruly", "p": "adj.", "d": "Disorderly and difficult to control.", "c": "難以駕馭的;不守規矩的", "s": "The teacher struggled to manage the unruly classroom.", "t": "這位老師在管理這個難以駕馭的班級時顯得很吃力。", "as": "Her unruly curls refused to stay in place all day.", "at": "她那難以馴服的捲髮整天都無法保持整齊。", "a": 1}, {"w": "restive", "p": "adj.", "d": "Resistant, stubborn, impatient.", "c": "焦躁不安的/難駕馭的", "s": "The restive crowd grew louder as the delayed concert failed to start.", "t": "隨著延遲的演唱會遲遲未能開始,這群焦躁的群眾變得越來越喧鬧。", "as": "The restive horse refused to stand still during the fitting.", "at": "這匹難以駕馭的馬在試穿馬具時不肯乖乖站定。", "a": 1}, {"w": "nonconformist", "p": "n.", "d": "A person whose behavior or views do not follow prevailing ideas or social standards.", "c": "不墨守成規的人；反傳統者", "s": "As a lifelong nonconformist, the writer rejected popular trends and published only on paper.", "t": "作為終身的反傳統者，這位作家拒絕流行趨勢，堅持只用紙本出版。", "as": "The startup was founded by a nonconformist who challenged every conventional corporate rule.", "at": "這家新創公司由一位挑戰所有傳統企業規則的非傳統人士創立。", "a": 1}, {"w": "traitorous", "p": "adj.", "d": "Guilty of or involving betrayal.", "c": "叛逆的;背叛的", "s": "The soldier was court-martialed for his traitorous actions.", "t": "這名士兵因他背叛的行為而遭到軍事審判。", "as": "Her traitorous alliance with the rival company shocked her longtime colleagues.", "at": "她與這家競爭公司背叛性的結盟讓她共事多年的同事們大感震驚。", "a": 1}, {"w": "insurrection", "p": "n.", "d": "A violent uprising against authority.", "c": "暴動;起義", "s": "The failed insurrection resulted in dozens of arrests.", "t": "這場失敗的起義導致了數十人被捕。", "as": "Historians still debate the causes of the insurrection .", "at": "歷史學家至今仍在爭論這場起義的成因。", "a": 1}, {"w": "revolt", "p": "n./v.", "d": "A rebellion against authority; to rise in rebellion.", "c": "叛亂;反抗", "s": "The peasant revolt spread quickly across the countryside.", "t": "這場農民叛亂迅速蔓延至整個鄉村地區。", "as": "Citizens began to revolt against the oppressive regime.", "at": "公民開始起身反抗這個壓迫性的政權。", "a": 1}, {"w": "sedition", "p": "n.", "d": "Speech or behavior intended to persuade people to rebel against state authority.", "c": "煽動叛亂；煽動性的言行", "s": "The rebel leader was charged with sedition after urging citizens to overthrow the king.", "t": "叛軍領袖因鼓動公民推翻國王而被控煽動叛亂。", "as": "The government claimed the underground newspaper promoted sedition.", "at": "政府聲稱該地下報紙宣揚煽動叛亂。", "a": 1}, {"w": "anarchist", "p": "n.", "d": "One who wants to eliminate all government.", "c": "無政府主義者", "s": "The anarchist believed that all forms of government were inherently oppressive.", "t": "這位無政府主義者認為一切形式的政府本質上都具有壓迫性。", "as": "Historians study the movement to understand what drew so many young people to become anarchists.", "at": "歷史學家研究這場運動,以了解為何有這麼多年輕人被吸引成為無政府主義者。", "a": 1}]}, {"unit": 62, "theme": "Loyalty and Devotion", "themeZh": "忠誠與奉獻", "antonymLessons": [63], "cards": [{"w": "fidelity", "p": "n.", "d": "Loyalty, devotion.", "c": "忠誠/忠實", "s": "The old soldier's fidelity to his country never wavered.", "t": "這位老兵對祖國的忠誠始終未曾動搖。", "as": "The translation stayed close to the original text with remarkable fidelity.", "at": "這篇翻譯以驚人的忠實度緊貼原文。"}, {"w": "steadfast", "p": "adj.", "d": "Firmly loyal or unwavering.", "c": "堅定不移的", "s": "She remained steadfast in her support despite mounting criticism.", "t": "儘管遭受越來越多批評,她仍堅定不移地表達支持。", "as": "His steadfastededication to the project impressed the entire board.", "at": "他對這項計畫堅定不移的奉獻精神讓整個董事會印象深刻。"}, {"w": "staunch", "p": "adj.", "d": "Strong, trusty, firm.", "c": "堅定的/忠誠的", "s": "She has always been a staunchedefender of workers' rights.", "t": "她一直是勞工權益的堅定捍衛者。", "as": "He remained a staunch ally even when the rest of the team gave up.", "at": "即使團隊其他人都放棄了,他依然是個忠誠堅定的盟友。"}, {"w": "faithful", "p": "adj.", "d": "Loyal and constant in affection or duty.", "c": "忠誠的", "s": "The dog remained faithful to its owner for fifteen years.", "t": "這隻狗對主人忠心耿耿了十五年。", "as": "She gave a faithful account of the events.", "at": "她提供了對這些事件忠實的描述。"}, {"w": "unswerving", "p": "adj.", "d": "Not changing or wavering; steady.", "c": "不動搖的;堅定不移的", "s": "His unswerving loyalty to the team never faltered, even in defeat.", "t": "即使在失敗時,他對這支隊伍不動搖的忠誠也從未減退。", "as": "She showed unswerving commitment to her research for over a decade.", "at": "她十多年來對自己的研究展現了堅定不移的投入。"}, {"w": "dutiful", "p": "adj.", "d": "Conscientiously fulfilling one's duty or obligations.", "c": "盡職的;孝順的", "s": "The dutiful son visited his parents every weekend.", "t": "這位孝順的兒子每個週末都會去看望父母。", "as": "A dutiful employee never misses a deadline.", "at": "盡職的員工絕不會錯過任何期限。", "a": 1}, {"w": "adherent", "p": "n.", "d": "Backer, supporter.", "c": "擁護者/信徒", "s": "The movement gained many adherents after the leader's inspiring speech.", "t": "在這位領袖發表激勵人心的演說之後,這場運動獲得了許多擁護者。", "as": "He remained a loyal adherent of the party throughout his life.", "at": "他一生都是這個政黨忠實的支持者。", "a": 1}]}, {"unit": 63, "theme": "Betrayal and Treachery", "themeZh": "背叛與不忠", "antonymLessons": [62], "cards": [{"w": "perfidious", "p": "adj.", "d": "Treacherous, false.", "c": "背信棄義的", "s": "The perfidious advisor secretly worked for the enemy kingdom.", "t": "這位背信棄義的謀士暗中為敵國效力。", "as": "History remembers him as a perfidious traitor who betrayed his closest allies.", "at": "歷史記得他是個背叛了最親密盟友的奸詐叛徒。"}, {"w": "traitor", "p": "n.", "d": "A person who betrays their country, cause, or trust.", "c": "叛徒", "s": "The general was branded a traitor for surrendering the fortress.", "t": "這位將軍因投降這座堡壘而被貼上了叛徒的標籤。", "as": "History remembers him as a traitor who sold secrets to the enemy.", "at": "歷史將他記載為向敵人出賣機密的叛徒。"}, {"w": "turncoat", "p": "n.", "d": "A person who deserts one party or cause for another.", "c": "叛徒;變節者", "s": "He was branded a turncoat after switching political parties overnight.", "t": "他一夜之間轉換政黨立場,因而被貼上叛徒的標籤。", "as": "The soldier was executed as a turncoat for aiding the enemy.", "at": "這名士兵因協助敵軍而被以叛徒罪名處決。"}, {"w": "apostate", "p": "n./adj.", "d": "A person who abandons their religious or political beliefs.", "c": "變節者;背教者", "s": "The former party leader was branded an apostate after joining the opposition.", "t": "這位前黨魁在加入反對黨後,被貼上變節者的標籤。", "as": "He lived the rest of his life as an apostate , cut off from his childhood church.", "at": "他往後的餘生都以背教者的身分度過,與童年的教會斷絕了關係。"}, {"w": "renegade", "p": "n./adj.", "d": "A person who deserts a group or cause for another; rebellious.", "c": "叛徒;反叛的", "s": "The former officer became a renegade after exposing the agency's secrets.", "t": "這位前任軍官在揭露這個機構的秘密後成了一個叛徒。", "as": "A renegade faction split from the main political party.", "at": "一個反叛的派系從這個主要政黨中分裂了出去。"}, {"w": "duplicitous", "p": "adj.", "d": "Deceitful; deliberately deceptive.", "c": "口是心非的;欺詐的", "s": "Her duplicitous behavior betrayed the trust of her closest friends.", "t": "她口是心非的行為背叛了摯友對她的信任。", "as": "The duplicitous salesman promised things he never intended to deliver.", "at": "這位欺詐的業務員承諾了他根本無意兌現的事。"}, {"w": "faithless", "p": "adj.", "d": "Disloyal or not trustworthy.", "c": "不忠的;不可靠的", "s": "The novel's faithless husband abandons his family.", "t": "這本小說裡不忠的丈夫拋棄了他的家人。", "as": "She felt betrayed by her faithless business partner.", "at": "她感到被這位不可靠的生意夥伴背叛了。"}, {"w": "perfidy", "p": "n.", "d": "Deliberate breach of faith or trust; treachery.", "c": "背信;奸詐行為", "s": "The spy's perfidy endangered the lives of his entire unit.", "t": "這位間諜的背信行為危及了整個部隊的性命。", "as": "The novel explores themes of loyalty and perfidyeduring wartime.", "at": "這本小說探討了戰時的忠誠與背信這兩個主題。"}, {"w": "dishonorable", "p": "adj.", "d": "Bringing shame or disgrace.", "c": "不名譽的;可恥的", "s": "The soldier received a dishonorabledischarge for his conduct.", "t": "這名士兵因其行為而遭受不名譽退伍的處分。", "as": "Breaking the promise was seen as a dishonorable act.", "at": "違背承諾被視為一種不名譽的行為。", "a": 1}, {"w": "disaffected", "p": "adj.", "d": "Rebellious, resentful of authority.", "c": "心懷不滿的/叛逆的", "s": "A group of disaffected workers organized a walkout over unfair wages.", "t": "一群心懷不滿的工人因薪資不公而組織了罷工。", "as": "The novel follows a disaffected teenager who rejects his family's values.", "at": "這部小說描述一位叛逆的青少年拒絕接受家族的價值觀。", "a": 1}]}, {"unit": 64, "theme": "Knowledge and Learning", "themeZh": "學識與博學", "antonymLessons": [65], "cards": [{"w": "erudite", "p": "adj.", "d": "Very scholarly.", "c": "博學的", "s": "The erudite professor could discuss any topic in world history.", "t": "這位博學的教授能夠談論世界歷史中的任何主題。", "as": "Her erudite commentary impressed even the most seasoned scholars.", "at": "她博學的評論連最資深的學者都感到印象深刻。"}, {"w": "pedantic", "p": "adj.", "d": "Excessively concerned with minor details or formal rules.", "c": "拘泥形式的;學究氣的", "s": "Her pedantic insistence on proper citation format frustrated the students.", "t": "她對正確引用格式學究氣的堅持讓學生們感到挫折。", "as": "The professor's pedantic lecture bored even his most attentive students.", "at": "這位教授拘泥形式的講課讓即使最專注的學生也感到無聊。"}, {"w": "learned", "p": "adj.", "d": "Having much knowledge acquired through study.", "c": "博學的", "s": "The learned professor was known for his encyclopedic knowledge.", "t": "這位博學的教授以其百科全書般的知識聞名。", "as": "A learned audience filled the lecture hall.", "at": "這間演講廳裡坐滿了博學的聽眾。"}, {"w": "sage", "p": "adj.", "d": "Wise, intelligent.", "c": "睿智的/聖人", "s": "The village turned to the old sage for guidance in troubled times.", "t": "在動盪時期,村民們向這位年長的智者尋求指引。", "as": "Her sage advice helped him avoid a costly mistake.", "at": "她明智的建議幫助他避免了一個代價高昂的錯誤。"}, {"w": "savant", "p": "n.", "d": "A learned person, especially one with detailed knowledge in a specific field.", "c": "博學之士;學者", "s": "He was regarded as a mathematical savant from a very young age.", "t": "他從很小的時候就被視為一位數學博學之士。", "as": "The museum consulted a local savant to authenticate the artifact.", "at": "這座博物館諮詢了一位當地的博學之士來鑑定這件文物的真偽。"}, {"w": "omniscient", "p": "adj.", "d": "Knowing, seeing, or understanding everything.", "c": "全知的/無所不知的", "s": "The novel is narrated by an omniscient voice that reveals every character's thoughts.", "t": "這部小說由一個全知的敘述者講述,揭露每個角色的內心想法。", "as": "Ancient myths often depicted their gods as omniscient beings.", "at": "古代神話經常將祂們的神祇描繪成全知全能的存在。"}, {"w": "cognizant", "p": "adj.", "d": "Aware.", "c": "認識到的", "s": "Drivers must remain cognizant of pedestrians when turning at intersections.", "t": "駕駛在路口轉彎時必須隨時意識到行人的存在。", "as": "She was fully cognizant of the risks before starting her own business.", "at": "在創業之前,她完全意識到其中的風險。"}, {"w": "educated", "p": "adj.", "d": "Having received formal instruction or training; informed.", "c": "受過教育的;有根據的", "s": "She made an educated guess based on the available data.", "t": "她根據現有的資料做出了一個有根據的猜測。", "as": "A well- educated workforce drives economic growth.", "at": "一支受過良好教育的勞動力能推動經濟成長。", "a": 1}, {"w": "cultured", "p": "adj.", "d": "Having refined taste and manners.", "c": "有文化教養的", "s": "The diplomat came across as cultured and well-traveled.", "t": "這位外交官給人的印象是有文化教養且見多識廣。", "as": "A cultured audience appreciated the opera's subtle humor.", "at": "有文化素養的觀眾欣賞這齣歌劇細膩的幽默。", "a": 1}, {"w": "cultivated", "p": "adj./v.", "d": "(of land) used for gardening or farming; grown.", "c": "耕種的；栽培的", "s": "Humans have cultivated rice for thousands of years, transforming wild grasses into a staple food crop that now supports nearly half of the world's population.", "t": "人類種植水稻已有數千年的歷史，將野生草類轉化為現在養活世界近一半人口的主糧作物。", "as": "", "at": "", "a": 1}, {"w": "enlightened", "p": "adj.", "d": "Having or showing a rational, modern, and well-informed outlook.", "c": "開明的;有見識的", "s": "The new policy reflects a more enlightened approach to education.", "t": "這項新政策反映出一種更開明的教育方針。", "as": "He was praised as an enlightened leader ahead of his time.", "at": "他被讚揚為一位超前時代的開明領袖。", "a": 1}, {"w": "pundit", "p": "n.", "d": "An expert commentator, especially in politics or media.", "c": "評論家;權威人士", "s": "Political pundit s debated the election results on live television.", "t": "政治評論家在電視直播中辯論這場選舉的結果。", "as": "The financial pundit predicted a downturn in the coming months.", "at": "這位財經評論家預測未來幾個月將會出現經濟衰退。", "a": 1}, {"w": "intellectual", "p": "adj./n.", "d": "Relating to the intellect; a person devoted to intellectual pursuits.", "c": "知識的;知識分子", "s": "The debate offered a stimulating intellectual challenge.", "t": "這場辯論提供了一次令人振奮的知識性挑戰。", "as": "She was regarded as one of the city's leading intellectual s.", "at": "她被視為這座城市頂尖的知識分子之一。", "a": 1}, {"w": "pedant", "p": "n.", "d": "A person who is overly concerned with minor details or rules.", "c": "拘泥細節的人;賣弄學問者", "s": "His colleagues saw him as a pedant obsessed with grammar rules.", "t": "他的同事視他為一個對文法規則過度執著的拘泥之人。", "as": "The pedant corrected every minor error in the casual conversation.", "at": "這位賣弄學問的人在這場閒談中糾正了每一個細微的錯誤。", "a": 1}]}, {"unit": 65, "theme": "Ignorance and Foolishness", "themeZh": "無知與愚蠢", "antonymLessons": [64], "cards": [{"w": "benighted", "p": "adj.", "d": "Lacking cultural or moral enlightenment; ignorant.", "c": "愚昧的;未開化的", "s": "The reformer worked to bring education to what he called the benighted countryside.", "t": "這位改革者致力於為他口中「愚昧」的鄉村地區帶來教育。", "as": "Later generations often view earlier eras as benighted , forgetting their own future critics.", "at": "後代常視前人的時代為愚昧無知,卻忘了自己也終將被後人如此評價。"}, {"w": "obtuse", "p": "adj.", "d": "Stupid; not clear or precise.", "c": "遲鈍的", "s": "It would be obtuse not to notice the tension in the room.", "t": "沒注意到房間裡的緊張氣氛,實在太遲鈍了。", "as": "His obtuse comments showed he hadn't understood the presentation at all.", "at": "他遲鈍不得要領的評論顯示他根本沒聽懂這場簡報。"}, {"w": "fatuous", "p": "adj.", "d": "Foolish, silly, inane.", "c": "愚蠢的/昏庸的", "s": "His fatuous comment revealed just how little he understood the issue.", "t": "他那句愚蠢的評論顯露出他對這個議題的理解有多麼淺薄。", "as": "It was a fatuous suggestion that no serious person would consider.", "at": "這是個荒唐愚蠢的建議,沒有任何認真的人會考慮。"}, {"w": "inane", "p": "adj.", "d": "Foolish.", "c": "愚蠢的", "s": "He asked such an inane question that the whole class started laughing.", "t": "他問了一個非常愚蠢的問題,全班都笑了出來。", "as": "The talk show is full of inane chatter about celebrities.", "at": "這個脫口秀節目充斥著關於名人的無聊蠢話。"}, {"w": "vacuous", "p": "adj.", "d": "Lack of content or ideas, stupid.", "c": "空洞的/愚蠢的", "s": "The politician's vacuous speech offered no real solutions to the crisis.", "t": "這位政治人物空洞的演說對這場危機沒有提出任何實質的解決方案。", "as": "Critics dismissed the film's dialogue as vacuous and forgettable.", "at": "評論家批評這部電影的對白空洞乏味,毫無記憶點。"}, {"w": "dolt", "p": "n.", "d": "A stupid person.", "c": "笨蛋;蠢材", "s": "Only a dolt would sign a contract without reading it.", "t": "只有笨蛋才會不讀合約內容就簽字。", "as": "He called himself a dolt for forgetting the appointment.", "at": "他因忘記約會而自嘲是個蠢材。"}, {"w": "simpleton", "p": "n.", "d": "A foolish or gullible person.", "c": "傻瓜;笨蛋", "s": "He felt like a simpleton for falling for such an obvious scam.", "t": "他因中了如此明顯的騙局而覺得自己像個笨蛋。", "as": "The fable's protagonist is a well-meaning simpleton who learns from his mistakes.", "at": "這則寓言的主角是個心地善良、卻從錯誤中學習的傻瓜。"}, {"w": "asinine", "p": "adj.", "d": "Stupid, silly.", "c": "愚蠢的", "s": "The plan struck everyone as completely asinine.", "t": "這項計畫在大家看來簡直愚蠢至極。", "as": "He made an asinine comment that embarrassed the whole team.", "at": "他說了一句愚蠢的話,讓整個團隊都感到尷尬。"}, {"w": "foolish", "p": "adj.", "d": "Lacking good sense; unwise.", "c": "愚蠢的", "s": "It would be foolish to ignore the warning signs.", "t": "無視這些警訊將會是愚蠢的行為。", "as": "She felt foolish after realizing her mistake.", "at": "意識到自己的錯誤後,她感到很愚蠢。", "a": 1}, {"w": "silly", "p": "adj.", "d": "Lacking seriousness or good sense; foolish.", "c": "愚蠢的;傻氣的", "s": "He felt silly for forgetting such an obvious detail.", "t": "他因忘記如此顯而易見的細節而感到有點傻。", "as": "The children played a silly game to pass the time.", "at": "孩子們玩了一個傻氣的遊戲來打發時間。", "a": 1}, {"w": "stupid", "p": "adj.", "d": "Lacking intelligence or good sense.", "c": "愚蠢的", "s": "It was a stupid mistake that could have easily been avoided.", "t": "那是一個原本可以輕易避免的愚蠢錯誤。", "as": "He felt stupid for forgetting his own phone number.", "at": "他因為忘記自己的電話號碼而覺得自己很蠢。", "a": 1}, {"w": "unenlightened", "p": "adj.", "d": "Lacking knowledge, understanding, or modern views.", "c": "未開化的;無知的", "s": "The policy reflected an unenlightened view of mental health treatment.", "t": "這項政策反映了對心理健康治療缺乏理解的觀點。", "as": "He was criticized for holding unenlightened opinions about gender roles.", "at": "他因抱持著關於性別角色未開化的觀點而受到批評。", "a": 1}, {"w": "witless", "p": "adj.", "d": "Lacking intelligence or good sense.", "c": "愚蠢的;無知的", "s": "The witlessedecision to skip the safety check nearly caused a disaster.", "t": "跳過安全檢查這個愚蠢的決定差點釀成一場災難。", "as": "He felt utterly witless when he realized his mistake in front of everyone.", "at": "當他在眾人面前意識到自己的錯誤時,他感到自己愚蠢至極。", "a": 1}, {"w": "senseless", "p": "adj.", "d": "Lacking meaning or purpose; unconscious.", "c": "無意義的;失去知覺的", "s": "The community mourned the senseless violence that claimed so many lives.", "t": "這個社區為這場奪走無數性命、毫無意義的暴力事件哀悼。", "as": "He was knocked senseless by the unexpected blow.", "at": "這突如其來的一擊讓他失去了知覺。", "a": 1}, {"w": "naive", "p": "adj.", "d": "Unworldly, unsophisticated.", "c": "天真的/幼稚的", "s": "It was naive of him to trust a stranger with his savings.", "t": "他把積蓄託付給一個陌生人,實在太天真了。", "as": "Her naive view of the world changed after she began traveling.", "at": "在她開始旅行之後,她對世界那種天真的看法就改變了。", "a": 1}, {"w": "gullible", "p": "adj.", "d": "Easily cheated or fooled.", "c": "易受騙的/輕信的", "s": "The scammer targeted gullible elderly people who trusted him instantly.", "t": "這名詐騙犯專門鎖定容易上當、立刻信任他的老年人。", "as": "She was gullible enough to believe the obviously fake email.", "at": "她輕信到相信了那封明顯是假的電子郵件。", "a": 1}, {"w": "absurd", "p": "adj.", "d": "Ridiculous.", "c": "荒謬的", "s": "It seemed absurd to cancel the picnic just because of one cloud.", "t": "僅僅因為一朵烏雲就取消野餐,似乎太荒謬了。", "as": "The lawyer called the accusation completely absurd.", "at": "這位律師稱這項指控完全是荒謬的。", "a": 1}, {"w": "ludicrous", "p": "adj.", "d": "So foolish or unreasonable as to be laughable.", "c": "荒謬可笑的", "s": "The idea of finishing the project in one day seemed ludicrous .", "t": "在一天內完成這項專案的想法似乎荒謬可笑。", "as": "He made a ludicrous claim that no one in the room believed.", "at": "他提出了一個房裡沒有人相信的荒謬可笑的說法。", "a": 1}]}, {"unit": 66, "theme": "Doubt and Skepticism", "themeZh": "懷疑與質疑", "antonymLessons": [67], "cards": [{"w": "skeptical", "p": "adj.", "d": "Doubting or questioning.", "c": "懷疑的", "s": "She remained skeptical of the results because the research hadn't been peer-reviewed or replicated.", "t": "她對結果仍持懷疑態度，因為這項研究尚未經過同儕審查或重複驗證。", "as": "", "at": ""}, {"w": "dubious", "p": "adj.", "d": "Doubtful.", "c": "可疑的", "s": "He gave a dubious excuse for why he was late to work.", "t": "他為自己上班遲到給了一個可疑的藉口。", "as": "The salesman made dubious claims about the product's benefits.", "at": "這名推銷員對產品的功效提出了可疑的說詞。"}, {"w": "incredulous", "p": "adj.", "d": "Skeptical:suspicious.", "c": "懷疑的/不輕信的", "s": "She gave an incredulous look when he claimed to have run a marathon in two hours.", "t": "當他宣稱自己兩小時內跑完馬拉松時,她露出懷疑的表情。", "as": "The audience remained incredulousedespite the magician's convincing trick.", "at": "儘管魔術師的把戲相當逼真,觀眾仍然半信半疑。"}, {"w": "cynical", "p": "adj.", "d": "Believing that all others are motivated by self-interest.", "c": "憤世嫉俗的", "s": "After years of disappointment, he became cynical about politicians' promises.", "t": "多年的失望讓他對政治人物的承諾變得憤世嫉俗。", "as": "Her cynical attitude made it hard for her to trust anyone's good intentions.", "at": "她那種憤世嫉俗的態度讓她很難相信任何人的善意。"}, {"w": "misgiving", "p": "n.", "d": "A feeling of doubt, worry, or fear about what may happen.", "c": "疑慮；擔憂", "s": "Despite a deep misgiving about the stability of the stock market, he invested half of his savings anyway.", "t": "儘管對股市穩定性深感疑慮，他最終還是決定投入自己一半的積蓄。", "as": "She handed the car keys to her teenage son with a serious misgiving about his reckless friends.", "at": "她帶著沉重的擔憂將車鑰匙遞給十幾歲的兒子，因為她知道他的朋友們十分魯莽。"}, {"w": "qualm", "p": "n.", "d": "Twinge of conscience.", "c": "疑慮/不安", "s": "He felt no qualm about breaking the minor rule.", "t": "他對違反這條小規定絲毫沒有感到良心不安。", "as": "She had a sudden qualm about accepting money from a stranger.", "at": "她突然對收下一個陌生人的錢感到一陣不安。"}, {"w": "wary", "p": "adj.", "d": "Watchful, shrewd.", "c": "機警的/謹慎的", "s": "She grew wary of strangers after the incident downtown.", "t": "市中心那起事件之後,她對陌生人變得十分警惕。", "as": "Investors remained wary of the volatile stock market.", "at": "投資人對波動劇烈的股市依然保持謹慎戒心。"}, {"w": "doubtful", "p": "adj.", "d": "Uncertain; feeling doubt.", "c": "懷疑的;不確定的", "s": "It remains doubtful whether the merger will succeed.", "t": "這次合併是否會成功仍不確定。", "as": "She looked doubtful about the plan's chances of success.", "at": "她對這項計畫的成功機率顯得存疑。", "a": 1}, {"w": "irresolute", "p": "adj.", "d": "Showing uncertainty or indecisiveness.", "c": "猶豫不決的", "s": "His irresolute leadership left the team without clear direction.", "t": "他猶豫不決的領導讓團隊失去了明確的方向。", "as": "She stood irresolute at the crossroads, unsure which path to take.", "at": "她站在十字路口猶豫不決,不知該走哪條路。", "a": 1}, {"w": "agnostic", "p": "adj.", "d": "Believing that the existence of God cannot be proven or disproven.", "c": "不可知論的", "s": "He describes himself as agnostic rather than atheist.", "t": "他形容自己是不可知論者,而非無神論者。", "as": "The philosopher remained agnostic about questions that science could not answer.", "at": "這位哲學家對科學無法解答的問題始終抱持不可知的態度。", "a": 1}]}, {"unit": 67, "theme": "Certainty and Conviction", "themeZh": "確信與堅信", "antonymLessons": [66], "cards": [{"w": "conviction", "p": "n.", "d": "A firmly held belief, or a formal judgment that someone is guilty of a crime.", "c": "堅定信念；確信；定罪", "s": "The abolitionist spoke with profound moral conviction and refused to compromise her ideals even when threatened with political retaliation.", "t": "這位廢奴主義者帶著深刻的道德信念演說，即使面臨政治報復威脅，也拒絕妥協理想。", "as": "Despite years of academic rejection, the scientist maintained his conviction that his unconventional energy theory would eventually change the world.", "at": "儘管多年遭學界拒絕，這位科學家仍堅信自己的非傳統能源理論終將改變世界。"}, {"w": "certitude", "p": "n.", "d": "Complete certainty or freedom from doubt.", "c": "確信；確定性；十足把握", "s": "Although the defense attorney argued persuasively, the prosecutor presented DNA evidence with absolute certitude, leaving the jury with no doubt about the defendant's guilt.", "t": "儘管辯護律師論證有力，檢察官仍以絕對確信提出 DNA 證據，使陪審團對被告有罪毫無疑問。", "as": "Economists predict market trends from historical data, but they admit that no one can forecast future stock values with complete certitude.", "at": "經濟學家根據歷史資料預測市場趨勢，但承認沒有人能以完全把握預測未來股票估值。"}, {"w": "unequivocal", "p": "adj.", "d": "Leaving no doubt; clear and unambiguous.", "c": "明確的/毫不含糊的", "s": "His response was unequivocal, leaving no room for misinterpretation.", "t": "他的回應非常明確,絲毫不留誤解的餘地。", "as": "The board gave an unequivocal endorsement of the new CEO.", "at": "董事會對這位新任執行長給予了明確無疑的支持。"}, {"w": "indubitable", "p": "adj.", "d": "Impossible to doubt; unquestionable.", "c": "無庸置疑的", "s": "Her talent was indubitable , even to her harshest critics.", "t": "即使是她最嚴厲的評論者也不得不承認她的才華無庸置疑。", "as": "The evidence provided indubitable proof of the theory.", "at": "這項證據提供了這個理論無庸置疑的證明。"}, {"w": "incontrovertible", "p": "adj.", "d": "Undeniable.", "c": "無可辯駁的/不容置疑的", "s": "The DNA test provided incontrovertible proof of his innocence.", "t": "DNA檢測提供了無可辯駁的證據,證明他的清白。", "as": "The data offers incontrovertible evidence that the climate is changing.", "at": "這些數據提供了氣候正在變遷的無可辯駁的證據。"}, {"w": "undeniable", "p": "adj.", "d": "Cannot be disputed.", "c": "不可否認的", "s": "Simone Biles' talent as a gymnast is undeniable.", "t": "西蒙·拜爾斯身為體操選手的天賦是不可否認的。", "as": "There is undeniable evidence linking smoking to lung disease.", "at": "有不可否認的證據將吸菸與肺部疾病連結在一起。"}, {"w": "dogmatic", "p": "adj.", "d": "Aggressively and arrogantly certain about unproved principles.", "c": "武斷的/教條式的", "s": "His dogmatic insistence on being right made compromise impossible.", "t": "他武斷地堅持自己是對的,使得妥協變得不可能。", "as": "The professor was too dogmatic to consider any opposing theory.", "at": "這位教授過於教條,無法考慮任何相反的理論。"}, {"w": "categorical", "p": "adj.", "d": "Absolute and unconditional; without exception.", "c": "絕對的;斷然的", "s": "The spokesperson issued a categoricaledenial of all the allegations.", "t": "發言人對所有指控發出了斷然的否認。", "as": "Her categorical refusal left no room for further negotiation.", "at": "她斷然的拒絕,讓後續已無協商的餘地。"}, {"w": "incontestable", "p": "adj.", "d": "Not able to be disputed; certain.", "c": "無可爭辯的;確鑿的", "s": "The evidence against him was incontestable .", "t": "對他不利的證據無可爭辯。", "as": "Her achievements in the field are incontestable .", "at": "她在這個領域的成就是無可爭辯的。", "a": 1}, {"w": "definitive", "p": "adj.", "d": "Conclusive and authoritative; final.", "c": "決定性的/權威的", "s": "The dictionary is the definitive source for spelling and definitions.", "t": "這本字典是拼字與釋義最權威的來源。", "as": "Scientists have yet to reach a definitive conclusion about the cause.", "at": "科學家們對於病因尚未得出決定性的結論。", "a": 1}, {"w": "demonstrable", "p": "adj.", "d": "Able to be shown or proven clearly.", "c": "可證明的", "s": "The new treatment showed demonstrable improvements in patient recovery.", "t": "這種新療法在病患康復方面顯示出可證明的進步。", "as": "Her claims were backed by demonstrable evidence.", "at": "她的說法有可證明的證據支持。", "a": 1}, {"w": "unimpeachable", "p": "adj.", "d": "Beyond doubt or reproach; unquestionable.", "c": "無可指摘的;不容置疑的", "s": "Her unimpeachable integrity made her the ideal candidate for the position.", "t": "她無可指摘的正直讓她成為這個職位的理想人選。", "as": "The witness provided unimpeachable evidence that settled the case.", "at": "這位證人提供了無可置疑的證據,使這起案件得以定案。", "a": 1}, {"w": "emphatic", "p": "adj.", "d": "Expressing something forcibly and clearly.", "c": "強調的;斷然的", "s": "Her emphaticedenial left no room for doubt.", "t": "她斷然的否認沒有留下任何懷疑的空間。", "as": "He gave an emphatic nod to show his agreement.", "at": "他用力點頭表示斷然的贊同。", "a": 1}, {"w": "confident", "p": "adj.", "d": "Feeling sure or self-assured.", "c": "有信心的", "s": "Michael Jordan is confident in his abilities as a basketball player.", "t": "麥可喬丹對自己身為籃球員的能力充滿信心。", "as": "She felt confident enough to give the presentation without notes.", "at": "她自信滿滿,足以不看筆記就完成這場簡報。", "a": 1}]}, {"unit": 68, "theme": "Luck and Good Fortune", "themeZh": "幸運與福氣", "antonymLessons": [69], "cards": [{"w": "fortuitous", "p": "adj.", "d": "Lucky, accidental.", "c": "偶然的/幸運的", "s": "Their meeting at the airport was entirely fortuitous, yet it changed both their lives.", "t": "他們在機場的相遇純屬偶然,卻改變了兩人的一生。", "as": "It was a fortuitous coincidence that the two old friends moved to the same city.", "at": "這兩位老朋友搬到同一座城市純屬幸運的巧合。"}, {"w": "serendipity", "p": "n.", "d": "The occurrence of finding something valuable or pleasant by happy accident.", "c": "意外收穫；幸運的巧合；緣分", "s": "The accidental discovery of penicillin is a famous example of serendipity.", "t": "盤尼西林的意外發現是幸運巧合的著名例子。", "as": "Meeting my childhood friend in a Paris café was pure serendipity.", "at": "在巴黎咖啡館偶遇童年好友，完全是幸運的巧合。"}, {"w": "auspicious", "p": "adj.", "d": "Favorable, indicative of good things.", "c": "吉利的/預示好兆頭的", "s": "The couple chose an auspiciousedate for their wedding according to tradition.", "t": "這對新人按照傳統選了一個吉利的日子舉行婚禮。", "as": "The company's strong first quarter was an auspicious sign for the year ahead.", "at": "這家公司強勁的第一季表現,為接下來的一年帶來了好兆頭。"}, {"w": "propitious", "p": "adj.", "d": "Favorable.", "c": "吉利的/有利的", "s": "The fortune teller said it was a propitious time to start a new business.", "t": "算命師說現在是創業的吉利時機。", "as": "Clear skies and calm winds made conditions propitious for the launch.", "at": "晴朗的天空與平靜的風勢使發射條件十分有利。"}, {"w": "felicitous", "p": "adj.", "d": "Happy.", "c": "恰當的/令人愉悅的", "s": "Her felicitous choice of words made the toast memorable.", "t": "她用詞恰到好處,讓這段祝酒詞令人難忘。", "as": "It was a felicitous coincidence that they met on the same flight.", "at": "他們竟然搭上了同一班飛機,真是個令人愉快的巧合。"}, {"w": "boon", "p": "n.", "d": "A gift or blessing.", "c": "恩惠/福音", "s": "The unexpected rain was a boon for the struggling farmers.", "t": "這場意外的降雨對苦苦掙扎的農民來說是一大福音。", "as": "New technology has been a boon to people with disabilities.", "at": "新科技對身心障礙者而言一直是一大福音。"}, {"w": "fortunate", "p": "adj.", "d": "Having good luck; favorable.", "c": "幸運的", "s": "She felt fortunate to have such supportive friends.", "t": "她覺得自己很幸運能有這麼支持她的朋友。", "as": "It was fortunate that the storm passed without much damage.", "at": "幸運的是,這場暴風雨過去後沒有造成太大的損害。"}, {"w": "advantageous", "p": "adj.", "d": "Beneficial or useful.", "c": "有利的", "s": "Speaking multiple languages is advantageous in today's job market.", "t": "在當今的就業市場上,會說多種語言是很有利的。", "as": "It would be advantageous for the company to expand into overseas markets.", "at": "對這家公司來說,拓展海外市場將會是有利的。", "a": 1}, {"w": "beneficial", "p": "adj.", "d": "Helpful, advantageous, or producing a good result.", "c": "有益的；有利的", "s": "Studies show that regular exercise combined with a balanced diet is highly beneficial to long-term cognitive health.", "t": "研究顯示，規律運動結合均衡飲食對長期的認知健康非常有益。", "as": "The two neighboring nations signed a trade agreement that was mutually beneficial to their economies.", "at": "這兩個鄰國簽署了一項對雙方經濟互利的貿易協定。", "a": 1}, {"w": "favorable", "p": "adj.", "d": "Showing approval or support; likely to lead to success or good results.", "c": "有利的/贊同的", "s": "The weather conditions were favorable for the outdoor event.", "t": "天氣條件對這場戶外活動十分有利。", "as": "Early reviews of the new restaurant have been overwhelmingly favorable.", "at": "這間新餐廳早期的評價幾乎一面倒地正面有利。", "a": 1}, {"w": "fortune", "p": "n.", "d": "Chance or luck; a large amount of money.", "c": "命運;財富", "s": "He made his fortune in the tech industry.", "t": "他在科技產業裡累積了財富。", "as": "A fortune teller predicted a change in her fortune .", "at": "一位算命師預言了她命運的轉變。", "a": 1}]}, {"unit": 69, "theme": "Disaster and Misfortune", "themeZh": "災難與不幸", "antonymLessons": [68], "cards": [{"w": "calamity", "p": "n.", "d": "An event with disastrous consequences.", "c": "災難/大禍", "s": "The flood was the greatest calamity the town had faced in a century.", "t": "這場洪水是這座城鎮一世紀以來所面臨的最大災難。", "as": "Losing his job right before the wedding felt like a personal calamity.", "at": "在婚禮前失業對他而言簡直是個人的一場大災難。"}, {"w": "catastrophe", "p": "n.", "d": "A sudden and widespread disaster.", "c": "大災難", "s": "The earthquake was the worst natural catastrophe the region had seen in decades.", "t": "這場地震是這個地區數十年來最嚴重的自然災難。", "as": "Missing the flight felt like a personal catastrophe at the time, though it hardly mattered a year later.", "at": "當下錯過班機感覺像是個人的一場大災難,但一年後根本無關緊要。"}, {"w": "cataclysm", "p": "n.", "d": "A large-scale, violent event causing great change or destruction.", "c": "大災變;劇變", "s": "The financial cataclysm of 2008 wiped out savings across the globe.", "t": "2008年的金融大災變,讓全球的存款一夕蒸發。", "as": "Geologists study ancient rock layers for evidence of past cataclysm.", "at": "地質學家研究古老的岩層,尋找過去發生大災變的證據。"}, {"w": "debacle", "p": "n.", "d": "Fiasco, catastrophe.", "c": "慘敗/崩潰", "s": "The product launch turned into a complete debacle.", "t": "這次產品發表會演變成一場徹底的慘敗。", "as": "The company is still recovering from last year's financial debacle.", "at": "這家公司至今仍在從去年那場財務慘敗中復原。"}, {"w": "fiasco", "p": "n.", "d": "Complete failure.", "c": "慘敗", "s": "The company's product launch turned into a complete fiasco.", "t": "這家公司的產品發表會演變成一場徹底的慘敗。", "as": "The disastrous performance was a fiasco that the actors wanted to forget.", "at": "這場災難般的演出是一場演員們都想遺忘的慘敗。"}, {"w": "catastrophic", "p": "adj.", "d": "Disastrous.", "c": "災難性的", "s": "The flood caused catastrophicedamage to homes along the river.", "t": "這場洪水對河岸邊的房屋造成了災難性的破壞。", "as": "A single mistake could have catastrophic consequences for the entire mission.", "at": "一個小錯誤就可能為整個任務帶來災難性的後果。"}, {"w": "dire", "p": "adj.", "d": "Fraught with extreme danger; nearly hopeless.", "c": "極度危急的/悲慘的", "s": "Doctors warned that the patient's condition was dire.", "t": "醫生警告這名病患的情況極為危急。", "as": "Without immediate aid, the refugees faced dire circumstances.", "at": "若無立即援助,這些難民將面臨極為悲慘的處境。"}, {"w": "ruinous", "p": "adj.", "d": "Causing or likely to cause ruin or disaster.", "c": "毀滅性的;災難性的", "s": "The company's ruinousedebt eventually forced it into bankruptcy.", "t": "這家公司毀滅性的債務最終迫使它走向破產。", "as": "A ruinous fire swept through the historic district overnight.", "at": "一場毀滅性的大火在一夜之間席捲了這個歷史街區。"}, {"w": "(wreak) havoc", "p": "n.", "d": "Ruin.", "c": "大破壞/浩劫", "s": "The hurricane wreaked (wreak) havoc on the small coastal town.", "t": "這場颶風對這座沿海小鎮造成了嚴重的破壞。", "as": "A single computer virus can wreak (wreak) havoc across an entire network.", "at": "一個電腦病毒就能對整個網路系統造成巨大的破壞。"}, {"w": "adversity", "p": "n.", "d": "Great trouble or difficulty.", "c": "逆境；不幸", "s": "She showed remarkable strength in the face of adversity.", "t": "面對逆境,她展現出驚人的堅強意志。", "as": "The team grew closer through shared adversityeduring the tough season.", "at": "在這個艱難的賽季中,這支隊伍因共同經歷的逆境而變得更加團結。"}, {"w": "disaster", "p": "n.", "d": "A sudden event causing great damage or suffering.", "c": "災難", "s": "The flood was the worst natural disaster in decades.", "t": "這場洪水是數十年來最嚴重的天災。", "as": "The failed launch turned into a public relations disaster .", "at": "這次失敗的發射變成了一場公關災難。", "a": 1}, {"w": "tragedy", "p": "n.", "d": "An event causing great suffering; a serious drama with an unhappy ending.", "c": "悲劇;慘劇", "s": "The earthquake was a tragedy that devastated the entire region.", "t": "這場地震是一場摧毀了整個地區的慘劇。", "as": "Shakespeare's greatest tragedy explores themes of ambition and guilt.", "at": "莎士比亞最偉大的悲劇探討了野心與罪惡感的主題。", "a": 1}, {"w": "mishap", "p": "n.", "d": "An unlucky accident or an unfortunate event, usually a minor one.", "c": "小災難；不幸事故；晦氣事", "s": "Despite a minor mishap in which the wedding cake went to the wrong venue, the reception was a grand success.", "t": "儘管發生了婚禮蛋糕被送到錯誤場地的小意外，婚宴最終依舊非常成功。", "as": "The expedition was delayed by an unfortunate mishap involving a lost passport and a flat tire.", "at": "這趟遠征因一次不幸的小意外而耽擱，包括護照遺失和輪胎爆胎。", "a": 1}, {"w": "cataclysmic", "p": "adj.", "d": "Relating to a large-scale, violent event.", "c": "劇變性的;大災變的", "s": "The volcano's cataclysmic eruption buried the entire city in ash.", "t": "這座火山劇變性的噴發,將整座城市埋在灰燼之下。", "as": "The company's bankruptcy had cataclysmic effects on the local economy.", "at": "這家公司的破產對當地經濟造成了劇變性的影響。", "a": 1}, {"w": "disastrous", "p": "adj.", "d": "Causing great damage, distress, or ruin; catastrophic.", "c": "災難性的；慘重的", "s": "Failing to backup digital financial records can lead to disastrous consequences if main server hard drives crash.", "t": "如果主要伺服器硬碟崩潰，未能備份數位財務記錄可能會導致「災難性的」後果。", "as": "", "at": "", "a": 1}, {"w": "woe", "p": "n.", "d": "Great sorrow or distress; trouble.", "c": "悲哀;苦難", "s": "The family endured years of financial woe after the factory closed.", "t": "這座工廠關閉後,這個家庭忍受了多年的財務困境。", "as": "She poured out her woe to a sympathetic friend.", "at": "她向一位善解人意的朋友傾訴了自己的悲傷。", "a": 1}, {"w": "accident", "p": "n.", "d": "An unfortunate mishap.", "c": "意外事故", "s": "The car accident on the highway caused a long traffic jam.", "t": "高速公路上的這起車禍造成了長時間的交通壅塞。", "as": "It was pure accident that the two old friends ran into each other at the airport.", "at": "這兩位老朋友在機場巧遇,純屬意外。", "a": 1}]}, {"unit": 70, "theme": "Lively and Energetic", "themeZh": "活潑與充滿活力", "antonymLessons": [14], "cards": [{"w": "vivacious", "p": "adj.", "d": "Lively.", "c": "活潑的/快活的", "s": "Her vivacious personality made her the life of every party.", "t": "她活潑開朗的個性讓她成為每場派對的靈魂人物。", "as": "The vivacious young actress charmed the entire audience.", "at": "這位活潑生動的年輕女演員迷倒了全場觀眾。"}, {"w": "animated", "p": "adj.", "d": "Lively.", "c": "生動的/活潑的", "s": "The children watched their favorite animated movie for the tenth time.", "t": "孩子們第十次觀看他們最喜歡的動畫電影。", "as": "Her animated storytelling kept the whole class engaged.", "at": "她生動活潑的說故事方式讓全班學生都聽得入迷。"}, {"w": "spirited", "p": "adj.", "d": "Full of energy, courage, or enthusiasm.", "c": "生氣勃勃的;精神飽滿的", "s": "The team put up a spiritededefense in the final quarter.", "t": "這支隊伍在最後一節展現了鬥志高昂的防守。", "as": "She gave a spirited speech that energized the entire crowd.", "at": "她發表了一場精神飽滿的演說,讓全場群眾振奮不已。"}, {"w": "dynamic", "p": "adj.", "d": "Energetic, forceful, or constantly changing and developing.", "c": "充滿活力的；動態的；不斷變化的", "s": "The technology market is highly dynamic, requiring companies to innovate constantly and adapt to rapidly changing consumer preferences.", "t": "科技市場高度動態，要求企業持續創新並適應快速變化的消費者偏好。", "as": "The novel's protagonist is a dynamic character whose moral values shift dramatically as he faces severe hardships throughout his journey.", "at": "小說主角是一名會發展變化的角色，他在旅程中面對艱難困苦時，道德價值觀也劇烈轉變。"}, {"w": "vigorous", "p": "adj.", "d": "Strong, healthy, and full of energy.", "c": "精力充沛的;強健的", "s": "He maintained a vigorous exercise routine well into his eighties.", "t": "他直到八十多歲仍維持著精力充沛的運動習慣。", "as": "The debate turned into a vigorous exchange of opposing views.", "at": "這場辯論演變成一場針鋒相對、活力十足的意見交流。"}, {"w": "sprightly", "p": "adj.", "d": "Lively and energetic, especially for an older person.", "c": "活潑的;生氣勃勃的", "s": "Despite her age, she remained remarkably sprightly and active.", "t": "儘管年事已高,她依然出奇地活潑且充滿活力。", "as": "The sprightly puppy bounded across the yard chasing butterflies.", "at": "這隻活潑的小狗在院子裡追著蝴蝶蹦蹦跳跳。"}, {"w": "effervescent", "p": "adj.", "d": "Lively; full of uplifted spirit; vivacious.", "c": "興高采烈的；冒泡的", "s": "Her effervescent personality made her the star of every party.", "t": "她那充滿活力、興高采烈的個性讓她成為每場派對的焦點。", "as": "The effervescent soda fizzed loudly as he opened the bottle.", "at": "他打開瓶子時,這瓶冒著氣泡的汽水發出響亮的嘶嘶聲。"}, {"w": "robust", "p": "adj.", "d": "Strong and healthy; vigorous; (of an economy) growing successfully.", "c": "強勁的；健壯的", "s": "The economist predicted robust growth for the upcoming quarter, citing strong consumer spending and low unemployment rates as indicators that the market was recovering quickly from the recession.", "t": "經濟學家預測下一季度將出現強勁的增長，理由是強勁的消費者支出和低失業率表明市場正在從衰退中迅速復甦。", "as": "", "at": ""}, {"w": "frisky", "p": "adj.", "d": "Lively and playful.", "c": "活潑好動的;嬉戲的", "s": "The frisky kittens chased each other around the room.", "t": "這些活潑好動的小貓在房間裡互相追逐。", "as": "Spring weather made the horses especially frisky .", "at": "春天的天氣讓這些馬兒格外活潑好動。", "a": 1}, {"w": "spry", "p": "adj.", "d": "Active and energetic, especially of an older person.", "c": "矯健的;敏捷的", "s": "Her spry grandmother still hikes every weekend.", "t": "她那身手矯健的祖母仍然每個週末都去健行。", "as": "The spry old cat leaped effortlessly onto the counter.", "at": "這隻矯健的老貓輕鬆一躍就跳上了流理台。", "a": 1}, {"w": "sparkling", "p": "adj.", "d": "Shining with flashes of light; lively and vivacious.", "c": "閃耀的;活潑的", "s": "They toasted the new year with a glass of sparkling wine.", "t": "他們舉起一杯氣泡酒,慶祝新年到來。", "as": "Her sparkling personality made her the life of every party.", "at": "她活潑的個性讓她成為每場派對的靈魂人物。", "a": 1}, {"w": "scintillating", "p": "adj.", "d": "Sparkling.", "c": "閃耀的/機智風趣的", "s": "Her scintillating wit made her the most sought-after guest at every dinner party.", "t": "她閃耀機智的談吐讓她成為每場晚宴上最受歡迎的賓客。", "as": "The scintillating chandelier cast a thousand tiny lights across the ballroom.", "at": "這座閃耀的水晶吊燈在舞廳灑下上千點細碎的光芒。", "a": 1}]}, {"unit": 71, "theme": "Shy and Modest", "themeZh": "害羞與謙遜", "antonymLessons": [3], "cards": [{"w": "bashful", "p": "adj.", "d": "Shy, excessively timid.", "c": "害羞的/靦腆的", "s": "The bashful boy hid behind his mother whenever a stranger spoke to him.", "t": "每當有陌生人跟他說話,這個害羞的男孩就會躲到媽媽身後。", "as": "Despite being famous, the actress remained surprisingly bashful in interviews.", "at": "儘管聲名遠播,這位女演員在訪談中依然出奇地靦腆。"}, {"w": "demure", "p": "adj.", "d": "Quiet, modest, reserved.", "c": "文靜的/端莊的", "s": "She gave a demure smile and looked away shyly.", "t": "她露出文靜的微笑,害羞地把目光移開。", "as": "Despite her demure appearance, she was known to be fiercely competitive.", "at": "儘管外表端莊文靜,她卻以好勝著稱。"}, {"w": "unassuming", "p": "adj.", "d": "Not pretentious or arrogant; modest.", "c": "謙遜的;不張揚的", "s": "Despite his fame, he remained remarkably unassuming and down-to-earth.", "t": "儘管聲名遠播,他依然出奇地謙遜且腳踏實地。", "as": "The restaurant had an unassuming exterior that hid its excellent food.", "at": "這家餐廳低調不張揚的外觀掩蓋了它美味的食物。"}, {"w": "humble", "p": "adj.", "d": "Modest or low estimate of one's importance.", "c": "謙遜的", "s": "Despite his success, he remained humble and approachable.", "t": "儘管取得成功,他依然保持謙遜且平易近人。", "as": "She gave a humble acceptance speech, thanking her entire team.", "at": "她發表了一段謙遜的獲獎感言,感謝她整個團隊。"}, {"w": "modest", "p": "adj.", "d": "Unassuming or humble in the estimation of one's abilities or achievements.", "c": "謙虛的/樸實的", "s": "Despite his many awards, he remained modest and humble.", "t": "儘管獲獎無數,他依然保持謙虛謙遜。", "as": "They live a modest lifestyle despite their considerable wealth.", "at": "儘管坐擁可觀的財富,他們仍過著樸實無華的生活。"}, {"w": "diffident", "p": "adj.", "d": "Shy, quiet, modest.", "c": "缺乏自信的/靦腆的", "s": "The diffident new student rarely spoke up in class.", "t": "這位缺乏自信的新生在課堂上很少發言。", "as": "Despite her talent, she remained diffident about sharing her artwork.", "at": "儘管才華洋溢,她對分享自己的作品仍顯得十分靦腆。"}, {"w": "meek", "p": "adj.", "d": "Quiet, gentle, and submissive.", "c": "溫順的;謙卑的", "s": "The meek new employee rarely spoke up in meetings.", "t": "這位溫順的新進員工在會議中很少發言。", "as": "Despite his meekedemeanor, he was fiercely determined.", "at": "儘管他表現得溫順謙和,內心卻異常堅定。"}, {"w": "reserved", "p": "adj.", "d": "Slow to reveal emotion or opinions; kept back for a particular purpose.", "c": "矜持的;預留的", "s": "Her reserved manner made her difficult to get to know at first.", "t": "她矜持的態度讓人一開始很難認識她。", "as": "A table had been reserved for them near the window.", "at": "靠窗的一張桌子已為他們預留好了。"}, {"w": "subdued", "p": "adj.", "d": "Lacking liveliness; quiet and restrained.", "c": "柔和的;抑制的", "s": "The room had a subdued atmosphere after the disappointing news.", "t": "在這則令人失望的消息之後,這個房間裡瀰漫著低沉的氣氛。", "as": "She spoke in a subdued tone out of respect for the mourners.", "at": "出於對這些哀悼者的尊重,她以柔和克制的語氣說話。", "a": 1}, {"w": "standoffish", "p": "adj.", "d": "Reserved, cold, or distant in manner.", "c": "冷淡的;疏遠的", "s": "Her standoffishedemeanor made her hard to approach at first.", "t": "她冷淡疏遠的態度讓她起初讓人難以親近。", "as": "New coworkers found him standoffish until they got to know him better.", "at": "新同事一開始覺得他很冷淡,直到更了解他之後才改觀。", "a": 1}, {"w": "prim", "p": "adj.", "d": "Stiffly formal and correct; disapproving of impropriety.", "c": "拘謹的;一本正經的", "s": "The prim schoolteacher never tolerated slouching in her classroom.", "t": "這位拘謹古板的老師從不容忍學生在她的教室裡懶散地坐著。", "as": "Her prim manners contrasted sharply with her sister's carefree attitude.", "at": "她一本正經的舉止與她妹妹無拘無束的態度形成鮮明對比。", "a": 1}, {"w": "decorous", "p": "adj.", "d": "Socially proper, appropriate.", "c": "得體的/合乎禮儀的", "s": "Guests were expected to maintain decorous behavior at the formal dinner.", "t": "賓客們在這場正式晚宴上被期望保持得體的舉止。", "as": "Her decorous manner impressed even the strictest etiquette instructor.", "at": "她合乎禮儀的舉止,連最嚴格的禮儀老師都印象深刻。", "a": 1}, {"w": "unsociable", "p": "adj.", "d": "Not enjoying the company of others; withdrawn.", "c": "不善社交的;孤僻的", "s": "He grew increasingly unsociable after retiring from his job.", "t": "他退休後變得越來越不善社交。", "as": "Her unsociable nature made group projects particularly stressful for her.", "at": "她孤僻的性格讓團體專案對她來說特別有壓力。", "a": 1}]}, {"unit": 72, "theme": "Kindness and Compassion", "themeZh": "仁慈與同情", "antonymLessons": [11], "cards": [{"w": "compassionate", "p": "adj.", "d": "Feeling or showing sympathy and concern for others.", "c": "有同情心的;仁慈的", "s": "The nurse's compassionate care comforted patients during their most difficult moments.", "t": "護理師富有同情心的照顧,在病人最艱難的時刻給予他們安慰。", "as": "He responded to the criticism with a surprisingly compassionate letter rather than anger.", "at": "面對批評,他以一封出乎意料充滿同情心的信回應,而非憤怒。"}, {"w": "benevolent", "p": "adj.", "d": "Kind, generous, and willing to help others.", "c": "仁慈的；慈善的", "s": "The wealthy industrialist was known for his benevolent nature, donating millions to fund public libraries.", "t": "這位富有的實業家以其仁慈的本性而聞名，捐贈了數百萬美元來資助公共圖書館。", "as": "The ruler's benevolent policies significantly improved the standard of living for the lower class.", "at": "這位統治者的仁政顯著改善了底層階級的生活水準。"}, {"w": "humane", "p": "adj.", "d": "Showing compassion and benevolence.", "c": "人道的;仁慈的", "s": "The shelter promotes humane treatment of all animals.", "t": "這座收容所提倡對所有動物採取人道的對待方式。", "as": "They advocated for more humane prison conditions.", "at": "他們主張改善監獄環境,使其更加人道。"}, {"w": "magnanimous", "p": "adj.", "d": "Noble, generous.", "c": "寬宏大量的", "s": "The winning team was magnanimous in victory, praising their opponents.", "t": "獲勝的隊伍在勝利時展現出寬宏大量,對對手大加讚賞。", "as": "It was magnanimous of her to forgive him so quickly.", "at": "她這麼快就原諒了他,實在是非常寬宏大量。"}, {"w": "clement", "p": "adj.", "d": "Mild or merciful, especially of weather or judgment.", "c": "溫和的;仁慈的", "s": "The judge showed a clement attitude toward the first-time offender.", "t": "法官對這位初犯者展現了仁慈的態度。", "as": "Farmers hoped for clement weather during the harvest season.", "at": "農民們期盼收穫季節能有溫和宜人的天氣。"}, {"w": "lenient", "p": "adj.", "d": "Permissive, merciful, or tolerant.", "c": "寬容的/仁慈的", "s": "The teacher was lenient with late assignments, understanding students' challenges.", "t": "這位老師對遲交作業採取寬容的態度,體諒學生面臨的困難。", "as": "The judge decided to be more lenient given the defendant's clean record.", "at": "考量到被告的清白紀錄,法官決定從寬處理。"}, {"w": "merciful", "p": "adj.", "d": "Showing compassion or forgiveness toward others.", "c": "仁慈的;寬容的", "s": "The judge was merciful in sentencing the first-time offender.", "t": "這位法官在判決這名初犯時展現了仁慈之心。", "as": "A merciful ruler pardoned the rebels instead of executing them.", "at": "一位仁慈的統治者赦免了這些叛軍,而非將他們處決。"}, {"w": "altruistic", "p": "adj.", "d": "Unselfish.", "c": "利他的/無私的", "s": "Her altruisticedecision to donate a kidney to a stranger amazed everyone.", "t": "她無私地決定捐腎給一名陌生人,讓所有人都感到驚訝。", "as": "The charity relies on the altruistic efforts of hundreds of volunteers.", "at": "這個慈善機構仰賴數百名志工無私的付出。"}, {"w": "charitable", "p": "adj.", "d": "Generous in giving to those in need; kind and forgiving in judgment.", "c": "慈善的;寬容的", "s": "The foundation donates a significant portion of its profits to charitable causes.", "t": "這個基金會將相當大部分的利潤捐給慈善事業。", "as": "She tried to take a charitable view of her coworker's mistake.", "at": "她試著以寬容的態度看待同事的錯誤。"}, {"w": "benign", "p": "adj.", "d": "Gentle and harmless; not cancerous.", "c": "良性的；無害的；慈祥的", "s": "The patient felt an immense wave of relief when the doctor confirmed that the tumor was entirely benign.", "t": "當醫生證實腫瘤完全是良性時，病人感到無比的寬慰。", "as": "The old king possessed a benign expression that instantly put his anxious subjects at ease.", "at": "老國王有著慈祥的面容，這讓焦慮的臣民們立刻安心下來。"}, {"w": "philanthropy", "p": "n.", "d": "The practice of donating money or resources to help others.", "c": "慈善事業", "s": "Her philanthropy funded scholarships for underprivileged students.", "t": "她的慈善事業資助了弱勢學生的獎學金。", "as": "Corporate philanthropy increased significantly after the disaster.", "at": "在這場災難之後,企業的慈善捐助大幅增加。", "a": 1}, {"w": "clemency", "p": "n.", "d": "Mercy.", "c": "寬容/仁慈", "s": "The governor granted clemency to the prisoner just days before his execution.", "t": "州長在這名囚犯行刑前幾天給予他減刑寬赦。", "as": "The judge showed rare clemency toward the young first-time offender.", "at": "法官對這名年輕的初犯展現了難得的寬容。", "a": 1}, {"w": "empathy", "p": "n.", "d": "Sensitivity to another's feelings as if they were one's own.", "c": "同理心", "s": "Good nurses show great empathy toward their patients' fears.", "t": "優秀的護理師對病人的恐懼展現出高度的同理心。", "as": "Her empathy for the refugees inspired her to volunteer at the shelter.", "at": "她對難民的同理心促使她到收容所擔任志工。", "a": 1}]}, {"unit": 73, "theme": "Beauty and Elegance", "themeZh": "美麗與優雅", "antonymLessons": [74], "cards": [{"w": "exquisite", "p": "adj.", "d": "Extremely beautiful or finely made.", "c": "精緻的;絕美的", "s": "The museum displayed an exquisite collection of ancient jade.", "t": "這座博物館展示了一批絕美的古代玉器收藏。", "as": "Her wedding dress was exquisite , down to the smallest detail.", "at": "她的婚紗精緻絕倫,連最小的細節都無可挑剔。"}, {"w": "resplendent", "p": "adj.", "d": "Shiny, glowing.", "c": "燦爛的/光輝奪目的", "s": "The bride looked resplendent in her embroidered silk gown.", "t": "新娘身穿刺繡絲質禮服,看起來光彩奪目。", "as": "The cathedral's dome was resplendent with gold mosaics.", "at": "這座大教堂的圓頂因金色馬賽克鑲嵌而燦爛奪目。"}, {"w": "elegant", "p": "adj.", "d": "Graceful and stylish in appearance or manner.", "c": "優雅的;精緻的", "s": "She wore an elegant gown to the gala.", "t": "她穿著一襲優雅的禮服出席這場盛會。", "as": "The mathematician found an elegant solution to the problem.", "at": "這位數學家找到了這個問題精緻優雅的解法。"}, {"w": "aesthetic", "p": "adj.", "d": "Having to do with artistic beauty.", "c": "美學的", "s": "The architect focused on both function and aesthetic appeal in her design.", "t": "這位建築師在設計中兼顧功能性與美學上的吸引力。", "as": "He has a keen aesthetic sense when it comes to interior design.", "at": "他在室內設計方面擁有敏銳的美感。"}, {"w": "ornate", "p": "adj.", "d": "Highly elaborate, excessively decorated.", "c": "華麗的/裝飾繁複的", "s": "The cathedral's ceiling featured ornate carvings of angels and saints.", "t": "這座大教堂的天花板飾有天使與聖徒的華麗雕刻。", "as": "Her ornate wedding gown was covered in hand-sewn pearls.", "at": "她那件華麗的婚紗上綴滿了手縫的珍珠。"}, {"w": "tasteful", "p": "adj.", "d": "Showing good judgment about beauty and style.", "c": "有品味的;高雅的", "s": "The couple decorated their home with tasteful , minimalist furniture.", "t": "這對夫妻用有品味的極簡家具裝飾了他們的家。", "as": "Her tasteful choice of colors impressed the entire design committee.", "at": "她高雅的用色選擇讓整個設計委員會印象深刻。", "a": 1}, {"w": "refined", "p": "adj.", "d": "Elegant and cultured; free from impurities.", "c": "精緻的;精煉的", "s": "Her refined taste in art impressed the museum curator.", "t": "她對藝術精緻的品味讓這位博物館策展人印象深刻。", "as": "The recipe calls for refined sugar rather than raw sugar.", "at": "這份食譜需要精製糖,而非原糖。", "a": 1}, {"w": "genteel", "p": "adj.", "d": "Polite, refined, or affectedly proper.", "c": "文雅的;上流的", "s": "She grew up in a genteel household with strict manners.", "t": "她在一個講究禮儀、上流的家庭中長大。", "as": "His genteel manner masked a ruthless business sense.", "at": "他文雅的舉止掩蓋了他無情的商業手腕。", "a": 1}, {"w": "dazzling", "p": "adj.", "d": "Extremely impressive or bright.", "c": "耀眼的;令人目眩的", "s": "Her dazzling performance earned a standing ovation.", "t": "她令人目眩神迷的表演贏得了全場起立鼓掌。", "as": "The fireworks created a dazzlingedisplay over the harbor.", "at": "煙火在港口上空綻放出耀眼的景象。", "a": 1}, {"w": "sublime", "p": "adj.", "d": "Lofty, grand, exalted.", "c": "崇高的/壯麗的", "s": "Standing atop the mountain, she felt a sublime sense of awe.", "t": "站在山頂上,她感受到一種崇高的敬畏之情。", "as": "The symphony's final movement was described by critics as truly sublime.", "at": "評論家將這首交響曲的終樂章形容為真正壯麗崇高的傑作。", "a": 1}]}, {"unit": 74, "theme": "Ugliness and Repulsiveness", "themeZh": "醜陋與令人厭惡", "antonymLessons": [73], "cards": [{"w": "grotesque", "p": "adj.", "d": "Strange, bizarre, misshapen.", "c": "奇形怪狀的/荒謬的", "s": "The gargoyles on the cathedral had grotesque faces.", "t": "這座大教堂上的滴水嘴獸有著奇形怪狀的臉孔。", "as": "The critics called the sculpture grotesque and unsettling.", "at": "評論家形容這座雕塑既怪誕又令人不安。"}, {"w": "repugnant", "p": "adj.", "d": "Distasteful, repulsive.", "c": "令人反感的", "s": "The idea of eating insects was repugnant to him.", "t": "吃昆蟲的想法讓他感到十分反感。", "as": "She found his dishonesty absolutely repugnant.", "at": "她覺得他的不誠實令人極度反感。"}, {"w": "repulsive", "p": "adj.", "d": "Arousing intense disgust.", "c": "令人厭惡的;排斥的", "s": "The rotting smell coming from the fridge was absolutely repulsive .", "t": "從冰箱裡飄出的腐臭味令人極度作嘔。", "as": "Audiences found the villain's cruelty genuinely repulsive .", "at": "觀眾對這個反派的殘忍感到真正的厭惡。"}, {"w": "loathsome", "p": "adj.", "d": "Causing hatred or disgust.", "c": "令人厭惡的", "s": "The critics called the film's villain utterly loathsome .", "t": "評論家們稱這部電影的反派角色極其令人厭惡。", "as": "His loathsome behavior at the party alienated everyone present.", "at": "他在派對上令人厭惡的行為讓在場所有人都對他敬而遠之。"}, {"w": "abhorrent", "p": "adj.", "d": "Detestable, despised.", "c": "令人厭惡的", "s": "Cruelty to animals is abhorrent to most people.", "t": "虐待動物的行為讓大多數人感到厭惡。", "as": "He found the idea of cheating on the exam utterly abhorrent.", "at": "他認為考試作弊的想法令人極度厭惡。"}, {"w": "odious", "p": "adj.", "d": "Loathsome; evil; revolting in a disgusting way.", "c": "可惡的", "s": "The senator's odious remarks about immigrants sparked outrage.", "t": "這位參議員對移民所發表的可惡言論引發了眾怒。", "as": "Cleaning the sewer was an odious task nobody wanted.", "at": "清理下水道是一項沒人願意做的令人厭惡的工作。"}, {"w": "detestable", "p": "adj.", "d": "Deserving intense dislike or hatred.", "c": "可憎的;令人厭惡的", "s": "His detestable manners embarrassed the whole family.", "t": "他令人厭惡的舉止讓全家人都感到尷尬。", "as": "The crime was described as detestable by everyone involved.", "at": "所有相關人士都稱這起罪行令人髮指。", "a": 1}, {"w": "disgusting", "p": "adj.", "d": "Causing intense distaste or revulsion.", "c": "令人厭惡的", "s": "The smell coming from the fridge was truly disgusting .", "t": "冰箱裡飄出的氣味實在令人作嘔。", "as": "She found his rude comments absolutely disgusting .", "at": "她覺得他無禮的評論非常令人厭惡。", "a": 1}, {"w": "obnoxious", "p": "adj.", "d": "Causing disapproval or protest.", "c": "令人討厭的/惹人反感的", "s": "His obnoxious jokes at the dinner party embarrassed everyone at the table.", "t": "他在晚宴上開的討人厭的玩笑讓在座每個人都感到尷尬。", "as": "The neighbor's obnoxious behavior finally led to a formal complaint.", "at": "這位鄰居惹人反感的行為最終導致了一份正式投訴。", "a": 1}, {"w": "repellent", "p": "adj./n.", "d": "Causing distaste or aversion; a substance that repels.", "c": "令人厭惡的;驅蟲劑", "s": "She found his arrogant behavior utterly repellent .", "t": "她認為他傲慢的行為令人極度厭惡。", "as": "They applied insect repellent before hiking through the forest.", "at": "他們在穿越這片森林健行前先擦了驅蟲劑。", "a": 1}, {"w": "objectionable", "p": "adj.", "d": "Causing disapproval or offense.", "c": "令人反感的;不妥的", "s": "The committee found several passages in the script objectionable .", "t": "委員會認為劇本中有幾段內容令人反感。", "as": "His objectionable behavior at the meeting embarrassed his colleagues.", "at": "他在會議上不妥的行為讓同事們感到尷尬。", "a": 1}, {"w": "vile", "p": "adj.", "d": "Extremely unpleasant or morally wrong.", "c": "卑鄙的;惡劣的", "s": "The crime was condemned as a vile act of cruelty.", "t": "這起犯罪被譴責為一項殘忍卑鄙的行為。", "as": "A vile smell filled the abandoned warehouse.", "at": "一股令人作嘔的惡臭瀰漫在這座廢棄的倉庫中。", "a": 1}, {"w": "nauseating", "p": "adj.", "d": "Causing a feeling of sickness or disgust.", "c": "令人作嘔的;噁心的", "s": "The nauseating smell from the dumpster forced them to close the window.", "t": "垃圾桶散發出的噁心臭味迫使他們關上窗戶。", "as": "His hypocrisy became nauseating to those who knew him best.", "at": "他的虛偽對最了解他的人來說變得令人作嘔。", "a": 1}, {"w": "monstrous", "p": "adj.", "d": "Extremely large, ugly, or shocking; morally repugnant.", "c": "巨大醜陋的;令人髮指的", "s": "A monstrous wave crashed over the ship's deck.", "t": "一道巨大駭人的海浪拍打在這艘船的甲板上。", "as": "The tribunal condemned the regime's monstrous crimes against civilians.", "at": "這個法庭譴責了這個政權對平民犯下的令人髮指的罪行。", "a": 1}]}, {"unit": 75, "theme": "Beginnings and Origins", "themeZh": "開始與起源", "antonymLessons": [76], "cards": [{"w": "inception", "p": "n.", "d": "The start, the beginning of something.", "c": "開端", "s": "The company has grown tremendously since its inception ten years ago.", "t": "自從十年前創立以來,這家公司已有了長足的發展。", "as": "He has led the project from its inception to its final launch.", "at": "他從這項計畫一開始就領導著它,直到最終上線。"}, {"w": "genesis", "p": "n.", "d": "The origin or beginning of something.", "c": "起源;創始", "s": "The company's genesis traces back to a small garage workshop.", "t": "這家公司的起源可以追溯到一間小車庫工作室。", "as": "The idea's genesis came from a casual conversation.", "at": "這個想法的起源來自於一次隨意的談話。"}, {"w": "nascent", "p": "adj.", "d": "Beginning to exist or develop.", "c": "初生的/新生的", "s": "The nascent tech industry in the city attracted young entrepreneurs.", "t": "這座城市裡剛起步的科技產業吸引了許多年輕創業家。", "as": "Her nascent interest in painting soon grew into a full-time career.", "at": "她對繪畫剛萌芽的興趣,不久後便發展成了全職事業。"}, {"w": "incipient", "p": "adj.", "d": "Just beginning to exist.", "c": "初期的", "s": "Doctors were able to treat the incipient stage of the disease before it spread.", "t": "醫生得以在疾病擴散之前治療這個初期階段。", "as": "The manager noticed incipient signs of conflict between the two employees.", "at": "經理注意到這兩名員工之間初現的衝突跡象。"}, {"w": "embryonic", "p": "adj.", "d": "In an early or undeveloped stage.", "c": "胚胎的;萌芽階段的", "s": "The project is still in its embryonic stages of planning.", "t": "這項計畫仍處於規劃的萌芽階段。", "as": "Doctors monitored the embryonicedevelopment closely.", "at": "醫生密切監測著這個胚胎的發育情況。"}, {"w": "initiate", "p": "v.", "d": "To start, get going.", "c": "開始/發起", "s": "The company plans to initiate a new training program next month.", "t": "這家公司計畫下個月啟動一項新的培訓計畫。", "as": "She was the first to initiate contact after the argument.", "at": "在那次爭吵之後,是她率先主動聯絡對方。"}, {"w": "rudimentary", "p": "adj.", "d": "Elementary, basic.", "c": "基本的", "s": "He only has a rudimentary understanding of how computers work.", "t": "他對電腦運作方式只有基本的了解。", "as": "The village still relies on rudimentary tools to farm the land.", "at": "這座村莊耕種土地時仍然依賴基本的工具。"}, {"w": "advent", "p": "n.", "d": "Arrival of an important event.", "c": "到來/出現", "s": "The advent of the internet changed how people communicate forever.", "t": "網際網路的出現徹底改變了人們溝通的方式。", "as": "Life in the village changed drastically after the advent of electricity.", "at": "電力出現之後,這座村莊的生活徹底改變了。"}, {"w": "onset", "p": "n.", "d": "The beginning or early stages.", "c": "開始/發作", "s": "At the onset of her career as a lawyer, things were looking up.", "t": "在她律師生涯剛起步的時候,一切看起來都很順利。", "as": "Doctors say early treatment can delay the onset of the disease.", "at": "醫生表示及早治療可以延緩這種疾病的發作。"}, {"w": "fledgling", "p": "n.", "d": "Little-known, newly developed.", "c": "無經驗的人/幼鳥", "s": "The fledgling company struggled to compete with established giants.", "t": "這家新興公司很難與根基穩固的巨頭競爭。", "as": "A fledgling fell from its nest during the storm.", "at": "一隻剛長羽毛的雛鳥在暴風雨中從巢裡掉了出來。"}, {"w": "outset", "p": "n.", "d": "The start, beginning, or initial stage of an event or journey.", "c": "開始；開端", "s": "The manager made it clear from the outset that everyone might need to work weekends.", "t": "經理從專案一開始就明確表示，每個人可能都需要在週末工作。", "as": "We encountered trouble at the outset of our trip when the car broke down outside the driveway.", "at": "旅程一開始我們就遇到麻煩，車子剛開出車道便故障了。", "a": 1}, {"w": "neophyte", "p": "n.", "d": "Someone who is young or inexperienced.", "c": "新手/初學者", "s": "As a neophyte in the field, she relied heavily on her mentor's guidance.", "t": "身為這個領域的新手,她十分仰賴導師的指導。", "as": "The veteran climbers patiently taught the neophytes basic safety techniques.", "at": "這些經驗豐富的登山者耐心地教導新手基本的安全技巧。", "a": 1}, {"w": "novice", "p": "n.", "d": "A beginner, someone without training or experience.", "c": "新手/初學者", "s": "As a novice skier, she stayed on the easier slopes all afternoon.", "t": "身為滑雪新手,她整個下午都待在較容易的坡道上。", "as": "The instructor patiently guided the novices through their first pottery lesson.", "at": "這位老師耐心地引導這些初學者上完第一堂陶藝課。", "a": 1}, {"w": "originate", "p": "v.", "d": "To begin, arise.", "c": "發源/創立", "s": "The rumor seemed to originate from a single anonymous post online.", "t": "這個謠言似乎源自於網路上一則匿名貼文。", "as": "The tradition is believed to originate in ancient China.", "at": "這項傳統據信起源於古代中國。", "a": 1}]}, {"unit": 76, "theme": "Endings and Finality", "themeZh": "結束與終結", "antonymLessons": [75], "cards": [{"w": "terminate", "p": "v.", "d": "To end.", "c": "終止", "s": "The company decided to terminate his contract after only three months.", "t": "這家公司在僅僅三個月後就決定終止他的合約。", "as": "The bus route will terminate at the main station downtown.", "at": "這條公車路線將在市中心的主要車站終止行駛。"}, {"w": "culminate", "p": "v.", "d": "To reach the highest point.", "c": "達到頂點", "s": "Years of hard work finally culminated in her promotion to director.", "t": "多年的努力最終在她升任總監時達到了頂點。", "as": "The festival will culminate in a spectacular fireworks display.", "at": "這場慶典將以一場壯觀的煙火秀作為最高潮。"}, {"w": "cessation", "p": "n.", "d": "A stopping.", "c": "停止", "s": "Both countries finally agreed to a cessation of hostilities after months of fighting.", "t": "經過數月的交戰,兩國終於同意停止敵對行動。", "as": "Doctors recommend the immediate cessation of smoking for anyone with heart disease.", "at": "醫生建議患有心臟病的人立刻停止吸菸。"}, {"w": "denouement", "p": "n.", "d": "The final resolution of the plot of a story.", "c": "結局;收場", "s": "The novel's denouement tied up every loose thread.", "t": "這本小說的結局收束了所有的伏筆。", "as": "Audiences were surprised by the film's quiet denouement .", "at": "觀眾對這部電影平靜的結局感到驚訝。"}, {"w": "abolish", "p": "v.", "d": "To formally put an end to a system, practice, or institution.", "c": "廢除", "s": "Reformers spent decades campaigning to abolish the unjust tax.", "t": "改革者花了數十年遊說廢除這項不公平的稅。", "as": "The new government promised to abolish the outdated curfew law.", "at": "新政府承諾將廢除那條過時的宵禁法規。"}, {"w": "consummate", "p": "adj.", "d": "Complete, of the highest degree.", "c": "圓滿的/技藝高超的", "s": "The violinist gave a consummate performance that left the audience speechless.", "t": "這位小提琴家獻上了一場技藝高超的演出,讓觀眾說不出話來。", "as": "He is a consummate professional who never misses a deadline.", "at": "他是個完美稱職的專業人士,從未錯過任何截止期限。"}, {"w": "culmination", "p": "n.", "d": "The climax toward which something progresses.", "c": "頂點/最高潮", "s": "The graduation ceremony marked the culmination of four years of hard work.", "t": "這場畢業典禮標誌著四年辛勤努力的最高潮。", "as": "The final battle scene is the culmination of the entire film.", "at": "最後的戰鬥場景是整部電影的高潮所在。", "a": 1}, {"w": "ultimate", "p": "adj.", "d": "Final.", "c": "最終的/極限的", "s": "Winning the championship was the team's ultimate goal all season.", "t": "贏得冠軍是這支隊伍整季以來最終的目標。", "as": "The ultimatedecision rests with the company's board of directors.", "at": "最終的決定權在於公司的董事會。", "a": 1}]}, {"unit": 77, "theme": "Agreement and Harmony", "themeZh": "一致與和諧", "antonymLessons": [78], "cards": [{"w": "concord", "p": "n.", "d": "Harmonious agreement.", "c": "和睦/協調", "s": "The two nations signed a treaty to promote lasting concord.", "t": "這兩個國家簽署了一項條約,以促進長久的和睦關係。", "as": "The committee finally reached concord after weeks of debate.", "at": "經過數週的辯論,委員會終於達成了共識。"}, {"w": "accord", "p": "n.", "d": "An agreement.", "c": "協議/一致", "s": "The two nations finally reached an accord after years of negotiation.", "t": "經過多年談判,這兩國終於達成了協議。", "as": "The peace accord ended decades of conflict between the two tribes.", "at": "這項和平協議結束了這兩個部族長達數十年的衝突。"}, {"w": "consensus", "p": "n.", "d": "General agreement.", "c": "共識", "s": "The team finally reached a consensus on the decision.", "t": "團隊終於就這項決定達成了共識。", "as": "Scientists have reached a broad consensus on the causes of climate change.", "at": "科學家們對氣候變遷的成因已達成廣泛的共識。"}, {"w": "concur", "p": "v.", "d": "To agree.", "c": "同意", "s": "The other doctors concurred with her diagnosis after reviewing the test results.", "t": "其他醫生在檢視檢驗結果後同意了她的診斷。", "as": "I concur with your opinion that the project needs more time.", "at": "我同意你的看法,這項專案需要更多時間。"}, {"w": "unanimous", "p": "adj.", "d": "Fully in agreement, especially by all members of a group.", "c": "一致同意的", "s": "The decision was unanimous, with everyone agreeing on the solution.", "t": "這項決定獲得了全體一致的同意,每個人都認同這個解決方案。", "as": "The jury reached a unanimous verdict after only two hours.", "at": "陪審團僅花了兩個小時就達成了一致的判決。"}, {"w": "harmony", "p": "n.", "d": "The state of forming a pleasing or consistent whole; agreement.", "c": "和諧;融洽", "s": "The community worked to restore harmony after the dispute.", "t": "社區努力在這場爭執後恢復和諧。", "as": "The choir sang in perfect harmony .", "at": "這個合唱團以完美的和聲演唱著。"}, {"w": "congruent", "p": "adj.", "d": "In agreement or harmony; identical in shape and size (geometry).", "c": "一致的;全等的(幾何)", "s": "Her actions were finally congruent with the values she preached.", "t": "她的行為終於與她宣揚的價值觀一致了。", "as": "The two triangles are congruent , with all corresponding sides and angles equal.", "at": "這兩個三角形是全等的,對應的邊與角皆相等。"}, {"w": "compatible", "p": "adj.", "d": "Harmonious, well-matched.", "c": "相容的/和諧的", "s": "The new software is compatible with most older computers.", "t": "這款新軟體與大多數舊型電腦相容。", "as": "Their personalities turned out to be surprisingly compatible.", "at": "他們的個性出乎意料地十分契合。"}, {"w": "consonant", "p": "adj.", "d": "In harmony.", "c": "一致的/和諧的", "s": "Her actions were entirely consonant with the values she preached.", "t": "她的行為與她所宣揚的價值觀完全一致。", "as": "The new policy is consonant with the company's long-term goals.", "at": "這項新政策與公司的長期目標一致。"}, {"w": "rapport", "p": "n.", "d": "Mutual understanding and harmony.", "c": "融洽關係/默契", "s": "The therapist quickly built rapport with her nervous new client.", "t": "這位治療師很快就和她緊張的新個案建立起融洽的關係。", "as": "Their instant rapport made the interview feel more like a friendly conversation.", "at": "他們之間立刻建立起的默契,讓這場訪談更像是一場友善的交談。"}, {"w": "assent", "p": "n./v.", "d": "Agreement or approval; to agree.", "c": "同意;贊同", "s": "The board gave its assent to the merger after weeks of debate.", "t": "經過數週的討論,董事會終於同意了這項合併案。", "as": "She reluctantly assent to her brother's plan.", "at": "她勉強同意了哥哥的計畫。"}, {"w": "unison", "p": "n.", "d": "Simultaneous action or speech, or voices sounding the same note at the same time.", "c": "一致；齊唱；同時行動", "s": "The students sang the opening verse in perfect unison before dividing into harmonies.", "t": "學生先完美齊唱開場歌詞，然後才分成不同聲部。", "as": "The soldiers marched in complete unison, their boots striking the ground together.", "at": "士兵步伐完全一致，靴子同時踏向地面。", "a": 1}, {"w": "congruous", "p": "adj.", "d": "Appropriate or in agreement with something.", "c": "相稱的;調和的", "s": "The modern addition was designed to be congruous with the historic building's style.", "t": "這棟現代增建的部分,經過設計以與這座歷史建築的風格相協調。", "as": "His calm response was entirely congruous with his usual demeanor.", "at": "他鎮定的回應,完全符合他一貫的作風。", "a": 1}, {"w": "congruity", "p": "n.", "d": "The quality of being in agreement.", "c": "一致性/協調", "s": "Editors checked the manuscript for congruity between the timeline and the plot.", "t": "編輯檢查了這份手稿的時間軸與情節是否一致。", "as": "There was a striking congruity between her values and her actions.", "at": "她的價值觀與行為之間有著驚人的一致性。", "a": 1}, {"w": "compatibility", "p": "n.", "d": "The state of being able to exist or work together harmoniously.", "c": "相容性;協調性", "s": "The couple's counselor focused on improving their emotional compatibility.", "t": "這對夫妻的諮商師,著重於改善他們情感上的協調性。", "as": "Before buying the software, check its compatibility with your current operating system.", "at": "在購買這套軟體前,請確認它與你目前作業系統的相容性。", "a": 1}, {"w": "amity", "p": "n.", "d": "Friendly relations, especially between nations.", "c": "友好關係;和睦", "s": "The treaty was meant to establish lasting amity between the two former rivals.", "t": "這項條約旨在讓兩個昔日的對手建立長久的友好關係。", "as": "The two departments finally worked in amity after months of conflict.", "at": "經過數月的衝突後,這兩個部門終於能和睦共事。", "a": 1}, {"w": "affinity", "p": "n.", "d": "A spontaneous feeling of closeness.", "c": "親近感/密切關係", "s": "She has always felt a strong affinity for animals.", "t": "她一直對動物有著強烈的親近感。", "as": "The two artists share a natural affinity for surrealist imagery.", "at": "這兩位藝術家對超現實主義的意象有著天生的親近感。", "a": 1}]}, {"unit": 78, "theme": "Disagreement and Conflict", "themeZh": "分歧與衝突", "antonymLessons": [77], "cards": [{"w": "discord", "p": "n.", "d": "Disagreement.", "c": "不和/紛爭", "s": "Disputes over money caused intense discord in the family.", "t": "金錢糾紛在這個家庭中造成了嚴重的不和。", "as": "The new policy sowed discord among the staff.", "at": "這項新政策在員工之間播下了不和的種子。"}, {"w": "dissent", "p": "v.", "d": "To differ, disagree, protest.", "c": "異議/不同意", "s": "Several board members chose to dissent from the majority decision.", "t": "有幾位董事會成員選擇對這項多數決議表示異議。", "as": "The judge's dissenting opinion argued the ruling was unconstitutional.", "at": "這位法官持不同意見,主張這項判決違憲。"}, {"w": "schism", "p": "n.", "d": "Split.", "c": "分裂/派系", "s": "A deep schism formed within the church over the new policy.", "t": "教會內部因這項新政策而產生了嚴重的分裂。", "as": "The schism between the two political factions grew wider every year.", "at": "這兩個政治派系之間的分裂每年都在擴大。"}, {"w": "rift", "p": "n.", "d": "Opening, split.", "c": "裂縫/不和", "s": "A political riftedivided the once-unified party.", "t": "一場政治分裂讓這個曾經團結一致的政黨產生了裂痕。", "as": "The disagreement created a lasting rift between the two brothers.", "at": "這場爭執在這對兄弟之間造成了一道長久的裂痕。"}, {"w": "strife", "p": "n.", "d": "Discord, disagreement.", "c": "衝突/爭吵", "s": "Years of political strife left the country deeply divided.", "t": "多年的政治衝突讓這個國家陷入深刻的分裂。", "as": "The inheritance sparked bitter strife among the siblings.", "at": "這筆遺產引發了兄弟姊妹之間激烈的爭執。"}, {"w": "incongruous", "p": "adj.", "d": "Out of place.", "c": "不協調的", "s": "The bright pink door looked incongruous against the plain gray building.", "t": "這扇亮粉色的門和樸素的灰色建築看起來很不協調。", "as": "His casual clothing seemed incongruous at such a formal event.", "at": "在如此正式的場合,他休閒的穿著顯得格格不入。"}, {"w": "contention", "p": "n.", "d": "A point asserted in an argument; heated disagreement.", "c": "論點;爭執", "s": "Her main contention was that the data had been misinterpreted from the start.", "t": "她的主要論點是,這些數據從一開始就被誤讀了。", "as": "The proposed budget cuts became a point of fierce contention at the meeting.", "at": "這項預算刪減提案,在會議上成了激烈爭執的焦點。"}, {"w": "controversy", "p": "n.", "d": "Disagreement, typical when prolonged or public.", "c": "爭議；辯論", "s": "The proposed municipal development project sparked intense controversy among local residents concerned about environmental damage.", "t": "擬議的市政開發項目，在擔心環境破壞的當地居民中引發了激烈的「爭議」。", "as": "", "at": "", "a": 1}, {"w": "altercation", "p": "n.", "d": "A dispute, fight.", "c": "爭吵/口角", "s": "A heated altercation broke out between the two drivers after the collision.", "t": "碰撞事故發生後,這兩名駕駛之間爆發了激烈的爭吵。", "as": "The neighbors' altercation over the property line lasted for months.", "at": "鄰居之間因地界問題引起的爭執持續了好幾個月。", "a": 1}, {"w": "quarrel", "p": "n.", "d": "An angry argument or dispute.", "c": "爭吵", "s": "The couple had a loud quarrel over money.", "t": "這對夫妻因金錢問題大聲爭吵。", "as": "The two brothers haven't spoken since their quarrel last year.", "at": "自從去年那次爭吵以後,這對兄弟就沒再說過話。", "a": 1}, {"w": "disharmony", "p": "n.", "d": "Lack of harmony or agreement.", "c": "不和諧;不協調", "s": "The merger created unexpected disharmony between the two teams.", "t": "這次合併在兩個團隊之間造成了意外的不和諧。", "as": "Musical disharmony in the final chord was intentional.", "at": "最後和弦中的音樂不協調是刻意為之的。", "a": 1}, {"w": "enmity", "p": "n.", "d": "Ill will, hatred, hostility.", "c": "敵意/仇恨", "s": "Decades of enmity between the two families finally came to an end.", "t": "這兩個家族間長達數十年的仇恨終於畫下句點。", "as": "The border dispute created lasting enmity between the neighboring countries.", "at": "這場邊界爭議在這兩個鄰國之間造成了長久的敵意。", "a": 1}, {"w": "polemic", "p": "n.", "d": "An aggressive argument against a specific opinion.", "c": "論戰/爭辯文章", "s": "The essay was less an analysis than a fiery polemic against government policy.", "t": "這篇文章與其說是分析,不如說是一篇對政府政策的激烈論戰。", "as": "His polemic against modern art sparked outrage among critics.", "at": "他抨擊現代藝術的論戰文章激起了評論家的憤怒。", "a": 1}, {"w": "disagree", "p": "v.", "d": "To hold a different opinion.", "c": "不同意;意見不合", "s": "The two economists disagree on the cause of inflation.", "t": "這兩位經濟學家對通膨的成因意見不合。", "as": "I have to disagree with your assessment of the situation.", "at": "我必須不同意你對這個情況的評估。", "a": 1}, {"w": "disagreement", "p": "n.", "d": "A difference of opinion.", "c": "意見分歧", "s": "An intense disagreement arose over the contract terms.", "t": "針對合約條款產生了激烈的意見分歧。", "as": "The siblings had a minor disagreement about where to go for dinner.", "at": "這對兄妹對於去哪裡吃晚餐有些小小的意見分歧。", "a": 1}, {"w": "wrangle", "p": "v./n.", "d": "To have a long, complicated dispute or argument.", "c": "爭吵;口角", "s": "The two siblings would wrangle constantly over who got to use the car.", "t": "這對兄妹經常為了誰能用車而爭吵不休。", "as": "The committee's wrangle over funding delayed the project for months.", "at": "這個委員會對資金的爭執讓這項計畫延誤了好幾個月。", "a": 1}]}, {"unit": 79, "theme": "Respect and Reverence", "themeZh": "尊敬與崇敬", "antonymLessons": [80], "cards": [{"w": "revere", "p": "v.", "d": "To honor, respect, admire.", "c": "尊崇/敬畏", "s": "Students revered their old professor for his wisdom and kindness.", "t": "學生們敬重這位老教授的智慧與仁慈。", "as": "The community continues to revere the founder of their town.", "at": "這個社區至今仍然十分敬重這座城鎮的創立者。"}, {"w": "venerate", "p": "v.", "d": "To honor or show deep respect for age or tradition.", "c": "尊崇", "s": "The community continues to venerate the founder of their temple.", "t": "這個社區至今仍持續尊崇這座寺廟的創立者。", "as": "Many cultures venerate their elders for their wisdom and experience.", "at": "許多文化都會因長者的智慧與經驗而尊崇他們。"}, {"w": "esteem", "p": "n.", "d": "Respect and admiration felt for a person or achievement.", "c": "尊敬；尊重", "s": "The retired professor was held in high esteem by generations of university students for her scholarly wisdom.", "t": "這位退休教授因其學術智慧而受到幾代大學生的崇高「尊敬」。", "as": "", "at": ""}, {"w": "deference", "p": "n.", "d": "Respectful submission to another's wishes or judgment.", "c": "順從;敬重", "s": "Out of deference to her elders, she waited to speak.", "t": "出於對長輩的敬重,她等待著發言。", "as": "The young lawyer showed great deference toward the senior judge.", "at": "這位年輕律師對資深法官表現出極大的敬重。"}, {"w": "homage", "p": "n.", "d": "Special honor or respect shown publicly.", "c": "致敬;敬意", "s": "The film pays homage to classic detective stories.", "t": "這部電影向經典偵探故事致敬。", "as": "Fans paid homage to the late musician at the memorial.", "at": "粉絲們在追思會上向這位已故音樂家致敬。"}, {"w": "reverence", "p": "n.", "d": "Deep respect for someone or something.", "c": "崇敬;敬畏", "s": "Visitors approached the ancient shrine with quiet reverence .", "t": "遊客們懷著靜默的崇敬走近這座古老的神殿。", "as": "Students regarded the retiring professor with genuine reverence .", "at": "學生們對這位即將退休的教授懷有真誠的崇敬。"}, {"w": "admire", "p": "v.", "d": "To respect or look up to.", "c": "欽佩/仰慕", "s": "I admire my mother's dedication to her work.", "t": "我很欽佩我母親對工作的奉獻精神。", "as": "Tourists gathered to admire the breathtaking view from the summit.", "at": "遊客們聚在一起,欣賞從山頂望去令人屏息的美景。"}, {"w": "exalt", "p": "v.", "d": "To hold someone or something in very high regard.", "c": "讚揚；高舉", "s": "Classical poetry often tends to artificially exalt the virtues of romantic love while ignoring its incredibly messy and complicated realities. It paints a picture of perfection that rarely exists in actual relationships.", "t": "古典詩歌往往傾向於人為地過度讚揚浪漫愛情的優點，而忽略了它極其混亂和複雜的現實。它描繪了一幅在實際關係中很少存在的完美圖景。", "as": "", "at": ""}, {"w": "veneration", "p": "n.", "d": "Great respect or reverence.", "c": "崇敬;敬仰", "s": "The temple was built as an act of veneration toward the ancient deity.", "t": "這座神廟是為了表達對這位古代神祇的崇敬而建造的。", "as": "Students spoke of their retired professor with genuine veneration .", "at": "學生們談起他們這位退休的教授時,語氣中充滿了真誠的敬仰。", "a": 1}, {"w": "adoration", "p": "n.", "d": "Deep love, respect, or worship.", "c": "崇拜;愛慕", "s": "The fans greeted their idol with unrestrained adoration.", "t": "粉絲們以毫無保留的崇拜迎接他們的偶像。", "as": "He gazed at the newborn with pure adoration.", "at": "他望著剛出生的孩子,眼神充滿純粹的愛慕。", "a": 1}, {"w": "approbation", "p": "n.", "d": "Praise.", "c": "讚許/認可", "s": "The young painter sought her mentor's approbation for every new piece.", "t": "這位年輕畫家每完成一幅新作品,都渴望得到導師的讚許。", "as": "The proposal received the committee's full approbation without a single objection.", "at": "這項提案獲得委員會全體一致的讚同,沒有任何異議。", "a": 1}, {"w": "dignity", "p": "n.", "d": "The state or quality of being worthy of honor or respect.", "c": "尊嚴；莊嚴", "s": "Elderly citizens deserve to live with comfort, respect, and dignity throughout their retirement years in society.", "t": "年長公民在社會上的退休歲月中，值得過著舒適、受尊重且保有「尊嚴」的生活。", "as": "", "at": "", "a": 1}]}, {"unit": 80, "theme": "Contempt and Scorn", "themeZh": "輕蔑與鄙視", "antonymLessons": [79], "cards": [{"w": "scorn", "p": "v.", "d": "To look down on with disdain.", "c": "輕蔑/鄙視", "s": "It's difficult for me not to scorn those who use improper grammar.", "t": "我很難不去輕視那些文法不正確的人。", "as": "She scorn anyone who gave up on their dreams too easily.", "at": "她鄙視那些輕易放棄夢想的人。"}, {"w": "disdain", "p": "n.", "d": "Contempt.", "c": "蔑視", "s": "She looked at the cheap gift with obvious disdain.", "t": "她帶著明顯的蔑視神情看著那份廉價的禮物。", "as": "He treated his younger coworkers with disdain, refusing to listen to their ideas.", "at": "他以蔑視的態度對待年輕同事,拒絕聽取他們的想法。"}, {"w": "derision", "p": "n.", "d": "Contemptuous ridicule or mockery.", "c": "嘲笑;譏諷", "s": "His idea was met with laughter and derision .", "t": "他的想法遭到了嘲笑與譏諷。", "as": "She endured years of derision before her theory was accepted.", "at": "在她的理論被接受之前,她忍受了多年的嘲諷。"}, {"w": "contemptuous", "p": "adj.", "d": "Expressing a feeling that something is worthless.", "c": "蔑視的", "s": "He gave a contemptuous laugh when I suggested he apologize.", "t": "當我建議他道歉時,他發出了輕蔑的笑聲。", "as": "Her contemptuous tone made it clear she thought the plan was foolish.", "at": "她輕蔑的語氣清楚表明她認為這個計畫很愚蠢。"}, {"w": "scoff", "p": "v.", "d": "To speak with contempt or derision about something.", "c": "嘲笑;譏諷", "s": "He tended to scoff at ideas he considered old-fashioned.", "t": "他總是傾向嘲笑他認為過時的想法。", "as": "Critics began to scoff at the film's implausible plot.", "at": "評論家開始譏諷這部電影不合情理的情節。"}, {"w": "spurn", "p": "v.", "d": "To reject with disdain or contempt.", "c": "蔑視拒絕;唾棄", "s": "She chose to spurn the lucrative offer for personal reasons.", "t": "她出於個人原因選擇蔑視拒絕這項高薪的提議。", "as": "He felt spurn ed when his proposal was dismissed without discussion.", "at": "他的提案未經討論就遭到否決,讓他感到被蔑視拒絕。"}, {"w": "flout", "p": "v.", "d": "To disregard.", "c": "嘲弄/無視", "s": "The company was fined for continuing to flout safety regulations.", "t": "這家公司因持續無視安全規範而遭到罰款。", "as": "He openly flouted the school's dress code every single day.", "at": "他每天都公然無視學校的服儀規定。"}, {"w": "despise", "p": "v.", "d": "To strongly dislike or look down upon.", "c": "鄙視/厭惡", "s": "The judge despisedishonesty.", "t": "這位法官厭惡不誠實的行為。", "as": "She has come to despise the sound of her own alarm clock.", "at": "她已經開始厭惡自己鬧鐘的聲音了。"}, {"w": "jeer", "p": "v./n.", "d": "To mock or taunt someone rudely.", "c": "嘲笑;奚落", "s": "The crowd began to jeer at the losing team.", "t": "群眾開始對這支輸球的隊伍嘲笑奚落。", "as": "He ignored the jeer s from the opposing fans.", "at": "他無視了對方球迷的嘲弄聲。"}, {"w": "mock", "p": "vb.", "d": "To make fun of; to imitate.", "c": "嘲笑", "s": "The other kids would mock him for his accent.", "t": "其他孩子總是嘲笑他說話的口音。", "as": "She hated being mocked for her unusual fashion choices.", "at": "她很討厭因自己與眾不同的穿衣風格而遭到嘲笑。"}, {"w": "ridicule", "p": "n./v.", "d": "Mockery or derision; to make fun of someone.", "c": "嘲笑;奚落", "s": "He endured years of ridicule before finally proving his critics wrong.", "t": "他忍受了多年的嘲笑,最終才證明批評他的人是錯的。", "as": "Classmates would ridicule him mercilessly for his stutter.", "at": "同學們曾毫不留情地嘲笑他的口吃。"}, {"w": "taunt", "p": "v./n.", "d": "To provoke or mock someone with insulting remarks.", "c": "嘲弄;奚落", "s": "Classmates would taunt him about his stutter until he switched schools.", "t": "同學們過去常常嘲弄他口吃的問題,直到他轉學為止。", "as": "The crowd hurled taunt s at the losing team.", "at": "群眾對這支落敗的隊伍發出了陣陣奚落。", "a": 1}, {"w": "repudiate", "p": "v.", "d": "To reject, decline.", "c": "拒絕/否認", "s": "The senator was forced to repudiate his earlier statement after public backlash.", "t": "這位參議員在遭到公眾強烈反對後,被迫收回先前的言論。", "as": "She decided to repudiate the contract after discovering the hidden fees.", "at": "她發現隱藏費用後,決定拒絕承認這份合約。", "a": 1}, {"w": "slight", "p": "adj./n./v.", "d": "Small in degree; a discourteous act or remark.", "c": "輕微的;怠慢", "s": "There was only a slight chance of rain that afternoon.", "t": "那天下午下雨的機率只有些微而已。", "as": "She felt it as a slight when she wasn't invited to the meeting.", "at": "沒被邀請參加這場會議讓她感覺受到了怠慢。", "a": 1}]}, {"unit": 81, "theme": "Chaos and Disorder", "themeZh": "混亂與失序", "antonymLessons": [], "cards": [{"w": "anarchy", "p": "n.", "d": "A state without government or effective control; disorder and confusion.", "c": "無政府狀態；混亂", "s": "Without a central government to enforce the law, the country rapidly descended into total anarchy.", "t": "在沒有中央政府執法的情況下，該國迅速陷入了完全的無政府混亂狀態。", "as": "The critics argued that the removal of trade regulations would create economic anarchy.", "at": "批評者認為，取消貿易管制將會造成經濟混亂。"}, {"w": "pandemonium", "p": "n.", "d": "Disorder, uproar.", "c": "大混亂/喧鬧", "s": "Pandemonium broke out in the stadium when the lights suddenly went off.", "t": "當燈光突然熄滅時,體育場內頓時陷入一片大亂。", "as": "The classroom descended into pandemonium once the fire alarm rang.", "at": "火警警報一響,教室裡立刻陷入一片混亂喧鬧。"}, {"w": "bedlam", "p": "n.", "d": "Uproar, confusion.", "c": "混亂/喧鬧", "s": "The stadium erupted into bedlam when the home team scored.", "t": "當主場球隊得分時,整座體育館陷入一片混亂喧鬧。", "as": "The classroom descended into bedlam the moment the teacher stepped out.", "at": "老師一離開教室,班上立刻陷入一片混亂。"}, {"w": "(wreak) havoc", "p": "n.", "d": "Ruin.", "c": "大破壞/浩劫", "s": "The hurricane wreaked (wreak) havoc on the small coastal town.", "t": "這場颶風對這座沿海小鎮造成了嚴重的破壞。", "as": "A single computer virus can wreak (wreak) havoc across an entire network.", "at": "一個電腦病毒就能對整個網路系統造成巨大的破壞。"}, {"w": "turmoil", "p": "n.", "d": "A very puzzling scenario or situation; tumult.", "c": "混亂", "s": "The country was thrown into turmoil after the sudden resignation of the president.", "t": "在總統突然辭職後,這個國家陷入了一片混亂。", "as": "Her personal life was in complete turmoileduring the divorce.", "at": "在離婚期間,她的個人生活陷入了徹底的混亂。"}, {"w": "upheaval", "p": "n.", "d": "A sudden, violent, or major change that causes disorder and uncertainty.", "c": "劇變；動盪；動亂；大變動", "s": "The sudden collapse of the currency triggered widespread economic upheaval and forced thousands of businesses into bankruptcy.", "t": "貨幣突然崩盤，引發廣泛的經濟動盪，迫使數千家企業破產。", "as": "Moving abroad as a teenager was a profound emotional upheaval for Marcus.", "at": "對馬庫斯而言，青少年時期移居國外是一次深刻的情感巨變。"}, {"w": "haphazard", "p": "adj.", "d": "Lacking organization or planning.", "c": "雜亂無章的/隨意的", "s": "The project was completed in a haphazard manner.", "t": "這項計畫是以雜亂無章的方式完成的。", "as": "Books were stacked in a haphazard pile across the floor.", "at": "書本雜亂無章地堆放在地板上。"}, {"w": "erratic", "p": "adj.", "d": "Not consistent or regular in pattern or behavior.", "c": "反覆無常的;不穩定的", "s": "His erraticedriving alarmed the other passengers.", "t": "他反覆無常的駕駛方式讓其他乘客感到驚慌。", "as": "The stock's erratic performance worried investors.", "at": "這支股票不穩定的表現讓投資人感到憂心。"}, {"w": "disordered", "p": "adj.", "d": "Lacking order; disturbed or confused.", "c": "混亂的;失調的", "s": "Papers lay disordered across his desk.", "t": "紙張散亂無序地堆滿他的桌面。", "as": "The patient exhibited signs of disordered thinking.", "at": "這位病患出現了思維混亂的跡象。", "a": 1}, {"w": "indiscriminate", "p": "adj.", "d": "Choosing at random without careful selection.", "c": "不加選擇的", "s": "The company's indiscriminate hiring policy led it to accept almost anyone who applied.", "t": "公司不加選擇的招聘政策導致幾乎所有應徵者都會被錄取。", "as": "The bombing caused indiscriminatedestruction, damaging homes, schools, and hospitals alike.", "at": "這場轟炸造成了不加選擇的破壞,住家、學校和醫院無一倖免。", "a": 1}, {"w": "frenzy", "p": "n.", "d": "Wild fit.", "c": "狂熱/狂暴", "s": "Shoppers were in a frenzy trying to grab the last discounted items.", "t": "購物者們陷入一陣狂熱,爭相搶奪最後的折扣商品。", "as": "The crowd worked itself into a frenzy as the concert was about to begin.", "at": "演唱會即將開始時,群眾陷入了一陣狂熱。", "a": 1}, {"w": "muddle", "p": "n./v.", "d": "A state of confusion; to mix up or confuse.", "c": "混亂;搞混", "s": "The instructions left her in a complete muddle .", "t": "這些說明讓她陷入了一團完全的混亂。", "as": "He tends to muddledates and names when telling stories.", "at": "他講故事時常常會把日期和人名搞混。", "a": 1}]}, {"unit": 82, "theme": "Necessary and Essential", "themeZh": "必要與不可或缺", "antonymLessons": [83], "cards": [{"w": "imperative", "p": "adj.", "d": "Urgent, necessary, compulsory.", "c": "必要的/命令的", "s": "It is imperative that we leave before the storm arrives.", "t": "我們必須在暴風雨來臨之前離開。", "as": "Getting enough sleep is imperative for good health.", "at": "充足的睡眠對健康而言是不可或缺的。"}, {"w": "requisite", "p": "n.", "d": "Requirement.", "c": "必需品/必要條件", "s": "She had all the requisite skills for the job.", "t": "她具備了這份工作所有必要的技能。", "as": "A valid passport is a requisite for international travel.", "at": "有效護照是國際旅行的必要條件。"}, {"w": "vital", "p": "adj.", "d": "Urgently necessary.", "c": "至關重要的", "s": "It is vital that you respond by the deadline.", "t": "你務必在截止期限前回覆,這一點至關重要。", "as": "Clean water is vital for human survival.", "at": "乾淨的水對人類的生存至關重要。"}, {"w": "integral", "p": "adj.", "d": "Essential.", "c": "不可或缺的/整體的", "s": "Trust is an integral part of any successful relationship.", "t": "信任是任何成功關係中不可或缺的一部分。", "as": "The engine is an integral component of the entire machine.", "at": "引擎是整部機器不可或缺的組成部分。"}, {"w": "obligatory", "p": "adj.", "d": "Required by law, rule, or custom.", "c": "義務的;必須的", "s": "Attendance at the safety briefing was obligatory for all new hires.", "t": "所有新進員工都必須出席這場安全講習。", "as": "The exchange of gifts had become an obligatory holiday tradition.", "at": "交換禮物已成為這個節日必不可少的傳統。"}, {"w": "mandatory", "p": "adj.", "d": "Required by law or rule.", "c": "強制的；義務的", "s": "Wearing helmets on motorcycles is mandatory in most countries for safety reasons.", "t": "出於安全考量，在大多數國家騎機車戴安全帽是強制規定。", "as": "", "at": "", "a": 1}, {"w": "intrinsic", "p": "adj.", "d": "Within itself, inherent.", "c": "內在的/固有的", "s": "The painting's value lies in its intrinsic beauty, not its price.", "t": "這幅畫的價值在於它本身固有的美,而非它的價格。", "as": "Curiosity seems to be an intrinsic trait in young children.", "at": "好奇心似乎是幼童與生俱來的特質。", "a": 1}, {"w": "paramount", "p": "adj.", "d": "Supreme, foremost.", "c": "首要的/至高無上的", "s": "Safety is of paramount importance during the construction project.", "t": "在這項建築工程中,安全是最重要的考量。", "as": "The judge ruled that the child's welfare was paramount.", "at": "法官裁定孩子的福祉是至高無上的考量。", "a": 1}]}, {"unit": 83, "theme": "Unnecessary and Excessive", "themeZh": "多餘與過度", "antonymLessons": [82], "cards": [{"w": "superfluous", "p": "adj.", "d": "Exceeding what is sufficient or necessary; extra.", "c": "多餘的；累贅的", "s": "The editor deleted several superfluous sentences from the essay to make the argument more direct and concise.", "t": "編輯從文章中刪除了幾句「多餘的（累贅的）」句子，使論點更加直接簡練。", "as": "", "at": ""}, {"w": "redundant", "p": "adj.", "d": "Not or no longer needed or useful; superfluous.", "c": "多餘的；累贅的", "s": "Automated manufacturing systems made many manual assembly line positions redundant , leading to workforce retraining initiatives.", "t": "自動化製造系統使得許多手動組裝線職位變得「多餘」，從而引發了勞動力再培訓計畫。", "as": "", "at": ""}, {"w": "gratuitous", "p": "adj.", "d": "Uncalled for, unwarranted.", "c": "無端的/不必要的", "s": "Critics felt the film included too much gratuitous violence.", "t": "評論家認為這部電影包含了過多不必要的暴力場面。", "as": "Her gratuitous insult left the whole room in awkward silence.", "at": "她那句毫無來由的侮辱讓整個房間陷入尷尬的沉默。"}, {"w": "extraneous", "p": "adj.", "d": "Not relevant or essential to the current subject; coming from outside.", "c": "無關的；多餘的；外來的", "s": "Delete any extraneous information that does not support the essay's main argument.", "t": "刪除任何無法支持文章主要論點的多餘資訊。", "as": "The judge told the attorney to stop introducing extraneousedrama that might confuse the jury.", "at": "法官要求律師停止加入可能混淆陪審團的無關戲劇化言論。"}, {"w": "surplus", "p": "n.", "d": "An amount left over after requirements have been met; an excess of supply.", "c": "剩餘；過剩；盈餘", "s": "The farm exported its large corn surplus to neighboring countries.", "t": "農場將大量剩餘玉米出口到鄰國。", "as": "The city used its budget surplus to repair public parks.", "at": "市政府利用預算盈餘修繕公園。"}, {"w": "excessive", "p": "adj.", "d": "More than what is necessary or reasonable.", "c": "過度的;過分的", "s": "The fine seemed excessive for such a minor offense.", "t": "對於這麼輕微的違規,這筆罰款似乎過重了。", "as": "Excessive screen time can affect children's sleep.", "at": "過度的螢幕使用時間可能會影響孩子的睡眠。", "a": 1}]}, {"unit": 84, "theme": "Old and Outdated", "themeZh": "古老與過時", "antonymLessons": [85], "cards": [{"w": "archaic", "p": "adj.", "d": "Out-of-date.", "c": "古老的/過時的", "s": "The law still contains several archaic terms rarely used today.", "t": "這項法律仍包含幾個如今幾乎不再使用的過時術語。", "as": "His archaic writing style made the essay hard to follow.", "at": "他古舊過時的寫作風格讓這篇文章很難讀懂。"}, {"w": "antiquated", "p": "adj.", "d": "Old-fashioned, outdated, or no longer useful.", "c": "陳舊的；過時的", "s": "The factory was forced to close because its antiquated machinery could no longer compete with modern technology.", "t": "這家工廠被迫關閉，因為其陳舊的機械設備已無法與現代技術競爭。", "as": "Many citizens argued that the government's voting system was antiquated and needed major reform.", "at": "許多公民認為政府的選舉投票制度過於過時，需要進行重大改革。"}, {"w": "obsolete", "p": "adj.", "d": "Old; outdated, as in no longer in use.", "c": "過時的", "s": "The old computer system became obsolete within just a few years.", "t": "這套舊電腦系統在短短幾年內就變得過時了。", "as": "Many manual jobs have been made obsolete by new technology.", "at": "許多人工工作已因新科技而被淘汰。"}, {"w": "anachronistic", "p": "adj.", "d": "Being out of correct chronological order.", "c": "時代錯置的", "s": "The film's costumes felt anachronistic, mixing medieval armor with modern sunglasses.", "t": "這部電影的服裝顯得時代錯置,把中世紀盔甲和現代太陽眼鏡混搭在一起。", "as": "Some critics find the novel's old-fashioned values anachronistic in a modern setting.", "at": "有些評論家認為這部小說裡老派的價值觀,放在現代背景下顯得不合時宜。"}, {"w": "outmoded", "p": "adj.", "d": "No longer fashionable or useful.", "c": "過時的;不合時宜的", "s": "The factory replaced its outmoded machinery with modern equipment.", "t": "這家工廠以現代設備汰換了過時的機械。", "as": "Some argue the tradition has become outmoded in today's society.", "at": "有些人認為這項傳統在現今社會已經變得不合時宜。"}, {"w": "passé", "p": "adj.", "d": "Outmoded, old-fashioned.", "c": "過時的", "s": "Wearing suits to the office is considered somewhat passé in tech companies.", "t": "在科技公司裡,穿西裝上班被認為有點過時。", "as": "Critics say the band's sound has become passé.", "at": "評論家表示這支樂團的音樂風格已經過時了。"}, {"w": "primeval", "p": "adj.", "d": "Original, ancient.", "c": "原始的/太古的", "s": "The documentary explores a primeval forest untouched by human hands for millennia.", "t": "這部紀錄片探索了一片數千年未被人類觸及的原始森林。", "as": "Scientists believe the fossils date back to a primeval era before complex life evolved.", "at": "科學家相信這些化石可追溯至複雜生命演化之前的太古時代。"}, {"w": "venerable", "p": "adj.", "d": "Respected, worshiped.", "c": "值得尊敬的/莊嚴的", "s": "The venerable old professor had taught at the university for fifty years.", "t": "這位德高望重的老教授已在這所大學任教五十年。", "as": "The temple is a venerable landmark visited by pilgrims for centuries.", "at": "這座寺廟是數百年來朝聖者前來參拜的莊嚴地標。"}, {"w": "ancient", "p": "adj.", "d": "Belonging to the very distant past; very old.", "c": "古代的;古老的", "s": "Archaeologists uncovered pottery from an ancient civilization beneath the desert sand.", "t": "考古學家在沙漠底下發現了一個古文明的陶器。", "as": "The village's ancient customs are still practiced during the harvest festival.", "at": "這個村莊古老的習俗至今仍在豐收節時保留著。", "a": 1}, {"w": "bygone", "p": "adj. / n.", "d": "Belonging to an earlier time; something that happened in the past.", "c": "過去的；以往的；往事", "s": "The museum displayed artifacts from a bygone era, offering a glimpse into daily life during the Renaissance.", "t": "博物館展示了來自過去時代的文物，讓人們得以一窺文藝復興時期的日常生活。", "as": "The philosopher urged his followers to leave each bygone conflict behind and focus entirely on future endeavors.", "at": "哲學家敦促追隨者放下每一段過往的衝突，全心專注於未來的努力。", "a": 1}, {"w": "defunct", "p": "adj.", "d": "No longer existing or functional.", "c": "不復存在的/已廢棄的", "s": "After people stopped using fax machines, the fax company became defunct.", "t": "在人們不再使用傳真機後,這家傳真機公司就停止營運了。", "as": "The once-popular website has been defunct for years.", "at": "這個曾經風靡一時的網站已經停止運作多年了。", "a": 1}, {"w": "obsolescent", "p": "adj.", "d": "Becoming disused or outdated.", "c": "逐漸過時的", "s": "The factory's obsolescent machinery was finally replaced last year.", "t": "這座工廠日漸過時的機器終於在去年被汰換了。", "as": "Fax machines have become largely obsolescent in most modern offices.", "at": "傳真機在大多數現代辦公室裡已經幾乎被淘汰。", "a": 1}, {"w": "moribund", "p": "adj.", "d": "Dying, at the point of death.", "c": "垂死的", "s": "The once-thriving mill town had become a moribund shell of its former self.", "t": "這座曾經繁榮的磨坊小鎮已淪為一具垂死的空殼。", "as": "Analysts described the industry as moribund, with no hope of recovery.", "at": "分析師形容這個產業已經奄奄一息,毫無復甦的希望。", "a": 1}, {"w": "vestige", "p": "n.", "d": "Evidence, trace.", "c": "遺跡/痕跡", "s": "A few crumbling walls were the only vestige of the ancient city.", "t": "幾面搖搖欲墜的殘牆是這座古城僅存的遺跡。", "as": "Not a single vestige of the old amusement park remained.", "at": "這座舊遊樂園沒有留下任何一絲痕跡。", "a": 1}]}, {"unit": 85, "theme": "New and Original", "themeZh": "新穎與原創", "antonymLessons": [84], "cards": [{"w": "novel", "p": "adj.", "d": "New or unusual in an interesting way.", "c": "新穎的", "s": "The scientist proposed a novel solution to the energy crisis, suggesting a method of harnessing solar power that had never been tested before but showed great promise.", "t": "科學家對能源危機提出了一個新穎的解決方案，建議了一種以前從未測試過但顯示出巨大潛力的利用太陽能的方法。", "as": "", "at": ""}, {"w": "innovative", "p": "adj.", "d": "Featuring new methods or ideas; original and creative.", "c": "創新的；革新的", "s": "The startup introduced an innovative business model that reduced operational costs while improving customer service.", "t": "這家初創公司推出了一種「創新的」商業模式，在改善客戶服務的同時降低了營運成本。", "as": "", "at": ""}, {"w": "unprecedented", "p": "adj.", "d": "Never done or known before; unparalleled.", "c": "史無前例的；前所未有的", "s": "Global temperature spikes this summer reached unprecedented levels that alarmed climate scientists worldwide.", "t": "今年夏天全球溫度的驟升達到了「史無前例的」水平，引發了全球氣候科學家的警惕。", "as": "", "at": ""}, {"w": "fresh", "p": "adj.", "d": "Newly produced or obtained; not stale.", "c": "新鮮的", "s": "She bought fresh vegetables from the farmers market.", "t": "她從農夫市集買了新鮮的蔬菜。", "as": "A fresh coat of paint transformed the old room.", "at": "一層新塗的油漆讓這個舊房間煥然一新。"}, {"w": "inventive", "p": "adj.", "d": "Having the ability to create or design new things or to think originally.", "c": "有創意的；獨具匠心的", "s": "The chef is known for his inventive approach to cooking, often combining unexpected ingredients from different cultures to create entirely new flavor profiles that surprise and delight diners.", "t": "這位廚師以其獨具匠心的烹飪方法而聞名，經常將來自不同文化的意想不到的食材結合在一起，創造出令食客驚喜和愉悅的全新風味。", "as": "", "at": ""}, {"w": "imaginative", "p": "adj.", "d": "Creative and full of new ideas.", "c": "富有想像力的", "s": "The artist's work is highly imaginative.", "t": "這位藝術家的作品極具想像力。", "as": "The children came up with an imaginative story about a dragon who loved to bake.", "at": "孩子們構思出一個充滿想像力的故事,講述一隻喜歡烘焙的龍。", "a": 1}, {"w": "unique", "p": "adj.", "d": "Being the only one of its kind; unusual.", "c": "獨特的;唯一的", "s": "Each snowflake has a unique crystalline pattern.", "t": "每一片雪花都有著獨特的結晶圖案。", "as": "Her unique perspective added value to the entire discussion.", "at": "她獨特的觀點為整場討論增添了價值。", "a": 1}, {"w": "creative", "p": "adj.", "d": "Involving original imagination or ideas.", "c": "有創意的", "s": "She found a creative solution to the budget problem.", "t": "她找到了一個對預算問題有創意的解決方案。", "as": "The class encourages creative thinking through open-ended projects.", "at": "這門課透過開放式的專題來鼓勵創意思考。", "a": 1}, {"w": "unconventional", "p": "adj.", "d": "Not based on or conforming to conventional or accepted standards.", "c": "非傳統的;不落俗套的", "s": "The architect was known for her bold, unconventionaledesigns.", "t": "這位建築師以她大膽、不落俗套的設計聞名。", "as": "He took an unconventional approach to solving the budget crisis.", "at": "他採取了一種非傳統的方式來解決這場預算危機。", "a": 1}, {"w": "newfound", "p": "adj.", "d": "Recently discovered or developed.", "c": "新發現的/新獲得的", "s": "The recently-released prisoner enjoyed his newfound freedom.", "t": "這名剛獲釋的囚犯享受著他新獲得的自由。", "as": "Her newfound confidence surprised everyone at the reunion.", "at": "她新獲得的自信讓聚會上的每個人都感到驚訝。", "a": 1}, {"w": "neologism", "p": "n.", "d": "A newly coined word or expression.", "c": "新詞;新造詞語", "s": "The internet has produced countless neologism s in recent decades.", "t": "近幾十年來,網路已經創造出無數的新詞。", "as": "Linguists track how each new neologism enters common usage.", "at": "語言學家追蹤每個新詞如何進入常見用法。", "a": 1}]}, {"unit": 86, "theme": "Skill and Mastery", "themeZh": "技巧與精通", "antonymLessons": [87], "cards": [{"w": "adept", "p": "adj.", "d": "Very skilled or proficient at something.", "c": "熟練的/精通的", "s": "He is adept at solving complex math problems.", "t": "他很擅長解決複雜的數學問題。", "as": "Beth loves playing the piano, but she's especially adept at the violin.", "at": "貝絲喜歡彈鋼琴,但她在小提琴方面尤其精通。"}, {"w": "adroit", "p": "adj.", "d": "Skillful.", "c": "熟練的/機敏的", "s": "The adroit negotiator managed to satisfy both sides of the dispute.", "t": "這位機敏的談判者成功讓爭議雙方都感到滿意。", "as": "She is remarkably adroit at solving problems under pressure.", "at": "她在壓力之下解決問題的能力極為熟練。"}, {"w": "deft", "p": "adj.", "d": "Neatly skillful and quick in one's movements.", "c": "靈巧的/熟練的", "s": "The pianist's deft fingers danced across the keys.", "t": "這位鋼琴家靈巧的手指在琴鍵上翩然舞動。", "as": "With a deft flick of the wrist, the chef flipped the pancake perfectly.", "at": "主廚手腕輕巧一甩,便完美地把煎餅翻了面。"}, {"w": "dexterous", "p": "adj.", "d": "Skillful in physical movements, especially of the hands.", "c": "靈巧的/手巧的", "s": "The surgeon's dexterous hands made the delicate operation look effortless.", "t": "這位外科醫生靈巧的雙手讓這場精細的手術看似毫不費力。", "as": "The pianist's dexterous fingers flew across the keys.", "at": "這位鋼琴家靈巧的手指在琴鍵上飛快地舞動。"}, {"w": "proficient", "p": "adj.", "d": "Competent or skilled in doing something.", "c": "精通的;熟練的", "s": "After years of practice, she became remarkably proficient in French.", "t": "經過多年的練習,她的法語變得異常精通。", "as": "The team hired a proficient programmer to fix the software bug.", "at": "這個團隊聘請了一位熟練的程式設計師來修復這個軟體錯誤。"}, {"w": "virtuoso", "p": "n.", "d": "A highly skilled performer, usually a musical performer.", "c": "藝術名家", "s": "The young virtuoso performed a flawless violin concerto.", "t": "這位年輕的演奏名家演奏了一首完美無瑕的小提琴協奏曲。", "as": "Critics called him a virtuoso of the piano after his debut recital.", "at": "評論家在他首次獨奏會後稱他為鋼琴演奏大師。"}, {"w": "consummate", "p": "adj.", "d": "Complete, of the highest degree.", "c": "圓滿的/技藝高超的", "s": "The violinist gave a consummate performance that left the audience speechless.", "t": "這位小提琴家獻上了一場技藝高超的演出,讓觀眾說不出話來。", "as": "He is a consummate professional who never misses a deadline.", "at": "他是個完美稱職的專業人士,從未錯過任何截止期限。"}, {"w": "masterful", "p": "adj.", "d": "Having or showing great skill; imperious.", "c": "精湛的;專橫的", "s": "The pianist gave a masterful performance of the challenging concerto.", "t": "這位鋼琴家對這首艱難的協奏曲做出了精湛的演出。", "as": "His masterful manner intimidated the junior staff.", "at": "他專橫的態度讓資淺員工感到畏懼。"}, {"w": "accomplished", "p": "adj.", "d": "Highly skilled or successful, especially in a particular field.", "c": "有成就的;熟練的", "s": "An accomplished violinist by age twelve, she later toured with the national orchestra.", "t": "她十二歲就已是位造詣深厚的小提琴家,後來還隨國家交響樂團巡演。", "as": "The panel included several accomplished scientists in the field of genetics.", "at": "這個評審小組包括好幾位基因學領域中成就斐然的科學家。"}, {"w": "expert", "p": "n./adj.", "d": "A person with comprehensive knowledge in a particular area.", "c": "專家;熟練的", "s": "The museum consulted an expert to authenticate the painting.", "t": "這座博物館請了一位專家來鑑定這幅畫的真偽。", "as": "She became an expert negotiator after years of practice.", "at": "經過多年的歷練,她成了一位熟練的談判專家。"}, {"w": "brilliant", "p": "adj.", "d": "Exceptionally clever, talented, or bright.", "c": "才華洋溢的;燦爛的", "s": "Her brilliant solution to the engineering problem saved the company months of work.", "t": "她對這個工程難題提出的絕妙解決方案,替公司省下了好幾個月的工作時間。", "as": "The fireworks lit up the night sky in brilliant bursts of color.", "at": "煙火在夜空中綻放出燦爛的色彩。", "a": 1}, {"w": "masterly", "p": "adj.", "d": "Showing great skill or ability.", "c": "精湛的;熟練的", "s": "The surgeon completed the operation with masterly precision.", "t": "這位外科醫生以精湛熟練的精準度完成了這場手術。", "as": "Critics praised the novel's masterly handling of multiple storylines.", "at": "評論家讚揚這本小說對多條故事線精湛的處理手法。", "a": 1}, {"w": "exemplary", "p": "adj.", "d": "Serving as a desirable model; outstandingly good.", "c": "模範的;典範的", "s": "Her exemplary conduct earned her a leadership award.", "t": "她模範的行為讓她獲得了領導力獎項。", "as": "The soldier received a medal for exemplary bravery.", "at": "這位士兵因典範般的勇氣而獲頒獎章。", "a": 1}, {"w": "connoisseur", "p": "n.", "d": "Expert.", "c": "鑑賞家/行家", "s": "He considers himself a connoisseur of fine wine.", "t": "他自認是一位美酒鑑賞行家。", "as": "As a connoisseur of classical music, she rarely missed a symphony performance.", "at": "身為古典音樂的行家,她幾乎不會錯過任何一場交響樂演出。", "a": 1}, {"w": "competent", "p": "adj.", "d": "Having the necessary ability or skill.", "c": "有能力的/勝任的", "s": "Noah has worked at this job for a long time and is a competent engineer.", "t": "諾亞在這份工作上已經做了很久,是一位稱職能幹的工程師。", "as": "The new hire proved to be more than competenteduring her first week.", "at": "這位新進員工在第一週就證明了自己相當能幹。", "a": 1}, {"w": "aficionado", "p": "n.", "d": "A person who is very knowledgeable and enthusiastic about an activity.", "c": "狂熱愛好者;行家", "s": "As a jazz aficionado , she owns over a thousand vinyl records.", "t": "身為爵士樂狂熱愛好者,她擁有超過一千張黑膠唱片。", "as": "The wine aficionado could identify a vintage by smell alone.", "at": "這位葡萄酒行家光憑氣味就能辨識出年份。", "a": 1}, {"w": "prowess", "p": "n.", "d": "Extraordinary ability.", "c": "非凡的能力/英勇", "s": "His athletic prowess was evident from a very young age.", "t": "他過人的運動天賦從很小的時候就展現出來。", "as": "The knight was celebrated throughout the kingdom for his prowess in battle.", "at": "這位騎士以其在戰場上的英勇表現,聞名於整個王國。", "a": 1}, {"w": "facility", "p": "n.", "d": "A building or place designed for a specific purpose; natural ability.", "c": "設施;能力", "s": "The town built a new sports facility last year.", "t": "這座城鎮去年建了一座新的運動設施。", "as": "She showed remarkable facility for learning new languages.", "at": "她展現出學習新語言方面驚人的能力。", "a": 1}]}, {"unit": 87, "theme": "Clumsy and Incompetent", "themeZh": "笨拙與無能", "antonymLessons": [86], "cards": [{"w": "inept", "p": "adj.", "d": "Having or showing no skill; clumsy.", "c": "笨拙的/不稱職的", "s": "His inept handling of the situation only made things worse.", "t": "他笨拙的處理方式只讓情況變得更糟。", "as": "The new manager proved surprisingly inept at resolving conflicts.", "at": "這位新任經理在化解衝突方面出人意料地顯得笨拙無能。"}, {"w": "awkward", "p": "adj.", "d": "Causing embarrassment or discomfort; lacking grace.", "c": "尷尬的;笨拙的", "s": "There was an awkward silence after his joke fell flat.", "t": "他的笑話冷場後,現場陷入一陣尷尬的沉默。", "as": "The teenager's awkwardedance moves made everyone at the party laugh.", "at": "這位青少年笨拙的舞步,逗得派對上所有人哈哈大笑。"}, {"w": "maladroit", "p": "adj.", "d": "Clumsy, awkward, or lacking skill and coordination.", "c": "笨拙的；不靈巧的", "s": "The new waiter's maladroit movement sent hot soup onto a customer's lap.", "t": "新服務生笨拙的動作將熱湯潑到客人腿上。", "as": "The diplomat's maladroit remark accidentally offended the prime minister.", "at": "外交官笨拙不當的言論意外冒犯了總理。"}, {"w": "bungling", "p": "adj./n.", "d": "Clumsy or incompetent, especially in performing a task.", "c": "笨拙的;搞砸", "s": "The bungling waiter managed to spill soup on three different tables.", "t": "這位笨手笨腳的服務生設法在三張不同的桌子上灑了湯。", "as": "Their bungling of the merger cost the company millions in lost contracts.", "at": "他們把這次併購案搞砸了,讓公司損失了數百萬的合約。"}, {"w": "gauche", "p": "adj.", "d": "Lacking social poise or refinement.", "c": "笨拙的/不得體的", "s": "His gauche comment about her weight embarrassed everyone at the table.", "t": "他關於她體重那句不得體的評論讓餐桌上每個人都感到尷尬。", "as": "The new intern felt gauche among the polished executives at the gala.", "at": "在這場晚會上,面對這群優雅世故的高階主管,這位新實習生感覺自己笨拙又格格不入。"}, {"w": "incompetent", "p": "adj.", "d": "Not having the necessary skill to do something successfully.", "c": "無能的;不稱職的", "s": "The manager was fired for being incompetent .", "t": "這位經理因不稱職而遭到解雇。", "as": "Voters called out the incompetent handling of the crisis.", "at": "選民批評了這次危機處理的無能。"}, {"w": "clumsy", "p": "adj.", "d": "Awkward in movement or in handling things.", "c": "笨拙的", "s": "His clumsy attempt to catch the falling vase only made things worse.", "t": "他笨拙地想接住掉落的花瓶,結果只讓情況更糟。", "as": "She felt clumsy on the ice during her first skating lesson.", "at": "第一堂溜冰課上,她在冰上感覺笨手笨腳。", "a": 1}, {"w": "cumbersome", "p": "adj.", "d": "Unwieldy, burdensome.", "c": "笨重的/累贅的", "s": "The old software was slow and cumbersome compared to the new app.", "t": "與新的應用程式相比,這款舊軟體既緩慢又笨重。", "as": "Carrying the cumbersome equipment up the mountain slowed the team down.", "at": "扛著這些笨重的設備上山拖慢了整支隊伍的速度。", "a": 1}, {"w": "unwieldy", "p": "adj.", "d": "Bulky, difficult to handle.", "c": "笨重的/難處理的", "s": "The unwieldy suitcase was nearly impossible to carry up the stairs.", "t": "這個笨重的行李箱幾乎不可能扛上樓梯。", "as": "The company's unwieldy bureaucracy slowed down every decision.", "at": "這家公司笨重的官僚體系拖慢了每一項決策的速度。", "a": 1}, {"w": "boorish", "p": "adj.", "d": "Rude and ill-mannered.", "c": "粗魯的;無禮的", "s": "His boorish behavior at the wedding embarrassed the entire family.", "t": "他在婚禮上粗魯的行為,讓整個家族都感到丟臉。", "as": "The critic called the comedian's jokes boorish and outdated.", "at": "這位評論家批評這位喜劇演員的笑話粗俗又過時。", "a": 1}, {"w": "uncouth", "p": "adj.", "d": "Lacking good manners, refinement, or grace.", "c": "粗野的;粗魯的", "s": "His uncouth table manners embarrassed his date at the formal dinner.", "t": "他粗魯的餐桌禮儀在這場正式晚宴上讓他的約會對象感到尷尬。", "as": "The character is portrayed as an uncouth outsider unfamiliar with city customs.", "at": "這個角色被描繪成一個對城市習俗一無所知、粗野的外來者。", "a": 1}, {"w": "mediocre", "p": "adj.", "d": "Of only moderate quality; not very good.", "c": "平庸的;普通的", "s": "The critics called the film mediocre at best.", "t": "評論家認為這部電影頂多只能算是平庸之作。", "as": "He was tired of settling for a mediocre performance.", "at": "他厭倦了滿足於平庸的表現。", "a": 1}]}, {"unit": 88, "theme": "Hesitation and Delay", "themeZh": "猶豫與拖延", "antonymLessons": [17], "cards": [{"w": "procrastinate", "p": "v.", "d": "To delay, put off.", "c": "拖延/耽擱", "s": "He tends to procrastinate until the night before a deadline.", "t": "他總是習慣拖到截止日期前一晚才動手。", "as": "She promised herself she would stop procrastinateing on her thesis.", "at": "她告訴自己不再拖延撰寫論文。"}, {"w": "vacillate", "p": "v.", "d": "To hesitate, fluctuate.", "c": "猶豫不決/搖擺", "s": "He continued to vacillate between the two job offers for weeks.", "t": "他猶豫不決地在這兩份工作邀約之間搖擺了好幾個星期。", "as": "The council seemed to vacillate on every major decision.", "at": "這個委員會似乎在每一項重大決策上都猶豫不決。"}, {"w": "dither", "p": "v.", "d": "To be indecisive.", "c": "猶豫不決", "s": "Stop dithering and just choose a restaurant already!", "t": "別再猶豫不決了,快選一家餐廳吧!", "as": "He continued to dither over which college to attend.", "at": "他仍在猶豫該就讀哪所大學。"}, {"w": "dilatory", "p": "adj.", "d": "Tending to delay, causing delay.", "c": "拖延的/延誤的", "s": "The company's dilatory response frustrated customers waiting for refunds.", "t": "這家公司拖延的回應讓等待退款的顧客感到十分不滿。", "as": "Lawyers accused the defense of using dilatory tactics to delay the trial.", "at": "律師指控辯方使用拖延戰術來延誤這場審判。"}, {"w": "linger", "p": "vb.", "d": "To hang around; to stay.", "c": "逗留", "s": "The smell of fresh coffee continued to linger in the kitchen.", "t": "廚房裡持續瀰漫著新鮮咖啡的香氣。", "as": "She chose to linger a little longer at the museum after everyone else left.", "at": "在其他人都離開後,她選擇在博物館多逗留一會兒。"}, {"w": "dally", "p": "v.", "d": "To act playfully; to waste time.", "c": "調情;閒混", "s": "Stop dallying and finish your homework.", "t": "別再閒混了,快把功課做完。", "as": "He liked to dally with several admirers at once.", "at": "他喜歡同時和好幾個仰慕者調情。", "a": 1}, {"w": "defer", "p": "v.", "d": "To postpone something; to yield to another's wisdom.", "c": "延遲/順從", "s": "The committee decided to defer its decision until next month.", "t": "委員會決定將這項決議延後到下個月再做。", "as": "On matters of design, the engineers chose to defer to the architect's judgment.", "at": "在設計事務上,工程師們選擇聽從建築師的判斷。", "a": 1}, {"w": "postpone", "p": "v.", "d": "To delay or reschedule to a later time.", "c": "推遲;延後", "s": "The organizers decided to postpone the outdoor concert due to rain.", "t": "由於下雨,主辦單位決定延後這場戶外音樂會。", "as": "She had to postpone her trip because of a family emergency.", "at": "由於家庭緊急事件,她不得不推遲她的行程。", "a": 1}]}, {"unit": 89, "theme": "Surprise and Wonder", "themeZh": "驚奇與讚嘆", "antonymLessons": [], "cards": [{"w": "astound", "p": "v.", "d": "To shock or greatly surprise someone.", "c": "使震驚;使驚愕", "s": "The magician's final trick continued to astound audiences decades later.", "t": "這位魔術師的最後一個把戲,數十年後仍讓觀眾驚嘆不已。", "as": "It never ceases to astound me how quickly technology changes.", "at": "科技變化的速度之快,總是讓我感到震驚。"}, {"w": "flabbergast", "p": "v.", "d": "To surprise someone greatly.", "c": "使大吃一驚;使目瞪口呆", "s": "The magician's final trick left the audience flabbergast ed.", "t": "這位魔術師的最後一個把戲讓觀眾大吃一驚。", "as": "She was flabbergast ed to learn she had won the award.", "at": "得知自己得獎的消息讓她驚訝得目瞪口呆。"}, {"w": "dumbfound", "p": "v.", "d": "To astonish someone greatly, leaving them speechless.", "c": "使目瞪口呆", "s": "The magician's trick dumbfound ed the entire audience.", "t": "這位魔術師的把戲讓整個觀眾席都目瞪口呆。", "as": "She was dumbfound ed by his sudden proposal.", "at": "他突如其來的求婚讓她目瞪口呆。"}, {"w": "stupefy", "p": "v.", "d": "To astonish, make insensible.", "c": "使目瞪口呆/使麻木", "s": "The magician's final trick continued to stupefy the entire audience.", "t": "這位魔術師最後的把戲讓全場觀眾看得目瞪口呆。", "as": "The sheer scale of the ancient ruins stupefyed the visiting archaeologists.", "at": "這座古代遺跡的龐大規模讓來訪的考古學家們驚嘆不已。"}, {"w": "bewilder", "p": "v.", "d": "To confuse someone greatly.", "c": "使困惑;使迷惘", "s": "The maze of hallways continued to bewilder new employees for weeks.", "t": "這座迷宮般的走廊,讓新進員工好幾個星期都摸不著頭緒。", "as": "The sudden change in the rules seemed designed to bewilder the players.", "at": "規則的突然改變,似乎就是要讓玩家感到困惑。"}, {"w": "perplex", "p": "v.", "d": "To confuse.", "c": "使困惑/使費解", "s": "The riddle continued to perplex even the brightest students.", "t": "這道謎題持續困擾著即使是最聰明的學生。", "as": "Her sudden change in behavior began to perplex her closest friends.", "at": "她行為的突然轉變開始讓她最親近的朋友感到困惑。", "a": 1}, {"w": "stun", "p": "v.", "d": "To knock unconscious or daze; to astonish.", "c": "使昏迷;使震驚", "s": "The blow to his head was enough to stun him momentarily.", "t": "這一擊擊中他的頭部,足以讓他瞬間昏迷。", "as": "The announcement of her resignation seemed to stun the entire office.", "at": "她辭職的消息似乎讓整個辦公室都感到震驚。", "a": 1}, {"w": "baffle", "p": "v.", "d": "To completely confuse or perplex.", "c": "使困惑;難倒", "s": "The disappearing coin trick continued to baffle even seasoned magicians.", "t": "這個消失硬幣的把戲,連經驗豐富的魔術師都感到困惑。", "as": "The sudden drop in sales baffle the entire marketing team.", "at": "銷售額突然下滑,讓整個行銷團隊都摸不著頭緒。", "a": 1}, {"w": "mystify", "p": "v.", "d": "To cause confusion or bewilderment.", "c": "使困惑;使迷惑", "s": "The magician's final trick continued to mystify audiences for years.", "t": "這位魔術師的最後一個戲法多年來持續讓觀眾感到困惑。", "as": "Her sudden resignation seemed to mystify everyone in the department.", "at": "她突然的辭職似乎讓部門裡的每個人都感到不解。", "a": 1}, {"w": "disconcert", "p": "v.", "d": "To disturb the composure of; to unsettle.", "c": "使不安;使困惑", "s": "The sudden silence began to disconcert the speaker.", "t": "突如其來的沉默開始讓這位講者感到不安。", "as": "Her blunt question disconcert ed the entire panel.", "at": "她直率的問題讓整個評審團感到困惑不安。", "a": 1}, {"w": "prodigy", "p": "n.", "d": "Marvel, phenomenon.", "c": "神童/奇蹟", "s": "The young violinist was hailed as a musical prodigy.", "t": "這位年輕的小提琴手被譽為音樂神童。", "as": "He was a chess prodigy, winning tournaments before the age of ten.", "at": "他是個西洋棋神童,不到十歲就贏得多項錦標賽冠軍。", "a": 1}]}, {"unit": 90, "theme": "Reveal and Disclose", "themeZh": "揭露與公開", "antonymLessons": [25], "cards": [{"w": "divulge", "p": "v.", "d": "To disclose, reveal.", "c": "洩露/暴露", "s": "She refused to divulge the identity of her source.", "t": "她拒絕透露她消息來源的身分。", "as": "He accidentally divulged the surprise party plans to his sister.", "at": "他不小心向姊姊洩露了驚喜派對的計畫。"}, {"w": "disclose", "p": "v.", "d": "To reveal, make public.", "c": "揭露/公開", "s": "The company was required to disclose its financial losses to shareholders.", "t": "這家公司被要求向股東公開其財務虧損。", "as": "She refused to disclose the identity of her source.", "at": "她拒絕透露她消息來源的身分。"}, {"w": "unveil", "p": "v.", "d": "To remove a covering from; to reveal publicly.", "c": "揭幕;揭露", "s": "The mayor will unveil the new statue at tomorrow's ceremony.", "t": "這位市長將在明天的典禮上為這座新雕像揭幕。", "as": "The company plans to unveil its latest product next month.", "at": "這家公司計畫在下個月揭露他們最新的產品。"}, {"w": "reveal", "p": "v.", "d": "To make known previously secret or hidden information.", "c": "揭露;透露", "s": "She finally decided to reveal the truth about her past.", "t": "她終於決定揭露她過去的真相。", "as": "The investigation began to reveal a pattern of fraudulent activity.", "at": "這項調查開始揭露一系列的詐欺行為模式。"}, {"w": "expose", "p": "v.", "d": "To reveal or make visible; to uncover wrongdoing.", "c": "揭露;暴露", "s": "The journalist worked for months to expose the scandal.", "t": "這位記者花了數月時間揭露這場醜聞。", "as": "Prolonged sun can expose skin to harmful UV rays.", "at": "長時間曝曬會讓皮膚暴露在有害的紫外線之下。"}, {"w": "manifest", "p": "adj. / v.", "d": "Clear or obvious to the eye or mind; to display or show.", "c": "明顯的；顯現；證實", "s": "The artist's rejection of industrial mass production was manifest in his careful reliance on medieval handcrafted binding techniques.", "t": "這位藝術家對工業化量產的反感，在其對中世紀手工裝訂技術的用心依賴中「顯現（表現得很明顯）」。", "as": "", "at": ""}, {"w": "proclaim", "p": "v.", "d": "To announce officially or publicly.", "c": "宣告/宣布", "s": "The president will proclaim the new law during the ceremony tomorrow.", "t": "總統將於明天的典禮上宣布這項新法律。", "as": "The king proclaim a new law.", "at": "國王頒布了一項新法律。"}, {"w": "promulgate", "p": "v.", "d": "To make known officially.", "c": "公布/頒布", "s": "The government plans to promulgate the new tax law next month.", "t": "政府計畫在下個月頒布這項新的稅法。", "as": "The committee will promulgate the updated safety guidelines to all employees.", "at": "委員會將向所有員工公布更新後的安全準則。"}, {"w": "broadcast", "p": "v./n.", "d": "To transmit a program by radio or television; such a transmission.", "c": "廣播;播送", "s": "The station will broadcast the game live starting at seven.", "t": "電台將於七點開始現場轉播這場比賽。", "as": "Millions tuned in to watch the historic broadcast.", "at": "數百萬人收看了這場具有歷史意義的轉播。"}, {"w": "publicize", "p": "v.", "d": "To bring to public attention.", "c": "宣傳;公開", "s": "The organization worked hard to publicize its upcoming charity event.", "t": "這個組織努力宣傳即將到來的慈善活動。", "as": "The scandal was publicized widely before the company could respond.", "at": "在這家公司能夠回應之前,這場醜聞就已經被廣泛公開。"}, {"w": "disseminate", "p": "v.", "d": "To scatter, spread.", "c": "散佈/傳播", "s": "The organization works to disseminate accurate health information.", "t": "這個組織致力於傳播正確的健康資訊。", "as": "News of the discovery quickly disseminated across the scientific community.", "at": "這項發現的消息迅速在科學界傳開。", "a": 1}, {"w": "illuminate", "p": "v.", "d": "To light up or clarify.", "c": "照亮/闡明", "s": "The lantern illuminate the path through the forest.", "t": "這盞燈籠照亮了穿越森林的小徑。", "as": "Her lecture helped illuminate the more confusing parts of the theory.", "at": "她的講座有助於闡明這項理論中較令人困惑的部分。", "a": 1}, {"w": "testify", "p": "v.", "d": "To give evidence as a witness, especially in court.", "c": "作證;證明", "s": "The eyewitness agreed to testify at the upcoming trial.", "t": "這位目擊者同意在即將到來的審判中出庭作證。", "as": "Her calm demeanor seemed to testify to her innocence.", "at": "她鎮定的態度似乎證明了她的清白。", "a": 1}, {"w": "apprise", "p": "v.", "d": "To inform someone of something.", "c": "通知;告知", "s": "Please apprise the team of any changes to the schedule immediately.", "t": "行程若有任何變動,請立刻告知團隊。", "as": "The lawyer kept her client fully apprise of every development in the case.", "at": "律師隨時讓當事人充分了解案件的每個進展。", "a": 1}, {"w": "elucidate", "p": "v.", "d": "To make something clear; explain thoroughly.", "c": "闡明；說明", "s": "The professor used a clear diagram to elucidate the complex chemical process of cellular respiration for her students.", "t": "教授使用了一張清晰的圖表向學生「闡明（說明）」細胞呼吸複雜的化學過程。", "as": "", "at": "", "a": 1}, {"w": "explicate", "p": "v.", "d": "To analyze and explain in detail.", "c": "詳細解說;闡明", "s": "The critic began to explicate the poem's hidden symbolism.", "t": "這位評論家開始詳細解說這首詩隱藏的象徵意義。", "as": "Her thesis aims to explicate the causes of the economic collapse.", "at": "她的論文旨在闡明這場經濟崩潰的成因。", "a": 1}, {"w": "clarify", "p": "v.", "d": "To make something clearer or easier to understand.", "c": "澄清;闡明", "s": "Could you clarify what you meant by that last comment?", "t": "你能澄清一下,你最後那句話是什麼意思嗎?", "as": "The professor paused to clarify a particularly confusing formula.", "at": "教授停下來,闡明一個特別令人困惑的公式。", "a": 1}]}, {"unit": 91, "theme": "Universal and Widespread", "themeZh": "普遍與廣泛", "antonymLessons": [92], "cards": [{"w": "ubiquitous", "p": "adj.", "d": "Present, appearing, or found everywhere.", "c": "無所不在的；普遍的", "s": "Smartphones have become so ubiquitous in modern society that people of all age groups rely on them constantly.", "t": "智慧型手機在現代社會中已變得「無所不在」，各年齡層的人都時刻依賴著它們。", "as": "", "at": ""}, {"w": "pervasive", "p": "adj.", "d": "Spreading widely throughout an area or a group of people.", "c": "瀰漫的/普遍存在的", "s": "The pervasive scent of freshly baked cookies filled the entire house.", "t": "剛烤好的餅乾香氣瀰漫了整棟房子。", "as": "Corruption remains a pervasive problem in many governments.", "at": "貪腐依然是許多政府中普遍存在的問題。"}, {"w": "omnipresent", "p": "adj.", "d": "Existing everywhere at once.", "c": "無所不在的", "s": "Smartphones have become nearly omnipresent in modern society.", "t": "智慧型手機在現代社會中幾乎已經無所不在。", "as": "In many religious traditions, God is described as omnipresent.", "at": "在許多宗教傳統中,神被描述為無所不在的存在。"}, {"w": "prevalent", "p": "adj.", "d": "Widespread or common in a particular area or at a particular time.", "c": "盛行的；普遍的", "s": "Smartphone usage has become so prevalent among teenagers that school districts are rethinking digital device policies.", "t": "智慧型手機的使用在青少年中變得如此「普遍（盛行）」，以致於學區正在重新思考數位裝置政策。", "as": "", "at": ""}, {"w": "rampant", "p": "adj.", "d": "Going unchecked, widespread.", "c": "猖獗的", "s": "Corruption was rampant within the local government for decades.", "t": "數十年來,貪腐在地方政府中十分猖獗。", "as": "The disease became rampant after the flood destroyed the water supply.", "at": "洪水破壞了供水系統後,這種疾病開始猖獗蔓延。"}, {"w": "rife", "p": "adj.", "d": "Widespread.", "c": "普遍的/盛傳的", "s": "Corruption was rife throughout the local government.", "t": "貪腐在當地政府中十分普遍。", "as": "Rumors were rife about the company's upcoming layoffs.", "at": "關於公司即將裁員的謠言四處盛傳。"}, {"w": "widespread", "p": "adj.", "d": "Found or occurring over a large area.", "c": "普遍的/廣泛的", "s": "The disease became widespread.", "t": "這種疾病變得十分普遍。", "as": "There is widespread support for the new environmental policy.", "at": "這項新的環境政策獲得廣泛的支持。"}, {"w": "sweeping", "p": "adj.", "d": "Wide in range or effect; extending far.", "c": "全面的;大範圍的", "s": "The new law introduced sweeping changes to the healthcare system.", "t": "這項新法為醫療體系帶來了全面性的變革。", "as": "He made a sweeping generalization about the entire industry.", "at": "他對整個產業做出了一個以偏概全的概括論斷。"}, {"w": "universal", "p": "adj.", "d": "Present everywhere.", "c": "普遍的/宇宙的", "s": "The desire for love and belonging seems to be a universal human need.", "t": "對愛與歸屬感的渴望似乎是一種普遍的人類需求。", "as": "The company hopes to design a universal remote that works with any device.", "at": "這家公司希望設計出一款能與任何裝置搭配使用的通用遙控器。", "a": 1}, {"w": "broad", "p": "adj.", "d": "Wide in extent or scope.", "c": "寬廣的;廣泛的", "s": "The professor gave a broad overview before diving into the details.", "t": "教授先做了一個廣泛的概述,再深入細節。", "as": "He has a surprisingly broad knowledge of world history for someone his age.", "at": "以他的年紀來說,他對世界史的了解出奇地廣博。", "a": 1}, {"w": "extensive", "p": "adj.", "d": "Covering a large area or scope.", "c": "廣泛的", "s": "The Art Institute of Chicago has an extensive Impressionist collection.", "t": "芝加哥藝術博物館擁有一批廣泛豐富的印象派收藏。", "as": "The company conducted extensive research before launching the product.", "at": "這家公司在產品上市前進行了廣泛的研究。", "a": 1}, {"w": "ever-present", "p": "adj.", "d": "Constantly existing or occurring; always there.", "c": "無所不在的;始終存在的", "s": "Fear of failure was an ever-present concern for the young athlete.", "t": "對失敗的恐懼是這位年輕運動員始終存在的隱憂。", "as": "The mountain remained an ever-present backdrop to the small town.", "at": "這座山始終是這座小鎮無所不在的背景。", "a": 1}, {"w": "common", "p": "adj.", "d": "Occurring frequently or shared.", "c": "常見的", "s": "It's very common for students to feel stressed before exams.", "t": "學生在考試前感到緊張是非常常見的。", "as": "Colds are especially commoneduring the winter months.", "at": "感冒在冬季月份特別常見。", "a": 1}, {"w": "ubiquity", "p": "n.", "d": "The state of being present everywhere at once.", "c": "無所不在;普遍存在", "s": "The ubiquity of smartphones has transformed nearly every aspect of daily life.", "t": "智慧型手機的無所不在已經改變了日常生活幾乎每一個層面。", "as": "Advertisers benefit from the brand's ubiquity across social media platforms.", "at": "廣告商受益於這個品牌在社群媒體平台上的普遍存在。", "a": 1}]}, {"unit": 92, "theme": "Rare and Scarce", "themeZh": "稀少與罕見", "antonymLessons": [91, 20], "cards": [{"w": "sparse", "p": "adj.", "d": "Thinly scattered or distributed.", "c": "稀疏的;稀少的", "s": "Vegetation grew sparse in the harsh desert climate.", "t": "在這片嚴酷的沙漠氣候中,植被生長得十分稀疏。", "as": "The lecture hall had only a sparse audience that evening.", "at": "那天晚上,這間演講廳裡只有稀稀落落的聽眾。"}, {"w": "meager", "p": "adj.", "d": "Deficient in size or quality.", "c": "貧乏的/微薄的", "s": "The family survived on a meagerediet of rice and beans.", "t": "這個家庭靠著微薄的米飯和豆子維生。", "as": "His meager salary barely covered the rent each month.", "at": "他微薄的薪水幾乎不夠支付每個月的房租。"}, {"w": "paucity", "p": "n.", "d": "The presence of something only in small or insufficient quantities or amounts.", "c": "缺乏；少量", "s": "The defense attorney argued that there was a severe paucity of hard evidence connecting his client to the crime scene. Based on this lack of proof, he demanded an immediate acquittal.", "t": "辯護律師辯稱，嚴重缺乏將他的委託人與犯罪現場聯繫起來的確鑿證據。基於這種證據的匱乏，他要求立即無罪釋放。", "as": "", "at": ""}, {"w": "dearth", "p": "n.", "d": "Lack, scarcity.", "c": "缺乏/稀少", "s": "There is a dearth of affordable housing in the city.", "t": "這座城市極度缺乏可負擔的住房。", "as": "The region suffers from a dearth of skilled workers.", "at": "這個地區苦於缺乏具備專業技能的勞動力。"}, {"w": "infrequent", "p": "adj.", "d": "Not occurring often.", "c": "罕見的；不常發生的", "s": "Because the remote island is difficult to reach by boat, visits from tourists are highly infrequent. The local residents generally go months without seeing a new face.", "t": "因為這座偏遠的島嶼很難乘船抵達，所以遊客的造訪非常罕見。當地居民通常幾個月都見不到生面孔。", "as": "", "at": ""}, {"w": "scarcity", "p": "n.", "d": "The state of being in short supply.", "c": "稀缺;匱乏", "s": "The drought caused a severe scarcity of clean water.", "t": "這場乾旱導致了嚴重的乾淨水源匱乏。", "as": "Economists study how scarcity affects the price of goods.", "at": "經濟學家研究稀缺性如何影響商品的價格。", "a": 1}, {"w": "shortage", "p": "n.", "d": "A state in which something needed is not available in sufficient amounts.", "c": "短缺;不足", "s": "The drought led to a severe water shortage across the region.", "t": "這場乾旱導致這個地區嚴重的水資源短缺。", "as": "Hospitals faced a critical shortage of medical supplies during the outbreak.", "at": "醫院在這場疫情爆發期間面臨醫療用品的嚴重短缺。", "a": 1}, {"w": "sporadic", "p": "adj.", "d": "Occasional.", "c": "偶爾的/零星的", "s": "There were only sporadic reports of the disease in the region last year.", "t": "去年該地區只有零星的病例報告。", "as": "The gunfire was sporadic throughout the night, coming in short bursts.", "at": "整晚槍聲斷斷續續,零星地響起。", "a": 1}, {"w": "singular", "p": "adj.", "d": "Remarkable.", "c": "異常的/單一的", "s": "She showed a singular talent for languages from a very young age.", "t": "她從很小的時候就展現出異於常人的語言天賦。", "as": "It was a singular achievement for someone so young.", "at": "對一個這麼年輕的人來說,這是一項非凡的成就。", "a": 1}, {"w": "anomalous", "p": "adj.", "d": "Deviating from what is standard or expected.", "c": "異常的;反常的", "s": "The satellite detected an anomalous reading that scientists could not immediately explain.", "t": "衛星偵測到一個科學家一時無法解釋的異常讀數。", "as": "Her sudden drop in grades was anomalous given her usually strong performance.", "at": "以她一貫優異的表現來看,成績突然下滑是相當異常的。", "a": 1}, {"w": "aberrant", "p": "adj.", "d": "Deviating from what is normal or expected.", "c": "異常的;脫軌的", "s": "The scientist noted the cell's aberrant growth pattern and flagged it for further study.", "t": "科學家注意到那個細胞異常的生長模式,標記起來進一步研究。", "as": "His usually calm boss displayed aberrant behavior after the merger was announced.", "at": "併購案宣布後,他一向冷靜的老闆表現出異常的行為。", "a": 1}]}];
